// The outline worklist driver (docs/ARCH.md section 6.1): per crate, cfg
// stripping, module loading, import resolution, and macro expansion are
// one loop, not separate phases. W-RESOLVE owns the loop and the cfg,
// module, and import steps; W-MACRO owns expansion. Expansion runs per
// file at lex time through `expand::expand_lexed`, with this crate's
// real cfg environment (section 1.6) fed into the expander's facts, so
// its item strip and `cfg!` agree with the strip below. The frozen
// call-level interface (`expand::expand_call`) takes over when the
// parser keeps macro calls as nodes; today a `mod` item generated by a
// macro in an already-discovered file is not discovered as a new file
// edge (the loop re-registers its items, but file discovery ran on the
// unexpanded outline).
//
// Output shape: one merged Ast for collect. Defs outside the root module
// carry module-mangled flat names (`a$b$name`, never a legal Rust
// identifier; `ResolvedTables::display_names` keeps the source path of
// each, so flat names never reach program output or diagnostics), and
// every path the resolver can prove is rewritten to the
// flat name (one segment, or two for `Type::assoc`), so collect and
// check keep their flat tables while the binding tables here hold the
// real module semantics. DefIds are computed with the same formulas
// collect uses on the flat names, so slot keys and def ids agree by
// construction (the mangled name carries the module path in the hash).
use super::cfg::{self, CfgEnv};
use super::imports::*;
use super::macro_scope::{FileMacroScope, ScopeEvent};
use super::modules;
use crate::ast::*;
use crate::def::{self, CrateIds, DefId, DefPathHash};
use crate::diag::{Diag, FileId, SourceMap, Span};
use crate::driver::graph::Namespace;
use crate::intern::{FxMap, Interner, Known, Sym};
use crate::stdload::StdPlan;
use crate::ty::defs::{ModuleId, ROOT_MODULE};
use crate::{lexer, parser, scan};
use std::path::PathBuf;

/// The selected crate to resolve: its root file and text (with any std
/// splice already appended by the driver), its cfg environment, its
/// stable identity, and its dependency tree from the Cargo graph.
/// Dependency crates lust compiles from source resolve in the same
/// workspace session (ARCH 1.8): one shared interner and one shared
/// binding table set, one detached module subtree per crate, so
/// `dep::Item` paths and cross-crate visibility use the same code as
/// same-crate paths.
#[derive(Clone)]
pub struct CrateInput {
    pub root_path: PathBuf,
    pub root_text: String,
    pub env: CfgEnv,
    pub crate_ids: CrateIds,
    pub crate_name: String,
    /// Env values Cargo sets for rustc for the selected crate,
    /// build script outputs included (see `ExpandCtx::cargo_env`).
    pub cargo_env: Vec<(String, String)>,
    /// The selected crate's direct dependency lib units, recursively.
    pub deps: Vec<super::cargo::DepUnit>,
    /// The requesting client's env and shown paths, for `env!` and `file!` in every crate.
    pub client: crate::expand::ClientView,
    /// Where the driver's std splice starts in `root_text`, if it
    /// spliced. Std source modules (src/stdmods.rs) are hidden only
    /// when they sit at or after this offset.
    pub std_splice_lo: Option<u32>,
    /// The Cargo workspace root (W-PANIC): `file!()` names a file under it
    /// relative to it, as Cargo hands paths to rustc (docs/ARCH.md 3.5).
    /// None for a single file.
    pub display_root: Option<PathBuf>,
}

/// One crate's own resolve inputs inside a workspace session (the
/// selected crate or one source dependency).
#[derive(Clone)]
struct OneInput {
    root_path: PathBuf,
    root_text: String,
    env: CfgEnv,
    /// The merged program's ids: every crate in the session computes
    /// def hashes with the selected crate's stable hash over flat
    /// names that carry a per-crate prefix, which is what collect
    /// recomputes on the merged AST. Slots are per final bin (1.7),
    /// so one identity space per merged program is consistent.
    crate_ids: CrateIds,
    crate_name: String,
    /// See `CrateInput::cargo_env`, per crate.
    cargo_env: Vec<(String, String)>,
    /// `CrateInput::std_splice_lo` for the selected crate; None for a
    /// dependency.
    std_splice_lo: Option<u32>,
    /// See `CrateInput::display_root`.
    display_root: Option<PathBuf>,
}

/// The resolved crate the driver compiles: the merged Ast, the source
/// map with every file's text, the binding tables, and per-fn panic
/// lines and body hashes in flattened order.
pub struct ResolvedCrate {
    pub ast: Ast,
    pub map: SourceMap,
    pub tables: ResolvedTables,
    pub fn_lines: Vec<u32>,
    pub body_hashes: Vec<u64>,
    /// A hash of the crate's module and import structure: every `mod`,
    /// `use`, and `extern crate` item (which flattening drops from the
    /// Ast), per file in worklist order. The driver folds it into its
    /// environment hash, so an import-only or module-tree edit is never
    /// mistaken for a body-only edit. `Sym` ids hash directly: the
    /// driver compares hashes inside one session only.
    pub structure_hash: u64,
    /// Every file's text concatenated, for the diagnostic source hash.
    pub all_text: String,
    /// What the files ask of std (`stdload::StdPlan::asks`): every file
    /// but the std platform crate's, the root without its std splice.
    /// The driver owns std splicing and the platform crate: when these
    /// differ from its plan, it resolves once more.
    pub std_asks: StdPlan,
    /// What the std platform crate's files ask, when it joined.
    pub platform_asks: Option<StdPlan>,
    /// Outside inputs expansion read across the crate's files (added
    /// for W-MACRO; see `expand::Dep`).
    pub expand_deps: Vec<crate::expand::Dep>,
    /// Wall time per worklist phase in milliseconds, summed over the
    /// workspace's crates, for the driver's `--timings` output.
    pub timings: Vec<(&'static str, f64)>,
    /// The structural Ast scan, assembled from per-file chunk scans
    /// (cached per file in `ResolveCache`). It is equal to a scan of
    /// the merged `ast`; the driver uses it instead of rescanning.
    pub scans: crate::driver::ast_hash::AstScans,
    /// The module dependency record, under `LUST_B3_OBSERVE=1` (resolve/mdr.rs).
    pub mdr: Option<crate::resolve::mdr::Mdr>,
    /// Which resolve of the cache made `ast` (`ResolveCache::set_merged`): the cache's
    /// final chunks are parts of it.
    pub generation: u64,
}

/// A failed resolution: the source map and combined text for rendering,
/// plus the diagnostics (whose spans may name any discovered file).
pub struct ResolveError {
    pub map: SourceMap,
    pub all_text: String,
    /// As `ResolvedCrate::std_asks`, over the files seen before the error.
    pub std_asks: StdPlan,
    pub platform_asks: Option<StdPlan>,
    pub diags: Vec<Diag>,
}

/// True when a crate root file needs the resolver: any `mod`, `use`,
/// `const`/`static`/`type` item keyword, `#[cfg`, `#[path`, `macro_rules`,
/// or an `include!` call in its token stream. Token-exact (strings and comments
/// never count); a `use` of `std` alone also routes here, which costs a
/// full rebuild but keeps one code path for imports and cfg.
///
/// A big file is lexed in pieces in parallel (see `route_pieces`); the
/// answer is the same as one serial lex.
pub fn needs_resolve(root_text: &str, interner: &Interner) -> bool {
    route_root(root_text, interner).0
}

/// `needs_resolve`, plus the root's token list when the answer is yes:
/// exactly a serial lex at file 0, base 0, which is how discovery lexes a
/// single-file crate root. The driver seeds the resolve cache with it
/// (`ResolveCache::seed_root`), so the root is not lexed twice.
pub fn route_root(root_text: &str, interner: &Interner) -> (bool, Option<lexer::Lexed>) {
    let (yes, _, lexed) = route_root_std(root_text, interner, false);
    (yes, lexed)
}

/// `route_root`, plus `stdmods::needs(root_text)` when `std` is set
/// (else false), found in the same parallel pass: each piece ends right
/// after a newline, so no word crosses a cut and the file's answer is
/// any piece's answer.
pub fn route_root_std(root_text: &str, interner: &Interner, std: bool) -> (bool, u32, Option<lexer::Lexed>) {
    if let Some(pieces) = route_pieces(root_text) {
        let answers = par_map(&pieces, |&(a, b)| {
            let lexed = lexer::lex(&root_text[a..b], FileId(0), a as u32, interner).ok()?;
            let std_mods = if std { crate::stdmods::needs(&root_text[a..b]) } else { 0 };
            piece_cut_ok(&lexed, b, root_text.len()).then(|| (route_keywords(&lexed, interner), std_mods, lexed))
        });
        if let Some(answers) = answers.into_iter().collect::<Option<Vec<(bool, u32, lexer::Lexed)>>>() {
            let std_mods = answers.iter().fold(0, |m, a| m | a.1);
            // The brace scan needs the whole file in order: each piece but
            // the last ends in an end-of-input token that `join_lexed` drops.
            let last = answers.len() - 1;
            let yes = answers.iter().any(|a| a.0) || {
                let mut scan = NestedFnScan::default();
                answers.iter().enumerate().any(|(k, a)| scan.feed(&a.2.tokens[..a.2.tokens.len() - usize::from(k < last)]))
            };
            return (yes, std_mods, yes.then(|| join_lexed(answers.into_iter().map(|a| a.2).collect())));
        }
    }
    let std_mods = if std { crate::stdmods::needs(root_text) } else { 0 };
    let Ok(lexed) = lexer::lex(root_text, FileId(0), 0, interner) else { return (false, std_mods, None) };
    let yes = needs_resolve_lexed(&lexed, interner);
    (yes, std_mods, yes.then_some(lexed))
}

/// Cut points for lexing a big file in parallel: about four pieces per
/// thread (`pool::threads`), each cut right after a line that ends in `}` or `;`. Each piece
/// lexes on its own, and `piece_cut_ok` checks that every cut really
/// falls between tokens; on any doubt the caller lexes serially (a cut
/// inside a string or comment leaves its start unterminated, so that
/// piece fails to lex or fails the check). The routing test of a piece
/// needs no context from its neighbors: a leading `::` triggers with no
/// previous token as it does after `}` or `;`, and no lookahead reaches
/// past a trailing `}` or `;`. None for a small file.
fn route_pieces(text: &str) -> Option<Vec<(usize, usize)>> {
    const MIN_PIECE: usize = 16 * 1024;
    let target = (text.len() / (crate::pool::threads() * 4)).max(MIN_PIECE);
    if text.len() < 2 * target {
        return None;
    }
    let b = text.as_bytes();
    let mut pieces = Vec::new();
    let mut start = 0;
    let mut at = target;
    while at < b.len() {
        match b[at..].iter().position(|&c| c == b'\n') {
            Some(k) => {
                let nl = at + k;
                if nl > start && matches!(b[nl - 1], b'}' | b';') && nl + 1 < b.len() {
                    pieces.push((start, nl + 1));
                    start = nl + 1;
                    at = start + target;
                } else {
                    at = nl + 1;
                }
            }
            None => break,
        }
    }
    pieces.push((start, b.len()));
    Some(pieces)
}

/// True when a piece lexed from `text[..b]` of a file of length `len` may
/// join its neighbors: the last piece always may; any other must end with
/// its own `}` or `;` right before the newline at its end. Then the serial
/// lexer is between tokens there too, in its start state, and no token or
/// lookahead crosses the cut.
fn piece_cut_ok(lexed: &lexer::Lexed, b: usize, len: usize) -> bool {
    let n = lexed.tokens.len();
    b == len
        || (n >= 2
            && matches!(lexed.tokens[n - 2].tok, lexer::Tok::RBrace | lexer::Tok::Semi)
            && lexed.tokens[n - 2].span.hi as usize == b - 1)
}

/// Lexes one file. A big file lexes in parallel pieces (`route_pieces`)
/// that join into exactly the tokens and string table of one serial lex;
/// when any piece fails its cut check or does not lex, the serial lex
/// runs, so errors are the serial ones.
fn lex_file(text: &str, file: FileId, interner: &Interner) -> Result<lexer::Lexed, Diag> {
    if let Some(pieces) = route_pieces(text) {
        let parts = par_map(&pieces, |&(a, b)| {
            let l = lexer::lex(&text[a..b], file, a as u32, interner).ok()?;
            piece_cut_ok(&l, b, text.len()).then_some(l)
        });
        if let Some(parts) = parts.into_iter().collect::<Option<Vec<_>>>() {
            return Ok(join_lexed(parts));
        }
    }
    lexer::lex(text, file, 0, interner)
}

/// Joins piece lexes in order: one final `Eof`, and string-table indexes
/// (`Tok::shift_strings`) moved past the strings of earlier pieces.
fn join_lexed(parts: Vec<lexer::Lexed>) -> lexer::Lexed {
    let mut out = lexer::Lexed { tokens: Vec::with_capacity(parts.iter().map(|p| p.tokens.len()).sum()), strings: Vec::new() };
    let last = parts.len() - 1;
    for (k, mut part) in parts.into_iter().enumerate() {
        let base = out.strings.len() as u32;
        if k < last {
            part.tokens.pop();
        }
        out.tokens.extend(part.tokens.into_iter().map(|mut t| {
            t.tok.shift_strings(base);
            t
        }));
        out.strings.append(&mut part.strings);
    }
    out
}

/// Item-aligned ranges of a file's parse stream (its expanded tokens when it
/// has macros) for parsing one big file in parallel (one-shot resolves
/// only; see the parse phase). A cut sits between a `}` or `;` at bracket
/// depth zero and a token that `starts_item` says can only begin an item
/// there. Cutting stops at the first unbalanced closer.
///
/// Why a segment parse equals the parse in place (`parser::parse_items`):
/// expansion runs on the whole file before this, so no macro is left to
/// expand across a cut; a `;` or `}` at depth zero followed by an item start
/// ends an item, so every range holds whole items, and an item parse reads
/// only its own tokens; between items the parser keeps no state but a
/// deferred error, which fails its segment. Any segment error makes the
/// caller parse the whole file again, so a cut never changes a diagnostic.
///
/// One range for a file under about 200 KB (the parse phase already runs
/// files in parallel, and segments of a small file would only nest), and
/// for a file with an inner attribute anywhere (`#` then `!` as tokens):
/// strip reads a file-level cfg from the first item, and the parser takes
/// `#!` only before any item.
fn item_segments(toks: &[lexer::Token], interner: &Interner) -> Vec<std::ops::Range<usize>> {
    use crate::lexer::Tok;
    const MIN_SEGMENT: usize = 4096;
    if toks.len() < 16 * MIN_SEGMENT || toks.windows(2).any(|w| w[0].tok == Tok::Pound && w[1].tok == Tok::Bang) {
        return vec![0..toks.len()];
    }
    let union = interner.intern("union");
    let target = (toks.len() / (crate::pool::threads() * 4)).max(MIN_SEGMENT);
    let mut out = Vec::new();
    let (mut start, mut depth) = (0usize, 0i64);
    for i in 0..toks.len().saturating_sub(1) {
        match toks[i].tok {
            Tok::LParen | Tok::LBracket | Tok::LBrace => depth += 1,
            Tok::RParen | Tok::RBracket | Tok::RBrace => depth -= 1,
            _ => {}
        }
        if depth < 0 {
            break;
        }
        if depth == 0 && i + 1 - start >= target && matches!(toks[i].tok, Tok::RBrace | Tok::Semi) && starts_item(toks, i + 1, union) {
            out.push(start..i + 1);
            start = i + 1;
        }
    }
    out.push(start..toks.len());
    out
}

/// True when `toks[i]` can only begin an item where `item_segments` cuts:
/// right after a `}` or `;` at bracket depth zero of a file's top level.
/// Rule for this list: a token may enter it only if it cannot continue a
/// top-level item there. An item goes on after such a `}` only inside a
/// `const` or `static` value (`= { 1 } + 2;`), where none of these can come
/// next. A missing start only loses a cut.
fn starts_item(toks: &[lexer::Token], i: usize, union: Sym) -> bool {
    use crate::lexer::Tok;
    let next = toks.get(i + 1).map(|t| t.tok);
    match toks[i].tok {
        Tok::Pound
        | Tok::Pub
        | Tok::Fn
        | Tok::Struct
        | Tok::Enum
        | Tok::Impl
        | Tok::Trait
        | Tok::Mod
        | Tok::Use
        | Tok::Const
        | Tok::Static
        | Tok::Type
        | Tok::Extern
        | Tok::Unsafe
        | Tok::Async => true,
        // `union U` (a contextual keyword), and a macro call `name!` or `path::name!`.
        Tok::Ident(s) => (s == union && matches!(next, Some(Tok::Ident(_)))) || is_macro_call(toks, i),
        Tok::SelfUpper | Tok::Crate | Tok::Super | Tok::SelfLower | Tok::PathSep => is_macro_call(toks, i),
        _ => false,
    }
}

/// True when `toks[i..]` is a macro call head: a path (`a::b`, a leading
/// `::` allowed) then `!`.
fn is_macro_call(toks: &[lexer::Token], mut i: usize) -> bool {
    use crate::lexer::Tok;
    if toks.get(i).map(|t| t.tok) == Some(Tok::PathSep) {
        i += 1;
    }
    loop {
        if !matches!(toks.get(i).map(|t| t.tok), Some(Tok::Ident(_) | Tok::SelfUpper | Tok::Crate | Tok::Super | Tok::SelfLower)) {
            return false;
        }
        match toks.get(i + 1).map(|t| t.tok) {
            Some(Tok::Bang) => return true,
            Some(Tok::PathSep) => i += 2,
            _ => return false,
        }
    }
}

/// The lexed form of `needs_resolve`, for callers that already lexed.
pub fn needs_resolve_lexed(lexed: &lexer::Lexed, interner: &Interner) -> bool {
    route_keywords(lexed, interner) || NestedFnScan::default().feed(&lexed.tokens)
}

/// The token-local part of `needs_resolve_lexed`: each token with a few
/// after it decides, so a big file's pieces answer it in parallel.
fn route_keywords(lexed: &lexer::Lexed, interner: &Interner) -> bool {
    use crate::lexer::Tok;
    // Symbols, not texts: this reads every identifier token of the root.
    let (macro_rules, include) = (interner.intern("macro_rules"), interner.intern("include"));
    let std_sym = interner.intern("std");
    let alloc_sym = interner.intern("alloc");
    let toks = &lexed.tokens;
    for (i, t) in toks.iter().enumerate() {
        match t.tok {
            Tok::Mod | Tok::Use | Tok::Static | Tok::Extern | Tok::Crate | Tok::Super => return true,
            // `pub(in self::m)`: only the resolver checks that the path
            // names an enclosing module (rustc E0433, E0742).
            Tok::In if i >= 2 && toks[i - 1].tok == Tok::LParen && toks[i - 2].tok == Tok::Pub => return true,
            Tok::PathSep => {
                // A leading `::` (not a segment join): the token before
                // it is not a path segment end.
                let prev = if i == 0 { None } else { Some(toks[i - 1].tok) };
                if !matches!(
                    prev,
                    Some(Tok::Ident(_)) | Some(Tok::SelfUpper) | Some(Tok::Gt) | Some(Tok::Crate) | Some(Tok::Super) | Some(Tok::SelfLower)
                ) {
                    return true;
                }
            }
            Tok::Const if matches!(toks.get(i + 1).map(|t| t.tok), Some(Tok::Ident(_)) | Some(Tok::Underscore)) => return true,
            Tok::Type => return true,
            // A root type named like a std prelude type or a primitive takes
            // a flat name only the resolver gives (`flat_name`).
            Tok::Struct | Tok::Enum | Tok::Trait
                if matches!(toks.get(i + 1).map(|t| t.tok), Some(Tok::Ident(s))
                    if PRELUDE_TYPES.contains(&interner.get(s)) || crate::ty::lang::is_primitive_type_name(interner.get(s))) =>
            {
                return true;
            }
            Tok::Pound => {
                // `#[cfg`, `#[cfg_attr`, `#[path`, `#[macro_use`, inner forms too.
                let mut j = i + 1;
                if toks.get(j).map(|t| t.tok) == Some(Tok::Bang) {
                    j += 1;
                }
                if toks.get(j).map(|t| t.tok) == Some(Tok::LBracket)
                    && let Some(Tok::Ident(s)) = toks.get(j + 1).map(|t| t.tok)
                    && matches!(interner.get(s), "cfg" | "cfg_attr" | "path" | "macro_use" | "macro_export" | "no_implicit_prelude")
                {
                    return true;
                }
            }
            Tok::Ident(s) if s == macro_rules => return true,
            // A path from `alloc`: only the resolver knows whether the
            // crate root links it (`extern crate alloc;`).
            Tok::Ident(s)
                if s == alloc_sym
                    && matches!(toks.get(i + 1).map(|t| t.tok), Some(Tok::PathSep))
                    && (i == 0 || toks[i - 1].tok != Tok::PathSep) =>
            {
                return true;
            }
            // `std::io::..` and the other platform modules: their items
            // live in the shipped platform crate, which only the
            // worklist loads (W-SHIM).
            Tok::Ident(s)
                if s == std_sym
                    && matches!(toks.get(i + 1).map(|t| t.tok), Some(Tok::PathSep))
                    && match toks.get(i + 2).map(|t| t.tok) {
                        Some(Tok::Ident(m)) => {
                            // `std::env::args` (and its `Args` type) and
                            // `std::process::exit` keep the compiler's std
                            // handling: no route change.
                            let item = match (toks.get(i + 3).map(|t| t.tok), toks.get(i + 4).map(|t| t.tok)) {
                                (Some(Tok::PathSep), Some(Tok::Ident(n))) => interner.get(n),
                                _ => "",
                            };
                            match interner.get(m) {
                                "env" => !matches!(item, "args" | "Args"),
                                "process" => !matches!(item, "exit" | "abort"),
                                // They return `io::Result`: `std::io::Error` is
                                // in the platform crate (mentions_std_platform).
                                "thread" => matches!(item, "available_parallelism" | "Builder"),
                                m => super::imports::STD_PLATFORM_MODULES.contains(&m),
                            }
                        }
                        Some(Tok::LBrace) => true,
                        _ => false,
                    } =>
            {
                return true;
            }
            // An `include!` can introduce items and macro definitions
            // other chunks would not see (added for W-MACRO).
            Tok::Ident(s) if s == include && matches!(toks.get(i + 1).map(|t| t.tok), Some(Tok::Bang)) => return true,
            _ => {}
        }
    }
    false
}

/// Finds a `fn` item inside the body of a fn of a generic item (`fn
/// f<T>() { fn g() {} }`, or a method of `impl<T>`): the resolver rejects
/// a path in it to an outer generic param (rustc E0401), which otherwise
/// reads the module item that the param shadows. Also finds an `impl` or
/// `trait` item inside any fn body: only the resolver hoists a block impl
/// to its module's items (`hoist_block_impls`). A brace stack over the
/// whole file's tokens, fed in order (a big file's pieces one by one).
#[derive(Default)]
struct NestedFnScan {
    /// Per open brace: (a fn body, inside a generic item).
    stack: Vec<(bool, bool)>,
    fn_pending: bool,
    generic_pending: bool,
}

impl NestedFnScan {
    /// Scans the next tokens; true once a nested fn in a generic item is found.
    fn feed(&mut self, toks: &[lexer::Token]) -> bool {
        use crate::lexer::Tok;
        for (i, t) in toks.iter().enumerate() {
            let next = |k: usize| toks.get(i + k).map(|t| t.tok);
            match t.tok {
                Tok::Fn if matches!(next(1), Some(Tok::Ident(_))) => {
                    if self.stack.iter().any(|&(body, _)| body) && self.stack.last().is_some_and(|&(_, g)| g) {
                        return true;
                    }
                    self.fn_pending = true;
                    self.generic_pending |= next(2) == Some(Tok::Lt);
                }
                // An item `impl` or `trait` in a body: the token before
                // it ends a statement or an attribute (`impl Trait` types
                // follow `:`, `->`, `<`, `(`, `,`, or `&`).
                Tok::Impl | Tok::Trait
                    if self.stack.iter().any(|&(body, _)| body)
                        && (i == 0 || matches!(toks[i - 1].tok, Tok::LBrace | Tok::RBrace | Tok::Semi | Tok::RBracket | Tok::RParen | Tok::Unsafe | Tok::Pub)) =>
                {
                    return true;
                }
                Tok::Impl if next(1) == Some(Tok::Lt) => self.generic_pending = true,
                Tok::Trait if next(2) == Some(Tok::Lt) => self.generic_pending = true,
                Tok::Semi => (self.fn_pending, self.generic_pending) = (false, false),
                Tok::LBrace => {
                    let outer = self.stack.last().is_some_and(|&(_, g)| g);
                    self.stack.push((self.fn_pending, self.generic_pending || outer));
                    (self.fn_pending, self.generic_pending) = (false, false);
                }
                Tok::RBrace => {
                    self.stack.pop();
                }
                _ => {}
            }
        }
        false
    }
}

/// One file during resolution, or one item segment of a big file (see
/// `item_segments`): the segments of a file are adjacent works, and every
/// step treats a segment as a list of whole items of that file.
struct FileWork {
    path: PathBuf,
    file_id: FileId,
    ast: Ast,
    /// The module this file's top-level items belong to.
    module: ModuleId,
    /// The segment's index in its file; 0 for an unsegmented file.
    segment: usize,
    /// The `ResolveCache` key and text hash of this file, for the
    /// final-chunk lookup and store at flatten time.
    key: String,
    text_hash: u64,
    /// The hash of the expanded token stream this Ast came from:
    /// a final-chunk hit needs it to stand too, because a macro
    /// environment change can move bodies without moving the
    /// rewrite epoch.
    exp_hash: u64,
}

/// The key under which a module's item list is later found in the walks:
/// the file that holds it, plus the inline module name path inside it.
type ItemListKey = (usize, Vec<Sym>);

/// The expander cfg environment for one crate session: the resolver
/// facts of section 1.6 in the expander's fact form.
pub(crate) fn expand_cfg(env: &CfgEnv) -> crate::expand::builtin::CfgEnv {
    let mut facts: Vec<(String, Option<String>)> = Vec::new();
    for f in &env.flags {
        facts.push((f.clone(), None));
    }
    for (n, v) in &env.pairs {
        facts.push((n.clone(), Some(v.clone())));
    }
    for f in &env.features {
        facts.push(("feature".to_string(), Some(f.clone())));
    }
    crate::expand::builtin::CfgEnv { test: env.flags.contains("test"), debug_assertions: env.flags.contains("debug_assertions"), facts, panic_unwind: false }
}

/// Evaluates every `#[cfg]`/`#[cfg_attr]` predicate and `cfg!` call in
/// one lexed file against the crate env, for the unknown-name error
/// alone (L0520): expansion strips cfg items with its own evaluator
/// before the parse-time strip below could see them, so an unknown
/// name must be caught here or it would silently drop the item.
/// Macro definition bodies are skipped: their tokens are templates,
/// not item attributes yet.
pub(crate) fn check_cfg_names(lexed: &lexer::Lexed, env: &CfgEnv, interner: &Interner) -> Result<(), Diag> {
    use crate::lexer::Tok;
    let toks = &lexed.tokens;
    // Symbols, not texts, per token: this scans every token of the crate.
    let (macro_rules, cfg) = (interner.intern("macro_rules"), interner.intern("cfg"));
    let mut i = 0;
    while i < toks.len() {
        // Skip a macro_rules body (one delimited group after the name).
        if toks[i].tok == Tok::Ident(macro_rules) && toks.get(i + 1).map(|t| t.tok) == Some(Tok::Bang) {
            i += 2;
            // Optional macro name, then the delimited body.
            if matches!(toks.get(i).map(|t| t.tok), Some(Tok::Ident(_))) {
                i += 1;
            }
            if let Some(open) = toks.get(i).map(|t| t.tok) {
                let close = match open {
                    Tok::LParen => Tok::RParen,
                    Tok::LBracket => Tok::RBracket,
                    Tok::LBrace => Tok::RBrace,
                    _ => Tok::Eof,
                };
                let mut depth = 0usize;
                while i < toks.len() {
                    if toks[i].tok == open {
                        depth += 1;
                    } else if toks[i].tok == close {
                        depth -= 1;
                        if depth == 0 {
                            i += 1;
                            break;
                        }
                    } else if toks[i].tok == Tok::Eof {
                        break;
                    }
                    i += 1;
                }
            }
            continue;
        }
        // `#[cfg(...)]` and `#[cfg_attr(pred, ...)]`.
        if toks[i].tok == Tok::Pound {
            let mut j = i + 1;
            if toks.get(j).map(|t| t.tok) == Some(Tok::Bang) {
                j += 1;
            }
            if toks.get(j).map(|t| t.tok) == Some(Tok::LBracket) {
                if let Some(Tok::Ident(s)) = toks.get(j + 1).map(|t| t.tok) {
                    let name = interner.get(s);
                    if (name == "cfg" || name == "cfg_attr") && toks.get(j + 2).map(|t| t.tok) == Some(Tok::LParen) {
                        // Trees inside the parens; for cfg_attr only
                        // the part before the first top-level comma.
                        let mut depth = 0usize;
                        let mut end = toks.len();
                        for k in j + 2..toks.len() {
                            match toks[k].tok {
                                Tok::LParen => depth += 1,
                                Tok::RParen => {
                                    depth -= 1;
                                    if depth == 0 {
                                        end = k;
                                        break;
                                    }
                                }
                                Tok::Eof => break,
                                _ => {}
                            }
                        }
                        let mut trees = scan::outline_trees(&toks[j + 3..end]);
                        if name == "cfg_attr" {
                            if let Some(comma) =
                                trees.iter().position(|t| matches!(t, crate::lexer::TokenTree::Token(t) if t.tok == Tok::Comma))
                            {
                                trees.truncate(comma);
                            }
                        }
                        env.eval(&trees, &lexed.strings, interner, toks[i].span)?;
                    }
                }
            }
        }
        // `cfg!(...)` in expression position.
        if toks[i].tok == Tok::Ident(cfg)
            && toks.get(i + 1).map(|t| t.tok) == Some(Tok::Bang)
            && toks.get(i + 2).map(|t| t.tok) == Some(Tok::LParen)
        {
            let mut depth = 0usize;
            let mut end = toks.len();
            for k in i + 2..toks.len() {
                match toks[k].tok {
                    Tok::LParen => depth += 1,
                    Tok::RParen => {
                        depth -= 1;
                        if depth == 0 {
                            end = k;
                            break;
                        }
                    }
                    Tok::Eof => break,
                    _ => {}
                }
            }
            let trees = scan::outline_trees(&toks[i + 3..end]);
            env.eval(&trees, &lexed.strings, interner, toks[i].span)?;
        }
        i += 1;
    }
    Ok(())
}

/// Builds a source map from discovered (path, text, file id) triples: an id no triple has
/// gets an empty file, and of two triples with one id the map keeps the first (the text
/// keeps both). The files' line indexes are made on the pool (`SourceMap::with_texts`).
fn make_map(seen: &[(PathBuf, String, FileId)]) -> (SourceMap, String) {
    let mut sorted: Vec<&(PathBuf, String, FileId)> = seen.iter().collect();
    sorted.sort_by_key(|(_, _, f)| f.0);
    let mut files: Vec<(String, &str)> = Vec::with_capacity(sorted.len());
    let mut all = String::with_capacity(sorted.iter().map(|(_, text, _)| text.len() + 1).sum());
    for (path, text, file_id) in sorted {
        while (files.len() as u32) < file_id.0 {
            files.push((String::new(), ""));
        }
        if files.len() as u32 == file_id.0 {
            files.push((path.to_string_lossy().into_owned(), text));
        }
        all.push_str(text);
        all.push('\n');
    }
    (SourceMap::with_texts(&files), all)
}

/// Per-file front-end cache for one crate session (W-DRIVER phase 2):
/// the raw and expanded token streams and the outline of every file
/// whose text is unchanged since the last request. An edit to one
/// file re-lexes and re-expands only that file; parsing still reruns
/// per file (the Ast is not cloneable today), in parallel across
/// files, and the path rewrite pass runs in parallel too. Entries key
/// on canonical path plus module (the same file can serve two
/// modules) and carry the `FileId` their spans were lexed with: a
/// file set change that renumbers files misses cleanly instead of
/// reusing spans that name the wrong file. The cfg environment
/// fingerprints the whole cache: expansion answers depend on it.
/// Decided with W-RESOLVE through the `iface:` commit that added
/// `resolve_crate_cached`.
#[derive(Default)]
pub struct ResolveCache {
    env_fp: u64,
    files: FxMap<String, CachedFile>,
    /// Canonical path strings by written path: canonicalizing is a
    /// filesystem call per path, and discovery asks for every file
    /// on every request.
    canon: FxMap<PathBuf, String>,
    /// Set for a one-shot process, which compiles once: no later request
    /// reads the cache, so it stores nothing (no copies of token streams
    /// or final chunks), and the resolve skips the expanded-stream
    /// hashes that only key those entries.
    one_shot: bool,
    /// A root token list from routing (`seed_root`), stored by `begin`
    /// after its environment check: (key, text hash, tokens).
    seed: Option<(String, u64, lexer::Lexed)>,
    /// Counts the expansions stored (`put_expanded`, `begin`'s clear): a
    /// reader that saw this value when it read a file's expansion knows
    /// the entry is still that expansion while the value stands.
    expansions: u64,
    /// Counts resolves (`begin`): `file_expander` is the last one's only
    /// when its own count matches.
    resolves: u64,
    /// The local crate's per-file expander from the last resolve that
    /// got past expansion (see `FileExpander`).
    file_expander: Option<std::sync::Arc<FileExpander>>,
    /// This request's raw streams, unpacked on the pool before discovery takes them one
    /// file at a time (`unpack_raw`, `raw`): key, text hash, file id, stream. Empty between
    /// requests.
    unpacked: FxMap<String, (u64, FileId, lexer::Lexed)>,
    /// During a resolve: the session's merged Ast and the resolve that made it
    /// (`set_merged`), which a stored final chunk is taken back out of
    /// (`FinalChunk::at`).
    merged: Option<(std::sync::Arc<Ast>, u64)>,
}

impl ResolveCache {
    /// Hands the cache the session's merged Ast and its `ResolvedCrate::generation` before a resolve:
    /// the final chunks it stores are parts of that Ast (`FinalChunk::at`), not copies. The
    /// resolve lets go of it at its end, so the session can patch the Ast in place.
    pub fn set_merged(&mut self, ast: std::sync::Arc<Ast>, generation: u64) {
        self.merged = Some((ast, generation));
    }

    /// Every path an earlier resolve read (`canon`'s keys): the next build's
    /// source prefetch (`prefetch::write_list`).
    pub fn source_paths(&self) -> impl Iterator<Item = &std::path::Path> {
        self.canon.keys().map(PathBuf::as_path)
    }

    /// Lets go of the merged Ast `set_merged` gave.
    pub fn clear_merged(&mut self) {
        self.merged = None;
    }

    /// Drops the final chunks a patch of `file` changes in the session's merged Ast: the
    /// file's own, or every chunk when nodes of other files hold its spans (`others`).
    pub fn forget_final(&mut self, file: FileId, others: bool) {
        for f in self.files.values_mut().filter(|f| others || f.file_id == file) {
            f.final_chunk = None;
        }
    }

    /// For `main::census`: (cached files, files whose expanded stream has the raw stream's
    /// tokens and strings, those files' raw token count).
    pub(crate) fn same_streams(&self) -> (usize, usize, usize) {
        let mut same = (0, 0);
        for f in self.files.values() {
            if let (Some(raw), Some(exp)) = (f.raw.as_ref().map(lexer::PackedLexed::unpack), f.expanded.as_ref().map(|e| e.1.unpack()))
                && raw.tokens.len() == exp.tokens.len()
                && raw.strings == exp.strings
                && raw.tokens.iter().zip(&exp.tokens).all(|(a, b)| a.tok == b.tok && a.span == b.span)
            {
                same.0 += 1;
                same.1 += raw.tokens.len();
            }
        }
        (self.files.len(), same.0, same.1)
    }

    /// For `main::census` (LUST_FRONT_CENSUS=1, a probe of a front image): drops one part of
    /// every cached file (0 raw tokens, 1 outline, 2 expanded tokens, 3 final chunk, 4 std
    /// asks), or with 5 the path table, the seed and the file expander.
    pub(crate) fn drop_part(&mut self, part: usize) {
        for f in self.files.values_mut() {
            match part {
                0 => drop(f.raw.take()),
                1 => drop(f.outline.take()),
                2 => drop(f.expanded.take()),
                3 => drop(f.final_chunk.take()),
                4 => drop(f.std_asks.take()),
                _ => {}
            }
        }
        if part == 5 {
            drop(std::mem::take(&mut self.canon));
            drop(self.seed.take());
            drop(self.file_expander.take());
        }
    }
}

/// `lexed` without the inner tokens of each fn body range in `blank`
/// (`{` through `}`, by bytes), for the body patch: only the body it
/// edits needs its expansion, and what the expander does in one fn body
/// reaches no other (a body's macros, `use`s and items are its block's).
/// A range blanks only when it is one `{ .. }` group of `text` (a hidden
/// fn that holds a hoisted `static` init closure has a body span that is
/// not), and three things keep a body: a `macro_rules!` or
/// `macro_export` in it (a `#[macro_export]` definition in a body is
/// visible by path from anywhere), and a body inside a macro call's input
/// (the macro reads its tokens).
fn blank_bodies(lexed: lexer::Lexed, blank: &[(u32, u32)], text: &str) -> lexer::Lexed {
    use crate::lexer::Tok;
    if blank.is_empty() {
        return lexed;
    }
    // Byte ranges of macro call inputs (`name!` then a group), and of
    // every `{ .. }` group by its `{` start.
    let toks = &lexed.tokens;
    let mut calls: Vec<(u32, u32)> = Vec::new();
    let mut braces: FxMap<u32, u32> = FxMap::default();
    let mut open: Vec<(usize, bool)> = Vec::new();
    for (i, t) in toks.iter().enumerate() {
        match t.tok {
            Tok::LParen | Tok::LBracket | Tok::LBrace => {
                let call = i >= 2 && toks[i - 1].tok == Tok::Bang && matches!(toks[i - 2].tok, Tok::Ident(_));
                open.push((i, call));
            }
            Tok::RParen | Tok::RBracket | Tok::RBrace => {
                if let Some((o, call)) = open.pop() {
                    if call {
                        calls.push((toks[o].span.lo, t.span.hi));
                    }
                    if toks[o].tok == Tok::LBrace && t.tok == Tok::RBrace {
                        braces.insert(toks[o].span.lo, t.span.hi);
                    }
                }
            }
            _ => {}
        }
    }
    // Only an exact `{ .. }` group of this text blanks.
    let keep_body = |&(lo, hi): &(u32, u32)| {
        let inner = text.get(lo as usize..hi as usize).unwrap_or("macro_rules");
        braces.get(&lo) != Some(&hi) || inner.contains("macro_rules") || inner.contains("macro_export") || calls.iter().any(|&(a, b)| a <= lo && hi <= b)
    };
    let ranges: Vec<(u32, u32)> = blank.iter().copied().filter(|r| !keep_body(r)).collect();
    let mut k = 0;
    let tokens = lexed
        .tokens
        .into_iter()
        .filter(|t| {
            while k < ranges.len() && ranges[k].1 <= t.span.lo {
                k += 1;
            }
            // Inside: after the `{` and before the `}`.
            !(k < ranges.len() && ranges[k].0 < t.span.lo && t.span.hi < ranges[k].1)
        })
        .collect();
    lexer::Lexed { tokens, strings: lexed.strings }
}

/// What the body patch needs to expand one file of the local crate again
/// as the full resolve's last expansion round did (driver/patch.rs): that
/// round's macro environment and the expander's per-file inputs. A body
/// edit changes neither (it defines no macro and no module), so the new
/// text expands under them as a cold resolve would expand it.
pub struct FileExpander {
    /// `ResolveCache::resolves` of the resolve that built it.
    resolve: u64,
    menv: MacroEnv,
    magic: Sym,
    env: CfgEnv,
    cargo_env: Vec<(String, String)>,
    crate_name: String,
    display_root: Option<PathBuf>,
    /// Per file: its index in `menv`'s per-file tables, module path, and path.
    files: FxMap<FileId, (usize, Vec<Sym>, PathBuf)>,
}

impl FileExpander {
    /// The expansion of `text` as the new text of `file` (raw lex, textual
    /// splice, seeded expansion with the dependency record), as the
    /// resolve's expansion round runs it. None for a file it does not
    /// know (another crate's). `blank` holds byte ranges of `{ .. }` fn
    /// bodies (sorted, disjoint) whose inner tokens go before expansion
    /// (see `blank_bodies`).
    pub fn expand(
        &self,
        file: FileId,
        text: &str,
        blank: &[(u32, u32)],
        interner: &Interner,
        known: &Known,
        client: &crate::expand::ClientView,
    ) -> Option<Result<(lexer::Lexed, Vec<crate::expand::Dep>), Diag>> {
        let (di, module_path, path) = self.files.get(&file)?;
        let lexed = match lex_file(text, file, interner) {
            Ok(l) => blank_bodies(l, blank, text),
            Err(d) => return Some(Err(d)),
        };
        let ects = crate::expand::ExpandCtx {
            interner,
            known,
            file_path: match self.display_root.as_deref().and_then(|r| path.strip_prefix(r).ok()) {
                Some(rel) => rel.to_string_lossy().to_string(),
                None => path.to_string_lossy().to_string(),
            },
            real_path: path.clone(),
            cargo_env: self.cargo_env.clone(),
            src: text,
            cfg: expand_cfg(&self.env),
            module_path: module_path.clone(),
            crate_name: Some(self.crate_name.clone()),
            extern_crates: self.menv.extern_crates(interner),
            client,
        };
        let spliced = self.menv.splice(*di, lexed, self.magic);
        let extra = self.menv.glob_seeds.get(*di).map_or(&[][..], Vec::as_slice);
        Some(crate::expand::expand_lexed_seeded_extra(spliced, &ects, &self.menv.seeds, extra))
    }

    /// The cfg environment the expansions ran under.
    pub fn env(&self) -> &CfgEnv {
        &self.env
    }

    /// True when the textual splice of `file` puts definitions after an
    /// item at or past byte `at` (a `#[macro_use]` module): an edit before
    /// it moves the offset the splice finds the item by.
    pub fn splices_after(&self, file: FileId, at: u32) -> bool {
        let Some((di, _, _)) = self.files.get(&file) else { return true };
        self.menv.after_mods.get(*di).is_some_and(|a| a.iter().any(|(lo, _, _)| *lo >= at))
    }
}

struct CachedFile {
    text_hash: u64,
    file_id: FileId,
    /// The raw (unexpanded) token stream. Discovery outlines it and
    /// reads cfg strings from it; the parse phase starts from it.
    raw: Option<lexer::PackedLexed>,
    /// The outline scanned from `raw`.
    outline: Option<scan::Outline>,
    /// The expanded token stream the parser consumes (cfg-name
    /// checking and expansion already applied to `raw`), with the
    /// hash of every other input that expansion read
    /// (`expansion_input_hash`) and the outside reads it recorded (a
    /// hit stands while they read the same, `expand::deps_stale_in`).
    expanded: Option<(u64, lexer::PackedLexed, Vec<crate::expand::Dep>, u64)>,
    /// What the file asks of std, with the length of the text it was
    /// read from (`ResolveCache::std_asks`).
    std_asks: Option<(usize, StdPlan)>,
    /// The file's flattened, rewritten chunk plus its per-fn facts
    /// and structural scan, from a successful resolve. Valid only
    /// under the epoch it was stored with (see
    /// `ResolvedTables::rewrite_epoch`): strip, register, and the
    /// import fixpoint still run each request to rebuild the
    /// tables and the epoch, but the rewrite walk, the flatten,
    /// and the Ast scan for this file are skipped on a hit.
    final_chunk: Option<FinalChunk>,
    /// The `use` sites of `raw` (`MacroEnv::build`) and the module path they were scanned
    /// under: a function of the tokens and that path alone (`scan_use_sites` reads no cfg and
    /// no macro).
    use_sites: Option<(Vec<Sym>, std::sync::Arc<[UseSite]>)>,
}

/// One file's post-rewrite, post-flatten chunk, as cached in
/// `CachedFile::final_chunk`.
#[derive(Clone)]
struct FinalChunk {
    epoch: u64,
    exp_hash: u64,
    /// Where the chunk sits in the merged Ast resolve number `generation` made (`resolves`),
    /// which the next merge copies a hit from (`ChunkPart::Old`, `ResolveCache::merged`): the
    /// session keeps that Ast anyway, so the cache keeps no copy. A chunk stored by a resolve
    /// that did not finish has `generation` 0 and is no hit.
    at: crate::ast::ChunkSpan,
    generation: u64,
    fn_lines: Vec<u32>,
    body_hashes: Vec<u64>,
    nested_lines: Vec<u32>,
    nested_hashes: Vec<u64>,
    /// Each top-level fn's module as a name path (module ids are
    /// request local; paths are not).
    fn_module_paths: Vec<Vec<Sym>>,
    /// Each nested fn's module as a name path.
    nested_module_paths: Vec<Vec<Sym>>,
    /// This file's structure hash: its path text plus its `mod`,
    /// `use`, and `extern crate` items (`structure_items`).
    structure: u64,
    scan_items: Vec<scan::ItemScan>,
    /// Top-level fn body scans, then nested fn body scans, kept
    /// apart because the merged order puts every nested fn after
    /// every top-level fn (collect's order).
    scan_bodies: Vec<(u64, Vec<Sym>)>,
    nested_bodies: Vec<(u64, Vec<Sym>)>,
    /// What the rewrite read, with each answer then (resolve/mdr.rs): the
    /// chunk stands while those answers do (B3 step 3).
    deps: Option<crate::resolve::mdr::ChunkDeps>,
}

impl FinalChunk {
    /// A copy for a cache hit; the recorded reads only when `deps` (the
    /// observation reads them), as a hit stores nothing back.
    fn clone_for_hit(&self, deps: bool) -> FinalChunk {
        FinalChunk {
            epoch: self.epoch,
            exp_hash: self.exp_hash,
            at: self.at,
            generation: self.generation,
            fn_lines: self.fn_lines.clone(),
            body_hashes: self.body_hashes.clone(),
            nested_lines: self.nested_lines.clone(),
            nested_hashes: self.nested_hashes.clone(),
            fn_module_paths: self.fn_module_paths.clone(),
            nested_module_paths: self.nested_module_paths.clone(),
            structure: self.structure,
            scan_items: self.scan_items.clone(),
            scan_bodies: self.scan_bodies.clone(),
            nested_bodies: self.nested_bodies.clone(),
            deps: if deps { self.deps.clone() } else { None },
        }
    }
}

/// The cfg-environment fingerprint a cache's entries were built under.
fn env_fingerprint(input: &CrateInput) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = crate::intern::FxHasher::default();
    "resolve-cache-env-v1".hash(&mut h);
    for f in &input.env.flags {
        f.hash(&mut h);
    }
    for (n, v) in &input.env.pairs {
        n.hash(&mut h);
        v.hash(&mut h);
    }
    for f in &input.env.features {
        f.hash(&mut h);
    }
    for n in &input.env.custom_names {
        n.hash(&mut h);
    }
    input.env.allow_lust_dev.hash(&mut h);
    // Cargo env values, per-dependency build script cfg outputs, and
    // each dependency's own selection (features, edition, lib root):
    // a `rustc-cfg` or feature change re-expands a dependency's files,
    // so the fingerprint must move (a path dependency's `default` feature
    // edit kept its old `cfg!(feature)` answers, w-daemon-sound).
    for (k, v) in &input.cargo_env {
        k.hash(&mut h);
        v.hash(&mut h);
    }
    fn dep_fp(deps: &[super::cargo::DepUnit], h: &mut crate::intern::FxHasher) {
        use std::hash::Hash;
        for d in deps {
            d.package_id.hash(h);
            (&d.extern_name, &d.lib_name, &d.lib_src, &d.edition, &d.features).hash(h);
            for (k, v) in &d.cargo_env {
                k.hash(h);
                v.hash(h);
            }
            d.build_cfgs.hash(h);
            d.build_check_cfgs.hash(h);
            dep_fp(&d.deps, h);
        }
    }
    dep_fp(&input.deps, &mut h);
    input.crate_ids.stable.0.hash(&mut h);
    // `file!` text: a shown root change re-expands every file. (The
    // client env is not here: an expansion that read env keeps the
    // values it saw, and a hit needs them to stand, `deps_stale_in`.)
    input.client.shown_root.hash(&mut h);
    // `file!()` expands relative to it.
    input.display_root.hash(&mut h);
    h.finish()
}

impl ResolveCache {
    /// An empty cache; `one_shot` for a process that compiles once.
    pub fn new(one_shot: bool) -> ResolveCache {
        ResolveCache { one_shot, ..ResolveCache::default() }
    }

    /// Holds a crate root's raw token list, lexed by routing, for
    /// discovery: the root is the first file (file 0) of the root module.
    /// A later text edit or a std splice misses on the text hash.
    pub fn seed_root(&mut self, root_path: &std::path::Path, text: &str, lexed: lexer::Lexed) {
        let key = format!("{}#{}", modules::canonical_string(root_path), ROOT_MODULE.0);
        self.seed = Some((key, hash_str(text), lexed));
    }

    /// Drops every entry when the cfg environment changed, then stores a
    /// seeded root token list (raw tokens do not depend on cfg; a one-shot
    /// cache stores this one entry, which discovery moves out).
    fn begin(&mut self, input: &CrateInput) {
        let fp = env_fingerprint(input);
        if self.env_fp != fp {
            self.env_fp = fp;
            self.files.clear();
            self.expansions += 1;
        }
        self.resolves += 1;
        if let Some((key, text_hash, lexed)) = self.seed.take() {
            self.entry(&key, text_hash, FileId(0)).raw = Some(lexer::PackedLexed::pack(&lexed));
        }
    }

    /// The canonical string of one path, memoized for the session.
    fn canon(&mut self, path: &std::path::Path) -> String {
        self.canon.entry(path.to_path_buf()).or_insert_with(|| modules::canonical_string(path)).clone()
    }

    fn entry(&mut self, key: &str, text_hash: u64, file_id: FileId) -> &mut CachedFile {
        let fresh =
            || CachedFile { text_hash, file_id, raw: None, outline: None, expanded: None, std_asks: None, final_chunk: None, use_sites: None };
        let e = self.files.entry(key.to_string()).or_insert_with(fresh);
        if e.text_hash != text_hash || e.file_id != file_id {
            *e = fresh();
        }
        e
    }

    /// The valid entry for one file, when present, without
    /// allocating the key string (read accessors use this; a stale
    /// entry reads as absent and the next put resets it).
    fn peek(&self, key: &str, text_hash: u64, file_id: FileId) -> Option<&CachedFile> {
        self.files.get(key).filter(|e| e.text_hash == text_hash && e.file_id == file_id)
    }

    /// The cached raw token stream for one file, when its text and file
    /// id stand: unpacked (the cache keeps streams packed, `PackedLexed`,
    /// as a front image saves and restores the cache every build).
    fn raw(&mut self, key: &str, text_hash: u64, file_id: FileId) -> Option<lexer::Lexed> {
        if let Some((h, f, l)) = self.unpacked.remove(key)
            && h == text_hash
            && f == file_id
        {
            return Some(l);
        }
        let one_shot = self.one_shot;
        let e = self.files.get_mut(key).filter(|e| e.text_hash == text_hash && e.file_id == file_id)?;
        if one_shot { e.raw.take().map(|p| p.unpack()) } else { e.raw.as_ref().map(lexer::PackedLexed::unpack) }
    }

    /// Unpacks every stored raw stream on the pool, for this request's discovery (`raw`).
    fn unpack_raw(&mut self) {
        let stored: Vec<(&String, &CachedFile)> = self.files.iter().filter(|(_, e)| e.raw.is_some()).collect();
        let streams = par_map(&stored, |(_, e)| e.raw.as_ref().map(lexer::PackedLexed::unpack));
        self.unpacked = stored.iter().zip(streams).filter_map(|((k, e), l)| Some(((*k).clone(), (e.text_hash, e.file_id, l?)))).collect();
    }

    /// Every put stores nothing in a one-shot cache (see `one_shot`).
    fn put_raw(&mut self, key: &str, text_hash: u64, file_id: FileId, lexed: &lexer::Lexed) {
        if !self.one_shot {
            self.entry(key, text_hash, file_id).raw = Some(lexer::PackedLexed::pack(lexed));
        }
    }

    /// What one file asks of std (`StdPlan::asks` of `own`, its text
    /// or the root's text before the splice), cached with its text,
    /// one-shot caches included: the asks are four bits.
    fn std_asks(&mut self, key: &str, text_hash: u64, file_id: FileId, own: &str) -> StdPlan {
        let len = own.len();
        if let Some((l, asks)) = self.peek(key, text_hash, file_id).and_then(|e| e.std_asks)
            && l == len
        {
            return asks;
        }
        let asks = StdPlan::asks(own);
        self.entry(key, text_hash, file_id).std_asks = Some((len, asks));
        asks
    }

    /// The cached outline for one file, when its text and file id stand.
    fn outline(&mut self, key: &str, text_hash: u64, file_id: FileId) -> Option<scan::Outline> {
        self.peek(key, text_hash, file_id).and_then(|e| e.outline.clone())
    }

    fn put_outline(&mut self, key: &str, text_hash: u64, file_id: FileId, outline: &scan::Outline) {
        if !self.one_shot {
            self.entry(key, text_hash, file_id).outline = Some(outline.clone());
        }
    }

    /// The cached `use` sites of one file's raw stream, when its text and file id stand and
    /// they were scanned under module path `path`.
    fn use_sites(&self, key: &str, text_hash: u64, file_id: FileId, path: &[Sym]) -> Option<std::sync::Arc<[UseSite]>> {
        match &self.peek(key, text_hash, file_id)?.use_sites {
            Some((p, sites)) if p.as_slice() == path => Some(sites.clone()),
            _ => None,
        }
    }

    fn put_use_sites(&mut self, key: &str, text_hash: u64, file_id: FileId, path: Vec<Sym>, sites: std::sync::Arc<[UseSite]>) {
        if !self.one_shot {
            self.entry(key, text_hash, file_id).use_sites = Some((path, sites));
        }
    }

    /// The cached expansion of one file whose other inputs hash to
    /// `input_hash` (`expansion_input_hash`) and whose outside reads are
    /// not `stale`, unpacked, with the stream's own `hash_lexed`.
    fn expanded(
        &self,
        key: &str,
        text_hash: u64,
        file_id: FileId,
        input_hash: u64,
        stale: &dyn Fn(&[crate::expand::Dep]) -> bool,
    ) -> Option<(std::sync::Arc<lexer::Lexed>, Vec<crate::expand::Dep>, u64)> {
        match self.peek(key, text_hash, file_id).and_then(|e| e.expanded.as_ref()) {
            Some((h, l, deps, exp_hash)) if *h == input_hash && !stale(deps) => Some((std::sync::Arc::new(l.unpack()), deps.clone(), *exp_hash)),
            _ => None,
        }
    }

    /// Stores one file's expansion, packed, with the stream's `hash_lexed`.
    #[allow(clippy::too_many_arguments)]
    fn put_expanded(&mut self, key: &str, text_hash: u64, file_id: FileId, input_hash: u64, stream: lexer::PackedLexed, exp_hash: u64, deps: &[crate::expand::Dep]) {
        self.expansions += 1;
        self.entry(key, text_hash, file_id).expanded = Some((input_hash, stream, deps.to_vec(), exp_hash));
    }

    /// The `expansions` count (see there).
    pub fn expansions(&self) -> u64 {
        self.expansions
    }

    /// The last resolve's `FileExpander`, when that resolve built one.
    pub fn file_expander(&self) -> Option<std::sync::Arc<FileExpander>> {
        self.file_expander.clone().filter(|x| x.resolve == self.resolves)
    }

    /// The stored expansion of the file lexed as `file_id` with text
    /// `text`, if any. The item patch takes an unchanged body's expanded
    /// tokens from it (driver/patch.rs `kept_body`).
    pub fn expansion_of(&self, file_id: FileId, text: &str) -> Option<lexer::Lexed> {
        let text_hash = hash_str(text);
        self.files.values().find(|e| e.file_id == file_id && e.text_hash == text_hash).and_then(|e| e.expanded.as_ref()).map(|e| e.1.unpack())
    }

    fn put_final(&mut self, key: &str, text_hash: u64, file_id: FileId, chunk: FinalChunk) {
        if !self.one_shot {
            self.entry(key, text_hash, file_id).final_chunk = Some(chunk);
        }
    }
}

/// A content hash of one expanded token stream: token kinds,
/// payloads, spans, and string contents. This keys a file's final
/// chunk (`FinalChunk::exp_hash`): expansion output is exactly what
/// the parser consumes, whatever macro environment produced it.
fn hash_lexed(l: &lexer::Lexed) -> u64 {
    hash_tokens(&l.tokens, &l.strings)
}

/// `hash_lexed` over a token list and its string table.
fn hash_tokens(tokens: &[crate::lexer::Token], strings: &[String]) -> u64 {
    use crate::lexer::Tok;
    use std::hash::{Hash, Hasher};
    let mut h = crate::intern::FxHasher::default();
    "expanded-v1".hash(&mut h);
    for s in strings {
        s.hash(&mut h);
    }
    for t in tokens {
        std::mem::discriminant(&t.tok).hash(&mut h);
        match t.tok {
            Tok::Ident(s) | Tok::Reserved(s) | Tok::Lifetime(s) => h.write_u64(s.0 as u64),
            Tok::Int(v, suffix, _) => {
                h.write_u128(v);
                std::mem::discriminant(&suffix).hash(&mut h);
            }
            Tok::Char(c, _) => h.write_u64(c as u64),
            _ => {}
        }
        // Strings, including a literal's written text.
        for i in t.tok.string_indices() {
            strings.get(i as usize).map_or("", String::as_str).hash(&mut h);
        }
        h.write_u64(t.span.file.0 as u64);
        h.write_u64(t.span.lo as u64);
        h.write_u64(t.span.hi as u64);
    }
    h.finish()
}

/// Hash of the expansion inputs every file of one round shares: the
/// seed facts every expansion reads (`expand::parser_name_facts`; the
/// seeds themselves key each file, `expansion_input_hash`), the extern
/// crate names, the crate's `$crate` magic, name, Cargo env, display
/// root, and the client's shown root (`file!`). The cfg environment
/// keys the whole `ResolveCache` already.
fn expansion_env_hash(menv: &MacroEnv, job: &CrateJob, input: &OneInput, client: &crate::expand::ClientView, interner: &Interner) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = crate::intern::FxHasher::default();
    "expansion-env-v2".hash(&mut h);
    crate::expand::parser_name_facts(&menv.seeds, interner).hash(&mut h);
    let mut externs: Vec<&String> = menv.dep_owned.keys().collect();
    externs.sort_unstable();
    externs.hash(&mut h);
    h.write_u64(job.magic.0 as u64);
    input.crate_name.hash(&mut h);
    input.cargo_env.hash(&mut h);
    input.display_root.hash(&mut h);
    client.shown_root.hash(&mut h);
    h.finish()
}

fn seed_hash(h: &mut crate::intern::FxHasher, s: &crate::expand::MacroSeed) {
    use std::hash::{Hash, Hasher};
    s.path.iter().for_each(|p| h.write_u64(p.0 as u64));
    h.write_u64(hash_tokens(&s.tokens, &s.strings));
    s.import_into.as_ref().map(|v| v.iter().map(|p| p.0).collect::<Vec<_>>()).hash(h);
    s.ambiguous.hash(h);
    s.visible_in.as_ref().map(|v| v.iter().map(|p| p.0).collect::<Vec<_>>()).hash(h);
}

/// Hash of everything one file's expansion reads besides its own text
/// (`ResolveCache::expanded`): the round's shared inputs, the seeds and glob
/// seeds it can reach (`MacroEnv::reach`, `expand::reach_seeds`: the
/// expander seeds no other), the seed facts of its glob seeds
/// (`expand::parser_name_facts`), the macro sources spliced into it
/// (`MacroEnv::splice`), its module path, and its path.
#[allow(clippy::too_many_arguments)]
fn expansion_input_hash(env_hash: u64, menv: &MacroEnv, reach: &[Vec<usize>; 2], owned_hashes: &[u64], di: usize, module_path: &[Sym], path: &std::path::Path, interner: &Interner) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = crate::intern::FxHasher::default();
    h.write_u64(env_hash);
    let globs = menv.glob_seeds.get(di).map(Vec::as_slice).unwrap_or(&[]);
    for (list, reached) in [&menv.seeds[..], globs].into_iter().zip(reach) {
        reached.iter().for_each(|&i| seed_hash(&mut h, &list[i]));
        h.write_u64(u64::MAX);
    }
    crate::expand::parser_name_facts(globs, interner).hash(&mut h);
    for &i in menv.inherited.get(di).map(Vec::as_slice).unwrap_or(&[]) {
        h.write_u64(owned_hashes[i]);
    }
    h.write_u64(u64::MAX);
    for (pos, srcs, ext) in menv.after_mods.get(di).map(Vec::as_slice).unwrap_or(&[]) {
        h.write_u32(*pos);
        srcs.iter().for_each(|&i| h.write_u64(owned_hashes[i]));
        ext.hash(&mut h);
    }
    module_path.iter().for_each(|p| h.write_u64(p.0 as u64));
    path.hash(&mut h);
    h.finish()
}

/// The expansion cache's oracle (`LUST_CHECK_EXPKEY=1`): a hit's stream and
/// outside reads must equal a fresh expansion of the same file, contexts
/// compared by what they stand for (`diag::ctxt_hash`). A difference means
/// the key (`expansion_input_hash`) misses an input the expansion reads: it
/// panics.
fn check_expansion_hit(hit: &lexer::Lexed, deps: &[crate::expand::Dep], fresh: &Result<(lexer::Lexed, Vec<crate::expand::Dep>), Diag>, path: &std::path::Path) {
    let what = match fresh {
        Err(d) => Some(format!("the fresh expansion fails: {}", d.message)),
        Ok((f, _)) if f.strings != hit.strings => Some("the string tables differ".to_string()),
        Ok((f, _)) if f.tokens.len() != hit.tokens.len() => Some(format!("{} tokens, the hit has {}", f.tokens.len(), hit.tokens.len())),
        Ok((f, fresh_deps)) => {
            let mut memo = FxMap::default();
            let mut ctxt = |c| crate::diag::ctxt_hash(c, &mut memo);
            match f.tokens.iter().zip(&hit.tokens).position(|(a, b)| {
                a.tok != b.tok || (a.span.file, a.span.lo, a.span.hi) != (b.span.file, b.span.lo, b.span.hi) || ctxt(a.span.ctxt) != ctxt(b.span.ctxt)
            }) {
                Some(i) => Some(format!("token {i} is {:?}, the hit's {:?}", f.tokens[i], hit.tokens[i])),
                None if fresh_deps[..] != *deps => Some("the outside reads differ".to_string()),
                None => None,
            }
        }
    };
    if let Some(what) = what {
        panic!("expkey-check: {}: {what}", path.display());
    }
}

/// Runs `f` for each item on all cores, results in input order, on the
/// compiler's persistent pool (src/pool.rs).
fn par_map<T: Sync, R: Send>(items: &[T], f: impl Fn(&T) -> R + Sync) -> Vec<R> {
    crate::pool::par_map(items, f)
}

/// Workspace-session shared state: session-global file ids and the
/// file text cache (one file text per canonical path, as section 1.2
/// requires; defs stay per (crate, module)).
#[derive(Default)]
struct SharedFiles {
    next_file: u32,
    file_ids: FxMap<String, FileId>,
    text_by_path: FxMap<String, String>,
}

impl SharedFiles {
    /// The session-global FileId of one (file, module) pair.
    fn file_id(&mut self, path: &std::path::Path, module: ModuleId) -> FileId {
        let canon = modules::canonical_string(path);
        let next = &mut self.next_file;
        *self.file_ids.entry(format!("{canon}#{}", module.0)).or_insert_with(|| {
            let id = FileId(*next);
            *next += 1;
            id
        })
    }
}

/// One `macro_rules!` definition in token form, for cross-file and
/// cross-crate macro visibility: the definition's flat tokens and the
/// string table they index into (only the strings those tokens name,
/// `own_def_strings`; shared by every seed made from it), plus the
/// defining crate's `$crate` magic segment so expansion in another crate
/// can rewrite it.
#[derive(Clone)]
struct OwnedMacroSource {
    name: Sym,
    tokens: Vec<crate::lexer::Token>,
    strings: std::sync::Arc<Vec<String>>,
    magic: Sym,
    /// For a crate's exports: the module path, from its root, of the
    /// public binding (`prelude` for `pub mod prelude { pub use
    /// crate::args; }`); empty at the root. Empty for own sources.
    path: Vec<Sym>,
}

/// One macro definition's tokens with a string table of only the strings
/// they name, the tokens re-indexed into it. Each file that sees the
/// definition appends its table (seeds, `splice`), so a copy of the whole
/// defining file's table made the string tables of ts_goport's files hold
/// 29M strings for 3.7M tokens (fx-daemonmem: 2 GB in each Ast copy).
fn own_def_strings(toks: &[crate::lexer::Token], strings: &[String]) -> (Vec<crate::lexer::Token>, Vec<String>) {
    let mut out = Vec::new();
    let mut toks = toks.to_vec();
    for t in &mut toks {
        for i in t.tok.string_indices_mut().into_iter().flatten() {
            out.push(strings.get(*i as usize).cloned().unwrap_or_default());
            *i = out.len() as u32 - 1;
        }
    }
    (toks, out)
}

/// One crate of a workspace session, ready to resolve.
struct CrateJob {
    input: OneInput,
    root_module: ModuleId,
    flat_prefix: String,
    magic: Sym,
    /// Direct dependencies: (extern name, source job index or the
    /// L0508 reason when the dependency has no lust form yet).
    deps: Vec<(String, Result<usize, String>)>,
    /// The exact-layout list when this crate is an adapter crate.
    adapter: Option<Vec<String>>,
    /// True for the std splice job (`add_std_splice_job`): it shares
    /// the root module and file 0 with the selected crate, so its
    /// per-file cache entries take their own keys.
    std_splice: bool,
}

impl CrateJob {
    /// The per-file cache key of one file of this job: canonical path
    /// plus module, and a mark for the std splice job.
    fn file_key(&self, canon: &str, module: ModuleId) -> String {
        if self.std_splice { format!("{canon}#{}#std", module.0) } else { format!("{canon}#{}", module.0) }
    }
}

/// What one resolved crate contributes to the merged program.
struct CrateOut {
    /// Its files' chunks in order (a hit as its place in the session's merged
    /// Ast). The caller concatenates every crate's chunks at once: a crate's own
    /// concat was copied whole again, its shift on one thread.
    chunks: Vec<crate::ast::ChunkPart>,
    /// Per chunk, its cache entry (key, text hash, file id) when the cache
    /// holds it, so the caller records where the chunk sits in the merged Ast.
    chunk_keys: Vec<Option<(String, u64, FileId)>>,
    fn_lines: Vec<u32>,
    body_hashes: Vec<u64>,
    fn_module: Vec<ModuleId>,
    /// Nested (body-local) fns ride after every crate's top-level
    /// fns in the merged order, as collect and the Ast scan order
    /// them; the workspace wrapper appends these last.
    nested_lines: Vec<u32>,
    nested_hashes: Vec<u64>,
    nested_modules: Vec<ModuleId>,
    structure_hash: u64,
    seen: Vec<(PathBuf, String, FileId)>,
    std_asks: StdPlan,
    exported_macros: Vec<OwnedMacroSource>,
    /// The outside inputs this crate's last expansion round read.
    expand_deps: Vec<crate::expand::Dep>,
    timings: Vec<(&'static str, f64)>,
    /// Item scans and top-level fn body scans of this crate.
    scans: crate::driver::ast_hash::AstScans,
    /// Nested fn body scans of this crate; the workspace wrapper
    /// appends them after every crate's top-level bodies.
    nested_bodies: Vec<(u64, Vec<crate::intern::Sym>)>,
    /// This crate's share of the module dependency record (resolve/mdr.rs).
    mdr: Option<crate::resolve::mdr::CratePart>,
}

/// One crate's failed resolution inside a session.
struct OneError {
    diags: Vec<Diag>,
    seen: Vec<(PathBuf, String, FileId)>,
    std_asks: StdPlan,
}

/// Shim crates (ARCH 3.7): rustc-built, with a lust source API crate
/// in front once one exists.
const SHIM_CRATES: &[&str] = &["rustix", "nix", "signal-hook", "flate2", "jiff", "name-to-handle-at", "tikv-jemallocator"];

/// The lib root of the lust-side crate for a shim, if one exists in
/// `library/deps/<name>/src/lib.rs` (see `adapters::library_root`).
fn lust_dep_lib_root(name: &str) -> Option<PathBuf> {
    let root = super::adapters::library_root().join("deps").join(name).join("src/lib.rs");
    root.is_file().then_some(root)
}

/// How one resolved dependency classifies (ARCH 1.1): lust source with
/// this lib root (a path package, or the lust-side adapter/shim crate),
/// or unsupported with a reason that names the crate (L0508). The
/// class is a property of the resolved package, never of a source
/// spelling: a path package that happens to be named `indexmap` is
/// plain lust source. `lust_owned` marks the library's own crates
/// (adapters and shims): they skip the edition rule and see
/// `cfg(lust_dev)`. `adapter` carries an adapter's exact-layout list.
enum DepClass {
    Source { root: PathBuf, lust_owned: bool, adapter: Option<Vec<String>> },
    Unsupported(String),
}

/// Classifies one dependency unit. See `DepClass`.
fn classify_dep(dep: &super::cargo::DepUnit) -> DepClass {
    if dep.source.is_none() {
        return DepClass::Source { root: dep.lib_src.clone(), lust_owned: false, adapter: None };
    }
    let name = dep.package_name.as_str();
    if super::adapters::ADAPTER_PACKAGES.contains(&name) {
        return match super::adapters::load(name) {
            Ok(Some(a)) => match super::adapters::check_unit(&a, name, &dep.version, &dep.features) {
                Ok(()) => DepClass::Source { root: a.root, lust_owned: true, adapter: Some(a.exact_layout) },
                Err(why) => DepClass::Unsupported(why),
            },
            Ok(None) => DepClass::Unsupported(format!("dependency crate `{name}` has no lust adapter yet")),
            Err(e) => DepClass::Unsupported(format!("the lust adapter for `{name}` is broken: {e}")),
        };
    }
    if SHIM_CRATES.contains(&name) {
        if let Some(root) = lust_dep_lib_root(name) {
            return DepClass::Source { root, lust_owned: true, adapter: None };
        }
        return DepClass::Unsupported(format!("dependency crate `{name}` has no lust shim yet"));
    }
    DepClass::Unsupported(format!("dependency crate `{name}` is not a lust source crate, an adapter, or a shim crate yet"))
}

/// The root files of every source dependency under `deps` (each once,
/// transitively), for a new session's std plan guess
/// (`StdPlan::guess_crate`): a dependency's std module asks count as
/// the selected crate's do.
pub fn dep_roots(deps: &[super::cargo::DepUnit]) -> Vec<PathBuf> {
    let mut roots: Vec<PathBuf> = Vec::new();
    let mut stack: Vec<&super::cargo::DepUnit> = deps.iter().collect();
    while let Some(d) = stack.pop() {
        if let DepClass::Source { root, .. } = classify_dep(d)
            && !roots.contains(&root)
        {
            roots.push(root);
            stack.extend(d.deps.iter());
        }
    }
    roots
}

/// The `$crate` magic segment name of one crate in a session. Not a
/// legal Rust identifier, so source text can never write it.
fn crate_magic_name(stable: crate::def::StableCrateHash) -> String {
    format!("$lust$crate${:016x}", stable.0)
}

/// Runs the outline worklist for one crate. See the file header.
pub fn resolve_crate(input: &CrateInput, interner: &Interner, known: &Known) -> Result<ResolvedCrate, ResolveError> {
    resolve_crate_cached(input, interner, known, &mut ResolveCache::new(true))
}

/// Runs the outline worklist for the selected crate and every source
/// dependency in one workspace session (ARCH 1.8), dependencies first,
/// with a caller-kept per-file cache (the daemon's crate session
/// holds one across requests; it serves raw token streams and
/// outlines here, since expanded streams also depend on the macro
/// environment). See the file header for the merged-output shape.
pub fn resolve_crate_cached(
    input: &CrateInput,
    interner: &Interner,
    known: &Known,
    cache: &mut ResolveCache,
) -> Result<ResolvedCrate, ResolveError> {
    // The shipped std platform crate (W-SHIM) joins the session when
    // some file can name a platform module. Only the root text is known
    // up front; a mention in another file resolves once more with it.
    let with_platform = mentions_std_platform(&input.root_text);
    let out = resolve_crate_with(input, interner, known, cache, with_platform);
    if with_platform {
        return out;
    }
    let again = match &out {
        Ok(r) => mentions_std_platform(&r.all_text),
        Err(e) => mentions_std_platform(&e.all_text),
    };
    if again { resolve_crate_with(input, interner, known, cache, true) } else { out }
}

/// True when `text` can name a std platform module
/// (`STD_PLATFORM_MODULES`): a plain byte scan, so a mention in a
/// comment or string only costs the platform crate's resolve.
pub fn mentions_std_platform(text: &str) -> bool {
    // `thread::Builder` and `available_parallelism` return
    // `io::Result` (TRIAGE T5): naming either loads the platform
    // crate so check can name `std::io::Error`.
    if text.contains("thread::Builder") || text.contains("available_parallelism") {
        return true;
    }
    text.match_indices("std::").any(|(i, _)| {
        let rest = &text[i + 5..];
        match rest.strip_prefix('{') {
            Some(group) => group_names_platform(group),
            None => super::imports::STD_PLATFORM_MODULES.iter().any(|m| rest.starts_with(m) && !compiler_std_item(m, &rest[m.len()..])),
        }
    })
}

/// True when a `use std::{...}` group (`text` starts right after its
/// `{`) names a platform module as a word before the group closes, so
/// `use std::{}` and `use std::{rc::Rc}` load no platform crate.
fn group_names_platform(text: &str) -> bool {
    let mut depth = 0usize;
    let mut word_start = None;
    for (i, c) in text.char_indices() {
        if c.is_ascii_alphanumeric() || c == '_' {
            word_start.get_or_insert(i);
            continue;
        }
        if let Some(st) = word_start.take()
            && (&text[st..i] == "self" || super::imports::STD_PLATFORM_MODULES.contains(&&text[st..i]))
        {
            return true;
        }
        match c {
            '{' => depth += 1,
            '}' if depth == 0 => return false,
            '}' => depth -= 1,
            _ => {}
        }
    }
    false
}

/// True for `std::env::args` and `Args` and `std::process::exit`/`abort` (`rest`
/// follows the module name): the compiler's own std handling serves
/// them, as in `needs_resolve_lexed`, so they need no platform crate.
fn compiler_std_item(module: &str, rest: &str) -> bool {
    let items: &[&str] = match module {
        "env" => &["::args", "::Args"],
        "process" => &["::exit", "::abort"],
        _ => return false,
    };
    items.iter().any(|item| {
        rest.strip_prefix(item).is_some_and(|after| !after.starts_with(|c: char| c.is_ascii_alphanumeric() || c == '_'))
    })
}

/// The library root of the shipped std platform crate (W-SHIM).
pub fn std_platform_root() -> PathBuf {
    super::adapters::library_root().join("std/src/platform.rs")
}

/// Adds the shipped std platform crate as a job of the session: a
/// lust-owned crate named `std` (so its paths display as std's) that
/// registers as the `std` shipped crate for intrinsic privilege, with
/// no exact-layout types. Returns the job index.
fn add_platform_job(input: &CrateInput, tables: &mut ResolvedTables, jobs: &mut Vec<CrateJob>, interner: &Interner) -> Result<usize, Diag> {
    let root = std_platform_root();
    let root_text = std::fs::read_to_string(&root).map_err(|e| {
        Diag::new(
            "L0503",
            Span::default(),
            format!("cannot read the lust std platform crate {}: {e}", root.display()),
            "Reinstall lust, or point LUST_LIBRARY at a complete library tree.",
        )
    })?;
    let stable = crate::ty::lang::ShippedCrate::Std.stable_hash();
    let magic = interner.intern(&crate_magic_name(stable));
    let root_module = tables.add_crate_root(interner.intern("std"));
    tables.crate_magic.insert(magic, root_module);
    tables.std_platform = Some((root_module, magic));
    let mut env = input.env.with_features(&[]);
    env.allow_lust_dev = true;
    jobs.push(CrateJob {
        input: OneInput {
            root_path: root,
            root_text,
            env,
            crate_ids: input.crate_ids,
            crate_name: "std".to_string(),
            cargo_env: Vec::new(),
            std_splice_lo: None,
            display_root: input.display_root.clone(),
        },
        root_module,
        flat_prefix: format!("k{:016x}$", stable.0),
        magic,
        deps: Vec::new(),
        adapter: Some(Vec::new()),
        std_splice: false,
    });
    Ok(jobs.len() - 1)
}

/// Adds the std splice of the selected root (every byte of file 0 from
/// `std_splice_lo` on) as a job of its own, which resolves before every
/// crate but the platform crate (std source names platform items). A
/// dependency's `std::time` path walks into the hidden std modules the
/// splice defines (`ResolvedTables::std_modules`), so they must be
/// registered before any dependency resolves. The job is part of the
/// selected crate: same root module, flat names, and file 0, whose user
/// text it sees blanked (newlines kept), so every span and line stays
/// where the one-job resolve put it. Returns the job index.
fn add_std_splice_job(input: &CrateInput, lo: u32, jobs: &mut Vec<CrateJob>) -> usize {
    let lo = lo as usize;
    let mut text: String = input.root_text.as_bytes()[..lo].iter().map(|&b| if b == b'\n' { '\n' } else { ' ' }).collect();
    text.push_str(&input.root_text[lo..]);
    let root = &jobs[0];
    jobs.push(CrateJob {
        input: OneInput { root_text: text, ..root.input.clone() },
        root_module: root.root_module,
        flat_prefix: root.flat_prefix.clone(),
        magic: root.magic,
        deps: Vec::new(),
        adapter: None,
        std_splice: true,
    });
    jobs.len() - 1
}

/// `resolve_crate_cached` with the platform crate in or out. The
/// driver picks `with_platform` by its std plan (`stdload::StdPlan`).
pub fn resolve_crate_with(
    input: &CrateInput,
    interner: &Interner,
    known: &Known,
    cache: &mut ResolveCache,
    with_platform: bool,
) -> Result<ResolvedCrate, ResolveError> {
    cache.begin(input);
    let mut tables = ResolvedTables::new(interner.intern(&input.crate_name));
    tables.std_splice_lo = input.std_splice_lo;
    let main_magic = interner.intern(&crate_magic_name(input.crate_ids.stable));
    tables.crate_magic.insert(main_magic, ROOT_MODULE);
    // With a std splice, the root job resolves only the user text
    // before it; the splice is its own job (`add_std_splice_job`).
    let user_text = match input.std_splice_lo {
        Some(lo) => input.root_text[..lo as usize].to_string(),
        None => input.root_text.clone(),
    };
    let mut jobs: Vec<CrateJob> = vec![CrateJob {
        input: OneInput {
            root_path: input.root_path.clone(),
            root_text: user_text,
            env: input.env.clone(),
            crate_ids: input.crate_ids,
            crate_name: input.crate_name.clone(),
            cargo_env: input.cargo_env.clone(),
            std_splice_lo: input.std_splice_lo,
            display_root: input.display_root.clone(),
        },
        root_module: ROOT_MODULE,
        flat_prefix: String::new(),
        magic: main_magic,
        deps: Vec::new(),
        adapter: None,
        std_splice: false,
    }];
    // The session error map for job-build failures (a dependency root
    // that cannot be read, a non-2024 source dependency): the selected
    // crate's root file at the span's default file id.
    let build_err = |d: Diag| -> ResolveError {
        let (map, all_text) = make_map(&[(input.root_path.clone(), input.root_text.clone(), FileId(0))]);
        ResolveError { map, all_text, std_asks: StdPlan::default(), platform_asks: None, diags: vec![d] }
    };
    let mut by_key: FxMap<String, usize> = FxMap::default();
    let mut main_deps = Vec::new();
    for dep in &input.deps {
        match add_dep_job(dep, input, &mut tables, &mut jobs, &mut by_key, interner) {
            Ok(link) => main_deps.push(link),
            Err(d) => return Err(build_err(d)),
        }
    }
    for j in jobs.iter().filter(|j| !j.std_splice && j.adapter.is_none()) {
        tables.crate_cfgs.insert(j.root_module, (j.input.env.clone(), j.input.crate_name.clone()));
    }
    let mut platform_job = None;
    if with_platform {
        match add_platform_job(input, &mut tables, &mut jobs, interner) {
            // First, so it resolves before every crate that names it.
            Ok(j) => {
                platform_job = Some(j);
                main_deps.insert(0, ("$lust$std".to_string(), Ok(j)));
            }
            Err(d) => return Err(build_err(d)),
        }
    }
    jobs[0].deps = main_deps;
    // Extern preludes, per crate: std libs, then direct dependencies.
    for j in 0..jobs.len() {
        let (root_module, deps) = (jobs[j].root_module, jobs[j].deps.clone());
        for name in ["std", "core", "alloc"] {
            push_extern(&mut tables, input.crate_ids.local, root_module, name, true, None, None);
        }
        for (name, target) in &deps {
            match target {
                Ok(dj) => {
                    let dep_root = jobs[*dj].root_module;
                    push_extern(&mut tables, input.crate_ids.local, root_module, name, false, Some(dep_root), None);
                }
                Err(why) => push_extern(&mut tables, input.crate_ids.local, root_module, name, false, None, Some(why.clone())),
            }
        }
    }
    // After the extern preludes: the splice job's root module has the
    // selected crate's prelude already.
    let std_job = input.std_splice_lo.map(|lo| add_std_splice_job(input, lo, &mut jobs));
    // Dependencies first (a dev-dependency cycle, legal in Cargo test
    // crates, breaks at the back edge: that crate then resolves after
    // its dependent and the dependent's paths into it do not resolve).
    let mut order: Vec<usize> = Vec::new();
    let mut state = vec![0u8; jobs.len()];
    fn visit(j: usize, jobs: &[CrateJob], state: &mut [u8], order: &mut Vec<usize>) {
        if state[j] != 0 {
            return;
        }
        state[j] = 1;
        for (_, t) in &jobs[j].deps {
            if let Ok(d) = t {
                visit(*d, jobs, state, order);
            }
        }
        state[j] = 2;
        order.push(j);
    }
    visit(0, &jobs, &mut state, &mut order);
    if let Some(sj) = std_job {
        let at = platform_job.and_then(|p| order.iter().position(|&j| j == p)).map_or(0, |i| i + 1);
        order.insert(at, sj);
    }
    let mut shared = SharedFiles::default();
    // Every file an earlier resolve canonicalized, read again now in
    // parallel: discovery walks the module tree one file at a time and
    // finds these texts here (a CI checkout is not in the page cache, and
    // the walk read about 1000 files in turn). A file gone since is left
    // out, and a new one is the walk's own read, as before.
    {
        let seen: Vec<(&PathBuf, &String)> = cache.canon.iter().collect();
        // A front image build read most of them beside its load (`prefetch`).
        let pre = std::sync::Mutex::new(crate::resolve::prefetch::take().unwrap_or_default());
        let read = |path: &PathBuf| {
            let hit = pre.lock().unwrap().remove(path);
            hit.or_else(|| std::fs::read_to_string(path).ok())
        };
        for ((_, canon), text) in seen.iter().zip(par_map(&seen, |(path, _)| read(path))) {
            if let Some(text) = text {
                shared.text_by_path.insert((*canon).clone(), text);
            }
        }
    }
    // And every stored raw token stream, unpacked on the pool (discovery takes them in turn).
    cache.unpack_raw();
    // The selected crate's root file is FileId(0) even though its
    // dependencies resolve first: the spliced std ranges, the error
    // footer, and `Program::shipped_crate_at` all read file 0 as the
    // selected root.
    shared.file_id(&input.root_path, ROOT_MODULE);
    let mut all_seen: Vec<(PathBuf, String, FileId)> = Vec::new();
    let (mut std_asks, mut platform_asks) = (StdPlan::default(), with_platform.then(StdPlan::default));
    let mut add_asks = |j: usize, asks: StdPlan| match &mut platform_asks {
        Some(p) if platform_job == Some(j) => *p = p.or(asks),
        _ => std_asks = std_asks.or(asks),
    };
    let mut chunks: Vec<crate::ast::ChunkPart> = Vec::new();
    let mut chunk_keys: Vec<Option<(String, u64, FileId)>> = Vec::new();
    let mut mdr_parts: Vec<crate::resolve::mdr::CratePart> = Vec::new();
    let mut fn_lines: Vec<u32> = Vec::new();
    let mut body_hashes: Vec<u64> = Vec::new();
    let mut nested_lines: Vec<u32> = Vec::new();
    let mut nested_hashes: Vec<u64> = Vec::new();
    let mut nested_modules: Vec<ModuleId> = Vec::new();
    let mut structure_hash = 0u64;
    let mut exported_of: FxMap<usize, Vec<OwnedMacroSource>> = FxMap::default();
    let mut expand_deps: Vec<crate::expand::Dep> = Vec::new();
    let mut timings: Vec<(&'static str, f64)> = Vec::new();
    let mut scan_items = Vec::new();
    let mut scan_bodies = Vec::new();
    let mut nested_scan_bodies = Vec::new();
    for &j in &order {
        let mut dep_exports: Vec<(String, Vec<OwnedMacroSource>)> = jobs[j]
            .deps
            .iter()
            .filter_map(|(name, t)| t.as_ref().ok().map(|d| (name.clone(), exported_of.get(d).cloned().unwrap_or_default())))
            .collect();
        // A dependency's macro that calls `$crate::name!` reaches this
        // crate as a path from the defining crate's magic segment
        // (rewrite_dollar_crate), and a re-exported macro's defining
        // crate can be an indirect dependency. So every crate below
        // this one is also seeded under its magic segment, a name
        // source text cannot write.
        let mut below: Vec<usize> = Vec::new();
        let mut stack: Vec<usize> = jobs[j].deps.iter().filter_map(|(_, t)| t.as_ref().ok().copied()).collect();
        while let Some(d) = stack.pop() {
            if !below.contains(&d) {
                below.push(d);
                stack.extend(jobs[d].deps.iter().filter_map(|(_, t)| t.as_ref().ok().copied()));
            }
        }
        below.sort_unstable();
        for d in below {
            if let Some(sources) = exported_of.get(&d).filter(|s| !s.is_empty()) {
                dep_exports.push((interner.get(jobs[d].magic).to_string(), sources.clone()));
            }
        }
        match resolve_one(&jobs[j], &mut tables, &mut shared, cache, &dep_exports, &input.client, interner, known) {
            Ok(out) => {
                if let Some(exact_layout) = &jobs[j].adapter {
                    tables.adapters.push(super::imports::AdapterCrate {
                        name: jobs[j].input.crate_name.clone(),
                        files: out.seen.iter().map(|s| s.2).collect(),
                        exact_layout: exact_layout.clone(),
                    });
                }
                add_asks(j, out.std_asks);
                all_seen.extend(seen_whole(out.seen, j, std_job, input));
                fn_lines.extend(out.fn_lines);
                body_hashes.extend(out.body_hashes);
                nested_lines.extend(out.nested_lines);
                nested_hashes.extend(out.nested_hashes);
                nested_modules.extend(out.nested_modules);
                {
                    use std::hash::{Hash, Hasher};
                    let mut h = crate::intern::FxHasher::default();
                    structure_hash.hash(&mut h);
                    out.structure_hash.hash(&mut h);
                    structure_hash = h.finish();
                }
                tables.fn_module.extend(out.fn_module);
                mdr_parts.extend(out.mdr);
                expand_deps.extend(out.expand_deps);
                scan_items.extend(out.scans.items);
                scan_bodies.extend(out.scans.bodies);
                nested_scan_bodies.extend(out.nested_bodies);
                exported_of.insert(j, out.exported_macros);
                for (name, ms) in out.timings {
                    match timings.iter_mut().find(|(n, _)| *n == name) {
                        Some((_, total)) => *total += ms,
                        None => timings.push((name, ms)),
                    }
                }
                chunks.extend(out.chunks);
                chunk_keys.extend(out.chunk_keys);
            }
            Err(e) => {
                add_asks(j, e.std_asks);
                all_seen.extend(seen_whole(e.seen, j, std_job, input));
                cache.unpacked.clear();
                let (map, all_text) = make_map(&all_seen);
                return Err(ResolveError { map, all_text, std_asks, platform_asks, diags: e.diags });
            }
        }
    }
    fn_lines.extend(nested_lines);
    body_hashes.extend(nested_hashes);
    tables.fn_module.extend(nested_modules);
    // Streams of files no job took this request do not stay.
    cache.unpacked.clear();
    // The source map builds beside the merged Ast (each 10-70 ms on tsgo).
    let old = cache.merged.as_ref().map(|m| &*m.0);
    let ((map, all_text), (ast, spans)) = std::thread::scope(|s| {
        let map = s.spawn(|| make_map(&all_seen));
        let ast = Ast::concat_parts(chunks, old);
        (map.join().unwrap_or_else(|p| std::panic::resume_unwind(p)), ast)
    });
    // Each chunk the cache holds is a part of the merged Ast now: the cache keeps where.
    let generation = cache.resolves;
    for (key, at) in chunk_keys.into_iter().zip(spans) {
        if let Some((key, text_hash, file_id)) = key
            && let Some(c) = cache.files.get_mut(&key).filter(|e| e.text_hash == text_hash && e.file_id == file_id).and_then(|e| e.final_chunk.as_mut())
        {
            (c.at, c.generation) = (at, generation);
        }
    }
    scan_bodies.extend(nested_scan_bodies);
    let scans = crate::driver::ast_hash::AstScans { items: scan_items, bodies: scan_bodies };
    let mdr = crate::resolve::mdr::on().then(|| crate::resolve::mdr::build(&tables, &map, mdr_parts));
    Ok(ResolvedCrate { ast, map, tables, fn_lines, body_hashes, structure_hash, all_text, std_asks, platform_asks, expand_deps, timings, scans, mdr, generation })
}

/// Creates (or reuses) the job for one source dependency, recursively.
/// Returns the dependent's link: the job index, or the L0508 reason.
fn add_dep_job(
    dep: &super::cargo::DepUnit,
    input: &CrateInput,
    tables: &mut ResolvedTables,
    jobs: &mut Vec<CrateJob>,
    by_key: &mut FxMap<String, usize>,
    interner: &Interner,
) -> Result<(String, Result<usize, String>), Diag> {
    let (root, lust_owned, adapter) = match classify_dep(dep) {
        DepClass::Source { root, lust_owned, adapter } => (root, lust_owned, adapter),
        DepClass::Unsupported(why) => return Ok((dep.extern_name.clone(), Err(why))),
    };
    let key = format!("{}#{}", dep.package_id, dep.lib_name);
    if let Some(&j) = by_key.get(&key) {
        return Ok((dep.extern_name.clone(), Ok(j)));
    }
    if !lust_owned && dep.edition != "2024" {
        return Err(Diag::new(
            "L0530",
            Span::default(),
            format!("dependency crate `{}` is edition {}, but lust source crates must be edition 2024", dep.package_name, dep.edition),
            "Set `edition = \"2024\"` in the dependency package manifest.",
        ));
    }
    let root_text = std::fs::read_to_string(&root).map_err(|e| {
        Diag::new(
            "L0503",
            Span::default(),
            format!("cannot read dependency crate `{}` root {}: {e}", dep.package_name, root.display()),
            "Check the file exists and is readable.",
        )
    })?;
    let crate_name = dep.lib_name.replace('-', "_");
    let stable = def::stable_crate_hash(&dep.package_id, "lib", &dep.lib_name, false);
    let magic = interner.intern(&crate_magic_name(stable));
    let root_module = tables.add_crate_root(interner.intern(&crate_name));
    tables.crate_magic.insert(magic, root_module);
    let mut env = input.env.with_features(&dep.features);
    if lust_owned {
        env.allow_lust_dev = true;
    } else {
        // A source dependency sees its own build script's cfgs, as
        // under Cargo. Lust-owned adapter and shim sources do not:
        // their root is not the package Cargo would build.
        for c in &dep.build_cfgs {
            env.add_rustc_cfg(c);
        }
        for c in &dep.build_check_cfgs {
            env.add_check_cfg(c);
        }
    }
    let idx = jobs.len();
    by_key.insert(key, idx);
    jobs.push(CrateJob {
        input: OneInput {
            root_path: root,
            root_text,
            env,
            crate_ids: input.crate_ids,
            crate_name,
            cargo_env: if lust_owned { Vec::new() } else { dep.cargo_env.clone() },
            std_splice_lo: None,
            display_root: input.display_root.clone(),
        },
        root_module,
        flat_prefix: format!("k{:016x}$", stable.0),
        magic,
        deps: Vec::new(),
        adapter,
        std_splice: false,
    });
    let mut sub = Vec::new();
    for d in &dep.deps {
        sub.push(add_dep_job(d, input, tables, jobs, by_key, interner)?);
    }
    jobs[idx].deps = sub;
    Ok((dep.extern_name.clone(), Ok(idx)))
}

/// One discovered file of one crate during resolution.
struct FileDisc {
    path: PathBuf,
    text: String,
    file_id: FileId,
    /// The module this file's top-level items belong to.
    module: ModuleId,
    /// True when this file's submodules live in its own directory for a
    /// reason its name does not show: it is the crate root, or the
    /// `mod` declaration that loaded it carried a `#[path]` attribute
    /// (such a file owns its directory like `mod.rs`, as in rustc).
    dir_owner: bool,
    /// The `mod` declaration that loaded this file (none at the root).
    parent: Option<ParentDecl>,
    lexed: Option<lexer::Lexed>,
    outline: scan::Outline,
    /// The `use` sites of `lexed`, once the cache or a round's `MacroEnv::build` has them.
    use_sites: Option<std::sync::Arc<[UseSite]>>,
}

/// The `mod` declaration that loaded a file: where it sits, which is
/// the point that fixes textual macro inheritance (ARCH 6.1).
#[derive(Clone)]
struct ParentDecl {
    disc: usize,
    container: Vec<Sym>,
    lo: u32,
    macro_use: bool,
}

/// The seen list of the discovered files so far, for error maps.
/// One job's seen files for the session map, with file 0 split between
/// the root job and the std splice job (`add_std_splice_job`) shown
/// once, as the whole root text: the splice job resolves first, so it
/// carries file 0 and the root job drops its copy.
fn seen_whole(
    mut seen: Vec<(PathBuf, String, FileId)>,
    j: usize,
    std_job: Option<usize>,
    input: &CrateInput,
) -> Vec<(PathBuf, String, FileId)> {
    if std_job == Some(j) {
        for s in seen.iter_mut().filter(|s| s.2 == FileId(0)) {
            s.1.clone_from(&input.root_text);
        }
    } else if j == 0 && std_job.is_some() {
        seen.retain(|s| s.2 != FileId(0));
    }
    seen
}

fn seen_of(discs: &[FileDisc]) -> Vec<(PathBuf, String, FileId)> {
    discs.iter().map(|d| (d.path.clone(), d.text.clone(), d.file_id)).collect()
}

/// Creates the modules and file edges of one outline's `mod`
/// declarations, returning the inline module map of this file. New
/// file discs are appended to `discs` and queued for outline
/// processing. A declaration whose module already exists is a no-op,
/// which is what lets the same code serve the first discovery pass
/// and the macro-generated edges of later expansion rounds.
#[allow(clippy::too_many_arguments)]
fn outline_mods(
    di: usize,
    outline: &scan::Outline,
    strings: &[String],
    discs: &mut Vec<FileDisc>,
    queue: &mut Vec<usize>,
    tables: &mut ResolvedTables,
    shared: &mut SharedFiles,
    job: &CrateJob,
    interner: &Interner,
    diags: &mut Vec<Diag>,
) -> FxMap<Vec<Sym>, ModuleId> {
    let (file_path, file_module, dir_owner) = (discs[di].path.clone(), discs[di].module, discs[di].dir_owner);
    let mut inline_modules: FxMap<Vec<Sym>, ModuleId> = FxMap::default();
    inline_modules.insert(Vec::new(), file_module);
    // Inline module paths a cfg turned off: a declaration inside one
    // is disabled with it, so its file module is never loaded.
    let mut disabled_containers: Vec<Vec<Sym>> = Vec::new();
    for decl in &outline.mods {
        if (1..=decl.container.len()).any(|k| disabled_containers.iter().any(|d| d == &decl.container[..k])) {
            continue;
        }
        let enabled = match cfg::outline_enabled(&job.input.env, &decl.cfg, strings, interner, decl.span)
            .and_then(|e| Ok(e && cfg::outline_cfg_attr_enabled(&job.input.env, &decl.cfg_attr, strings, interner, decl.span)?))
        {
            Ok(e) => e,
            Err(d) => {
                diags.push(d);
                false
            }
        };
        if !enabled {
            if decl.inline {
                let mut key = decl.container.clone();
                key.push(decl.name);
                disabled_containers.push(key);
            }
            continue;
        }
        let parent = inline_modules.get(&decl.container).copied().unwrap_or(file_module);
        let mut child_path = tables.modules[parent.0 as usize].path.clone();
        child_path.push(decl.name);
        let existing = tables.module_by_path_in(job.root_module, &child_path);
        let child = match existing {
            Some(c) => c,
            None => {
                let vis = match decl.vis {
                    scan::OutlineVis::Private => VisKind::Priv,
                    scan::OutlineVis::Pub => VisKind::Pub,
                    scan::OutlineVis::Restricted => VisKind::Crate,
                };
                tables.add_module(parent, decl.name, vis, decl.span)
            }
        };
        tables.modules[child.0 as usize].macro_use |= decl.macro_use;
        if decl.inline {
            let mut key = decl.container.clone();
            key.push(decl.name);
            inline_modules.insert(key, child);
        } else if existing.is_none() {
            // A `#[path]` that is not `= "..."` is the parser's
            // malformed-input error (L0524), but this load runs from
            // the outline scan first, so report it here.
            if let Some(bad) = decl.path_bad {
                diags.push(Diag::new(
                    "L0524",
                    bad,
                    "malformed `path` attribute input".to_string(),
                    "Write the attribute in one of the forms Rust documents for it.",
                ));
                continue;
            }
            let inline_names: Vec<String> = decl.container.iter().map(|s| interner.get(*s).to_string()).collect();
            match modules::module_file(&file_path, dir_owner, &inline_names, interner.get(decl.name), decl.path_attr.as_deref(), decl.span) {
                Ok(f) => {
                    // The candidate this declaration did not take: once it
                    // appears a cold resolve rejects the pair (L0502), so
                    // the body patch checks it (`module_alts`).
                    if decl.path_attr.is_none() {
                        let (flat, nested) = modules::module_candidates(&file_path, dir_owner, &inline_names, interner.get(decl.name));
                        tables.module_alts.push(if f == flat { nested } else { flat });
                    }
                    let fcanon = modules::canonical_string(&f);
                    let ftext = match shared.text_by_path.get(&fcanon) {
                        Some(t) => t.clone(),
                        None => match std::fs::read_to_string(&f) {
                            Ok(t) => {
                                shared.text_by_path.insert(fcanon, t.clone());
                                t
                            }
                            Err(e) => {
                                diags.push(Diag::new(
                                    "L0503",
                                    decl.span,
                                    format!("cannot read module file {}: {e}", f.display()),
                                    "Check the file exists and is readable.",
                                ));
                                continue;
                            }
                        },
                    };
                    let file_id = shared.file_id(&f, child);
                    discs.push(FileDisc {
                        path: f,
                        text: ftext,
                        file_id,
                        module: child,
                        dir_owner: decl.path_attr.is_some(),
                        parent: Some(ParentDecl {
                            disc: di,
                            container: decl.container.clone(),
                            lo: decl.span.lo,
                            macro_use: decl.macro_use,
                        }),
                        lexed: None,
                        outline: scan::Outline::default(),
                        use_sites: None,
                    });
                    queue.push(discs.len() - 1);
                }
                Err(d) => diags.push(d),
            }
        }
    }
    inline_modules
}

/// Binds one outline's textual macro names in the macro namespace:
/// in their defining module, and `#[macro_export]` ones also at the
/// crate root. Expansion itself runs in the expander; these bindings
/// serve import resolution and path queries.
fn bind_outline_macros(
    outline: &scan::Outline,
    disc_module: ModuleId,
    inline_modules: &FxMap<Vec<Sym>, ModuleId>,
    job: &CrateJob,
    tables: &mut ResolvedTables,
    interner: &Interner,
) {
    for m in &outline.macros {
        let module = inline_modules.get(&m.container_path).copied().unwrap_or(disc_module);
        let hash = macro_hash(&job.input, &job.flat_prefix, interner, module, tables, m.name);
        let def = DefId { krate: job.input.crate_ids.local, hash };
        if tables.def_info.contains_key(&def) {
            continue;
        }
        // A definition's binding in its own module is textual only
        // (`macro_textual_binds`; rustc has none), and it never takes
        // the place of a real binding. `#[macro_export]` puts a real,
        // public one at the crate root, which replaces a textual-only
        // binding of the name there; an exported root definition has
        // only that one.
        if !(m.exported && module == job.root_module) && tables.lookup(module, Namespace::Macro, m.name).is_none() {
            tables.insert(module, Namespace::Macro, m.name, Bind { target: Target::Def(def), vis: VisKind::Priv, rank: 2, def_module: module });
            tables.macro_textual_binds.insert((module, m.name), def);
        }
        if m.exported {
            let root = job.root_module;
            if tables.macro_textual_binds.remove(&(root, m.name)).is_some() {
                tables.maps[root.0 as usize][ns_index(Namespace::Macro)].remove(&m.name);
                tables.touch(root, m.name);
            }
            tables.insert(root, Namespace::Macro, m.name, Bind { target: Target::Def(def), vis: VisKind::Pub, rank: 2, def_module: root });
        }
        tables.def_info.insert(def, DefInfo { kind: ResKind::Macro, flat: m.name, module, vis: VisKind::Priv });
        if job.flat_prefix.is_empty() {
            tables.flat[ns_index(Namespace::Macro)].insert(m.name, def);
        }
    }
}

/// Lexes and outlines one discovered file (the original text), creates
/// its module edges, and binds its macro names.
#[allow(clippy::too_many_arguments)]
fn process_disc_orig(
    di: usize,
    discs: &mut Vec<FileDisc>,
    queue: &mut Vec<usize>,
    tables: &mut ResolvedTables,
    shared: &mut SharedFiles,
    cache: &mut ResolveCache,
    job: &CrateJob,
    interner: &Interner,
    diags: &mut Vec<Diag>,
    std_asks: &mut StdPlan,
) {
    let (text, file_id, module) = (discs[di].text.clone(), discs[di].file_id, discs[di].module);
    // Raw tokens and outline from the per-file cache when the text
    // stands (keyed by canonical path plus module, as in discovery).
    let file_key = job.file_key(&cache.canon(&discs[di].path), module);
    let text_hash = hash_str(&text);
    // The root file's std splice is the driver's, not the user's ask.
    let own = match job.input.std_splice_lo {
        Some(lo) if file_id == FileId(0) => text.get(..lo as usize).unwrap_or(&text),
        _ => &text,
    };
    *std_asks = std_asks.or(cache.std_asks(&file_key, text_hash, file_id, own));
    let lexed = match cache.raw(&file_key, text_hash, file_id) {
        Some(l) => l,
        None => match lex_file(&text, file_id, interner) {
            Ok(l) => {
                cache.put_raw(&file_key, text_hash, file_id, &l);
                l
            }
            Err(d) => {
                diags.push(d);
                return;
            }
        },
    };
    let outline = match cache.outline(&file_key, text_hash, file_id) {
        Some(o) => o,
        None => {
            let o = scan::outline(&lexed, interner);
            cache.put_outline(&file_key, text_hash, file_id, &o);
            o
        }
    };
    let inline = outline_mods(di, &outline, &lexed.strings.clone(), discs, queue, tables, shared, job, interner, diags);
    bind_outline_macros(&outline, module, &inline, job, tables, interner);
    discs[di].use_sites = cache.use_sites(&file_key, text_hash, file_id, &tables.modules[module.0 as usize].path);
    discs[di].outline = outline;
    discs[di].lexed = Some(lexed);
}

/// One macro definition in this crate, located in one file's token
/// stream (the original tokens, or the expanded tokens for a
/// macro-generated definition).
struct MacroSrc {
    name: Sym,
    exported: bool,
    /// Index into the environment's owned source list.
    owned: usize,
    /// The disc (file) the definition was found in.
    disc: usize,
    /// The definition's module path from this crate's root.
    module_path: Vec<Sym>,
    /// The inline container path inside that file.
    container: Vec<Sym>,
    /// Byte offset of `macro_rules` in its file (textual order point).
    lo: u32,
}

/// The token range of one `macro_rules!` definition in a flat token
/// list, from its outline token index: through its closing group and
/// an optional `;`.
fn macro_tok_range(toks: &[crate::lexer::Token], start: usize) -> (usize, usize) {
    use crate::lexer::Tok;
    let mut i = start + 3; // macro_rules ! name
    let open = toks.get(i).map(|t| t.tok);
    let close = match open {
        Some(Tok::LParen) => Tok::RParen,
        Some(Tok::LBracket) => Tok::RBracket,
        Some(Tok::LBrace) => Tok::RBrace,
        _ => return (start, (start + 3).min(toks.len())),
    };
    let mut depth = 0usize;
    while i < toks.len() {
        match toks[i].tok {
            t if Some(t) == open => depth += 1,
            t if t == close => {
                depth -= 1;
                if depth == 0 {
                    i += 1;
                    break;
                }
            }
            Tok::Eof => break,
            _ => {}
        }
        i += 1;
    }
    if toks.get(i).map(|t| t.tok) == Some(Tok::Semi) {
        i += 1;
    }
    (start, i)
}

/// One module-level `use` naming a single name, for the macro
/// path-binding fixpoint.
#[derive(Clone)]
struct UseSite {
    module: Vec<Sym>,
    /// Where the binding is visible: None for `pub`, else the module
    /// path it is visible within (`pub(crate)` is the root, a private
    /// `use` its own module).
    vis: Option<Vec<Sym>>,
    segs: Vec<Sym>,
    leading: bool,
    alias: Sym,
    /// True for `use a::b::*`: `segs` is the glob target's written
    /// path and `alias` is unused.
    glob: bool,
    /// Byte offset of the `use` keyword in its file's stream (the
    /// textual scope point of a `use name;`).
    lo: u32,
}

/// The symbol a path-segment token stands for in a `use` tree.
fn use_seg_sym(tok: crate::lexer::Tok, interner: &Interner) -> Option<Sym> {
    use crate::lexer::Tok;
    Some(match tok {
        Tok::Ident(s) => s,
        Tok::SelfLower => interner.intern("self"),
        Tok::Super => interner.intern("super"),
        Tok::Crate => interner.intern("crate"),
        Tok::SelfUpper => interner.intern("Self"),
        _ => return None,
    })
}

/// Splits a `use` group `{ a, b::{c, d} }` body into its comma parts
/// (commas inside subgroups are hidden inside `Delim` trees).
fn comma_chunks(trees: &[crate::lexer::TokenTree]) -> Vec<Vec<crate::lexer::TokenTree>> {
    use crate::lexer::{Tok, TokenTree};
    let mut out: Vec<Vec<TokenTree>> = vec![Vec::new()];
    for t in trees {
        if matches!(t, TokenTree::Token(tok) if tok.tok == Tok::Comma) {
            out.push(Vec::new());
        } else if let Some(last) = out.last_mut() {
            last.push(t.clone());
        }
    }
    out.into_iter().filter(|c| !c.is_empty()).collect()
}

/// Parses the body trees of one `use` item (without `use` and `;`)
/// into single-name and glob sites under `prefix`. The expander does
/// not track a glob macro import inside one file, but a public glob
/// re-export must still seed dependent crates and other files.
#[allow(clippy::too_many_arguments)]
fn parse_use_trees(
    trees: &[crate::lexer::TokenTree],
    prefix: &[Sym],
    leading: bool,
    module: &[Sym],
    vis: &Option<Vec<Sym>>,
    lo: u32,
    interner: &Interner,
    out: &mut Vec<UseSite>,
) {
    use crate::lexer::{Delim, Tok, TokenTree};
    let tok = |i: usize| match trees.get(i) {
        Some(TokenTree::Token(t)) => Some(t.tok),
        _ => None,
    };
    let mut segs: Vec<Sym> = prefix.to_vec();
    let mut leading = leading;
    let mut i = 0;
    if tok(0) == Some(Tok::PathSep) {
        leading = true;
        i = 1;
    }
    // A group with no path before it: `use {a, b};` or `use ::{a, b};`.
    if let Some(TokenTree::Delim(Delim::Brace, inner, _)) = trees.get(i) {
        for chunk in comma_chunks(inner) {
            parse_use_trees(&chunk, &segs, leading, module, vis, lo, interner, out);
        }
        return;
    }
    let mut alias: Option<Sym> = None;
    let mut underscore = false;
    loop {
        let Some(sym) = tok(i).and_then(|t| use_seg_sym(t, interner)) else { return };
        segs.push(sym);
        i += 1;
        match tok(i) {
            Some(Tok::PathSep) => {
                i += 1;
                match trees.get(i) {
                    Some(TokenTree::Delim(Delim::Brace, inner, _)) => {
                        for chunk in comma_chunks(inner) {
                            parse_use_trees(&chunk, &segs, leading, module, vis, lo, interner, out);
                        }
                        return;
                    }
                    Some(TokenTree::Token(t)) if t.tok == Tok::Star => {
                        out.push(UseSite { module: module.to_vec(), vis: vis.clone(), segs, leading, alias: Sym(0), glob: true, lo });
                        return;
                    }
                    _ => continue,
                }
            }
            Some(Tok::As) => {
                match tok(i + 1) {
                    Some(Tok::Ident(s)) => alias = Some(s),
                    Some(Tok::Underscore) => underscore = true,
                    _ => return,
                }
                break;
            }
            _ => break,
        }
    }
    if underscore || segs.is_empty() {
        return;
    }
    let self_sym = interner.intern("self");
    let alias = alias
        .unwrap_or_else(|| if segs.len() > 1 && *segs.last().unwrap() == self_sym { segs[segs.len() - 2] } else { *segs.last().unwrap() });
    out.push(UseSite { module: module.to_vec(), vis: vis.clone(), segs, leading, alias, glob: false, lo });
}

/// Scans one file's item-level `use` items (top level and inline
/// module bodies) from its token trees.
fn scan_use_sites(trees: &[crate::lexer::TokenTree], module: &[Sym], interner: &Interner, out: &mut Vec<UseSite>) {
    use crate::lexer::{Delim, Tok, TokenTree};
    let tok = |trees: &[TokenTree], i: usize| match trees.get(i) {
        Some(TokenTree::Token(t)) => Some(t.tok),
        _ => None,
    };
    let mut i = 0;
    let private = Some(module.to_vec());
    let mut vis = private.clone();
    while i < trees.len() {
        match tok(trees, i) {
            Some(Tok::Pub) => {
                vis = None;
                i += 1;
                if let Some(TokenTree::Delim(Delim::Paren, inner, _)) = trees.get(i) {
                    vis = restricted_vis(inner, module);
                    i += 1;
                }
            }
            // `use<..>` is a precise-capturing bound in a signature
            // (`-> impl Send + use<>`), never a `use` item.
            Some(Tok::Use) if tok(trees, i + 1) != Some(Tok::Lt) => {
                let start = i + 1;
                let mut end = start;
                while end < trees.len() && tok(trees, end) != Some(Tok::Semi) {
                    end += 1;
                }
                let lo = match &trees[i] {
                    TokenTree::Token(t) => t.span.lo,
                    _ => 0,
                };
                parse_use_trees(&trees[start..end], &[], false, module, &vis, lo, interner, out);
                i = end + 1;
                vis = private.clone();
            }
            Some(Tok::Mod) => {
                if let (Some(name), Some(TokenTree::Delim(Delim::Brace, inner, _))) =
                    (tok(trees, i + 1).and_then(|t| use_seg_sym(t, interner)), trees.get(i + 2))
                {
                    let inner = inner.clone();
                    let mut sub = module.to_vec();
                    sub.push(name);
                    scan_use_sites(&inner, &sub, interner, out);
                    i += 3;
                } else {
                    i += 1;
                }
                vis = private.clone();
            }
            Some(_) | None => {
                // At item level a brace group belongs to an item the
                // pattern above does not open (fn body, impl, const):
                // the trees are nested, so skipping one tree skips it.
                if !matches!(tok(trees, i), Some(Tok::Pound)) {
                    vis = private.clone();
                }
                i += 1;
            }
        }
    }
}

/// The module path a `pub(..)` restriction makes a `use` visible
/// within: `crate`, `self`, `super`, or `in` a path from those. A form
/// this does not read (a bad path) keeps it private to `module`.
fn restricted_vis(inner: &[crate::lexer::TokenTree], module: &[Sym]) -> Option<Vec<Sym>> {
    use crate::lexer::{Tok, TokenTree};
    let toks: Vec<Tok> = inner.iter().filter_map(|t| if let TokenTree::Token(t) = t { Some(t.tok) } else { None }).collect();
    let segs: Vec<Tok> = toks.into_iter().filter(|t| *t != Tok::PathSep).collect();
    let segs = if segs.first() == Some(&Tok::In) { &segs[1..] } else { &segs[..] };
    let mut out = match segs.first() {
        Some(Tok::Crate) => Vec::new(),
        Some(Tok::SelfLower) => module.to_vec(),
        Some(Tok::Super) => module[..module.len().saturating_sub(1)].to_vec(),
        _ => return Some(module.to_vec()),
    };
    for t in &segs[1..] {
        match t {
            Tok::Super => {
                out.pop();
            }
            Tok::Ident(s) => out.push(*s),
            _ => return Some(module.to_vec()),
        }
    }
    Some(out)
}

/// Rewrites `$crate` in the template groups of one macro definition
/// to the defining crate's magic segment (a plain identifier token,
/// which transcription copies verbatim). Matcher groups keep their
/// tokens: `$crate` is illegal there and `compile_macro` rejects it.
fn rewrite_dollar_crate(tokens: &[crate::lexer::Token], magic: Sym) -> Vec<crate::lexer::Token> {
    use crate::lexer::{Tok, Token, TokenTree};
    fn rewrite(trees: &[TokenTree], magic: Sym) -> Vec<TokenTree> {
        let mut out = Vec::new();
        let mut i = 0;
        while i < trees.len() {
            let is_crate = matches!(trees.get(i), Some(TokenTree::Token(t)) if t.tok == Tok::Dollar)
                && matches!(trees.get(i + 1), Some(TokenTree::Token(t)) if t.tok == Tok::Crate);
            if is_crate {
                let span = match trees[i] {
                    TokenTree::Token(t) => t.span,
                    _ => unreachable!(),
                };
                out.push(TokenTree::Token(Token { tok: Tok::Ident(magic), span }));
                i += 2;
                continue;
            }
            match &trees[i] {
                TokenTree::Delim(d, inner, span) => out.push(TokenTree::Delim(*d, rewrite(inner, magic), *span)),
                t => out.push(t.clone()),
            }
            i += 1;
        }
        out
    }
    let (trees, balanced) = crate::lexer::build_trees(tokens);
    if !balanced {
        return tokens.to_vec();
    }
    // Arms at the top level of a definition body; the seed slice is
    // `macro_rules ! name <group>`, so rewrite inside that group per
    // arm: matcher group, `=>`, template group.
    let mut top = trees;
    if let Some(TokenTree::Delim(d, body, span)) = top.get(3).cloned() {
        let mut arms = Vec::new();
        let mut j = 0;
        while j < body.len() {
            match (body.get(j), body.get(j + 2)) {
                (Some(matcher @ TokenTree::Delim(..)), Some(TokenTree::Delim(td, template, tspan))) => {
                    arms.push(matcher.clone());
                    if let Some(arrow) = body.get(j + 1) {
                        arms.push(arrow.clone());
                    }
                    arms.push(TokenTree::Delim(*td, rewrite(template, magic), *tspan));
                    j += 3;
                }
                _ => {
                    arms.push(body[j].clone());
                    j += 1;
                }
            }
        }
        top[3] = TokenTree::Delim(d, arms, span);
    }
    let mut out = Vec::new();
    crate::lexer::flatten_trees(&top, &mut out);
    out
}

/// Renames the macro in one definition token slice (`macro_rules !
/// name ...`) to a re-export binding's alias, when they differ. The
/// expander registers a seed under the name its tokens define, so an
/// aliased re-export must carry the alias in its tokens.
fn rename_macro_token(tokens: &mut [crate::lexer::Token], alias: Sym) {
    use crate::lexer::Tok;
    if let Some(t) = tokens.get_mut(2)
        && let Tok::Ident(name) = t.tok
        && name != alias
    {
        t.tok = Tok::Ident(alias);
    }
}

/// Where a binding a glob (or a module re-export) copies is visible:
/// no further than either the `use` or the source binding.
fn glob_vis(site_vis: &Option<Vec<Sym>>, src_vis: Option<Vec<Sym>>) -> Option<Vec<Sym>> {
    match (site_vis, src_vis) {
        (None, v) => v,
        (Some(g), Some(v)) if v.len() > g.len() => Some(v),
        (g, _) => g.clone(),
    }
}

/// One binding a glob or module re-export at use site `si` copies into
/// `key`, under the re-export fixpoint's writer rule (`MacroEnv::build`):
/// a name another site owns stays, and a different macro from another
/// glob makes it ambiguous. Returns true when a table changed.
#[allow(clippy::too_many_arguments)]
fn copy_bind(
    si: usize,
    key: (Vec<Sym>, Sym),
    src: usize,
    vis: Option<Vec<Sym>>,
    from_ambiguous: bool,
    writer: &mut FxMap<(Vec<Sym>, Sym), (usize, bool)>,
    bindings: &mut FxMap<(Vec<Sym>, Sym), usize>,
    bvis: &mut FxMap<(Vec<Sym>, Sym), Option<Vec<Sym>>>,
    ambiguous: &mut FxMap<(Vec<Sym>, Sym), ()>,
) -> bool {
    let mut changed = false;
    match writer.get(&key).copied() {
        Some((w, other_glob)) if w != si => {
            if other_glob && bindings.get(&key) != Some(&src) && ambiguous.insert(key, ()).is_none() {
                changed = true;
            }
        }
        _ => {
            if bindings.get(&key) != Some(&src) {
                writer.insert(key.clone(), (si, true));
                bindings.insert(key.clone(), src);
                changed = true;
            }
            if bvis.get(&key) != Some(&vis) {
                bvis.insert(key.clone(), vis);
                changed = true;
            }
            if from_ambiguous && ambiguous.insert(key, ()).is_none() {
                changed = true;
            }
        }
    }
    changed
}

/// Sorts binding keys by module path text, then name text, so seeds
/// and exports come out in one order whatever the map's order.
fn keys_sort(keys: &mut [&(Vec<Sym>, Sym)], interner: &Interner) {
    keys.sort_by(|a, b| {
        let pa: Vec<&str> = a.0.iter().map(|s| interner.get(*s)).collect();
        let pb: Vec<&str> = b.0.iter().map(|s| interner.get(*s)).collect();
        pa.cmp(&pb).then_with(|| interner.get(a.1).cmp(interner.get(b.1)))
    });
}

/// The macro environment of one expansion round: every macro
/// definition visible by path in this crate, as expander seeds. Seeds
/// come from this crate's `#[macro_export]` definitions (crate root),
/// direct dependencies' exported definitions (`dep::` paths), and
/// public-single-name re-exports settled by a fixpoint over the
/// crate's `use` items (`crate::m::name` paths). Textual visibility
/// is the splice step's job (below); seeds never enter textual scope.
struct MacroEnv {
    seeds: Vec<crate::expand::MacroSeed>,
    /// Every macro source of this crate, for the exports other crates
    /// receive.
    own: Vec<OwnedMacroSource>,
    own_exported: Vec<bool>,
    /// Sources visible at this crate's root by path, under binding
    /// names (own exports plus root re-exports).
    root_sources: Vec<OwnedMacroSource>,
    /// Every source by owned index (own sources, then dependency
    /// exports), for textual splice materialization.
    owned_all: Vec<OwnedMacroSource>,
    srcs: Vec<MacroSrc>,
    /// Dependency exported sources by extern name, as owned indices.
    dep_owned: FxMap<String, Vec<usize>>,
    /// Textual macro sources inherited by each disc, in textual order.
    inherited: Vec<Vec<usize>>,
    /// Per disc: (declaration byte offset, textual sources, is an
    /// `extern crate` item) for each `#[macro_use]` file module or
    /// `#[macro_use] extern crate` in the original file: the sources
    /// join textual scope right after that item.
    after_mods: Vec<Vec<(u32, Vec<usize>, bool)>>,
    /// Per disc: extra seeds for macros this file's glob imports
    /// bring into plain-name scope (`use crate::prelude::*;`).
    glob_seeds: Vec<Vec<crate::expand::MacroSeed>>,
    /// Per disc: the textual macro scope for `use name;` imports, by
    /// owned source index.
    scopes: Vec<FileMacroScope<usize>>,
    /// The raw streams' `use` sites `build` scanned, by disc: the files keep them
    /// (`FileDisc::use_sites`, `ResolveCache::put_use_sites`).
    scanned: Vec<(usize, std::sync::Arc<[UseSite]>)>,
}

impl MacroEnv {
    /// Builds the environment from the files discovered so far (the
    /// original outlines, plus macro definitions the previous
    /// expansion round generated).
    fn build(
        job: &CrateJob,
        discs: &[FileDisc],
        expanded: &[Option<std::sync::Arc<lexer::Lexed>>],
        dep_exports: &[(String, Vec<OwnedMacroSource>)],
        tables: &ResolvedTables,
        interner: &Interner,
    ) -> MacroEnv {
        // All sources: this crate's definitions first, then the
        // exported definitions of direct source dependencies.
        let mut owned: Vec<OwnedMacroSource> = Vec::new();
        let mut srcs: Vec<MacroSrc> = Vec::new();
        // One source per definition occurrence, by (disc, byte
        // offset): the same definition seen through the original and
        // the expanded outline is one source, but two definitions of
        // one name in one module are two (the later shadows).
        let mut seen_defs: FxMap<(usize, u32), ()> = FxMap::default();
        let mut own_exported: Vec<bool> = Vec::new();
        let macro_rules = interner.intern("macro_rules");
        for (di, disc) in discs.iter().enumerate() {
            let base_path = tables.modules[disc.module.0 as usize].path.clone();
            let mut collect = |outline: &scan::Outline, lexed: &lexer::Lexed, owned: &mut Vec<OwnedMacroSource>| {
                for m in &outline.macros {
                    let mut mod_path = base_path.clone();
                    mod_path.extend(m.container_path.iter().copied());
                    if seen_defs.insert((di, m.span.lo), ()).is_some() {
                        continue;
                    }
                    let key = (mod_path, m.name);
                    let (lo, hi) = macro_tok_range(&lexed.tokens, m.container.1);
                    srcs.push(MacroSrc {
                        name: m.name,
                        exported: m.exported,
                        owned: owned.len(),
                        disc: di,
                        module_path: key.0.clone(),
                        container: m.container_path.clone(),
                        lo: m.span.lo,
                    });
                    own_exported.push(m.exported);
                    let (tokens, strings) = own_def_strings(&lexed.tokens[lo..hi], &lexed.strings);
                    owned.push(OwnedMacroSource { name: m.name, tokens, strings: std::sync::Arc::new(strings), magic: job.magic, path: Vec::new() });
                }
            };
            if let Some(orig) = &disc.lexed {
                collect(&disc.outline, orig, &mut owned);
            }
            if let Some(Some(exp)) = expanded.get(di)
                && exp.tokens.iter().any(|t| t.tok == crate::lexer::Tok::Ident(macro_rules))
            {
                // Only `outline.macros` feeds this collect, and a
                // macro definition needs a `macro_rules`
                // identifier token; most expanded files have none.
                let o = scan::outline(exp, interner);
                collect(&o, exp, &mut owned);
            }
        }
        let own = owned.clone();
        // Path bindings: (module path, name) -> owned index.
        let mut bindings: FxMap<(Vec<Sym>, Sym), usize> = FxMap::default();
        for s in &srcs {
            if s.exported {
                bindings.insert((Vec::new(), s.name), s.owned);
            }
        }
        let mut dep_owned: FxMap<String, Vec<usize>> = FxMap::default();
        // The module paths dependencies export macros under (and their
        // prefixes): real modules a module re-export can name.
        let mut dep_paths: FxMap<Vec<Sym>, ()> = FxMap::default();
        for (extern_name, sources) in dep_exports {
            let sym = interner.intern(extern_name);
            let mut idxs = Vec::new();
            dep_paths.insert(vec![sym], ());
            let first = owned.len();
            for src in sources {
                let mut path = vec![sym];
                path.extend_from_slice(&src.path);
                for k in 2..=path.len() {
                    dep_paths.insert(path[..k].to_vec(), ());
                }
                // One macro the dependency exports under several paths
                // is one source here, so two globs that bring it are no
                // conflict (rustc: the same item).
                let same = |o: &OwnedMacroSource| {
                    o.name == src.name
                        && o.magic == src.magic
                        && o.tokens.len() == src.tokens.len()
                        && o.tokens.iter().zip(&src.tokens).all(|(a, b)| a.tok == b.tok && a.span == b.span)
                };
                let idx = match (first..owned.len()).find(|&j| same(&owned[j])) {
                    Some(j) => j,
                    None => {
                        owned.push(src.clone());
                        owned.len() - 1
                    }
                };
                bindings.insert((path, src.name), idx);
                // `#[macro_use] extern crate` and textual scope take
                // only the root exports.
                if src.path.is_empty() && !idxs.contains(&idx) {
                    idxs.push(idx);
                }
            }
            dep_owned.insert(extern_name.clone(), idxs);
        }
        // The re-export fixpoint over this crate's use items.
        // Use sites only feed that fixpoint and the glob seeds:
        // with no macro source in this crate or its dependencies
        // the bindings stay empty whatever the use items say, and
        // a stream with no `use` token has no sites. Either way
        // the token trees (the expensive part) are not built.
        let no_sources = srcs.is_empty() && dep_exports.iter().all(|(_, s)| s.is_empty());
        // Each file's sites on the pool (its token trees are the cost: about
        // 1000 files a tsgo resolve), then in disc order: its raw stream's, which
        // the file keeps (`FileDisc::use_sites`: a warm resolve scans only the
        // files that changed), and its expanded stream's. The flag marks a raw
        // stream scanned now.
        let scan = |tokens: &[crate::lexer::Token], base: &[Sym]| {
            let mut mine: Vec<UseSite> = Vec::new();
            if tokens.iter().any(|t| t.tok == crate::lexer::Tok::Use) {
                let (trees, _) = crate::lexer::build_trees(tokens);
                scan_use_sites(&trees, base, interner, &mut mine);
            }
            mine
        };
        type Sites = (std::sync::Arc<[UseSite]>, bool, Vec<UseSite>);
        let file_sites = |di: &usize| -> Sites {
            let (di, disc) = (*di, &discs[*di]);
            let base = &tables.modules[disc.module.0 as usize].path;
            let (orig, now) = match (&disc.use_sites, &disc.lexed) {
                (Some(s), _) => (s.clone(), false),
                (None, Some(l)) => (scan(&l.tokens, base).into(), true),
                (None, None) => (std::sync::Arc::from([]), false),
            };
            let exp = match expanded.get(di) {
                Some(Some(e)) => scan(&e.tokens, base),
                _ => Vec::new(),
            };
            (orig, now, exp)
        };
        let per_disc: Vec<Sites> = if no_sources {
            (0..discs.len()).map(|_| (std::sync::Arc::from([]), false, Vec::new())).collect()
        } else {
            par_map(&(0..discs.len()).collect::<Vec<_>>(), file_sites)
        };
        let sites: Vec<&UseSite> = per_disc.iter().flat_map(|d| d.0.iter().chain(&d.2)).collect();
        let site_disc: Vec<usize> = per_disc.iter().enumerate().flat_map(|(di, d)| std::iter::repeat_n(di, d.0.len() + d.2.len())).collect();
        let scanned = per_disc.iter().enumerate().filter(|(_, d)| d.1).map(|(di, d)| (di, d.0.clone())).collect();
        let owned_names: Vec<Sym> = owned.iter().map(|o| o.name).collect();
        let (inherited, after_mods, scopes) = textual_env(job, discs, expanded, &srcs, &dep_owned, &owned_names, tables, interner);
        // The macro a one-segment `use name;` names through textual
        // scope at its `use` (rustc reads that scope before the module's
        // namespace; a `macro_rules!` definition is not in the latter).
        let site_textual: Vec<Option<usize>> = sites
            .iter()
            .zip(&site_disc)
            .map(|(site, &di)| {
                if site.glob || site.leading || site.segs.len() != 1 {
                    return None;
                }
                let base = &tables.modules[discs[di].module.0 as usize].path;
                let container = site.module.strip_prefix(base.as_slice())?;
                scopes[di].at(container, site.lo, site.segs[0])
            })
            .collect();
        let crate_sym = interner.intern("crate");
        let self_sym = interner.intern("self");
        let super_sym = interner.intern("super");
        // An ambiguous binding (see `ambiguous` below) resolves to
        // nothing, so a use of it never picks one of the globs' macros.
        let resolve_use = |segs: &[Sym],
                           leading: bool,
                           from: &[Sym],
                           textual: Option<usize>,
                           bindings: &FxMap<(Vec<Sym>, Sym), usize>,
                           bvis: &FxMap<(Vec<Sym>, Sym), Option<Vec<Sym>>>,
                           ambiguous: &FxMap<(Vec<Sym>, Sym), ()>|
         -> Option<usize> {
            let last = *segs.last()?;
            let middle = &segs[..segs.len() - 1];
            // A binding the use cannot see (rustc E0603) binds nothing.
            let by = |m: &[Sym]| {
                let key = (m.to_vec(), last);
                let visible = bvis.get(&key).is_none_or(|v| v.as_ref().is_none_or(|v| from.starts_with(v)));
                if ambiguous.contains_key(&key) || !visible { None } else { bindings.get(&key).copied() }
            };
            if segs.len() == 1 && !leading {
                return textual.or_else(|| by(from));
            }
            if segs[0] == crate_sym {
                let m = &middle[1.min(middle.len())..];
                return by(m);
            }
            if segs[0] == self_sym {
                let mut m = from.to_vec();
                m.extend_from_slice(&middle[1.min(middle.len())..]);
                return by(&m);
            }
            if segs[0] == super_sym {
                let supers = segs.iter().take_while(|&&s| s == super_sym).count();
                let keep = from.len().saturating_sub(supers);
                let mut m: Vec<Sym> = from[..keep].to_vec();
                m.extend_from_slice(&middle[supers.min(middle.len())..]);
                return by(&m);
            }
            if leading {
                return by(middle);
            }
            let mut m = from.to_vec();
            m.extend_from_slice(middle);
            by(&m).or_else(|| by(middle))
        };
        // The bindings-space module path a glob target names.
        let resolve_glob_module = |segs: &[Sym], leading: bool, from: &[Sym], bindings: &FxMap<(Vec<Sym>, Sym), usize>| -> Vec<Sym> {
            if segs.first() == Some(&crate_sym) {
                return segs[1..].to_vec();
            }
            if segs.first() == Some(&self_sym) {
                let mut m = from.to_vec();
                m.extend_from_slice(&segs[1..]);
                return m;
            }
            if segs.first() == Some(&super_sym) {
                let supers = segs.iter().take_while(|&&s| s == super_sym).count();
                let keep = from.len().saturating_sub(supers);
                let mut m: Vec<Sym> = from[..keep].to_vec();
                m.extend_from_slice(&segs[supers..]);
                return m;
            }
            if leading {
                return segs.to_vec();
            }
            let has = |m: &[Sym]| bindings.keys().any(|(bm, _)| bm == m);
            if has(segs) {
                return segs.to_vec();
            }
            let mut m = from.to_vec();
            m.extend_from_slice(segs);
            if has(&m) {
                return m;
            }
            segs.to_vec()
        };
        // Which use site wrote each binding (`writer`): a glob only
        // overwrites a binding it wrote itself, and an explicit use
        // overwrites a glob's binding but not another explicit one.
        // Two globs that bring different macros under one name make
        // that name ambiguous (`ambiguous`, rustc E0659 at a use), and
        // a glob of an ambiguous name passes the ambiguity on; an
        // explicit use clears it. Without the writer rule the two
        // globs overwrote each other every round and the fixpoint
        // never ended: one such crate hung the daemon for every later
        // request.
        let mut writer: FxMap<(Vec<Sym>, Sym), (usize, bool)> = FxMap::default();
        let mut ambiguous: FxMap<(Vec<Sym>, Sym), ()> = FxMap::default();
        // Where each binding is visible (see `UseSite::vis`); none
        // recorded is public (`#[macro_export]`, a dependency's).
        let mut bvis: FxMap<(Vec<Sym>, Sym), Option<Vec<Sym>>> = FxMap::default();
        let seen_from = |bvis: &FxMap<(Vec<Sym>, Sym), Option<Vec<Sym>>>, key: &(Vec<Sym>, Sym), from: &[Sym]| {
            bvis.get(key).is_none_or(|v| v.as_ref().is_none_or(|v| from.starts_with(v)))
        };
        let module_at: FxMap<&[Sym], ModuleId> = tables
            .modules
            .iter()
            .enumerate()
            .filter(|(_, m)| m.krate_root == job.root_module)
            .map(|(i, m)| (m.path.as_slice(), ModuleId(i as u32)))
            .collect();
        // A module a module re-export copies macros from: one a
        // dependency exports macros under (`dep::prelude`). Only those:
        // every file's expander compiles every seed, and this crate's
        // own module aliases (preludes re-exporting each other) would
        // multiply the seeds. Copies land under alias paths, which are
        // not dependency paths, so a copy is never copied again.
        let real_module = |m: &[Sym]| dep_paths.contains_key(m);
        // The dependency module a `use` path names (`dep::m`, or
        // `crate::m` when `m` names a dependency at the root), if any.
        let module_target = |segs: &[Sym]| -> Option<Vec<Sym>> {
            if matches!(segs.first(), Some(f) if *f == crate_sym || *f == self_sym || *f == super_sym) {
                return None;
            }
            real_module(segs).then(|| segs.to_vec())
        };
        // Names an explicit `use` binds in each module: they shadow a
        // glob's module of the same name.
        let explicit: FxMap<(Vec<Sym>, Sym), ()> = sites.iter().filter(|s| !s.glob).map(|s| ((s.module.clone(), s.alias), ())).collect();
        let mut rounds = 0usize;
        loop {
            let mut changed = false;
            for (si, site) in sites.iter().enumerate() {
                // A private glob binds nothing another module reads by
                // path in practice, and copying every macro of a
                // prelude-style module into each importer made this
                // fixpoint (and its seeds) quadratic on big crates; its
                // plain-name scope comes from `glob_seeds` below.
                if site.glob && site.vis.as_deref() == Some(site.module.as_slice()) {
                    continue;
                }
                if site.glob {
                    let target = resolve_glob_module(&site.segs, site.leading, &site.module, &bindings);
                    // The glob's own names, and the macros of the
                    // dependency submodules it brings (`pub use
                    // dep::effect::*;` makes `effect::typeparser::m` reach
                    // `dep::effect::typeparser::m`), unless a module or an
                    // explicit `use` binds that submodule's name here (it
                    // shadows the glob).
                    let names: Vec<((Vec<Sym>, Sym), (Vec<Sym>, Sym), usize, Option<Vec<Sym>>)> = bindings
                        .iter()
                        .filter(|((m, _), _)| {
                            if *m == target {
                                return true;
                            }
                            if m.len() <= target.len() || !m.starts_with(&target) || !real_module(m) {
                                return false;
                            }
                            let first = m[target.len()];
                            let mut child = site.module.clone();
                            child.push(first);
                            !module_at.contains_key(child.as_slice()) && !explicit.contains_key(&(site.module.clone(), first))
                        })
                        .filter(|(k, _)| seen_from(&bvis, k, &site.module))
                        .map(|(k, src)| {
                            let mut path = site.module.clone();
                            path.extend_from_slice(&k.0[target.len()..]);
                            ((path, k.1), k.clone(), *src, bvis.get(k).cloned().flatten())
                        })
                        .collect();
                    for (key, from_key, src, src_vis) in names {
                        let from_ambiguous = ambiguous.contains_key(&from_key);
                        changed |= copy_bind(si, key, src, glob_vis(&site.vis, src_vis), from_ambiguous, &mut writer, &mut bindings, &mut bvis, &mut ambiguous);
                    }
                    continue;
                }
                // A `use` of a module (`pub use dep::prelude;`) binds the
                // macros under that module at the alias path too, as a
                // glob would (an explicit use of a name still wins). A
                // private one is skipped like a private glob: every file's
                // `use crate::m;` would copy all of `m`'s macros.
                if site.vis.as_deref() != Some(site.module.as_slice())
                    && let Some(target) = module_target(&site.segs)
                {
                    let mut base = site.module.clone();
                    base.push(site.alias);
                    if !base.starts_with(&target) {
                        let copies: Vec<((Vec<Sym>, Sym), (Vec<Sym>, Sym), usize, Option<Vec<Sym>>)> = bindings
                            .iter()
                            .filter(|((m, _), _)| m.starts_with(&target) && real_module(m))
                            .filter(|(k, _)| seen_from(&bvis, k, &site.module))
                            .map(|(k, src)| {
                                let mut path = base.clone();
                                path.extend_from_slice(&k.0[target.len()..]);
                                ((path, k.1), k.clone(), *src, bvis.get(k).cloned().flatten())
                            })
                            .collect();
                        for (key, from_key, src, src_vis) in copies {
                            let from_ambiguous = ambiguous.contains_key(&from_key);
                            changed |= copy_bind(si, key, src, glob_vis(&site.vis, src_vis), from_ambiguous, &mut writer, &mut bindings, &mut bvis, &mut ambiguous);
                        }
                    }
                }
                if let Some(src) = resolve_use(&site.segs, site.leading, &site.module, site_textual[si], &bindings, &bvis, &ambiguous) {
                    let key = (site.module.clone(), site.alias);
                    let may = match writer.get(&key) {
                        None => true,
                        Some(&(w, w_glob)) => w == si || w_glob,
                    };
                    if may && (bindings.get(&key) != Some(&src) || writer.get(&key) != Some(&(si, false))) {
                        writer.insert(key.clone(), (si, false));
                        bindings.insert(key.clone(), src);
                        ambiguous.remove(&key);
                        changed = true;
                    }
                    if may && bvis.get(&key) != Some(&site.vis) {
                        bvis.insert(key.clone(), site.vis.clone());
                        changed = true;
                    }
                }
            }
            if !changed {
                break;
            }
            // Each binding settles once its sources settle, so the
            // rounds are bounded by the chain depth. A compile that
            // never ends is worse than an internal error.
            rounds += 1;
            assert!(rounds <= 4 * sites.len() + 16, "macro re-export fixpoint did not settle");
        }
        // A path call walks the modules of its path, and each one must
        // be visible from the caller (rustc E0603): the module path a
        // walk through `path` stays visible within is the narrowest
        // scope on it (they nest, so the longest).
        let narrower = |a: Option<Vec<Sym>>, b: Option<Vec<Sym>>| match (a, b) {
            (Some(a), Some(b)) => Some(if a.len() >= b.len() { a } else { b }),
            (a, b) => a.or(b),
        };
        let path_scope = |path: &[Sym], vis: Option<Vec<Sym>>| -> Option<Vec<Sym>> {
            let mut out = vis;
            for k in 1..=path.len() {
                let (Some(&m), Some(&parent)) = (module_at.get(&path[..k]), module_at.get(&path[..k - 1])) else { continue };
                let up = &path[..k - 1];
                let scope = match &tables.modules[m.0 as usize].vis {
                    VisKind::Pub => None,
                    VisKind::Crate => Some(Vec::new()),
                    VisKind::Priv => Some(up.to_vec()),
                    VisKind::Super => Some(up[..up.len().saturating_sub(1)].to_vec()),
                    VisKind::In(p) => Some(
                        tables
                            .resolve_in_path(&VisKind::in_path(*p, interner), parent, interner)
                            .map_or_else(|| up.to_vec(), |r| tables.modules[r.0 as usize].path.clone()),
                    ),
                };
                out = narrower(out, scope);
            }
            out
        };
        let mut seeds = Vec::with_capacity(bindings.len());
        let mut keys: Vec<&(Vec<Sym>, Sym)> = bindings.keys().collect();
        keys_sort(&mut keys, interner);
        // An ambiguous name gets no path seed: a path to it finds
        // nothing, so it is a reject, never a pick of one glob.
        for key in keys.into_iter().filter(|k| !ambiguous.contains_key(*k)) {
            let src = &owned[bindings[key]];
            let mut tokens = if src.magic != job.magic { rewrite_dollar_crate(&src.tokens, src.magic) } else { src.tokens.clone() };
            rename_macro_token(&mut tokens, key.1);
            seeds.push(crate::expand::MacroSeed {
                path: key.0.clone(),
                tokens,
                strings: src.strings.clone(),
                import_into: None,
                ambiguous: false,
                visible_in: path_scope(&key.0, bvis.get(key).cloned().flatten()),
            });
        }
        // Macros visible by path from outside this crate (its own
        // `#[macro_export]` definitions, root re-exports, and public
        // re-exports in public modules: `dep::prelude::args`), under
        // their binding names and module paths: what dependent crates
        // receive. Only a binding public along its whole path does.
        let mut root_sources: Vec<OwnedMacroSource> = Vec::new();
        let mut root_keys: Vec<&(Vec<Sym>, Sym)> = bindings
            .keys()
            .filter(|k| {
                !ambiguous.contains_key(*k)
                    && bvis.get(*k).is_none_or(Option::is_none)
                    && (k.0.is_empty() || (module_at.contains_key(k.0.as_slice()) && path_scope(&k.0, None).is_none()))
            })
            .collect();
        keys_sort(&mut root_keys, interner);
        for key in root_keys {
            let src = owned[bindings[key]].clone();
            root_sources.push(OwnedMacroSource { name: key.1, path: key.0.clone(), ..src });
        }
        // Glob imports in each file bring the target module's
        // path-visible macros into plain-name scope in the importing
        // module (the expander's prescan does not track globs, so the
        // worklist seeds them per file).
        // A name two globs in one module bring as different macros, or
        // one glob brings from an ambiguous binding, gets one ambiguous
        // seed instead: a plain call of it is the L0507 error. A glob
        // that brings a macro whose name std also exports (`assert`)
        // is ambiguous with the std macro of that name the same way.
        let mut glob_seeds: Vec<Vec<crate::expand::MacroSeed>> = Vec::with_capacity(discs.len());
        for d in &per_disc {
            // (importing module, name) -> (glob target, source, ambiguous), in first-seen order.
            let mut found: Vec<((Vec<Sym>, Sym), (Vec<Sym>, usize, bool))> = Vec::new();
            for site in d.0.iter().chain(&d.2) {
                if !site.glob {
                    continue;
                }
                let target = resolve_glob_module(&site.segs, site.leading, &site.module, &bindings);
                let mut names: Vec<(Sym, usize)> = bindings
                    .iter()
                    .filter(|(k, _)| k.0 == target && seen_from(&bvis, k, &site.module))
                    .map(|((_, n), src)| (*n, *src))
                    .collect();
                names.sort_by(|a, b| interner.get(a.0).cmp(interner.get(b.0)));
                for (name, src_idx) in names {
                    let amb = ambiguous.contains_key(&(target.clone(), name))
                        || crate::expand::builtin::is_std_macro_name(interner.get(name));
                    let key = (site.module.clone(), name);
                    match found.iter_mut().find(|(k, _)| *k == key) {
                        Some((_, (_, s, a))) => *a |= amb || *s != src_idx,
                        None => found.push((key, (target.clone(), src_idx, amb))),
                    }
                }
            }
            let mut extra: Vec<crate::expand::MacroSeed> = Vec::new();
            for ((module, name), (target, src_idx, amb)) in found {
                let src = &owned[src_idx];
                let mut tokens = if src.magic != job.magic { rewrite_dollar_crate(&src.tokens, src.magic) } else { src.tokens.clone() };
                rename_macro_token(&mut tokens, name);
                let visible_in = path_scope(&target, bvis.get(&(target.clone(), name)).cloned().flatten());
                extra.push(crate::expand::MacroSeed {
                    path: target,
                    tokens,
                    strings: src.strings.clone(),
                    import_into: Some(module),
                    ambiguous: amb,
                    visible_in,
                });
            }
            glob_seeds.push(extra);
        }
        MacroEnv { seeds, own, own_exported, root_sources, owned_all: owned, srcs, dep_owned, inherited, after_mods, glob_seeds, scopes, scanned }
    }

    /// The extern crate names a `::name::m!` path can start with here
    /// (`ExpandCtx::extern_crates`): every dependency, and the magic
    /// segment of every crate below this one.
    fn extern_crates(&self, interner: &Interner) -> Vec<Sym> {
        self.dep_owned.keys().map(|n| interner.intern(n)).collect()
    }

    /// The macro sources dependent crates see at this crate's root:
    /// its `#[macro_export]` definitions plus any macro re-exported
    /// at the root by a public `use` (glob or single-name).
    fn exported_sources(&self) -> Vec<OwnedMacroSource> {
        if !self.root_sources.is_empty() {
            return self.root_sources.clone();
        }
        self.own.iter().zip(&self.own_exported).filter(|(_, e)| **e).map(|(s, _)| s.clone()).collect()
    }

    /// The seeds of `seeds` and of its glob seeds that disc `di`'s expansion can reach
    /// (`expand::reach_seeds`; `index` is `seeds`'), from what it reads: its own tokens and
    /// the macro sources `splice` puts in them (`src_idents`: each source's identifiers, once
    /// for all files).
    fn reach(&self, di: usize, disc: &FileDisc, index: &crate::expand::SeedReach, src_idents: &[Option<Vec<Sym>>], interner: &Interner) -> [Vec<usize>; 2] {
        let Some(lexed) = &disc.lexed else { return Default::default() };
        let after = self.after_mods.get(di).map(Vec::as_slice).unwrap_or(&[]);
        let srcs = self.inherited.get(di).into_iter().flatten().chain(after.iter().flat_map(|(_, s, _)| s));
        let extra = crate::expand::SeedReach::new(self.glob_seeds.get(di).map_or(&[][..], Vec::as_slice), interner);
        crate::expand::reach_seeds([index, &extra], &lexed.tokens, srcs.map(|&i| src_idents[i].as_deref()), interner)
    }

    /// Splices the textual macro definitions visible in one file into
    /// its original token stream: inherited definitions just after
    /// any inner attributes (they are visible to the whole file), and
    /// each `#[macro_use]` file module's definitions right after its
    /// `mod` item (visible from that point on, as in Rust). The
    /// expander registers them in textual order and strips them from
    /// its output, so the parsed items are unaffected. Source
    /// strings are remapped into this file's string table.
    fn splice(&self, di: usize, lexed: lexer::Lexed, magic: Sym) -> lexer::Lexed {
        use crate::lexer::{Tok, Token};
        let start_srcs: &[usize] = self.inherited.get(di).map(Vec::as_slice).unwrap_or(&[]);
        let after: &[(u32, Vec<usize>, bool)] = self.after_mods.get(di).map(Vec::as_slice).unwrap_or(&[]);
        if start_srcs.is_empty() && after.is_empty() {
            return lexed;
        }
        let mut strings = lexed.strings.clone();
        let mut offsets: FxMap<usize, u32> = FxMap::default();
        let materialize = |idx: usize, strings: &mut Vec<String>, offsets: &mut FxMap<usize, u32>| -> Vec<Token> {
            let src = &self.owned_all[idx];
            let base = if src.magic != magic { rewrite_dollar_crate(&src.tokens, src.magic) } else { src.tokens.clone() };
            let offset = *offsets.entry(idx).or_insert_with(|| {
                let at = strings.len() as u32;
                strings.extend(src.strings.iter().cloned());
                at
            });
            base.iter()
                .map(|t| {
                    let mut tok = t.tok;
                    tok.shift_strings(offset);
                    Token { tok, span: t.span }
                })
                .collect()
        };
        // Insertion positions in the original token list.
        let toks = &lexed.tokens;
        let mut start_pos = 0usize;
        while toks.get(start_pos).map(|t| t.tok) == Some(Tok::Pound) && toks.get(start_pos + 1).map(|t| t.tok) == Some(Tok::Bang) {
            // One inner attribute `#![...]`: skip to its closing bracket.
            let mut depth = 0usize;
            let mut i = start_pos + 2;
            while i < toks.len() {
                match toks[i].tok {
                    Tok::LBracket => depth += 1,
                    Tok::RBracket => {
                        depth -= 1;
                        if depth == 0 {
                            i += 1;
                            break;
                        }
                    }
                    Tok::Eof => break,
                    _ => {}
                }
                i += 1;
            }
            start_pos = i;
        }
        let mut inserts: Vec<(usize, Vec<Token>)> = Vec::new();
        if !start_srcs.is_empty() {
            let mut all = Vec::new();
            for &idx in start_srcs {
                all.extend(materialize(idx, &mut strings, &mut offsets));
            }
            inserts.push((start_pos, all));
        }
        for (lo, srcs, is_extern) in after {
            let want = if *is_extern { Tok::Extern } else { Tok::Mod };
            let Some(mod_at) = toks.iter().position(|t| t.tok == want && t.span.lo == *lo) else { continue };
            let Some(semi) = toks[mod_at..].iter().position(|t| t.tok == Tok::Semi) else { continue };
            let mut all = Vec::new();
            for &idx in srcs {
                all.extend(materialize(idx, &mut strings, &mut offsets));
            }
            inserts.push((mod_at + semi + 1, all));
        }
        inserts.sort_by_key(|(pos, _)| *pos);
        let mut out: Vec<Token> = Vec::with_capacity(toks.len());
        let mut cur = 0usize;
        for (pos, add) in inserts {
            out.extend_from_slice(&toks[cur..pos.min(toks.len())]);
            cur = pos.min(toks.len());
            out.extend(add);
        }
        out.extend_from_slice(&toks[cur..]);
        lexer::Lexed { tokens: out, strings }
    }
}

/// Resolves one crate of a workspace session into the shared tables:
/// discovery, the expansion rounds of section 6.1 (cfg names, seeded
/// macro expansion, macro-generated module edges), the import
/// worklist, the path rewrite, and flattening.
fn resolve_one(
    job: &CrateJob,
    tables: &mut ResolvedTables,
    shared: &mut SharedFiles,
    cache: &mut ResolveCache,
    dep_exports: &[(String, Vec<OwnedMacroSource>)],
    client: &crate::expand::ClientView,
    interner: &Interner,
    known: &Known,
) -> Result<CrateOut, OneError> {
    let input = &job.input;
    let mut timings: Vec<(&'static str, f64)> = Vec::new();
    let mut last = std::time::Instant::now();
    macro_rules! lap {
        ($n:expr) => {{
            let now = std::time::Instant::now();
            timings.push(($n, (now - last).as_secs_f64() * 1e3));
            last = now;
        }};
    }
    let mut std_asks = StdPlan::default();
    let mut diags: Vec<Diag> = Vec::new();
    let root_file_id = shared.file_id(&input.root_path, job.root_module);
    let mut discs: Vec<FileDisc> = vec![FileDisc {
        path: input.root_path.clone(),
        text: input.root_text.clone(),
        file_id: root_file_id,
        module: job.root_module,
        dir_owner: true,
        parent: None,
        lexed: None,
        outline: scan::Outline::default(),
        use_sites: None,
    }];
    let mut queue: Vec<usize> = vec![0];
    while let Some(di) = queue.pop() {
        process_disc_orig(di, &mut discs, &mut queue, tables, shared, cache, job, interner, &mut diags, &mut std_asks);
    }
    if !diags.is_empty() {
        return Err(OneError { diags, seen: seen_of(&discs), std_asks });
    }
    lap!("resolve: discovery");
    // Unknown cfg names (L0520) are checked on the original tokens of
    // every file before expansion can strip the item that carries one, on
    // the pool; the first error in disc order is the answer.
    let checked = par_map(&discs, |disc| disc.lexed.as_ref().map_or(Ok(()), |orig| check_cfg_names(orig, &input.env, interner)));
    if let Some(Err(d)) = checked.into_iter().find(Result::is_err) {
        return Err(OneError { diags: vec![d], seen: seen_of(&discs), std_asks });
    }
    // Expansion rounds (6.1): expand every file with the macro
    // environment the outlines now prove, then look for module edges
    // the expansions generated; repeat until a round adds no file.
    let mut expanded: Vec<Option<std::sync::Arc<lexer::Lexed>>> = Vec::new();
    // The `hash_lexed` of each expanded stream, when the expansion
    // cache knows it (a hit, or a store this round).
    let mut exp_known: Vec<Option<u64>> = Vec::new();
    // Outside inputs the latest round's expansion of each file read.
    let mut file_deps: Vec<Vec<crate::expand::Dep>> = Vec::new();
    let mut menv = MacroEnv {
        seeds: Vec::new(),
        own: Vec::new(),
        own_exported: Vec::new(),
        root_sources: Vec::new(),
        owned_all: Vec::new(),
        srcs: Vec::new(),
        dep_owned: FxMap::default(),
        inherited: Vec::new(),
        after_mods: Vec::new(),
        glob_seeds: Vec::new(),
        scopes: Vec::new(),
        scanned: Vec::new(),
    };
    for round in 0..8 {
        expanded.resize_with(discs.len(), || None);
        menv = MacroEnv::build(job, &discs, &expanded, dep_exports, tables, interner);
        // Expansion is per file once the macro environment is built,
        // so it runs in parallel across files (as in the perf
        // landing); the first error in disc order is the answer.
        let module_paths: Vec<Vec<Sym>> = discs.iter().map(|d| tables.modules[d.module.0 as usize].path.clone()).collect();
        let indices: Vec<usize> = (0..discs.len()).collect();
        // A daemon session keeps each file's expansion: a file whose
        // text and other expansion inputs stand takes it back instead
        // of expanding again (a signature edit used to re-expand every
        // file of the crate). An expansion that read outside data (`env!`,
        // the `include!` family) comes back only while each of those reads
        // reads the same (`expand::deps_stale_in`).
        let keep = !cache.one_shot;
        let env_hash = if keep { expansion_env_hash(&menv, job, input, client, interner) } else { 0 };
        // Each macro source's hash and the seeds it names, and each file's reachable seeds
        // (`MacroEnv::reach`) and key, on the pool.
        let seed_index = keep.then(|| crate::expand::SeedReach::new(&menv.seeds, interner));
        let (owned_hashes, src_idents): (Vec<u64>, Vec<Option<Vec<Sym>>>) = match &seed_index {
            Some(_) => par_map(&menv.owned_all, |o| (hash_tokens(&o.tokens, &o.strings) ^ o.magic.0 as u64, crate::expand::stream_idents(&o.tokens, interner)))
                .into_iter()
                .unzip(),
            None => Default::default(),
        };
        let file_keys: Vec<Option<String>> = discs.iter().map(|d| (keep && d.lexed.is_some()).then(|| job.file_key(&cache.canon(&d.path), d.module))).collect();
        let (reaches, exp_keys): (Vec<[Vec<usize>; 2]>, Vec<Option<(String, u64, u64)>>) = par_map(&indices, |&di| {
            let (Some(x), Some(key)) = (&seed_index, &file_keys[di]) else { return Default::default() };
            let d = &discs[di];
            let reach = menv.reach(di, d, x, &src_idents, interner);
            let input_hash = expansion_input_hash(env_hash, &menv, &reach, &owned_hashes, di, &module_paths[di], &d.path, interner);
            (reach, Some((key.clone(), hash_str(&d.text), input_hash)))
        })
        .into_iter()
        .unzip();
        // The raw streams' `use` sites this round scanned stay with their files.
        for (di, sites) in std::mem::take(&mut menv.scanned) {
            if let Some((key, text_hash, _)) = &exp_keys[di] {
                cache.put_use_sites(key, *text_hash, discs[di].file_id, module_paths[di].clone(), sites.clone());
            }
            discs[di].use_sites = Some(sites);
        }
        // Each stored expansion unpacks on the pool (`PackedLexed`).
        let exp_hits: Vec<std::sync::Mutex<Option<(std::sync::Arc<lexer::Lexed>, Vec<crate::expand::Dep>, u64)>>> = {
            let cache: &ResolveCache = cache;
            par_map(&(0..exp_keys.len()).collect::<Vec<_>>(), |&di| {
                std::sync::Mutex::new(exp_keys[di].as_ref().and_then(|(key, th, ih)| {
                    cache.expanded(key, *th, discs[di].file_id, *ih, &|deps| crate::expand::deps_stale_in(deps, &input.cargo_env, client))
                }))
            })
        };
        exp_known.clear();
        exp_known.extend(exp_hits.iter().map(|h| h.lock().unwrap().as_ref().map(|x| x.2)));
        // The cache's oracle: every hit also expands fresh (`check_expansion_hit`).
        let check = keep && std::env::var_os("LUST_CHECK_EXPKEY").is_some_and(|v| v == "1");
        let results = par_map(&indices, |&di| -> Result<(Option<std::sync::Arc<lexer::Lexed>>, Vec<crate::expand::Dep>), Diag> {
            let hit = match exp_hits[di].lock().unwrap().take() {
                Some((l, deps, _)) if !check => return Ok((Some(l), deps)),
                hit => hit,
            };
            let (orig, text, path) = match &discs[di].lexed {
                Some(l) => (l.clone(), discs[di].text.clone(), discs[di].path.clone()),
                None => return Ok((None, Vec::new())),
            };
            let ects = crate::expand::ExpandCtx {
                interner,
                known,
                file_path: match input.display_root.as_deref().and_then(|r| path.strip_prefix(r).ok()) {
                    Some(rel) => rel.to_string_lossy().to_string(),
                    None => path.to_string_lossy().to_string(),
                },
                real_path: path.clone(),
                cargo_env: input.cargo_env.clone(),
                src: &text,
                cfg: expand_cfg(&input.env),
                module_path: module_paths[di].clone(),
                crate_name: Some(input.crate_name.clone()),
                extern_crates: menv.extern_crates(interner),
                client,
            };
            let spliced = menv.splice(di, orig, job.magic);
            // The crate's seeds, then this file's glob seeds, borrowed: a copy
            // of every seed per file cost more than the expansion of most files.
            let extra = menv.glob_seeds.get(di).map_or(&[][..], Vec::as_slice);
            if check {
                // The seeds the expander takes, from the stream it reads, are among the key's.
                let lists = [&crate::expand::SeedReach::new(&menv.seeds, interner), &crate::expand::SeedReach::new(extra, interner)];
                let read = crate::expand::reach_seeds(lists, &spliced.tokens, std::iter::empty(), interner);
                let key = &reaches[di];
                assert!(
                    read.iter().zip(key).all(|(r, k)| r.iter().all(|i| k.binary_search(i).is_ok())),
                    "expkey-check: {}: the expander reaches seeds {read:?}, the key {key:?}",
                    path.display()
                );
            }
            let fresh = crate::expand::expand_lexed_seeded_extra(spliced, &ects, &menv.seeds, extra);
            if let Some((l, deps, _)) = hit {
                check_expansion_hit(&l, &deps, &fresh, &path);
                return Ok((Some(l), deps));
            }
            fresh.map(|(l, deps)| (Some(std::sync::Arc::new(l)), deps))
        });
        file_deps.resize_with(discs.len(), Vec::new);
        // The new expansions the cache keeps (those before the first error, as a store in
        // file order kept them), packed and hashed on the pool.
        let stop = results.iter().position(Result::is_err).unwrap_or(results.len());
        let to_store: Vec<(usize, &lexer::Lexed)> = results[..stop]
            .iter()
            .enumerate()
            .filter_map(|(di, r)| match r {
                Ok((Some(l), _)) if exp_keys[di].is_some() && exp_known[di].is_none() => Some((di, &**l)),
                _ => None,
            })
            .collect();
        let packed = par_map(&to_store, |&(_, l)| (lexer::PackedLexed::pack(l), hash_lexed(l)));
        for (&(di, _), (stream, exp_hash)) in to_store.iter().zip(packed) {
            if let (Some((key, th, ih)), Ok((_, deps))) = (&exp_keys[di], &results[di]) {
                cache.put_expanded(key, *th, discs[di].file_id, *ih, stream, exp_hash, deps);
                exp_known[di] = Some(exp_hash);
            }
        }
        for (di, r) in results.into_iter().enumerate() {
            match r {
                Ok((l, deps)) => {
                    expanded[di] = l;
                    file_deps[di] = deps;
                }
                Err(d) => return Err(OneError { diags: vec![d], seen: seen_of(&discs), std_asks }),
            }
        }
        // Macro-generated module edges and macro definitions.
        // Only the outline's mods and macros are read here; a
        // stream with no `mod` token and no `macro_rules`
        // identifier has neither, so the outline is the default.
        // The outlines are made on the pool, then read in disc order.
        let before = discs.len();
        let mut new_queue: Vec<usize> = Vec::new();
        let macro_rules = interner.intern("macro_rules");
        let outlines = par_map(&indices, |&di| {
            let exp = expanded[di].as_ref()?;
            Some(match exp.tokens.iter().any(|t| t.tok == crate::lexer::Tok::Mod || t.tok == crate::lexer::Tok::Ident(macro_rules)) {
                true => scan::outline(exp, interner),
                false => scan::Outline::default(),
            })
        });
        for (di, outline) in outlines.into_iter().enumerate() {
            let (Some(exp), Some(outline)) = (expanded[di].as_ref(), outline) else { continue };
            let disc_module = discs[di].module;
            let inline = outline_mods(di, &outline, &exp.strings, &mut discs, &mut new_queue, tables, shared, job, interner, &mut diags);
            bind_outline_macros(&outline, disc_module, &inline, job, tables, interner);
        }
        while let Some(di) = new_queue.pop() {
            process_disc_orig(di, &mut discs, &mut new_queue, tables, shared, cache, job, interner, &mut diags, &mut std_asks);
        }
        if !diags.is_empty() {
            return Err(OneError { diags, seen: seen_of(&discs), std_asks });
        }
        // Files the expansions generated need their cfg names checked
        // and their own expansion in the next round.
        for disc in &discs[before..] {
            if let Some(orig) = &disc.lexed
                && let Err(d) = check_cfg_names(orig, &input.env, interner)
            {
                return Err(OneError { diags: vec![d], seen: seen_of(&discs), std_asks });
            }
        }
        if discs.len() == before {
            break;
        }
        if round == 7 {
            return Err(OneError {
                diags: vec![Diag::new(
                    "L0801",
                    Span::default(),
                    "macro-generated module discovery did not settle after 8 rounds".to_string(),
                    "This is a lust bug; report it.",
                )],
                seen: seen_of(&discs),
                std_asks,
            });
        }
    }
    // The local crate's files for its `FileExpander` (stored at the end).
    let keep_expander = job.root_module == ROOT_MODULE && !job.std_splice && !cache.one_shot;
    let seen_files: Vec<(FileId, (usize, Vec<Sym>, PathBuf))> = match keep_expander {
        true => discs.iter().enumerate().map(|(di, d)| (d.file_id, (di, tables.modules[d.module.0 as usize].path.clone(), d.path.clone()))).collect(),
        false => Vec::new(),
    };
    // Each file's textual macro scope by definition, for `use name;`
    // imports (`macro_scope`). A dependency's macro has no local def.
    let mut def_of: Vec<Option<DefId>> = vec![None; menv.owned_all.len()];
    for s in &menv.srcs {
        if let Some(module) = tables.module_by_path_in(job.root_module, &s.module_path) {
            let hash = macro_hash(input, &job.flat_prefix, interner, module, tables, s.name);
            def_of[s.owned] = Some(DefId { krate: input.crate_ids.local, hash });
        }
    }
    for (di, scope) in menv.scopes.iter().enumerate() {
        tables.macro_scopes.insert(discs[di].file_id, (discs[di].module, scope.map(|i| def_of[i])));
    }
    // Parse the expanded files in parallel, in FileId order. Every file
    // parses again from its expanded stream: a cache of parsed Asts held
    // a copy of the crate's Ast (240 MB of a tsgo front image) to save
    // about 20 ms of parsing per full resolve. The stream's hash keys the
    // file's final chunk; a one-shot cache stores none, so it needs no
    // hashes (0 keys nothing).
    let mut order: Vec<usize> = (0..discs.len()).collect();
    order.sort_by_key(|&di| discs[di].file_id.0);
    let keep = !cache.one_shot;
    let exp_hashes = if keep {
        par_map(&order, |&di| match (exp_known.get(di).copied().flatten(), expanded[di].as_ref(), discs[di].lexed.as_ref()) {
            (Some(h), Some(_), _) => h,
            (_, Some(l), _) => hash_lexed(l),
            (_, None, Some(l)) => hash_lexed(l),
            (_, None, None) => hash_lexed(&lexer::Lexed { tokens: Vec::new(), strings: Vec::new() }),
        })
    } else {
        vec![0; order.len()]
    };
    // The stream each file parses from, shared with the expansion cache:
    // a parse reads it and copies nothing.
    let streams: Vec<std::sync::Mutex<Option<std::sync::Arc<lexer::Lexed>>>> =
        expanded.into_iter().zip(discs.iter_mut()).map(|(e, d)| std::sync::Mutex::new(e.or_else(|| d.lexed.take().map(std::sync::Arc::new)))).collect();
    // Each file's cache key (the canonical path memo is the cache's own,
    // so serial).
    let keys: Vec<String> = order.iter().map(|&di| job.file_key(&cache.canon(&discs[di].path), discs[di].module)).collect();
    let positions: Vec<usize> = (0..order.len()).collect();
    // Each file's works: one, or one per item segment (see below).
    let parsed = par_map(&positions, |&pos| -> Result<Vec<FileWork>, Diag> {
        let di = order[pos];
        let disc = &discs[di];
        let lexed = streams[di].lock().unwrap().take().unwrap_or_else(|| std::sync::Arc::new(lexer::Lexed { tokens: Vec::new(), strings: Vec::new() }));
        // A one-shot resolve parses a big file in item segments in
        // parallel, and each segment is its own work through strip,
        // register, rewrite, and flatten. The per-file caches of a
        // daemon session key whole files, so it parses whole files. On
        // any segment error the file parses again in one piece: a cut
        // can move where an error in bad text shows (an item cut before
        // its missing `;` ends at the cut), and the answer must be the
        // one-piece answer.
        let segments = if keep { vec![0..lexed.tokens.len()] } else { item_segments(&lexed.tokens, interner) };
        let asts: Vec<Ast> = if segments.len() == 1 {
            vec![parser::parse(&lexed, interner, known)?]
        } else {
            // Later segments start under the file's inner allows, as
            // the one-piece parse scopes them.
            let seed = parser::leading_allows(&lexed, interner, known);
            match par_map(&segments, |r| {
                if r.start == 0 {
                    parser::parse_items(&lexed, r.clone(), interner, known)
                } else {
                    parser::parse_items_seeded(&lexed, r.clone(), interner, known, &seed)
                }
            })
            .into_iter()
            .collect()
            {
                Ok(asts) => asts,
                Err(_) => vec![parser::parse(&lexed, interner, known)?],
            }
        };
        let text_hash = hash_str(&disc.text);
        Ok(asts
            .into_iter()
            .enumerate()
            .map(|(k, ast)| FileWork {
                path: disc.path.clone(),
                file_id: disc.file_id,
                ast,
                module: disc.module,
                segment: k,
                key: keys[pos].clone(),
                text_hash,
                exp_hash: exp_hashes[pos],
            })
            .collect())
    });
    // No step reads the discs after the parse: their paths and texts move to the session's
    // map (a copy cost milliseconds of the crate's text).
    let seen: Vec<(PathBuf, String, FileId)> = discs.into_iter().map(|d| (d.path, d.text, d.file_id)).collect();
    let mut works: Vec<FileWork> = Vec::with_capacity(order.len());
    for r in parsed {
        match r {
            Ok(ws) => works.extend(ws),
            Err(d) => return Err(OneError { diags: vec![d], seen, std_asks }),
        }
    }
    lap!("resolve: expand+parse");
    // The module of every item list, by (works index, inline path).
    let mut list_module: FxMap<ItemListKey, ModuleId> = FxMap::default();
    for (fi, w) in works.iter().enumerate() {
        list_module.insert((fi, Vec::new()), w.module);
    }
    for (fi, w) in works.iter().enumerate() {
        collect_inline_modules(&w.ast.items, fi, &[], tables, &mut list_module);
    }
    // Strip, register, and run the import worklist.
    let mut inner_diags: Vec<Diag> = Vec::new();
    let mut imports: Vec<Import> = Vec::new();
    // Adt disambiguator counts over every Adt the shared tables
    // already hold (earlier crates of this workspace included),
    // counted in one pass here instead of per Adt in register.
    let mut adt_counts: FxMap<Sym, u32> = FxMap::default();
    for info in tables.def_info.values() {
        if info.kind == ResKind::Adt {
            *adt_counts.entry(info.flat).or_insert(0) += 1;
        }
    }
    // Counts store "seen so far"; the register entry call turns the
    // first sighting into disambiguator 0, so seed with count-1 by
    // storing the next disambiguator minus one... see the entry use:
    // entry().and_modify(+1).or_insert(0) yields the stored value,
    // so a name seen k times must start at k-1 (absent when k == 0).
    adt_counts.retain(|_, c| {
        *c -= 1;
        true
    });
    // The names a file's top-level item list defines. The item segments
    // of a big file are one item list, so the set spans them: a duplicate
    // in two segments is a duplicate (see `item_segments`).
    let mut file_names: FxMap<(u8, Sym), ()> = FxMap::default();
    for (fi, w) in works.iter_mut().enumerate() {
        if w.segment == 0 {
            file_names.clear();
        }
        strip_file(w, fi, input, interner, &list_module, tables, &mut inner_diags);
        register_items(
            &mut w.ast.items,
            w.module,
            fi,
            &[],
            input,
            &job.flat_prefix,
            interner,
            tables,
            &list_module,
            &mut imports,
            &mut adt_counts,
            &mut file_names,
            &mut inner_diags,
        );
    }
    lap!("resolve: strip+register");
    match run_imports(tables, &imports, interner) {
        Ok(ds) => inner_diags.extend(ds),
        Err(e) => inner_diags.push(Diag::new("L0506", Span::default(), e, "This is a lust bug; report it.")),
    }
    // A glob of a std module binds nothing; keep its path so the
    // rewrite pass can tell a non-prelude std type it imports (W-STD-A).
    tables.std_globs.clear();
    for imp in &imports {
        if let crate::resolve::imports::ImportKind::Glob { path } = &imp.kind
            && path.first().is_some_and(|s| matches!(interner.get(*s), "std" | "core" | "alloc"))
        {
            tables.std_globs.push((imp.module, path.clone()));
        }
    }
    let mdr_imports = crate::resolve::mdr::on().then(|| crate::resolve::mdr::imports_part(tables, &imports, interner));
    lap!("resolve: imports");
    if !inner_diags.is_empty() {
        return Err(OneError { diags: inner_diags, seen, std_asks });
    }
    for w in works.iter() {
        collect_assoc_vis(&w.ast, &w.ast.items, w.module, interner, tables);
        check_vis_restrictions(&w.ast.items, w.module, interner, tables, &mut inner_diags);
        check_stmt_vis_restrictions(&w.ast, w.module, interner, tables, &mut inner_diags);
        collect_stmt_impl_vis(&w.ast, w.module, interner, tables, &mut inner_diags);
    }
    if !inner_diags.is_empty() {
        return Err(OneError { diags: inner_diags, seen, std_asks });
    }
    lap!("resolve: visibility");
    // The tables are frozen now. Every file whose cached final
    // chunk was stored under this exact epoch (and expanded
    // stream) rewrites to that chunk, so its rewrite walk is
    // skipped and the chunk is taken over at flatten time.
    // B3 step 3: a cached chunk stands while the module and file structure is
    // fixed and every answer its rewrite read is the same (resolve/mdr.rs
    // `still_valid`). `LUST_B3_READS=0` keys chunks on the session-wide
    // rewrite epoch instead, as before. A one-shot resolve keeps no chunks,
    // so it needs neither.
    let local_names = tables.local_named_set();
    let by_reads = !cache.one_shot && std::env::var_os("LUST_B3_READS").is_none_or(|v| v != "0");
    let epoch = if cache.one_shot || by_reads { 0 } else { tables.rewrite_epoch() };
    let structure = by_reads.then(|| {
        let files: Vec<&str> = works.iter().map(|w| w.key.as_str()).collect();
        crate::resolve::mdr::structure(tables, &files)
    });
    lap!("resolve: names+structure");
    let mut answers = crate::resolve::mdr::Answers::new(tables);
    // The hit decisions share one answer memo, so they run in order, after
    // the answers they read are computed on the pool; the chunks they take
    // are copied out in parallel.
    // A stored chunk is a part of the session's merged Ast, of the resolve that made it.
    let merged = cache.merged.as_ref().filter(|m| m.1 != 0);
    let placed = |c: &FinalChunk| merged.is_some_and(|m| m.1 == c.generation);
    if let Some(s) = structure {
        answers.prefill(
            works.iter().filter_map(|w| {
                let c = cache.peek(&w.key, w.text_hash, w.file_id)?.final_chunk.as_ref()?;
                (c.exp_hash == w.exp_hash && placed(c)).then_some(c.deps.as_ref()?)
            }),
            s,
        );
    }
    let mut hit_refs: Vec<Option<&FinalChunk>> = Vec::with_capacity(works.len());
    for w in works.iter() {
        let hit = cache.peek(&w.key, w.text_hash, w.file_id).and_then(|e| e.final_chunk.as_ref()).filter(|c| {
            c.exp_hash == w.exp_hash
                && placed(c)
                && match structure {
                    Some(s) => c.deps.as_ref().is_some_and(|d| crate::resolve::mdr::still_valid(d, &mut answers, &local_names, s)),
                    None => !cache.one_shot && c.epoch == epoch,
                }
        });
        hit_refs.push(hit);
    }
    let observe = crate::resolve::mdr::on();
    let final_hits: Vec<Option<FinalChunk>> = par_map(&hit_refs, |c| c.map(|c| c.clone_for_hit(observe)));
    drop(hit_refs);
    lap!("resolve: epoch");
    // Rewrite paths to flat names, checking visibility. The tables
    // are frozen at this point and each work's Ast is its own (a file,
    // or an item segment of one), so the pass runs in parallel on the
    // compiler's pool; diagnostics merge back in work order. Each work
    // sits behind its own lock, taken once, so one task can own it
    // mutably. A work whose final chunk is cached is skipped.
    let rewritten = final_hits.iter().filter(|h| h.is_none()).count();
    let mut rw_reads: Vec<Option<crate::resolve::mdr::FileReads>> = vec![None; works.len()];
    let rw_diags: Vec<Diag> = {
        let tables: &ResolvedTables = tables;
        let cells: Vec<(usize, std::sync::Mutex<&mut FileWork>)> = works
            .iter_mut()
            .enumerate()
            .filter(|(fi, _)| final_hits[*fi].is_none())
            .map(|(fi, w)| (fi, std::sync::Mutex::new(w)))
            .collect();
        // An observed resolve records what each file's rewrite reads.
        crate::resolve::mdr::recording(by_reads || crate::resolve::mdr::on());
        let per_work = par_map(&cells, |(fi, cell)| {
            let mut w = cell.lock().unwrap();
            let module = w.module;
            let mut rw = Rewrite {
                tables,
                interner,
                list_module: &list_module,
                local_names: &local_names,
                diags: Vec::new(),
                gen_params: Vec::new(),
                std_splice_lo: input.std_splice_lo,
                gen_floor: 0,
            };
            crate::resolve::mdr::begin();
            rw.file_items(&mut w.ast, *fi, module, &[]);
            (*fi, rw.diags, crate::resolve::mdr::end())
        });
        crate::resolve::mdr::recording(false);
        let mut diags = Vec::new();
        for (fi, d, reads) in per_work {
            diags.extend(d);
            rw_reads[fi] = reads;
        }
        diags
    };
    if !rw_diags.is_empty() {
        return Err(OneError { diags: rw_diags, seen, std_asks });
    }
    // Each fresh chunk's answers, for its reuse by reads next time.
    let mut rw_deps: Vec<Option<crate::resolve::mdr::ChunkDeps>> = rw_reads
        .into_iter()
        .map(|r| {
            let r = r?;
            Some(match structure {
                Some(s) => crate::resolve::mdr::deps_of(r, &mut answers, &local_names, s),
                None => crate::resolve::mdr::ChunkDeps { reads: r, ..Default::default() },
            })
        })
        .collect();
    drop(answers);
    lap!("resolve: rewrite");
    // ---- Flatten: inline module bodies splice into top-level items;
    // mod, use, and extern crate items drop. Each fn's module is
    // recorded here from its origin (file plus inline module path):
    // keying it by flat name loses impl methods, whose names are not
    // module-mangled and repeat across modules, and the checker then
    // ran method bodies in the root module (wrong bindings and field
    // visibility). Per-fn lines and body hashes ride the same pass, in
    // the flattened order collect uses.
    // One pending chunk per file: a cache hit contributes its
    // stored chunk whole; a miss is flattened here and stored at
    // the end under the current epoch.
    struct Pending {
        key: String,
        text_hash: u64,
        exp_hash: u64,
        file_id: FileId,
        cacheable: bool,
        /// The cache holds this chunk (a hit, or stored below): its place in the
        /// merged Ast is recorded there after the concat.
        stored: bool,
        /// A hit's place in the session's merged Ast, which the concat copies it
        /// from (`ast` is empty then).
        old: Option<crate::ast::ChunkSpan>,
        ast: Ast,
        fn_lines: Vec<u32>,
        body_hashes: Vec<u64>,
        nested_lines: Vec<u32>,
        nested_hashes: Vec<u64>,
        fn_module_paths: Vec<Vec<Sym>>,
        nested_module_paths: Vec<Vec<Sym>>,
        /// The file's structure hash, on its first work; None on the
        /// later segments of a file.
        structure: Option<u64>,
        scan: Option<crate::driver::ast_hash::AstScans>,
        deps: Option<crate::resolve::mdr::ChunkDeps>,
    }
    // Module/import structure per file, hashed before flattening drops
    // it: the file path, then its `mod`, `use`, and `extern crate`
    // items over all its segments in order, so a file parsed in
    // segments hashes exactly as one piece.
    let structures: Vec<Option<u64>> = (0..works.len())
        .map(|k| {
            (works[k].segment == 0 && final_hits[k].is_none()).then(|| {
                use std::hash::{Hash, Hasher};
                let mut h = crate::intern::FxHasher::default();
                works[k].path.to_string_lossy().hash(&mut h);
                for w in std::iter::once(&works[k]).chain(works[k + 1..].iter().take_while(|w| w.segment > 0)) {
                    structure_items(&w.ast.items, &mut h);
                }
                h.finish()
            })
        })
        .collect();
    // Each file's text as `make_map` maps it (the first disc with the id), and the line
    // of a span, its line index made on first use: only chunks that missed read lines, and
    // a warm request flattens few of them.
    let mut texts: FxMap<FileId, &str> = FxMap::default();
    for (_, text, file_id) in &seen {
        texts.entry(*file_id).or_insert(text.as_str());
    }
    let mut line_indexes: FxMap<FileId, crate::diag::LineIndex> = FxMap::default();
    let mut line_of = |span: Span| {
        line_indexes.entry(span.file).or_insert_with(|| crate::diag::LineIndex::new(texts.get(&span.file).copied().unwrap_or(""))).line_col(span.lo).0
    };
    let mut pendings: Vec<Pending> = Vec::with_capacity(works.len());
    // The parsed Asts of the files whose cached chunk stands (most files of a full resolve):
    // they are freed off this thread, where their frees cost more than the rest of flatten.
    let mut unused: Vec<Ast> = Vec::new();
    for ((fi, mut w), hit) in works.into_iter().enumerate().zip(final_hits) {
        if let Some(c) = hit {
            unused.push(std::mem::take(&mut w.ast));
            pendings.push(Pending {
                key: w.key,
                text_hash: w.text_hash,
                exp_hash: w.exp_hash,
                file_id: w.file_id,
                cacheable: false,
                stored: true,
                old: Some(c.at),
                ast: Ast::default(),
                fn_lines: c.fn_lines,
                body_hashes: c.body_hashes,
                nested_lines: c.nested_lines,
                nested_hashes: c.nested_hashes,
                fn_module_paths: c.fn_module_paths,
                nested_module_paths: c.nested_module_paths,
                structure: Some(c.structure),
                scan: Some(crate::driver::ast_hash::AstScans {
                    items: c.scan_items,
                    bodies: c.scan_bodies.into_iter().chain(c.nested_bodies).collect(),
                }),
                deps: c.deps,
            });
            continue;
        }
        let structure = structures[fi];
        let mut flat_items = Vec::new();
        let mut flat_mods: Vec<ModuleId> = Vec::new();
        flatten_items_mods(std::mem::take(&mut w.ast.items), w.module, fi, &[], &list_module, &mut flat_items, &mut flat_mods);
        hoist_block_impls(&mut w.ast, &mut flat_items, &mut flat_mods);
        let (mut p_lines, mut p_hashes, mut p_paths) = (Vec::new(), Vec::new(), Vec::new());
        for (item, module) in flat_items.iter().zip(flat_mods.iter()) {
            let mut push = |def: &FnDef| {
                p_lines.push(line_of(def.name_span));
                let text = texts.get(&def.name_span.file).copied().unwrap_or("");
                let body_span = def.body.map(|b| w.ast.block(b).span).unwrap_or(def.name_span);
                let slice = text.get(body_span.lo as usize..body_span.hi as usize).unwrap_or("");
                p_hashes.push(hash_str(slice));
                p_paths.push(tables.modules[module.0 as usize].path.clone());
            };
            match &item.kind {
                ItemKind::Fn(d) => push(d),
                ItemKind::Impl(imp) => {
                    for d in &imp.fns {
                        push(d);
                    }
                }
                _ => {}
            }
        }
        // Nested fns (W-CORELANG body items) ride after the file's
        // top-level fns, in stmt item order, matching collect.
        let (mut n_lines, mut n_hashes, mut n_paths) = (Vec::new(), Vec::new(), Vec::new());
        for item in &w.ast.stmt_items {
            if let crate::ast::ItemKind::Fn(d) = &item.kind {
                n_lines.push(line_of(d.name_span));
                let text = texts.get(&d.name_span.file).copied().unwrap_or("");
                let body_span = d.body.map(|b| w.ast.block(b).span).unwrap_or(d.name_span);
                let slice = text.get(body_span.lo as usize..body_span.hi as usize).unwrap_or("");
                n_hashes.push(hash_str(slice));
                n_paths.push(tables.modules[w.module.0 as usize].path.clone());
            }
        }
        w.ast.items = flat_items;
        pendings.push(Pending {
            cacheable: keep,
            stored: false,
            old: None,
            key: w.key,
            text_hash: w.text_hash,
            exp_hash: w.exp_hash,
            file_id: w.file_id,
            ast: w.ast,
            fn_lines: p_lines,
            body_hashes: p_hashes,
            nested_lines: n_lines,
            nested_hashes: n_hashes,
            fn_module_paths: p_paths,
            nested_module_paths: n_paths,
            structure,
            scan: None,
            deps: rw_deps[fi].take(),
        });
    }
    if !unused.is_empty() {
        crate::pool::drop_detached("lust-drop", unused);
    }
    lap!("resolve: flatten");
    // Structural scans for the chunks that missed, in parallel
    // across files.
    let fresh_scans = par_map(&pendings, |pd| pd.scan.is_none().then(|| crate::driver::ast_hash::scan_ast_seq(&pd.ast)));
    for (pd, fresh) in pendings.iter_mut().zip(fresh_scans) {
        if pd.scan.is_none() {
            pd.scan = fresh;
        }
    }
    // Store the fresh chunks under this epoch for the next request.
    // A chunk scan lists nested bodies after its own top-level
    // bodies; split at the top-level count for storage.
    // (Segments exist only in one-shot resolves, which store nothing: a
    // stored chunk is always a whole file with its own structure hash.)
    for pd in pendings.iter_mut().filter(|pd| pd.cacheable) {
        let Some(structure) = pd.structure else { continue };
        pd.stored = true;
        let scan = pd.scan.as_ref().expect("every pending chunk is scanned");
        let top = pd.fn_lines.len().min(scan.bodies.len());
        cache.put_final(
            &pd.key,
            pd.text_hash,
            pd.file_id,
            FinalChunk {
                epoch,
                exp_hash: pd.exp_hash,
                at: crate::ast::ChunkSpan::default(),
                generation: 0,
                fn_lines: pd.fn_lines.clone(),
                body_hashes: pd.body_hashes.clone(),
                nested_lines: pd.nested_lines.clone(),
                nested_hashes: pd.nested_hashes.clone(),
                fn_module_paths: pd.fn_module_paths.clone(),
                nested_module_paths: pd.nested_module_paths.clone(),
                structure,
                scan_items: scan.items.clone(),
                scan_bodies: scan.bodies[..top].to_vec(),
                nested_bodies: scan.bodies[top..].to_vec(),
                deps: pd.deps.clone(),
            },
        );
    }
    let mdr = mdr_imports.map(|(uses, edges)| crate::resolve::mdr::CratePart {
        uses,
        edges,
        files: pendings
            .iter()
            .map(|pd| crate::resolve::mdr::FileRec { key: pd.key.clone(), text: pd.text_hash, reads: pd.deps.as_ref().map(|d| d.reads.clone()) })
            .collect(),
        rewritten,
    });
    // Assemble the crate outputs in file order. Module paths are
    // per-crate (every crate root has the empty path), so the map
    // holds only this job's crate: in a workspace session the other
    // crates' roots would collide on the same paths and every fn
    // would take the wrong crate's module.
    let module_by_path: FxMap<Vec<Sym>, ModuleId> = tables
        .modules
        .iter()
        .enumerate()
        .filter(|(_, m)| m.krate_root == job.root_module)
        .map(|(i, m)| (m.path.clone(), ModuleId(i as u32)))
        .collect();
    let mut chunks = Vec::with_capacity(pendings.len());
    let mut chunk_keys = Vec::with_capacity(pendings.len());
    let mut fn_lines = Vec::new();
    let mut body_hashes = Vec::new();
    let mut nested_lines: Vec<u32> = Vec::new();
    let mut nested_hashes: Vec<u64> = Vec::new();
    let mut nested_modules: Vec<ModuleId> = Vec::new();
    let mut fn_module = Vec::new();
    let mut scan_items = Vec::new();
    let mut scan_bodies = Vec::new();
    let mut nested_bodies = Vec::new();
    let mut structure = crate::intern::FxHasher::default();
    for pd in pendings {
        {
            use std::hash::Hash;
            if let Some(s) = pd.structure {
                s.hash(&mut structure);
            }
        }
        let top = pd.fn_lines.len();
        fn_lines.extend(pd.fn_lines);
        body_hashes.extend(pd.body_hashes);
        nested_lines.extend(pd.nested_lines);
        nested_hashes.extend(pd.nested_hashes);
        nested_modules.extend(pd.nested_module_paths.iter().map(|p| module_by_path.get(p).copied().unwrap_or(ROOT_MODULE)));
        fn_module.extend(pd.fn_module_paths.iter().map(|p| module_by_path.get(p).copied().unwrap_or(ROOT_MODULE)));
        let mut scan = pd.scan.expect("every pending chunk is scanned");
        scan_items.extend(scan.items);
        nested_bodies.extend(scan.bodies.drain(top.min(scan.bodies.len())..));
        scan_bodies.extend(scan.bodies);
        chunks.push(match pd.old {
            Some(at) => crate::ast::ChunkPart::Old(at),
            None => crate::ast::ChunkPart::Own(pd.ast),
        });
        chunk_keys.push(pd.stored.then_some((pd.key, pd.text_hash, pd.file_id)));
    }
    let structure_hash = {
        use std::hash::Hasher;
        structure.finish()
    };
    let exported_macros = menv.exported_sources();
    // The local crate keeps its last round's environment for the body
    // patch (a daemon session only).
    if keep_expander {
        let files = seen_files.into_iter().collect();
        cache.file_expander = Some(std::sync::Arc::new(FileExpander {
            resolve: cache.resolves,
            menv,
            magic: job.magic,
            env: input.env.clone(),
            cargo_env: input.cargo_env.clone(),
            crate_name: input.crate_name.clone(),
            display_root: input.display_root.clone(),
            files,
        }));
    }
    let scans = crate::driver::ast_hash::AstScans { items: scan_items, bodies: scan_bodies };
    lap!("resolve: chunk scan+concat");
    Ok(CrateOut {
        chunks,
        chunk_keys,
        fn_lines,
        body_hashes,
        fn_module,
        nested_lines,
        nested_hashes,
        nested_modules,
        structure_hash,
        seen,
        std_asks,
        exported_macros,
        expand_deps: file_deps.into_iter().flatten().collect(),
        timings,
        scans,
        nested_bodies,
        mdr,
    })
}

/// Hashes one item list's module and import structure for
/// `ResolvedCrate::structure_hash`: `mod` edges (recursing into inline
/// bodies), `use` trees, and `extern crate` items, in written order.
/// Item visibility rides in through a coarse tag, because flipping a
/// `use` or `mod` to `pub` changes re-export bindings.
fn structure_items(items: &[Item], h: &mut crate::intern::FxHasher) {
    use std::hash::Hash;
    fn tree(t: &UseTree, h: &mut crate::intern::FxHasher) {
        use std::hash::Hash;
        t.leading_colon.hash(h);
        (t.prefix.len() as u64).hash(h);
        for s in &t.prefix {
            s.name.hash(h);
        }
        match &t.kind {
            UseKind::Simple { rename } => {
                0u8.hash(h);
                rename.hash(h);
            }
            UseKind::Glob => 1u8.hash(h),
            UseKind::Group(children) => {
                2u8.hash(h);
                (children.len() as u64).hash(h);
                for c in children {
                    tree(c, h);
                }
            }
        }
    }
    for item in items {
        // Only structure items hash, visibility included (flipping a
        // `use` or `mod` to `pub` changes re-export bindings). Other
        // items hash nothing: adding a fn must not look like a
        // structure edit to the driver's mode split. Their effects
        // are in the driver's own Ast item hashes.
        let vis = |h: &mut crate::intern::FxHasher| match &item.vis {
            Vis::Private => 0u8.hash(h),
            Vis::Public => 1u8.hash(h),
            Vis::Restricted { path, .. } => {
                2u8.hash(h);
                for s in path {
                    s.name.hash(h);
                }
            }
        };
        match &item.kind {
            ItemKind::Mod(m) => {
                vis(h);
                0u8.hash(h);
                m.name.hash(h);
                match &m.body {
                    Some(body) => structure_items(body, h),
                    None => 0u8.hash(h),
                }
            }
            ItemKind::Use(u) => {
                vis(h);
                1u8.hash(h);
                tree(&u.tree, h);
            }
            ItemKind::ExternCrate(e) => {
                vis(h);
                2u8.hash(h);
                e.name.hash(h);
                e.rename.hash(h);
            }
            _ => {}
        }
    }
}

/// True when module path `a` is a prefix of `b` (an ancestor inline
/// module of it, or the same module).
fn path_prefix_of(a: &[Sym], b: &[Sym]) -> bool {
    a.len() <= b.len() && a == &b[..a.len()]
}

/// The `#[macro_use] extern crate name;` items at the top level of
/// one file, as (byte offset, extern name). Top level only, like the
/// expander's own prescan reach for extern crates.
fn extern_macro_use_events(lexed: &lexer::Lexed, interner: &Interner) -> Vec<(u32, String)> {
    use crate::lexer::Tok;
    let toks = &lexed.tokens;
    let mut out = Vec::new();
    let mut pending = false;
    let mut depth = 0usize;
    let mut i = 0;
    while i < toks.len() {
        match toks[i].tok {
            Tok::LBrace => depth += 1,
            Tok::RBrace => depth = depth.saturating_sub(1),
            Tok::Semi if depth == 0 => pending = false,
            Tok::Pound if depth == 0 => {
                let mut j = i + 1;
                if toks.get(j).map(|t| t.tok) == Some(Tok::Bang) {
                    j += 1;
                }
                if toks.get(j).map(|t| t.tok) == Some(Tok::LBracket) {
                    if let Some(Tok::Ident(s)) = toks.get(j + 1).map(|t| t.tok)
                        && interner.get(s) == "macro_use"
                    {
                        pending = true;
                    }
                    // Skip the attribute body.
                    let mut d = 0usize;
                    while j < toks.len() {
                        match toks[j].tok {
                            Tok::LBracket => d += 1,
                            Tok::RBracket => {
                                d -= 1;
                                if d == 0 {
                                    break;
                                }
                            }
                            Tok::Eof => break,
                            _ => {}
                        }
                        j += 1;
                    }
                    i = j;
                }
            }
            Tok::Extern if depth == 0 => {
                if pending
                    && toks.get(i + 1).map(|t| t.tok) == Some(Tok::Crate)
                    && let Some(Tok::Ident(name)) = toks.get(i + 2).map(|t| t.tok)
                {
                    out.push((toks[i].span.lo, interner.get(name).to_string()));
                }
                pending = false;
            }
            _ => {}
        }
        i += 1;
    }
    out
}

/// The textual macro environment of one crate (ARCH 6.1): for each
/// disc, the macro sources its whole file inherits, and the sources
/// each `#[macro_use]` file module adds after its declaration. A
/// macro is textually visible in a module after its definition point,
/// in child modules declared after it, and in the parent (from the
/// declaration point on) when the child module carries
/// `#[macro_use]`. Dependency macros enter only through
/// `#[macro_use] extern crate dep;`, which brings the dependency's
/// exported macros into textual scope at that point.
#[allow(clippy::too_many_arguments)]
fn textual_env(
    job: &CrateJob,
    discs: &[FileDisc],
    expanded: &[Option<std::sync::Arc<lexer::Lexed>>],
    srcs: &[MacroSrc],
    dep_owned: &FxMap<String, Vec<usize>>,
    owned_names: &[Sym],
    tables: &ResolvedTables,
    interner: &Interner,
) -> (Vec<Vec<usize>>, Vec<Vec<(u32, Vec<usize>, bool)>>, Vec<FileMacroScope<usize>>) {
    // With no textual macro source anywhere, every file inherits
    // nothing and no `#[macro_use]` join has sources to add: the
    // result is one empty list per disc.
    if srcs.is_empty() && dep_owned.values().all(|v| v.is_empty()) {
        let empty = FileMacroScope { inherited: Vec::new(), events: Vec::new() };
        return (vec![Vec::new(); discs.len()], vec![Vec::new(); discs.len()], vec![empty; discs.len()]);
    }
    struct Cx<'a> {
        job: &'a CrateJob,
        discs: &'a [FileDisc],
        decls: Vec<Vec<scan::ModDecl>>,
        extern_events: Vec<Vec<(u32, String)>>,
        srcs: &'a [MacroSrc],
        by_path: FxMap<Vec<Sym>, Vec<usize>>,
        exports_memo: FxMap<ModuleId, Vec<usize>>,
        inherited_memo: Vec<Option<Vec<usize>>>,
        dep_owned: &'a FxMap<String, Vec<usize>>,
        tables: &'a ResolvedTables,
    }
    impl Cx<'_> {
        /// The textual macros a `#[macro_use]` on module `m` exports:
        /// its own definitions plus, recursively, those of its
        /// `#[macro_use]` child modules.
        fn exports_of(&mut self, m: ModuleId) -> Vec<usize> {
            if let Some(v) = self.exports_memo.get(&m) {
                return v.clone();
            }
            let path = self.tables.modules[m.0 as usize].path.clone();
            let mut out: Vec<usize> = self.by_path.get(&path).cloned().unwrap_or_default();
            let children: Vec<ModuleId> = self
                .tables
                .modules
                .iter()
                .enumerate()
                .filter(|(_, info)| info.parent == Some(m) && info.macro_use)
                .map(|(i, _)| ModuleId(i as u32))
                .collect();
            for c in children {
                for idx in self.exports_of(c) {
                    if !out.contains(&idx) {
                        out.push(idx);
                    }
                }
            }
            self.exports_memo.insert(m, out.clone());
            out
        }

        /// The child module one `mod` declaration in disc `di` names.
        fn child_module(&self, di: usize, decl: &scan::ModDecl) -> Option<ModuleId> {
            let mut path = self.tables.modules[self.discs[di].module.0 as usize].path.clone();
            path.extend(decl.container.iter().copied());
            path.push(decl.name);
            self.tables.module_by_path_in(self.job.root_module, &path)
        }

        /// Textual macros visible at one point (container, byte
        /// offset) in one file, in textual order.
        fn textual_at(&mut self, di: usize, container: &[Sym], lo: u32) -> Vec<usize> {
            let mut out = self.inherited(di);
            let mut events: Vec<(u32, Vec<usize>)> = Vec::new();
            for s in self.srcs {
                if s.disc == di && s.lo < lo && path_prefix_of(&s.container, container) {
                    events.push((s.lo, vec![s.owned]));
                }
            }
            let decls = self.decls[di].clone();
            for decl in &decls {
                if decl.macro_use && decl.span.lo < lo && path_prefix_of(&decl.container, container) && !inside_decl(decl, container) {
                    if let Some(child) = self.child_module(di, decl) {
                        events.push((decl.span.lo, self.exports_of(child)));
                    }
                }
            }
            for (elo, name) in self.extern_events[di].clone() {
                if elo < lo
                    && let Some(idxs) = self.dep_owned.get(&name)
                {
                    events.push((elo, idxs.clone()));
                }
            }
            events.sort_by_key(|(l, _)| *l);
            for (_, idxs) in events {
                for idx in idxs {
                    if !out.contains(&idx) {
                        out.push(idx);
                    }
                }
            }
            out
        }

        /// The textual macros a whole file inherits from its parent
        /// module chain at its `mod` declaration point.
        fn inherited(&mut self, di: usize) -> Vec<usize> {
            if let Some(v) = &self.inherited_memo[di] {
                return v.clone();
            }
            // Guard against a parent cycle (cannot occur in a module
            // tree, but a memo placeholder keeps the recursion total).
            self.inherited_memo[di] = Some(Vec::new());
            let out = match self.discs[di].parent.clone() {
                None => Vec::new(),
                Some(p) => self.textual_at(p.disc, &p.container, p.lo),
            };
            self.inherited_memo[di] = Some(out.clone());
            out
        }
    }
    let mut by_path: FxMap<Vec<Sym>, Vec<(u32, usize)>> = FxMap::default();
    for s in srcs {
        by_path.entry(s.module_path.clone()).or_default().push((s.lo, s.owned));
    }
    let by_path: FxMap<Vec<Sym>, Vec<usize>> = by_path
        .into_iter()
        .map(|(k, mut v)| {
            v.sort_by_key(|(lo, _)| *lo);
            (k, v.into_iter().map(|(_, o)| o).collect())
        })
        .collect();
    let mut decls: Vec<Vec<scan::ModDecl>> = Vec::with_capacity(discs.len());
    let mut extern_events: Vec<Vec<(u32, String)>> = Vec::with_capacity(discs.len());
    for (di, disc) in discs.iter().enumerate() {
        let mut ds = disc.outline.mods.clone();
        if let Some(Some(exp)) = expanded.get(di)
            && exp.tokens.iter().any(|t| t.tok == crate::lexer::Tok::Mod)
        {
            // Only the outline's mods are read here (see the same
            // gate in the expansion round loop).
            ds.extend(scan::outline(exp, interner).mods);
        }
        decls.push(ds);
        extern_events.push(match &disc.lexed {
            Some(l) => extern_macro_use_events(l, interner),
            None => Vec::new(),
        });
    }
    let mut cx = Cx {
        job,
        discs,
        decls,
        extern_events,
        srcs,
        by_path,
        exports_memo: FxMap::default(),
        inherited_memo: vec![None; discs.len()],
        dep_owned,
        tables,
    };
    let mut inherited = Vec::with_capacity(discs.len());
    for di in 0..discs.len() {
        inherited.push(cx.inherited(di));
    }
    // Each file's textual scope for `use name;` imports: the inherited
    // macros, then its definitions and `#[macro_use]` joins in order.
    let named = |idxs: &[usize]| -> Vec<(Sym, usize)> { idxs.iter().map(|&i| (owned_names[i], i)).collect() };
    let mut scopes = Vec::with_capacity(discs.len());
    for di in 0..discs.len() {
        let mut events: Vec<ScopeEvent<usize>> = Vec::new();
        for s in srcs.iter().filter(|s| s.disc == di) {
            events.push(ScopeEvent { lo: s.lo, container: s.container.clone(), skip_inside: None, macros: vec![(s.name, s.owned)] });
        }
        for decl in cx.decls[di].clone().iter().filter(|d| d.macro_use) {
            if let Some(child) = cx.child_module(di, decl) {
                let mut inside = decl.container.clone();
                inside.push(decl.name);
                let macros = named(&cx.exports_of(child));
                events.push(ScopeEvent { lo: decl.span.lo, container: decl.container.clone(), skip_inside: Some(inside), macros });
            }
        }
        for (elo, name) in cx.extern_events[di].clone() {
            if let Some(idxs) = dep_owned.get(&name) {
                events.push(ScopeEvent { lo: elo, container: Vec::new(), skip_inside: None, macros: named(idxs) });
            }
        }
        events.sort_by_key(|e| e.lo);
        scopes.push(FileMacroScope { inherited: named(&inherited[di]), events });
    }
    // `#[macro_use]` file modules in the original outline: their
    // exported textual macros join the parent file after the `mod`.
    // A macro-generated `#[macro_use] mod` is not in the original
    // token stream, so it cannot be spliced; uses of its macros in
    // the same file then fail closed with an unknown-macro error.
    let mut after_mods: Vec<Vec<(u32, Vec<usize>, bool)>> = vec![Vec::new(); discs.len()];
    for (di, disc) in discs.iter().enumerate() {
        for decl in &disc.outline.mods {
            if decl.macro_use && !decl.inline {
                if let Some(child) = cx.child_module(di, decl) {
                    let idxs = cx.exports_of(child);
                    if !idxs.is_empty() {
                        after_mods[di].push((decl.span.lo, idxs, false));
                    }
                }
            }
        }
        for (elo, name) in &cx.extern_events[di] {
            if let Some(idxs) = cx.dep_owned.get(name)
                && !idxs.is_empty()
            {
                after_mods[di].push((*elo, idxs.clone(), true));
            }
        }
    }
    (inherited, after_mods, scopes)
}

/// True when `container` is inside the inline module one `mod`
/// declaration opens: a `#[macro_use]` join on that module applies
/// after it, not inside it.
fn inside_decl(decl: &scan::ModDecl, container: &[Sym]) -> bool {
    decl.inline && container.len() > decl.container.len() && container.starts_with(&decl.container) && container[decl.container.len()] == decl.name
}

/// Adds one extern crate to one crate's prelude tables, if that crate
/// has no entry with this name yet.
fn push_extern(
    tables: &mut ResolvedTables,
    local: crate::def::CrateId,
    owner: ModuleId,
    name: &str,
    is_std_lib: bool,
    root_module: Option<ModuleId>,
    unsupported: Option<String>,
) {
    if tables.extern_by_name(owner, name).is_some() {
        return;
    }
    let hash = def::item_hash(crate::def::StableCrateHash(hash_str(name) | 1), &[], def::DefKind::Module, name, 0);
    tables.externs.push(ExternInfo {
        name: name.to_string(),
        def: DefId { krate: local, hash },
        is_std_lib,
        owner,
        root_module,
        unsupported,
    });
}

/// A macro def's stable hash: the crate flat prefix, module path
/// segments, and the name. Nothing else computes macro hashes, and the
/// prefix keeps two crates' same-named macros apart in one session.
fn macro_hash(
    input: &OneInput,
    flat_prefix: &str,
    interner: &Interner,
    module: ModuleId,
    tables: &ResolvedTables,
    name: Sym,
) -> DefPathHash {
    let mut path: Vec<&str> = Vec::new();
    if !flat_prefix.is_empty() {
        path.push(flat_prefix);
    }
    path.extend(tables.modules[module.0 as usize].path.iter().map(|s| interner.get(*s)));
    def::item_hash(input.crate_ids.stable, &path, def::DefKind::Macro, interner.get(name), 0)
}

/// FxHash of a string, for body hashes and extern ids.
fn hash_str(s: &str) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = crate::intern::FxHasher::default();
    s.hash(&mut h);
    h.finish() | 1
}

/// Records the module of each inline item list in one file's items.
fn collect_inline_modules(items: &[Item], fi: usize, prefix: &[Sym], tables: &ResolvedTables, out: &mut FxMap<ItemListKey, ModuleId>) {
    let parent_mod = out.get(&(fi, prefix.to_vec())).copied();
    let parent_path: Vec<Sym> = parent_mod.map(|m| tables.modules[m.0 as usize].path.clone()).unwrap_or_default();
    let root = parent_mod.map(|m| tables.root_of(m)).unwrap_or(ROOT_MODULE);
    for item in items {
        if let ItemKind::Mod(m) = &item.kind {
            let mut key = prefix.to_vec();
            key.push(m.name);
            let mut full = parent_path.clone();
            full.push(m.name);
            if let Some(id) = tables.module_by_path_in(root, &full) {
                out.insert((fi, key.clone()), id);
                if let Some(body) = &m.body {
                    collect_inline_modules(body, fi, &key, tables, out);
                }
            }
        }
    }
}

/// True when an attribute list names `name` as its one-segment path.
/// L0522 for `#[no_implicit_prelude]`: paths honor it, but the checker
/// still finds prelude types, variants, traits' methods, and std macros
/// in such a module (false accepts), so lust rejects the attribute.
fn no_prelude_unsupported(attrs: &[Attr], interner: &Interner, diags: &mut Vec<Diag>) {
    for a in attrs.iter().filter(|a| a.path.len() == 1 && interner.get(a.path[0].name) == "no_implicit_prelude") {
        diags.push(crate::diag::not_yet("L0522", a.span, "`#[no_implicit_prelude]`"));
    }
}

fn has_attr(attrs: &[Attr], name: &str, interner: &Interner) -> bool {
    attrs.iter().any(|a| a.path.len() == 1 && interner.get(a.path[0].name) == name)
}

/// The `#[path = "..."]` value in an attribute list, when written. The
/// parser stores the `= lit` tail as raw token trees, or as an `Eq`
/// expression for the parenthesized form; both reduce to the string.
fn path_attr_value(attrs: &[Attr], ast: &Ast, interner: &Interner) -> Option<String> {
    for a in attrs {
        if a.path.len() != 1 || interner.get(a.path[0].name) != "path" {
            continue;
        }
        match &a.input {
            AttrInput::Eq(e) => {
                if let Expr::Str(i) = ast.expr(*e) {
                    return ast.strings.get(*i as usize).cloned();
                }
            }
            AttrInput::List(_, trees) => {
                for t in trees {
                    if let crate::lexer::TokenTree::Token(tok) = t
                        && let crate::lexer::Tok::Str(i, _) = tok.tok
                    {
                        return ast.strings.get(i as usize).cloned();
                    }
                }
            }
            AttrInput::None => {}
        }
    }
    None
}

/// Step 1 of the loop for one file: expand `cfg_attr`, strip cfg'd-out
/// items, fields, variants, and methods, and apply module inner
/// attribute flags (`no_implicit_prelude`, a crate-level cfg). Match
/// arm cfg is handled in the rewrite walk, where arms are visited.
fn strip_file(
    w: &mut FileWork,
    fi: usize,
    input: &OneInput,
    interner: &Interner,
    list_module: &FxMap<ItemListKey, ModuleId>,
    tables: &mut ResolvedTables,
    diags: &mut Vec<Diag>,
) {
    let strings = &w.ast.strings;
    let mut inner: Vec<Attr> = w.ast.inner_attrs.clone();
    if let Err(d) = cfg::expand_cfg_attr(&input.env, &mut inner, strings, interner) {
        diags.push(d);
    }
    let module = w.module;
    if has_attr(&inner, "no_implicit_prelude", interner) {
        tables.modules[module.0 as usize].no_prelude = true;
        no_prelude_unsupported(&inner, interner, diags);
    }
    match cfg::attrs_enabled(&input.env, &inner, strings, interner) {
        Ok(false) => {
            // A crate- or module-level cfg turned the whole file off.
            w.ast.items.clear();
            return;
        }
        Ok(true) => {}
        Err(d) => diags.push(d),
    }
    let mut items = std::mem::take(&mut w.ast.items);
    strip_items(&mut items, fi, &[], w, input, interner, list_module, tables, diags);
    w.ast.items = items;
}

/// The recursive half of `strip_file` over one item list.
fn strip_items(
    items: &mut Vec<Item>,
    fi: usize,
    prefix: &[Sym],
    w: &FileWork,
    input: &OneInput,
    interner: &Interner,
    list_module: &FxMap<ItemListKey, ModuleId>,
    tables: &mut ResolvedTables,
    diags: &mut Vec<Diag>,
) {
    let strings = &w.ast.strings;
    let mut keep = Vec::with_capacity(items.len());
    for mut item in items.drain(..) {
        if let Err(d) = cfg::expand_cfg_attr(&input.env, &mut item.attrs, strings, interner) {
            diags.push(d);
        }
        match cfg::attrs_enabled(&input.env, &item.attrs, strings, interner) {
            Ok(true) => {}
            Ok(false) => continue,
            Err(d) => {
                diags.push(d);
                continue;
            }
        }
        // A `cfg` in the inner attributes of an inline `mod`, `impl`, or
        // `trait` body turns the whole item off, like a file-level cfg.
        let item_inner: Option<&mut Vec<Attr>> = match &mut item.kind {
            ItemKind::Mod(m) => Some(&mut m.inner_attrs),
            ItemKind::Impl(i) => Some(&mut i.inner_attrs),
            ItemKind::Trait(t) => Some(&mut t.inner_attrs),
            _ => None,
        };
        if let Some(inner) = item_inner {
            if let Err(d) = cfg::expand_cfg_attr(&input.env, inner, strings, interner) {
                diags.push(d);
            }
            match cfg::attrs_enabled(&input.env, inner, strings, interner) {
                Ok(true) => {}
                Ok(false) => continue,
                Err(d) => {
                    diags.push(d);
                    continue;
                }
            }
        }
        match &mut item.kind {
            ItemKind::Struct(s) => {
                if let VariantFields::Struct(fs) | VariantFields::Tuple(fs) = &mut s.fields {
                    strip_fields(fs, input, strings, interner, diags);
                }
            }
            ItemKind::Enum(e) => {
                e.variants.retain_mut(|v| {
                    if let Err(d) = cfg::expand_cfg_attr(&input.env, &mut v.attrs, strings, interner) {
                        diags.push(d);
                    }
                    match cfg::attrs_enabled(&input.env, &v.attrs, strings, interner) {
                        Ok(on) => {
                            if on && let VariantFields::Struct(fs) | VariantFields::Tuple(fs) = &mut v.fields {
                                strip_fields(fs, input, strings, interner, diags);
                            }
                            on
                        }
                        Err(d) => {
                            diags.push(d);
                            false
                        }
                    }
                });
            }
            ItemKind::Impl(imp) => {
                imp.fns.retain_mut(|f| {
                    if let Err(d) = cfg::expand_cfg_attr(&input.env, &mut f.attrs, strings, interner) {
                        diags.push(d);
                    }
                    matches!(cfg::attrs_enabled(&input.env, &f.attrs, strings, interner), Ok(true))
                });
            }
            ItemKind::Mod(m) => {
                // The module's real visibility comes from the AST (the
                // outline could not read a restricted path).
                let mut key = prefix.to_vec();
                key.push(m.name);
                if let Some(&child) = list_module.get(&(fi, key.clone())) {
                    let vis = vis_from_ast(&item.vis, interner);
                    tables.modules[child.0 as usize].vis = vis;
                    if has_attr(&item.attrs, "no_implicit_prelude", interner) || has_attr(&m.inner_attrs, "no_implicit_prelude", interner) {
                        tables.modules[child.0 as usize].no_prelude = true;
                        no_prelude_unsupported(&item.attrs, interner, diags);
                        no_prelude_unsupported(&m.inner_attrs, interner, diags);
                    }
                    if let Some(body) = &mut m.body {
                        strip_items(body, fi, &key, w, input, interner, list_module, tables, diags);
                    }
                } else if m.body.is_some() {
                    // A cfg-stripped inline module (its own cfg ran in
                    // discovery): drop the whole item.
                    continue;
                }
            }
            _ => {}
        }
        keep.push(item);
    }
    *items = keep;
}

/// Strips cfg'd-out fields from one field list.
fn strip_fields(fs: &mut Vec<FieldDef>, input: &OneInput, strings: &[String], interner: &Interner, diags: &mut Vec<Diag>) {
    fs.retain_mut(|f| {
        if let Err(d) = cfg::expand_cfg_attr(&input.env, &mut f.attrs, strings, interner) {
            diags.push(d);
        }
        match cfg::attrs_enabled(&input.env, &f.attrs, strings, interner) {
            Ok(on) => on,
            Err(d) => {
                diags.push(d);
                false
            }
        }
    });
}

/// The flat name of a def in a module: the crate's flat prefix (empty
/// for the selected crate, a stable-hash prefix for a source
/// dependency), then the module path joined with `$`, then the name.
/// The selected crate's root keeps plain names, except names of the
/// std prelude types the checker knows as builtins (`PRELUDE_TYPES`) and
/// of primitive types: those become `crate$Name`, so a root `enum Option`
/// or `type u8 = u16` is never read as std's `Option` or the primitive
/// (or the reverse, in modules that do not import it).
/// Std prelude type names the checker resolves as builtins when they
/// are written plainly. A crate-root item of one of these names gets a
/// `crate$` flat name (`flat_name`), and its file goes through the
/// resolver (`needs_resolve_lexed`).
pub(crate) const PRELUDE_TYPES: &[&str] = &["Option", "Result", "Vec", "String", "Box"];

fn flat_name(tables: &ResolvedTables, flat_prefix: &str, module: ModuleId, name: Sym, interner: &Interner) -> Sym {
    let path = &tables.modules[module.0 as usize].path;
    if flat_prefix.is_empty() && path.is_empty() {
        let text = interner.get(name);
        if PRELUDE_TYPES.contains(&text) || crate::ty::lang::is_primitive_type_name(text) {
            return interner.intern(&format!("crate${text}"));
        }
        return name;
    }
    let mut s = String::from(flat_prefix);
    for seg in path {
        s.push_str(interner.get(*seg));
        s.push('$');
    }
    s.push_str(interner.get(name));
    interner.intern(&s)
}

/// Records the source path text of one renamed def in
/// `ResolvedTables::display_names`, for diagnostics: the module path
/// and name joined with `::`, prefixed with the crate name for a
/// source dependency (whose flat name carries only a crate hash).
/// Root defs of the selected crate keep their plain name and need no
/// entry. Display only; never a lookup key.
fn record_display(tables: &mut ResolvedTables, input: &OneInput, flat_prefix: &str, module: ModuleId, flat: Sym, name: Sym, interner: &Interner) {
    if flat == name {
        return;
    }
    let mut s = String::new();
    if !flat_prefix.is_empty() {
        s.push_str(&input.crate_name);
        s.push_str("::");
    }
    for (i, seg) in tables.modules[module.0 as usize].path.clone().iter().enumerate() {
        // A std source module shows as its std path (`std::time`).
        let hidden = if i == 0 && flat_prefix.is_empty() && tables.std_modules.iter().any(|&(n, _)| n == *seg) {
            crate::stdmods::display_path(interner.get(*seg))
        } else {
            None
        };
        match hidden {
            Some(p) => s.push_str(&p),
            None => s.push_str(interner.get(*seg)),
        }
        s.push_str("::");
    }
    s.push_str(interner.get(name));
    let display = interner.intern(&s);
    tables.display_names.insert(flat, display);
}

/// Step 3 input: registers every defined name in one item list, renames
/// defs to their flat names, and collects the module's imports. Module
/// bindings register first (same sweep): a `mod` item's name is a
/// type-namespace binding to the child module.
#[allow(clippy::too_many_arguments)]
fn register_items(
    items: &mut [Item],
    module: ModuleId,
    fi: usize,
    prefix: &[Sym],
    input: &OneInput,
    flat_prefix: &str,
    interner: &Interner,
    tables: &mut ResolvedTables,
    list_module: &FxMap<ItemListKey, ModuleId>,
    imports: &mut Vec<Import>,
    // Same-flat-name Adt counts so far, across the workspace tables
    // in registration order: the disambiguator source, without
    // rescanning every recorded def per Adt (quadratic at scale).
    adt_counts: &mut FxMap<Sym, u32>,
    // Names this item list defines, per namespace (empty at the start of
    // a list; a file's item segments share one). Two local definitions
    // of one name in one namespace are a duplicate (rustc E0428), even
    // when both hash to the same target (two fns) or to a module the
    // module tree already holds (two `mod` items): the binding insert
    // alone cannot see those. One report per duplicate item.
    seen: &mut FxMap<(u8, Sym), ()>,
    diags: &mut Vec<Diag>,
) {
    let check_dup = |seen: &mut FxMap<(u8, Sym), ()>, ns: Namespace, name: Sym, span: Span, reported: &mut bool, diags: &mut Vec<Diag>| {
        if seen.insert((ns_index(ns) as u8, name), ()).is_some() && !*reported {
            *reported = true;
            diags.push(Diag::new(
                "L0106",
                span,
                format!("`{}` is defined more than once", interner.get(name)),
                "Rename one of the definitions.",
            ));
        }
    };
    // Adt disambiguators count same-flat-name Adts in one pass order,
    // matching collect (which counts by name over the whole crate).
    for item in items.iter_mut() {
        let vis = || vis_from_ast(&item.vis, interner);
        let bind = |tables: &mut ResolvedTables, ns: Namespace, name: Sym, target: Target, vis: VisKind| {
            tables.insert(module, ns, name, Bind { target, vis, rank: 2, def_module: module });
        };
        let mut reported = false;
        match &mut item.kind {
            ItemKind::Mod(m) => {
                check_dup(seen, Namespace::Type, m.name, m.name_span, &mut reported, diags);
                let mut key = prefix.to_vec();
                key.push(m.name);
                // A std source module of the std splice (W-STD-C): bound
                // nowhere, reached only through its std paths.
                let hidden = module == ROOT_MODULE
                    && m.name_span.file == FileId(0)
                    && input.std_splice_lo.is_some_and(|lo| m.name_span.lo >= lo)
                    && crate::stdmods::by_name(interner.get(m.name)).is_some();
                if let Some(&child) = list_module.get(&(fi, key.clone())) {
                    tables.module_defs[child.0 as usize] = DefId {
                        krate: input.crate_ids.local,
                        hash: def::item_hash(
                            input.crate_ids.stable,
                            &[],
                            def::DefKind::Module,
                            interner.get(flat_name(tables, flat_prefix, module, m.name, interner)),
                            0,
                        ),
                    };
                    if hidden {
                        if !tables.std_modules.iter().any(|&(_, c)| c == child) {
                            tables.std_modules.push((m.name, child));
                        }
                    } else {
                        bind(tables, Namespace::Type, m.name, Target::Module(child), vis());
                    }
                    if let Some(body) = &mut m.body {
                        register_items(
                            body,
                            child,
                            fi,
                            &key,
                            input,
                            flat_prefix,
                            interner,
                            tables,
                            list_module,
                            imports,
                            adt_counts,
                            &mut FxMap::default(),
                            diags,
                        );
                    }
                }
            }
            ItemKind::Fn(f) => {
                check_dup(seen, Namespace::Value, f.name, f.name_span, &mut reported, diags);
                let flat = flat_name(tables, flat_prefix, module, f.name, interner);
                record_display(tables, input, flat_prefix, module, flat, f.name, interner);
                let def = DefId { krate: input.crate_ids.local, hash: def::free_fn_hash(input.crate_ids.stable, &[], interner.get(flat)) };
                bind(tables, Namespace::Value, f.name, Target::Def(def), vis());
                tables.def_info.insert(def, DefInfo { kind: ResKind::Fn, flat, module, vis: vis() });
                insert_flat(tables, Namespace::Value, flat, def, interner);
                f.name = flat;
            }
            ItemKind::Struct(s) => {
                // A braced struct has no constructor value: its name lives
                // only in the type namespace. Unit and tuple structs also
                // name their constructor in the value namespace.
                let has_ctor = !matches!(s.fields, VariantFields::Struct(_));
                check_dup(seen, Namespace::Type, s.name, s.name_span, &mut reported, diags);
                if has_ctor {
                    check_dup(seen, Namespace::Value, s.name, s.name_span, &mut reported, diags);
                }
                let flat = flat_name(tables, flat_prefix, module, s.name, interner);
                record_display(tables, input, flat_prefix, module, flat, s.name, interner);
                let disamb = *adt_counts.entry(flat).and_modify(|c| *c += 1).or_insert(0);
                let def = DefId {
                    krate: input.crate_ids.local,
                    hash: def::item_hash(input.crate_ids.stable, &[], def::DefKind::Adt, interner.get(flat), disamb),
                };
                bind(tables, Namespace::Type, s.name, Target::Def(def), vis());
                if has_ctor {
                    bind(tables, Namespace::Value, s.name, Target::Def(def), vis());
                }
                record_adt(tables, def, flat, module, vis(), &s.fields, interner);
                s.name = flat;
            }
            ItemKind::Enum(e) => {
                check_dup(seen, Namespace::Type, e.name, e.name_span, &mut reported, diags);
                let flat = flat_name(tables, flat_prefix, module, e.name, interner);
                record_display(tables, input, flat_prefix, module, flat, e.name, interner);
                let disamb = *adt_counts.entry(flat).and_modify(|c| *c += 1).or_insert(0);
                let def = DefId {
                    krate: input.crate_ids.local,
                    hash: def::item_hash(input.crate_ids.stable, &[], def::DefKind::Adt, interner.get(flat), disamb),
                };
                bind(tables, Namespace::Type, e.name, Target::Def(def), vis());
                tables.def_info.insert(def, DefInfo { kind: ResKind::Adt, flat, module, vis: vis() });
                tables.variants.insert(def, e.variants.iter().map(|v| v.name).collect());
                insert_flat(tables, Namespace::Type, flat, def, interner);
                // Enum variant fields have no visibility of their own
                // in Rust: they take the enum's visibility.
                for v in &e.variants {
                    if let VariantFields::Struct(fs) = &v.fields {
                        let entry = tables.field_vis.entry(def).or_insert_with(|| (module, FxMap::default()));
                        for f in fs {
                            entry.1.insert(f.name, vis());
                        }
                    }
                }
                e.name = flat;
            }
            ItemKind::Const(c) => {
                tables.const_init_module.insert(c.span, module);
                if let Some(name) = c.name {
                    check_dup(seen, Namespace::Value, name, c.name_span, &mut reported, diags);
                    let flat = flat_name(tables, flat_prefix, module, name, interner);
                    record_display(tables, input, flat_prefix, module, flat, name, interner);
                    let def = DefId {
                        krate: input.crate_ids.local,
                        hash: def::item_hash(input.crate_ids.stable, &[], def::DefKind::Const, interner.get(flat), 0),
                    };
                    bind(tables, Namespace::Value, name, Target::Def(def), vis());
                    tables.def_info.insert(def, DefInfo { kind: ResKind::Const, flat, module, vis: vis() });
                    insert_flat(tables, Namespace::Value, flat, def, interner);
                    c.name = Some(flat);
                }
            }
            ItemKind::Static(s) => {
                tables.const_init_module.insert(s.span, module);
                check_dup(seen, Namespace::Value, s.name, s.name_span, &mut reported, diags);
                let flat = flat_name(tables, flat_prefix, module, s.name, interner);
                record_display(tables, input, flat_prefix, module, flat, s.name, interner);
                let def = DefId {
                    krate: input.crate_ids.local,
                    hash: def::item_hash(input.crate_ids.stable, &[], def::DefKind::Static, interner.get(flat), 0),
                };
                bind(tables, Namespace::Value, s.name, Target::Def(def), vis());
                tables.def_info.insert(def, DefInfo { kind: ResKind::Static, flat, module, vis: vis() });
                insert_flat(tables, Namespace::Value, flat, def, interner);
                s.name = flat;
            }
            ItemKind::Type(a) => {
                check_dup(seen, Namespace::Type, a.name, a.name_span, &mut reported, diags);
                let flat = flat_name(tables, flat_prefix, module, a.name, interner);
                record_display(tables, input, flat_prefix, module, flat, a.name, interner);
                let def = DefId {
                    krate: input.crate_ids.local,
                    hash: def::item_hash(input.crate_ids.stable, &[], def::DefKind::TypeAlias, interner.get(flat), 0),
                };
                bind(tables, Namespace::Type, a.name, Target::Def(def), vis());
                tables.def_info.insert(def, DefInfo { kind: ResKind::Alias, flat, module, vis: vis() });
                insert_flat(tables, Namespace::Type, flat, def, interner);
                a.name = flat;
            }
            ItemKind::Trait(t) => {
                for c in &t.consts {
                    tables.const_init_module.insert(c.span, module);
                }
                check_dup(seen, Namespace::Type, t.name, t.name_span, &mut reported, diags);
                let flat = flat_name(tables, flat_prefix, module, t.name, interner);
                record_display(tables, input, flat_prefix, module, flat, t.name, interner);
                // The ordinal counts same-flat-name traits in
                // walk order, matching collect's trait defs.
                let disamb = tables.def_info.values().filter(|i| i.kind == ResKind::Trait && i.flat == flat).count() as u32;
                let def = DefId {
                    krate: input.crate_ids.local,
                    hash: def::item_hash(input.crate_ids.stable, &[], def::DefKind::Trait, interner.get(flat), disamb),
                };
                bind(tables, Namespace::Type, t.name, Target::Def(def), vis());
                tables.def_info.insert(def, DefInfo { kind: ResKind::Trait, flat, module, vis: vis() });
                insert_flat(tables, Namespace::Type, flat, def, interner);
                t.name = flat;
            }
            ItemKind::Impl(imp) => {
                // Associated fn visibility, once the self type resolves
                // in this module. The rewrite pass resolves the path
                // properly; here a one-segment or resolvable path is
                // enough to key the table. Associated consts record
                // their defining module for the const evaluator.
                for c in &imp.consts {
                    tables.const_init_module.insert(c.span, module);
                }
            }
            ItemKind::Use(u) => {
                flatten_use(&u.tree, module, vis(), imports, interner);
            }
            ItemKind::ExternCrate(e) => {
                let bind_name = e.rename.unwrap_or(e.name);
                // At the root, `extern crate alloc;` puts `alloc` in the
                // extern prelude (`ResolvedTables::extern_in_scope`).
                if module == tables.root_of(module)
                    && interner.get(bind_name) == "alloc"
                    && interner.get(e.name) == "alloc"
                    && !tables.alloc_roots.contains(&module)
                {
                    tables.alloc_roots.push(module);
                }
                let target = if e.name == interner.intern("self") {
                    Some(Target::Module(tables.root_of(module)))
                } else {
                    tables.extern_by_name(module, interner.get(e.name)).map(|i| tables.extern_target(i))
                };
                if e.name == interner.intern("self") && e.rename.is_none() {
                    diags.push(Diag::new(
                        "L0001",
                        e.span,
                        "`extern crate self;` requires renaming",
                        "Write `extern crate self as name;`.",
                    ));
                } else if target.is_none() && interner.get(e.name) != "proc_macro" {
                    // rustc accepts `extern crate proc_macro;` in any
                    // crate; a path through it rejects later (L0505).
                    diags.push(extern_crate_not_found(interner.get(e.name), e.name_span));
                }
                if bind_name != interner.intern("_") {
                    check_dup(seen, Namespace::Type, bind_name, e.span, &mut reported, diags);
                    if let Some(target) = target {
                        bind(tables, Namespace::Type, bind_name, target, vis());
                    }
                }
            }
            ItemKind::Union(u) => {
                check_dup(seen, Namespace::Type, u.name, u.name_span, &mut reported, diags);
            }
            _ => {}
        }
    }
}

/// L0506 for `extern crate name;` naming no crate of this build: not
/// std, core, alloc, or a dependency (rustc E0463), or the unstable
/// `test` crate (rustc E0658). Before this, the item was dropped silently.
fn extern_crate_not_found(name: &str, span: Span) -> Diag {
    if name == "test" {
        return Diag::new(
            "L0506",
            span,
            "the `test` crate is unstable: rustc needs `#![feature(test)]` (E0658)",
            "Remove the `extern crate test;`; `#[test]` fns need no extern crate.",
        );
    }
    Diag::new(
        "L0506",
        span,
        format!("cannot find crate `{name}`"),
        "Add the crate to [dependencies] in Cargo.toml and build the Cargo project, or remove the `extern crate`.",
    )
}

/// Indexes one item's flat name. A crate-root item of the selected crate
/// keeps its plain name as its flat name (`flat_name`), which a nearer
/// binding of the same name can shadow at a use site (`crate::f` in a
/// module with its own `f`): it is indexed under its `crate$` alias
/// too, a name source text cannot write, which the rewrite writes at
/// such a site (`Rewrite::flat_at`).
fn insert_flat(tables: &mut ResolvedTables, ns: Namespace, flat: Sym, def: DefId, interner: &Interner) {
    tables.flat[ns_index(ns)].insert(flat, def);
    if !interner.get(flat).contains('$') {
        tables.flat[ns_index(ns)].insert(root_alias(flat, interner), def);
    }
}

/// The `crate$` alias of a crate-root item's plain flat name.
fn root_alias(flat: Sym, interner: &Interner) -> Sym {
    interner.intern(&format!("crate${}", interner.get(flat)))
}

/// Records one struct's def info and field visibility.
fn record_adt(
    tables: &mut ResolvedTables,
    def: DefId,
    flat: Sym,
    module: ModuleId,
    vis: VisKind,
    fields: &VariantFields,
    interner: &Interner,
) {
    tables.def_info.insert(def, DefInfo { kind: ResKind::Adt, flat, module, vis });
    insert_flat(tables, Namespace::Type, flat, def, interner);
    // Only a unit or tuple struct names a constructor value.
    if !matches!(fields, VariantFields::Struct(_)) {
        insert_flat(tables, Namespace::Value, flat, def, interner);
    }
    if let VariantFields::Struct(fs) = fields {
        let mut map = FxMap::default();
        for f in fs {
            map.insert(f.name, vis_from_ast(&f.vis, interner));
        }
        tables.field_vis.insert(def, (module, map));
    }
    if let VariantFields::Tuple(fs) = fields {
        tables.tuple_field_vis.insert(def, (module, fs.iter().map(|f| vis_from_ast(&f.vis, interner)).collect()));
    }
}

/// Reports every written restricted visibility in `items` (at `module`)
/// that names no enclosing module (`ResolvedTables::restriction_ok`):
/// on items, struct fields, and inherent impl items, recursing into
/// inline modules as `collect_assoc_vis` does.
fn check_vis_restrictions(items: &[Item], module: ModuleId, interner: &Interner, tables: &ResolvedTables, diags: &mut Vec<Diag>) {
    let check = |v: &Vis, diags: &mut Vec<Diag>| {
        if let Vis::Restricted { span, .. } = v
            && !tables.restriction_ok(&vis_from_ast(v, interner), module, interner)
        {
            diags.push(Diag::new(
                "L0511",
                *span,
                "this visibility names no enclosing module",
                "Write `pub(crate)`, or `pub(in path)` with a path from `crate`, `self`, or `super` to an enclosing module.",
            ));
        }
    };
    for item in items {
        check(&item.vis, diags);
        match &item.kind {
            ItemKind::Struct(s) => {
                if let VariantFields::Tuple(fs) | VariantFields::Struct(fs) = &s.fields {
                    for f in fs {
                        check(&f.vis, diags);
                    }
                }
            }
            ItemKind::Impl(imp) if imp.trait_ref.is_none() => {
                for f in &imp.fns {
                    check(&f.vis, diags);
                }
                for c in &imp.consts {
                    check(&c.vis, diags);
                }
            }
            ItemKind::Mod(m) => {
                if let Some(body) = &m.body {
                    let mut full = tables.modules[module.0 as usize].path.clone();
                    full.push(m.name);
                    if let Some(child) = tables.module_by_path_in(tables.root_of(module), &full) {
                        check_vis_restrictions(body, child, interner, tables, diags);
                    }
                }
            }
            _ => {}
        }
    }
}

/// Every module item's span with its module, inline modules included:
/// the module of a body item is the one of the smallest span holding it.
fn module_item_spans(items: &[Item], module: ModuleId, tables: &ResolvedTables, out: &mut Vec<(Span, ModuleId)>) {
    for item in items {
        out.push((item.span, module));
        if let ItemKind::Mod(m) = &item.kind
            && let Some(body) = &m.body
        {
            let mut full = tables.modules[module.0 as usize].path.clone();
            full.push(m.name);
            if let Some(child) = tables.module_by_path_in(tables.root_of(module), &full) {
                module_item_spans(body, child, tables, out);
            }
        }
    }
}

/// Reports bad restricted visibilities on items inside function
/// bodies (`Ast::stmt_items`), like `check_vis_restrictions` does for
/// module items: a `pub(super)` or `pub(in ..)` there names modules
/// from the enclosing fn's module (rustc E0433 for one that names
/// none). The enclosing module is the smallest item span that holds
/// the body item, else the file's module.
fn check_stmt_vis_restrictions(ast: &Ast, module: ModuleId, interner: &Interner, tables: &ResolvedTables, diags: &mut Vec<Diag>) {
    if ast.stmt_items.is_empty() {
        return;
    }
    let mut spans: Vec<(Span, ModuleId)> = Vec::new();
    module_item_spans(&ast.items, module, tables, &mut spans);
    for item in &ast.stmt_items {
        let m = spans
            .iter()
            .filter(|(s, _)| s.file == item.span.file && s.lo <= item.span.lo && item.span.hi <= s.hi)
            .min_by_key(|(s, _)| s.hi - s.lo)
            .map_or(module, |(_, m)| *m);
        let check = |v: &Vis, diags: &mut Vec<Diag>| {
            if let Vis::Restricted { span, .. } = v
                && !tables.restriction_ok(&vis_from_ast(v, interner), m, interner)
            {
                diags.push(Diag::new(
                    "L0511",
                    *span,
                    "this visibility names no enclosing module",
                    "Write `pub(crate)`, or `pub(in path)` with a path from `crate`, `self`, or `super` to an enclosing module.",
                ));
            }
        };
        check(&item.vis, diags);
        if let ItemKind::Struct(s) = &item.kind
            && let VariantFields::Tuple(fs) | VariantFields::Struct(fs) = &s.fields
        {
            for f in fs {
                check(&f.vis, diags);
            }
        }
    }
}

/// `collect_assoc_vis` for the impls inside fn bodies, which flatten
/// hoists to module items later (`hoist_block_impls`): a private member
/// of a body impl of a module type is private to the fn's module (rustc
/// E0624). An impl of a block type needs no entry (no other module can
/// name the type). Each body impl's consts also record their module for
/// the const evaluator. When a block `use` is in scope, the written self
/// name may be an import that shadows an item, so an impl with a non-pub
/// member there is not supported yet (L0820); so is one whose self type
/// does not resolve here.
fn collect_stmt_impl_vis(ast: &Ast, module: ModuleId, interner: &Interner, tables: &mut ResolvedTables, diags: &mut Vec<Diag>) {
    if !ast.stmt_items.iter().any(|it| matches!(it.kind, ItemKind::Impl(_))) {
        return;
    }
    let holds = |s: Span, t: Span| s.file == t.file && s.lo <= t.lo && t.hi <= s.hi;
    let mut spans: Vec<(Span, ModuleId)> = Vec::new();
    module_item_spans(&ast.items, module, tables, &mut spans);
    for item in &ast.stmt_items {
        let ItemKind::Impl(imp) = &item.kind else { continue };
        let m = spans.iter().filter(|(s, _)| holds(*s, item.span)).min_by_key(|(s, _)| s.hi - s.lo).map_or(module, |(_, m)| *m);
        for c in &imp.consts {
            tables.const_init_module.insert(c.span, m);
        }
        if imp.trait_ref.is_some() {
            continue;
        }
        let private = imp.fns.iter().map(|f| &f.vis).chain(imp.consts.iter().map(|c| &c.vis)).any(|v| *v != Vis::Public);
        if !private {
            continue;
        }
        // The items of every block around the impl.
        let around: Vec<&Item> = ast
            .blocks
            .iter()
            .filter(|b| holds(b.span, item.span))
            .flat_map(|b| b.stmts.iter().filter_map(|s| if let Stmt::Item(i) = s { ast.stmt_items.get(*i as usize) } else { None }))
            .collect();
        if around.iter().any(|it| matches!(it.kind, ItemKind::Use(_))) {
            diags.push(crate::diag::not_yet("L0820", item.span, "a non-pub member of an impl in a fn body with a block `use` in scope"));
            continue;
        }
        let TyExpr::Path(segs) = ast.ty(imp.self_ty) else {
            diags.push(crate::diag::not_yet("L0820", item.span, "a non-pub member of an impl in a fn body for this self type"));
            continue;
        };
        let names: Vec<Sym> = segs.iter().map(|s| s.name).collect();
        let block_type = |it: &&Item| match &it.kind {
            ItemKind::Struct(x) => x.name == names[0],
            ItemKind::Enum(x) => x.name == names[0],
            ItemKind::Union(x) => x.name == names[0],
            ItemKind::Type(x) => x.name == names[0],
            ItemKind::Trait(x) => x.name == names[0],
            _ => false,
        };
        if names.len() == 1 && around.iter().any(block_type) {
            continue;
        }
        let PathRes::Done(Target::Def(def)) = tables.resolve_path(m, &names, Namespace::Type, PathMode::Lexical, false, interner) else {
            diags.push(crate::diag::not_yet("L0820", item.span, "a non-pub member of an impl in a fn body for this self type"));
            continue;
        };
        let entry = tables.assoc_vis.entry(def).or_default();
        for f in &imp.fns {
            entry.insert(f.name, (vis_from_ast(&f.vis, interner), m));
        }
        for c in &imp.consts {
            entry.insert(c.name, (vis_from_ast(&c.vis, interner), m));
        }
    }
}

/// Fills `assoc_vis` from every impl block whose self type resolves.
fn collect_assoc_vis(ast: &Ast, items: &[Item], module: ModuleId, interner: &Interner, tables: &mut ResolvedTables) {
    for item in items {
        match &item.kind {
            ItemKind::Impl(imp) => {
                // Trait impl methods take the trait's visibility, not the
                // (absent) written one; only inherent impls record here.
                if imp.trait_ref.is_none()
                    && let TyExpr::Path(segs) = ast.ty(imp.self_ty)
                {
                    let names: Vec<Sym> = segs.iter().map(|s| s.name).collect();
                    if let PathRes::Done(Target::Def(def)) =
                        tables.resolve_path(module, &names, Namespace::Type, PathMode::Lexical, false, interner)
                    {
                        let entry = tables.assoc_vis.entry(def).or_default();
                        for f in &imp.fns {
                            entry.insert(f.name, (vis_from_ast(&f.vis, interner), module));
                        }
                        for c in &imp.consts {
                            entry.insert(c.name, (vis_from_ast(&c.vis, interner), module));
                        }
                    }
                }
            }
            ItemKind::Mod(m) => {
                if let Some(body) = &m.body {
                    // Inline bodies were registered under their module;
                    // the path lookup finds it by name path.
                    let mut full = tables.modules[module.0 as usize].path.clone();
                    full.push(m.name);
                    if let Some(child) = tables.module_by_path_in(tables.root_of(module), &full) {
                        collect_assoc_vis(ast, body, child, interner, tables);
                    }
                }
            }
            _ => {}
        }
    }
}

// ---------- The rewrite pass ----------
//
// Every written path resolves here, in its module (plus lexical scopes
// in bodies). A proven path becomes its flat name; an ambiguous or
// private one is a diagnostic (L0507, L0510); an unproven one is left
// written, so collect and check report it with their own codes. A path
// into a non-std extern crate is L0505: cross-crate item resolution is
// not supported yet, and a false accept would be worse.

/// One lexical frame in a body walk. A block's frame holds its items
/// and `use`s from the block's start (`Rewrite::block` binds them
/// first), so they cover the whole block, as in rustc.
#[derive(Default, Clone)]
struct Frame {
    locals: Vec<Sym>,
    /// Value names of the block's own items (`fn`, `const`, `static`,
    /// and the constructor of a unit or tuple struct). A path that
    /// names one stays written: check resolves it through its block
    /// item scopes, and it hides module items of the name.
    items: Vec<Sym>,
    /// Type names of the block's own type items (struct, enum, union,
    /// trait, type alias) with their `Ast::stmt_items` index. A path
    /// through one stays written, as for `items`: check resolves it
    /// through its block type overlay (R18).
    types: Vec<(Sym, u32)>,
    /// The unit and tuple structs among `types`: a binding pattern of
    /// one of these names is a path pattern to it (`binding_pat`).
    ctors: Vec<Sym>,
    /// Function-local imports of block items (`use E::V;`, `use E::*;`,
    /// `use S as T;` for a block-local `E` or `S`): (name, namespace
    /// index) to the written path the name stands for. A use site
    /// rewrites the name to that path (`local_use_path`).
    local_uses: FxMap<(Sym, usize), LocalUse>,
    /// Function-local imports: (name, namespace index) to target.
    imports: FxMap<(Sym, usize), LocalBind>,
    /// Function-local `use std::... [as Name]` imports, in the
    /// shape of `ResolvedTables::std_aliases`.
    std_imports: FxMap<(Sym, usize), Vec<Sym>>,
    /// Names bound at explicit rank in this frame, by an explicit `use`
    /// or a nested item: a second explicit binding of one name in one
    /// namespace is a duplicate, where a glob binding is not.
    explicit: Vec<(Sym, usize)>,
    /// The block has a glob import of a std module (not an enum). It
    /// may bring any name, and it shadows outer scopes for those names
    /// (`Rewrite::std_glob_check`).
    std_mod_glob: bool,
    /// The paths of the block's std globs (modules and enums), for
    /// `Rewrite::std_glob_ambiguous`.
    std_glob_paths: Vec<Vec<Sym>>,
}

#[derive(Clone, Copy)]
enum LocalBind {
    Target(Target),
    Ambiguous,
}

/// One function-local import of a block item (`Frame::local_uses`).
/// `path` is the written path the imported name stands for (`[E, V]`
/// for `use E::V;`); `item` is the `Ast::stmt_items` index of the block
/// item its first segment names, so a use site can tell whether an
/// inner block shadows that name. `glob` marks a binding from
/// `use E::*;`; `ambiguous` two globs that bring different items.
#[derive(Clone)]
struct LocalUse {
    path: Vec<Sym>,
    item: u32,
    glob: bool,
    ambiguous: bool,
}

/// What the innermost frame that knows a path's first segment says
/// (`Rewrite::frame_hit`).
enum FrameHit {
    /// A local variable or a block item: the path stays written.
    Local,
    /// A function-local `use` of a crate item (or an ambiguous glob).
    Import(LocalBind),
    /// A function-local `use std::...`: the canonical std path.
    Std(Vec<Sym>),
    /// A function-local import of a block item (`Frame::local_uses`).
    LocalUse(LocalUse),
}

struct Rewrite<'a> {
    tables: &'a ResolvedTables,
    interner: &'a Interner,
    list_module: &'a FxMap<ItemListKey, ModuleId>,
    /// Every name some module defines locally, built once over the
    /// frozen tables (`ResolvedTables::local_named_set`).
    local_names: &'a FxMap<Sym, u8>,
    diags: Vec<Diag>,
    /// The type and const params (name, is const) of the item being
    /// rewritten, after its impl's or trait's for a method. As in rustc,
    /// a param shadows module items and imports for a path's first
    /// segment, so such paths stay as written; check resolves them
    /// against the item's generics.
    gen_params: Vec<(Sym, bool)>,
    /// `CrateInput::std_splice_lo`: a top-level inherent impl at or after
    /// it in the root file is a std method chunk of a lang enum (`impl<T>
    /// Option<T>`, stdload's `MethodChunk`), left as written. Std source
    /// must not resolve to user names; check resolves it in `STD_MODULE`.
    /// (The std source modules are `mod` items: the rewrite walks them.)
    std_splice_lo: Option<u32>,
    /// `gen_params` below this index belong to items around the block
    /// item being rewritten (a nested fn, const, or static). They still
    /// shadow module items, but a path to one is rustc E0401.
    gen_floor: usize,
}

impl Rewrite<'_> {
    /// The namespaces some module defines `name` in (`local_names`), noted
    /// as a read of the crate-wide set (resolve/mdr.rs).
    fn local_name(&self, name: Sym) -> Option<u8> {
        crate::resolve::mdr::read_name(name);
        self.local_names.get(&name).copied()
    }

    /// Rewrites one file's top-level items (recursing into inline mods).
    fn file_items(&mut self, ast: &mut Ast, fi: usize, module: ModuleId, prefix: &[Sym]) {
        let mut items = std::mem::take(&mut ast.items);
        self.items(ast, &mut items, fi, module, prefix);
        ast.items = items;
    }

    /// Rewrites the trait paths in one bound list.
    fn bounds(&mut self, ast: &mut Ast, bounds: &mut Vec<crate::ast::TraitBound>, span: Span, module: ModuleId) {
        self.bounds_in(ast, bounds, span, module, &[]);
    }

    /// `bounds` for an item in a body: its bounds also see `outer` (the
    /// item frames of the blocks around it).
    fn bounds_in(&mut self, ast: &mut Ast, bounds: &mut Vec<crate::ast::TraitBound>, span: Span, module: ModuleId, outer: &[Frame]) {
        for b in bounds.iter_mut() {
            if let crate::ast::TraitBound::Trait { trait_ref, .. } = b {
                self.rewrite_path(&mut trait_ref.path, Namespace::Type, span, module, outer, ast);
            }
        }
    }

    /// Whether a generic param (a const one when `is_const`) takes a
    /// path's first segment in namespace `ns`: any param in a type path,
    /// a const param as a one-segment value, a type param before `::`
    /// in a value path (`T::default()`).
    fn param_takes(ns: Namespace, single: bool, is_const: bool) -> bool {
        match ns {
            Namespace::Type => true,
            Namespace::Value => single == is_const,
            _ => false,
        }
    }

    /// Pushes one item's type and const params for the paths inside it;
    /// returns the length to truncate back to when the item ends.
    fn push_params(&mut self, g: &crate::ast::Generics) -> usize {
        let mark = self.gen_params.len();
        for p in &g.params {
            match p {
                crate::ast::GenericParam::Type { name, .. } => self.gen_params.push((*name, false)),
                crate::ast::GenericParam::Const { name, .. } => self.gen_params.push((*name, true)),
                crate::ast::GenericParam::Lifetime { .. } => {}
            }
        }
        mark
    }

    /// Rewrites one item's generic parameter bounds, defaults,
    /// and where clause (trait paths name traits in this module).
    fn generics(&mut self, ast: &mut Ast, g: &mut crate::ast::Generics, w: &mut crate::ast::WhereClause, module: ModuleId) {
        self.generics_in(ast, g, w, module, &[]);
    }

    /// `generics` for an item in a body (a nested fn, a block impl and its
    /// methods): bounds and types also see `outer`, the item frames of the
    /// blocks around it, so a block type in a where clause is that type.
    fn generics_in(&mut self, ast: &mut Ast, g: &mut crate::ast::Generics, w: &mut crate::ast::WhereClause, module: ModuleId, outer: &[Frame]) {
        for p in g.params.iter_mut() {
            match p {
                crate::ast::GenericParam::Type { bounds, default, span, .. } => {
                    self.bounds_in(ast, bounds, *span, module, outer);
                    if let Some(d) = *default {
                        self.ty(ast, d, module, outer);
                    }
                }
                crate::ast::GenericParam::Const { ty, default, .. } => {
                    let ty = *ty;
                    self.ty(ast, ty, module, outer);
                    // A default with a body of its own resolves like a
                    // const argument (`check/const_body.rs` checks it).
                    if let Some(d) = *default
                        && anon_const_module(ast, d, module)
                    {
                        self.expr(ast, d, module, &mut vec![Frame::default()]);
                    }
                }
                crate::ast::GenericParam::Lifetime { .. } => {}
            }
        }
        for pred in w.preds.iter_mut() {
            if let crate::ast::WherePred::Type { ty, bounds, .. } = pred {
                let ty = *ty;
                self.ty(ast, ty, module, outer);
                self.bounds_in(ast, bounds, w.span, module, outer);
            }
        }
    }

    fn items(&mut self, ast: &mut Ast, items: &mut Vec<Item>, fi: usize, module: ModuleId, prefix: &[Sym]) {
        for item in items.iter_mut() {
            if module == ROOT_MODULE
                && item.span.file == crate::diag::FileId(0)
                && self.std_splice_lo.is_some_and(|lo| item.span.lo >= lo)
                && matches!(&item.kind, ItemKind::Impl(imp) if imp.trait_ref.is_none())
            {
                continue;
            }
            match &mut item.kind {
                ItemKind::Fn(f) => {
                    let mut def = std::mem::replace(f, dummy_fn());
                    self.fn_def(ast, &mut def, module);
                    *f = def;
                }
                ItemKind::Struct(s) => {
                    let mark = self.push_params(&s.generics);
                    self.generics(ast, &mut s.generics, &mut s.where_clause, module);
                    let fields = match &mut s.fields {
                        VariantFields::Struct(fs) | VariantFields::Tuple(fs) => fs.iter_mut().map(|f| f.ty).collect::<Vec<_>>(),
                        VariantFields::Unit => Vec::new(),
                    };
                    for t in fields {
                        self.ty(ast, t, module, &[]);
                    }
                    self.gen_params.truncate(mark);
                }
                ItemKind::Enum(e) => {
                    let mark = self.push_params(&e.generics);
                    self.generics(ast, &mut e.generics, &mut e.where_clause, module);
                    let mut tys = Vec::new();
                    let mut discs = Vec::new();
                    for v in &mut e.variants {
                        if let VariantFields::Struct(fs) | VariantFields::Tuple(fs) = &v.fields {
                            tys.extend(fs.iter().map(|f| f.ty));
                        }
                        if let Some(d) = v.discriminant {
                            discs.push(d);
                        }
                    }
                    for t in tys {
                        self.ty(ast, t, module, &[]);
                    }
                    // Discriminants cannot use the enum's params (rustc
                    // rejects them there), so they resolve as before.
                    self.gen_params.truncate(mark);
                    let mut scopes = vec![Frame::default()];
                    for d in discs {
                        anon_const_module(ast, d, module);
                        self.expr(ast, d, module, &mut scopes);
                    }
                }
                ItemKind::Impl(imp) => {
                    let mark = self.push_params(&imp.generics);
                    self.generics(ast, &mut imp.generics, &mut imp.where_clause, module);
                    if let Some(tr) = &mut imp.trait_ref {
                        let span = imp.span;
                        self.rewrite_path(&mut tr.path, Namespace::Type, span, module, &[], ast);
                    }
                    self.ty(ast, imp.self_ty, module, &[]);
                    for at in imp.types.iter_mut() {
                        self.bounds(ast, &mut at.bounds, at.span, module);
                        self.generics(ast, &mut at.generics, &mut at.where_clause, module);
                        if let Some(d) = at.default {
                            self.ty(ast, d, module, &[]);
                        }
                    }
                    let const_tys: Vec<crate::ast::TyId> = imp.consts.iter().map(|c| c.ty).collect();
                    for t in const_tys {
                        self.ty(ast, t, module, &[]);
                    }
                    // Associated const values resolve like a const
                    // item's: in this module, with no locals in scope.
                    let values: Vec<crate::ast::ExprId> = imp.consts.iter().filter_map(|c| c.default).collect();
                    for v in values {
                        self.expr(ast, v, module, &mut vec![Frame::default()]);
                    }
                    let mut fns = std::mem::take(&mut imp.fns);
                    for f in &mut fns {
                        self.fn_def(ast, f, module);
                    }
                    imp.fns = fns;
                    self.gen_params.truncate(mark);
                }
                ItemKind::Trait(t) => {
                    let mark = self.push_params(&t.generics);
                    self.generics(ast, &mut t.generics, &mut t.where_clause, module);
                    self.bounds(ast, &mut t.bounds, t.span, module);
                    for at in t.types.iter_mut() {
                        self.bounds(ast, &mut at.bounds, at.span, module);
                        self.generics(ast, &mut at.generics, &mut at.where_clause, module);
                        if let Some(d) = at.default {
                            self.ty(ast, d, module, &[]);
                        }
                    }
                    let const_tys: Vec<crate::ast::TyId> = t.consts.iter().map(|c| c.ty).collect();
                    for ty in const_tys {
                        self.ty(ast, ty, module, &[]);
                    }
                    let values: Vec<crate::ast::ExprId> = t.consts.iter().filter_map(|c| c.default).collect();
                    for v in values {
                        self.expr(ast, v, module, &mut vec![Frame::default()]);
                    }
                    let mut fns = std::mem::take(&mut t.fns);
                    for f in &mut fns {
                        self.fn_def(ast, f, module);
                    }
                    t.fns = fns;
                    self.gen_params.truncate(mark);
                }
                ItemKind::Const(c) => {
                    self.ty(ast, c.ty, module, &[]);
                    if let Some(v) = c.value {
                        let mut scopes = vec![Frame::default()];
                        self.expr(ast, v, module, &mut scopes);
                    }
                }
                ItemKind::Static(s) => {
                    self.ty(ast, s.ty, module, &[]);
                    if let Some(v) = s.value {
                        let mut scopes = vec![Frame::default()];
                        self.expr(ast, v, module, &mut scopes);
                    }
                }
                ItemKind::Type(a) => {
                    let mark = self.push_params(&a.generics);
                    self.generics(ast, &mut a.generics, &mut a.where_clause, module);
                    self.ty(ast, a.ty, module, &[]);
                    self.gen_params.truncate(mark);
                }
                ItemKind::Mod(m) => {
                    let mut key = prefix.to_vec();
                    key.push(m.name);
                    if let (Some(body), Some(&child)) = (&mut m.body, self.list_module.get(&(fi, key.clone()))) {
                        self.items(ast, body, fi, child, &key);
                    }
                }
                _ => {}
            }
        }
    }

    /// Rewrites one fn's signature types and body.
    fn fn_def(&mut self, ast: &mut Ast, def: &mut FnDef, module: ModuleId) {
        self.fn_def_in(ast, def, module, &[]);
    }

    /// `fn_def` for a fn whose signature and body also see `outer`
    /// (the item frames of the blocks around a nested fn).
    fn fn_def_in(&mut self, ast: &mut Ast, def: &mut FnDef, module: ModuleId, outer: &[Frame]) {
        let mark = self.push_params(&def.generics);
        self.generics_in(ast, &mut def.generics, &mut def.where_clause, module, outer);
        // A typed receiver (`self: &Arc<Self>`) names types as a param does.
        if let Some(t) = def.self_param.as_ref().and_then(|sp| sp.ty) {
            self.ty(ast, t, module, outer);
        }
        for p in &def.params {
            let t = p.ty;
            self.ty(ast, t, module, outer);
        }
        if let Some(t) = def.ret {
            self.ty(ast, t, module, outer);
        }
        self.fn_body(ast, def, module, outer);
        self.gen_params.truncate(mark);
    }

    /// The body half of `fn_def_in`: the parameter bindings, then the
    /// body block. The item's params must already be in `gen_params`.
    fn fn_body(&mut self, ast: &mut Ast, def: &FnDef, module: ModuleId, outer: &[Frame]) {
        if let Some(body) = def.body {
            let mut scopes = if outer.is_empty() { vec![Frame::default()] } else { outer.to_vec() };
            let mut frame = Frame::default();
            for p in &def.params {
                match p.pat {
                    Some(pat) => self.pat_bindings(ast, pat, &mut frame.locals),
                    None => {
                        self.binding_over_block_import(p.name, !p.mutable, p.span, &scopes);
                        // A parameter named like a block `use` of a block
                        // enum's variant is that variant's path pattern in
                        // rustc (refutable, or a type mismatch); lust
                        // rejects it (a single-variant enum would be valid).
                        if let Some(FrameHit::LocalUse(_)) = self.frame_hit(&[p.name], Namespace::Value, &scopes) {
                            let n = self.interner.get(p.name);
                            self.diags.push(Diag::new(
                                "L0110",
                                p.span,
                                format!("parameter `{n}` names an imported variant here, so it would be a pattern, not a binding"),
                                "Rename the parameter.",
                            ));
                        }
                        frame.locals.push(p.name);
                    }
                }
            }
            scopes.push(frame);
            self.block(ast, body, module, &mut scopes);
        }
    }

    /// Collects the binding names a pattern introduces.
    fn pat_bindings(&self, ast: &Ast, id: PatId, out: &mut Vec<Sym>) {
        match ast.pat(id) {
            Pat::Binding { name, .. } => out.push(*name),
            Pat::At { name, inner, .. } => {
                out.push(*name);
                self.pat_bindings(ast, *inner, out);
            }
            Pat::TupleStruct { elems, .. } | Pat::Tuple(elems) | Pat::Or(elems) => {
                for e in elems {
                    self.pat_bindings(ast, *e, out);
                }
            }
            Pat::Struct { fields, .. } => {
                for (_, f) in fields {
                    self.pat_bindings(ast, *f, out);
                }
            }
            Pat::Slice { prefix, middle, suffix } => {
                for e in prefix.iter().chain(suffix) {
                    self.pat_bindings(ast, *e, out);
                }
                if let Some(m) = middle {
                    self.pat_bindings(ast, *m, out);
                }
            }
            Pat::Ref { inner, .. } | Pat::Paren(inner) => self.pat_bindings(ast, *inner, out),
            _ => {}
        }
    }

    /// True when `name` is a local or a block item in any open frame:
    /// check resolves a written path of that name to it first.
    fn frames_bind(scopes: &[Frame], name: Sym) -> bool {
        scopes.iter().rev().any(|f| f.locals.contains(&name) || f.items.contains(&name) || f.types.iter().any(|t| t.0 == name))
    }

    /// The innermost frame binding of a path's first segment, as
    /// rustc's ribs: frames from the innermost out, and in each one
    /// its locals, then its items, then its `use`s. The first segment
    /// of a longer path reads the type namespace.
    fn frame_hit(&self, segs: &[Sym], ns: Namespace, scopes: &[Frame]) -> Option<FrameHit> {
        let &first = segs.first()?;
        if matches!(self.interner.get(first), "crate" | "self" | "super" | "Self" | "::") {
            return None;
        }
        let asked = if segs.len() > 1 { Namespace::Type } else { ns };
        let key = (first, ns_index(asked));
        for frame in scopes.iter().rev() {
            if asked != Namespace::Type && (frame.locals.contains(&first) || frame.items.contains(&first)) {
                return Some(FrameHit::Local);
            }
            if asked == Namespace::Type && frame.types.iter().any(|t| t.0 == first) {
                return Some(FrameHit::Local);
            }
            if let Some(u) = frame.local_uses.get(&key) {
                return Some(FrameHit::LocalUse(u.clone()));
            }
            if let Some(b) = frame.imports.get(&key) {
                return Some(FrameHit::Import(*b));
            }
            if let Some(p) = frame.std_imports.get(&key) {
                return Some(FrameHit::Std(p.clone()));
            }
        }
        None
    }

    /// Resolves a path with lexical scopes first. A local variable or
    /// block item is reported as Absent with the `local` flag set:
    /// callers leave the path written. A function-local std import
    /// is Absent too (not local): `expand_std_alias` rewrites it.
    fn resolve(&self, segs: &[Sym], ns: Namespace, module: ModuleId, scopes: &[Frame]) -> (PathRes, bool) {
        match self.frame_hit(segs, ns, scopes) {
            Some(FrameHit::Local | FrameHit::LocalUse(_)) => (PathRes::Absent, true),
            Some(FrameHit::Std(_)) => (PathRes::Absent, false),
            Some(FrameHit::Import(LocalBind::Ambiguous)) => (PathRes::Ambiguous, false),
            Some(FrameHit::Import(LocalBind::Target(t))) => {
                if segs.len() == 1 {
                    (PathRes::Done(t), false)
                } else {
                    match self.tables.walk_from(module, t, &segs[1..], ns, self.interner) {
                        PathRes::Partial(t2, rest) => (PathRes::Partial(t2, rest + 1), false),
                        other => (other, false),
                    }
                }
            }
            None => (self.tables.resolve_path(module, segs, ns, PathMode::Lexical, false, self.interner), false),
        }
    }

    /// One frame's binding of a first segment in one namespace, as
    /// a `SegInfo`, for import resolution. Block items and explicit
    /// imports are hard bindings; glob copies are soft. A local
    /// variable never takes an import path's first segment, so
    /// locals do not count here.
    fn frame_seg(frame: &Frame, name: Sym, ns: Namespace) -> Option<SegInfo> {
        let key = (name, ns_index(ns));
        if (ns == Namespace::Value && frame.items.contains(&name))
            || (ns == Namespace::Type && frame.types.iter().any(|t| t.0 == name))
            || frame.local_uses.contains_key(&key)
        {
            // A block item hides any import of the name in its
            // frame, as in `frame_hit`. Its target is not a
            // `Target` the tables know; a path through it stays
            // written, so only its hard rank matters here. The
            // placeholder def never compares equal to a real one.
            return Some(SegInfo { bind: SegBind::Target(Target::Def(DefId::PLACEHOLDER)), glob: false });
        }
        if let Some(b) = frame.imports.get(&key) {
            return Some(match b {
                LocalBind::Ambiguous => SegInfo { bind: SegBind::Ambiguous, glob: true },
                LocalBind::Target(t) => SegInfo { bind: SegBind::Target(*t), glob: !frame.explicit.contains(&key) },
            });
        }
        if let Some(p) = frame.std_imports.get(&key) {
            return Some(SegInfo { bind: SegBind::Std(p.clone()), glob: !frame.explicit.contains(&key) });
        }
        None
    }

    /// Resolves a `use` path's first segment under import
    /// resolution (rustc E0659): unlike ordinary paths (`resolve`),
    /// a glob binding in an inner frame does not shadow a
    /// different item in an outer frame, the module, the std
    /// prelude, or the extern prelude: the pair is ambiguous. An
    /// explicit import or block item in any frame is a hard
    /// binding and stops the outward search. The same item by
    /// two paths is never ambiguous. Returns the binding an
    /// import through this segment reads, and whether a block
    /// frame provided it (the caller then walks the rest of the
    /// path from that binding instead of the module tables).
    fn import_seg(&self, name: Sym, ns: Namespace, module: ModuleId, scopes: &[Frame]) -> (SegInfo, bool) {
        let mut soft: Option<SegBind> = None;
        for frame in scopes.iter().rev() {
            let Some(info) = Self::frame_seg(frame, name, ns) else { continue };
            if matches!(info.bind, SegBind::Ambiguous) {
                return (SegInfo { bind: SegBind::Ambiguous, glob: true }, true);
            }
            match &soft {
                None => {
                    if info.glob {
                        soft = Some(info.bind);
                    } else {
                        return (info, true);
                    }
                }
                Some(prev) => {
                    // The search does not stop at an outer binding
                    // of the same item: a different binding further
                    // out still makes the inner glob ambiguous (an
                    // explicit import of `a::q` in an outer block
                    // does not cover the module `q` behind it).
                    if !self.tables.same_seg(prev, &info.bind, self.interner) {
                        return (SegInfo { bind: SegBind::Ambiguous, glob: true }, true);
                    }
                }
            }
        }
        let outer = self.tables.module_seg(module, name, ns, self.interner);
        match soft {
            None => (outer, false),
            Some(prev) => {
                if matches!(outer.bind, SegBind::None) {
                    (SegInfo { bind: prev, glob: true }, true)
                } else if matches!(outer.bind, SegBind::Ambiguous) || !self.tables.same_seg(&prev, &outer.bind, self.interner) {
                    (SegInfo { bind: SegBind::Ambiguous, glob: true }, true)
                } else {
                    (SegInfo { bind: prev, glob: true }, true)
                }
            }
        }
    }

    /// The import-resolution ambiguity check of one block `use`
    /// item (see `block`): each flattened import's first segment
    /// must not be ambiguous between a glob binding in scope and
    /// an outer item. A leading `::` reads the extern prelude
    /// only, and `crate`/`self`/`super` are keywords, so neither
    /// can be ambiguous this way.
    fn check_block_use(&mut self, ast: &Ast, idx: u32, module: ModuleId, scopes: &[Frame]) {
        let Some(item) = ast.stmt_items.get(idx as usize) else { return };
        let ItemKind::Use(u) = &item.kind else { return };
        let span = item.span;
        let mut flat = Vec::new();
        flatten_use(&u.tree, module, VisKind::Priv, &mut flat, self.interner);
        let mut seen: Vec<Sym> = Vec::new();
        for imp in flat {
            if imp.leading_colon {
                continue;
            }
            let path: &[Sym] = match &imp.kind {
                ImportKind::Single { path, .. } | ImportKind::CheckPath { path } | ImportKind::Glob { path } => path,
                ImportKind::BadLeading { .. } => continue,
            };
            let Some(&first) = path.first() else { continue };
            if matches!(self.interner.get(first), "crate" | "self" | "super" | "Self") || self.tables.crate_magic.contains_key(&first) {
                continue;
            }
            if seen.contains(&first) {
                continue;
            }
            let nss: &[Namespace] = if path.len() == 1 && matches!(imp.kind, ImportKind::Single { .. }) {
                &[Namespace::Type, Namespace::Value, Namespace::Macro]
            } else {
                &[Namespace::Type]
            };
            for &ns in nss {
                let (info, _) = self.import_seg(first, ns, module, scopes);
                if matches!(info.bind, SegBind::Ambiguous) {
                    // Ambiguity this name already has in the module
                    // tables alone (no frame glob over an outer
                    // item) keeps its existing diagnostics; the
                    // pair this check adds carries glob rank.
                    if info.glob {
                        seen.push(first);
                        self.diags.push(ambiguous_diag(self.interner.get(first), span));
                    }
                    break;
                }
            }
        }
    }

    /// The resolution a `use` path gets when a block frame binds
    /// its first segment: the rest of the path walks from that
    /// binding (`import_seg`), as rustc reads it, instead of
    /// from the module tables, where a nearer module binding of
    /// the name may name a different item. None when no frame
    /// binds the segment as a plain target (std aliases rewire
    /// their path instead, in `stmt_item`).
    fn frame_use_target(&self, path: &[Sym], leading: bool, module: ModuleId, scopes: &[Frame]) -> Option<PathRes> {
        if leading || path.is_empty() {
            return None;
        }
        let first = path[0];
        if matches!(self.interner.get(first), "crate" | "self" | "super" | "Self") || self.tables.crate_magic.contains_key(&first) {
            return None;
        }
        let (info, from_frame) = self.import_seg(first, Namespace::Type, module, scopes);
        if !from_frame {
            return None;
        }
        match info.bind {
            SegBind::Target(t) => Some(match self.tables.walk_from(module, t, &path[1..], Namespace::Type, self.interner) {
                PathRes::Partial(t2, rest) => PathRes::Partial(t2, rest + 1),
                other => other,
            }),
            SegBind::Ambiguous => Some(PathRes::Ambiguous),
            _ => None,
        }
    }

    /// Binds every visible name of module `src` into the innermost
    /// frame at glob rank, with the trait records a function-local
    /// glob makes (`stmt_item`'s glob branch, shared by the
    /// module-tables path and the frame-binding path).
    fn glob_from_module(&mut self, ast: &mut Ast, src: ModuleId, module: ModuleId, scopes: &mut [Frame], span: Span) {
        let mut entries = Vec::new();
        crate::resolve::mdr::read(src);
        for ns in [Namespace::Type, Namespace::Value, Namespace::Macro] {
            for (name, state) in &self.tables.maps[src.0 as usize][ns_index(ns)] {
                match state {
                    BindState::One(b) if self.tables.visible(&b.vis, b.def_module, module, self.interner) => {
                        entries.push((*name, ns, LocalBind::Target(b.target)));
                    }
                    BindState::Ambiguous => entries.push((*name, ns, LocalBind::Ambiguous)),
                    _ => {}
                }
            }
        }
        for (name, ns, bind) in entries {
            if ns == Namespace::Type
                && let LocalBind::Target(target) = bind
            {
                self.record_use_trait_target(ast, span, target);
            }
            insert_local(scopes, name, ns, bind, 1);
        }
        for (ns, name, _, _, path) in self.tables.visible_std_aliases(src, module, self.interner) {
            if ns == ns_index(Namespace::Type) as u8 {
                self.record_use_trait_std(ast, span, &path);
            }
            insert_glob_local_std(scopes, name, ns as usize, path);
        }
    }

    /// True when the checker would read the rewritten head `flat` of a
    /// path to `def` as something else at this site. It reads a written
    /// name as a local or block item first (value paths of one segment),
    /// then in the module's own table, and only then in the flat index.
    /// A crate-root item keeps its plain name as its flat name, so
    /// `super::f` from a module with its own `f`, or `crate::f` under a
    /// local `f`, would land on the nearer binding.
    fn misread(&self, flat: Sym, def: DefId, ns: Namespace, single: bool, module: ModuleId, scopes: &[Frame]) -> bool {
        if single && ns == Namespace::Value && Self::frames_bind(scopes, flat) {
            return true;
        }
        // The checker reads a written type name as a block type item
        // first (its R18 overlay), so a type path or a path prefix
        // under a block type item of the flat name would land on it.
        if (ns == Namespace::Type || !single) && scopes.iter().any(|f| f.types.iter().any(|t| t.0 == flat)) {
            return true;
        }
        // A crate-root item's flat name is its plain name, so a generic
        // param of the item being checked would take `crate::N` too.
        if self.gen_params[self.gen_floor..].iter().any(|&(n, is_const)| n == flat && Self::param_takes(ns, single, is_const)) {
            return true;
        }
        let ns = if single { ns } else { Namespace::Type };
        match self.tables.lookup(module, ns, flat) {
            Some(BindState::One(b)) => self.tables.target_def(b.target) != def,
            Some(BindState::Ambiguous) => true,
            None => false,
        }
    }

    /// The flat name to write for `def` at this site: its own, or,
    /// where the checker would read that as a nearer binding
    /// (`misread`), a crate-root item's `crate$` alias (`insert_flat`).
    /// Any other misread is the L0505 reject (a false reject).
    #[allow(clippy::too_many_arguments)]
    fn flat_at(&mut self, flat: Sym, def: DefId, ns: Namespace, single: bool, module: ModuleId, scopes: &[Frame], span: Span) -> Sym {
        if !self.misread(flat, def, ns, single, module, scopes) {
            return flat;
        }
        let alias = root_alias(flat, self.interner);
        let ns = if single { ns } else { Namespace::Type };
        if self.tables.flat[ns_index(ns)].get(&alias) == Some(&def) {
            return alias;
        }
        self.diags.push(crate::diag::not_yet(
            "L0505",
            span,
            "a path to a crate-root item whose name a nearer item, import, or local also binds",
        ));
        flat
    }

    /// Applies a resolution to a written path in place. `span` is the
    /// path's own span for diagnostics; `ns` and `scopes` are the
    /// namespace and frames the checker will read the rewritten path in.
    fn apply(&mut self, segs: &mut Vec<PathSeg>, res: PathRes, span: Span, module: ModuleId, ns: Namespace, scopes: &[Frame]) {
        match res {
            PathRes::Done(Target::Def(def)) => {
                if let Some(info) = self.tables.def_info.get(&def) {
                    let flat = self.flat_at(info.flat, def, ns, true, module, scopes, span);
                    let args = segs.last().map(|s| s.args.clone()).unwrap_or_default();
                    *segs = vec![PathSeg { name: flat, args }];
                }
            }
            PathRes::Done(Target::Variant(def, variant)) => {
                if let Some(info) = self.tables.def_info.get(&def) {
                    let flat = self.flat_at(info.flat, def, ns, false, module, scopes, span);
                    // Written generic args stay on their segment
                    // (`E::<u8>::V`, `V::<u8>`): the checker reads them.
                    let n = segs.len();
                    let variant_args = segs.last().map(|s| s.args.clone()).unwrap_or_default();
                    let enum_args = if n >= 2 { segs[n - 2].args.clone() } else { Default::default() };
                    *segs = vec![PathSeg { name: flat, args: enum_args }, PathSeg { name: variant, args: variant_args }];
                }
            }
            PathRes::Done(Target::Module(_)) => {
                // A module as a value or type is an error the checker
                // reports; leave the path written.
            }
            PathRes::Done(Target::Extern(i)) => {
                let e = &self.tables.externs[i as usize];
                if let Some(why) = &e.unsupported {
                    self.diags.push(unsupported_diag(why, span));
                } else if !e.is_std_lib {
                    self.diags.push(crate::diag::not_yet("L0505", span, "items from other crates"));
                }
            }
            PathRes::Partial(Target::Def(def), rest) => {
                if rest + 1 == segs.len() {
                    if let Some(info) = self.tables.def_info.get(&def) {
                        let flat = self.flat_at(info.flat, def, ns, false, module, scopes, span);
                        let item_seg = segs[rest].clone();
                        // Associated fn visibility (variants take the
                        // enum's vis, already checked by resolution).
                        if let Some(methods) = self.tables.assoc_vis.get(&def)
                            && let Some((vis, def_mod)) = methods.get(&item_seg.name)
                            && !self.tables.visible(vis, *def_mod, module, self.interner)
                        {
                            self.diags.push(private_diag(self.interner.get(item_seg.name), span));
                        }
                        // The def segment keeps its written generic
                        // arguments (`W::<u8>::item`): the checker
                        // reads them as the Self type's arguments.
                        let mut head = segs[rest.saturating_sub(1)].clone();
                        head.name = flat;
                        *segs = vec![head, item_seg];
                    }
                }
            }
            PathRes::Partial(Target::Variant(..), _) => {}
            PathRes::Partial(Target::Extern(i), _) => {
                let e = &self.tables.externs[i as usize];
                if let Some(why) = &e.unsupported {
                    self.diags.push(unsupported_diag(why, span));
                } else if !e.is_std_lib {
                    self.diags.push(crate::diag::not_yet("L0505", span, "items from other crates"));
                }
            }
            PathRes::Partial(Target::Module(_), _) => {}
            PathRes::Ambiguous => {
                let name = segs.last().map(|s| self.interner.get(s.name).to_string()).unwrap_or_default();
                self.diags.push(ambiguous_diag(&name, span));
            }
            PathRes::OrderDep => {
                let name: Vec<&str> = segs.iter().map(|s| self.interner.get(s.name)).collect();
                self.diags.push(crate::resolve::order::order_diag(&name.join("::"), span));
            }
            PathRes::Private => {
                let name = segs.last().map(|s| self.interner.get(s.name).to_string()).unwrap_or_default();
                self.diags.push(private_diag(&name, span));
            }
            PathRes::Prelude | PathRes::Absent => {}
        }
    }

    /// Rewrites a struct-literal or pattern path. A variant brought in
    /// by `use E::*` or `use E::V` binds in the value namespace, so
    /// probe it first; a plain struct name takes the type path as before.
    fn rewrite_ctor_path(&mut self, segs: &mut Vec<PathSeg>, span: Span, module: ModuleId, scopes: &[Frame], ast: &mut Ast) {
        let names: Vec<Sym> = segs.iter().map(|s| s.name).collect();
        let (res, local) = self.resolve(&names, Namespace::Value, module, scopes);
        if !local && matches!(res, PathRes::Done(Target::Variant(..))) {
            self.rewrite_path(segs, Namespace::Value, span, module, scopes, ast);
        } else {
            self.rewrite_path(segs, Namespace::Type, span, module, scopes, ast);
        }
    }

    /// Expands a path whose first segment is bound by a std import
    /// (`use std::option::Option as O2`, `use std::mem as m`) back
    /// to the canonical written std path. Function-local target
    /// imports and explicit module bindings already resolved by
    /// `resolve` keep the name; a glob binding (rank 1) loses to
    /// the explicit std import, as in Rust. The asked namespace
    /// wins, with the others as a fallback for the paths that probe
    /// two namespaces (variant constructors in patterns).
    fn expand_std_alias(&self, segs: &mut Vec<PathSeg>, names: &[Sym], ns: Namespace, module: ModuleId, scopes: &[Frame]) -> bool {
        let Some(&first) = names.first() else { return false };
        if matches!(self.interner.get(first), "crate" | "self" | "super" | "Self") {
            return false;
        }
        let asked = if names.len() > 1 { Namespace::Type } else { ns };
        let asked_idx = ns_index(asked);
        // A block's std import beats module items (`use std::mem::swap;`
        // in a body over a crate `fn swap`); a nearer frame binding of
        // the name beats it.
        match self.frame_hit(names, ns, scopes) {
            Some(FrameHit::Std(path)) => {
                if self.module_keeps_primitive(names, ns, &path) {
                    return false;
                }
                Self::splice_std_path(segs, &path);
                return true;
            }
            Some(_) => return false,
            None => {}
        }
        if matches!(self.tables.lookup(module, asked, first), Some(BindState::One(b)) if b.rank >= 2) {
            return false;
        }
        let mut order = [asked_idx; 3];
        let mut n_order = 1;
        for idx in [ns_index(Namespace::Type), ns_index(Namespace::Value), ns_index(Namespace::Macro)] {
            if !order[..n_order].contains(&idx) {
                order[n_order] = idx;
                n_order += 1;
            }
        }
        let alias = scopes
            .iter()
            .rev()
            .flat_map(|f| order[..n_order].iter().filter_map(move |&idx| f.std_imports.get(&(first, idx))))
            .next()
            .or_else(|| {
                order[..n_order]
                    .iter()
                    .filter_map(|&idx| {
                        crate::resolve::mdr::read_key(module, idx as u8, first);
                        self.tables.std_aliases.get(&(module, idx as u8, first)).map(|(_, p)| p)
                    })
                    .next()
            });
        let Some(alias) = alias else { return false };
        if self.module_keeps_primitive(names, ns, alias) {
            return false;
        }
        Self::splice_std_path(segs, alias);
        true
    }

    /// Expands a path through a crate module to a std alias that module
    /// binds (`mod m { pub use std::thread::spawn; }` read as
    /// `m::spawn`, or `m::mem::swap` after `pub use std::mem;`): the
    /// longest module prefix whose next segment is a std alias there,
    /// visible from `module`, is replaced by the alias's std path.
    /// Callers try it only for a path that resolves to nothing else.
    fn expand_module_std_alias(&self, segs: &mut Vec<PathSeg>, names: &[Sym], ns: Namespace, module: ModuleId) -> bool {
        for plen in (1..names.len()).rev() {
            let PathRes::Done(Target::Module(m)) = self.tables.resolve_module_path(module, &names[..plen], false, self.interner) else {
                continue;
            };
            let seg = names[plen];
            let asked = if plen + 1 == names.len() { ns } else { Namespace::Type };
            let key = (m, ns_index(asked) as u8, seg);
            crate::resolve::mdr::read_key(m, key.1, seg);
            let Some((vis, path)) = self.tables.std_aliases.get(&key) else { return false };
            if !self.tables.visible(vis, self.tables.std_alias_def_module(key), module, self.interner) {
                return false;
            }
            let mut out: Vec<PathSeg> = path.iter().map(|s| PathSeg::plain(*s)).collect();
            if let Some(last) = out.last_mut() {
                last.args = segs[plen].args.clone();
            }
            out.extend(segs[plen + 1..].iter().cloned());
            *segs = out;
            return true;
        }
        false
    }

    /// A module import does not shadow a primitive type in a type
    /// position: `use std::str;` keeps `&str` the primitive.
    fn module_keeps_primitive(&self, names: &[Sym], ns: Namespace, alias: &[Sym]) -> bool {
        names.len() == 1
            && ns == Namespace::Type
            && crate::ty::lang::is_primitive_type_name(self.interner.get(names[0]))
            && crate::ty::lang::std_is_module_path(&alias.iter().map(|s| self.interner.get(*s)).collect::<Vec<_>>())
    }

    /// Replaces a path's first segment with a canonical std path.
    fn splice_std_path(segs: &mut Vec<PathSeg>, alias: &[Sym]) {
        let mut out: Vec<PathSeg> = alias.iter().map(|s| PathSeg::plain(*s)).collect();
        // Turbofish on the imported name belongs on the aliased item.
        if let Some(last) = out.last_mut() {
            last.args = segs[0].args.clone();
        }
        out.extend(segs.iter().skip(1).cloned());
        *segs = out;
    }

    /// The precise diagnostic for a path whose longest module prefix
    /// resolves but whose next segment is not in that module. None
    /// when no prefix is a real local module (an associated item of a
    /// type, a std path, an extern crate root), when the segment
    /// exists under another form the checker reports itself (a module
    /// read as a value, a std alias), or when the module is a hidden
    /// std source module (it holds only part of a std module, so a
    /// name it lacks may still be a std item lust has no form for).
    fn missing_in_module(&self, names: &[Sym], ns: Namespace, module: ModuleId, span: Span) -> Option<Diag> {
        if names.len() < 2 || ns == Namespace::Macro {
            return None;
        }
        for plen in (1..names.len()).rev() {
            let PathRes::Done(Target::Module(m)) = self.tables.resolve_module_path(module, &names[..plen], false, self.interner) else {
                continue;
            };
            if self.tables.std_modules.iter().any(|&(_, sm)| sm == m) {
                return None;
            }
            let seg = names[plen];
            let last = plen + 1 == names.len();
            let test_ns = if last { ns } else { Namespace::Type };
            if self.tables.lookup(m, test_ns, seg).is_some() {
                return None;
            }
            if test_ns != Namespace::Type
                && matches!(self.tables.lookup(m, Namespace::Type, seg), Some(BindState::One(b)) if matches!(b.target, Target::Module(_)))
            {
                return None;
            }
            if last
                && (0..3).any(|i| {
                    crate::resolve::mdr::read_key(m, i, seg);
                    self.tables.std_aliases.contains_key(&(m, i, seg))
                })
            {
                return None;
            }
            let in_module = names[..plen].iter().map(|s| self.interner.get(*s)).collect::<Vec<_>>().join("::");
            let seg = self.interner.get(seg);
            let fix = "Check the spelling, or import the item from the module that defines it.";
            return Some(if test_ns == Namespace::Value {
                Diag::new("L0101", span, format!("cannot find value `{seg}` in module `{in_module}`"), fix)
            } else {
                Diag::new("L0102", span, format!("cannot find type `{seg}` in module `{in_module}`"), fix)
            });
        }
        None
    }

    /// Reports a path `alloc::...` (after any `::` marker) written where
    /// the crate root has no `extern crate alloc;` (rustc E0433 in
    /// edition 2024), and says so. Check would read it by name.
    fn alloc_unlinked(&mut self, names: &[Sym], module: ModuleId, span: Span) -> bool {
        if names.len() < 2 || self.interner.get(names[0]) != "alloc" || !self.tables.alloc_out_of_scope(module) {
            return false;
        }
        self.diags.push(Diag::new(
            "L0102",
            span,
            "cannot find crate `alloc`: it is not linked",
            "Add `extern crate alloc;` at the crate root, or use the `std` path.",
        ));
        true
    }

    /// Rewrites one written path (segments borrowed out of the arena by
    /// the caller, then put back through `set`).
    fn rewrite_path(&mut self, segs: &mut Vec<PathSeg>, ns: Namespace, span: Span, module: ModuleId, scopes: &[Frame], ast: &mut Ast) {
        // Generic arguments hold types and const exprs of their own.
        let mut tys = Vec::new();
        let mut consts = Vec::new();
        for s in segs.iter() {
            collect_arg_tys(&s.args, &mut tys);
            collect_arg_consts(&s.args, &mut consts);
        }
        for t in tys {
            self.ty(ast, t, module, scopes);
        }
        // A const argument's paths resolve like an array length's:
        // in this module, with no locals in scope.
        for e in consts {
            anon_const_module(ast, e, module);
            let mut scopes = vec![Frame::default()];
            self.expr(ast, e, module, &mut scopes);
        }
        let names: Vec<Sym> = segs.iter().map(|s| s.name).collect();
        // A leading `::` arrives as a marker segment (parser). Resolve
        // through the extern prelude, and drop the marker when the path
        // stays written (std compat reads plain `std::...`).
        if names.first().is_some_and(|n| self.interner.get(*n) == "::") {
            if self.alloc_unlinked(&names[1..], module, span) {
                return;
            }
            let res = self.tables.resolve_path(module, &names[1..], ns, PathMode::Lexical, true, self.interner);
            match res {
                PathRes::Partial(Target::Extern(i), _) | PathRes::Done(Target::Extern(i)) if self.tables.externs[i as usize].is_std_lib => {
                    segs.remove(0);
                }
                // An item (`::core::time::Duration::from_millis`): `rest`
                // counts from after the marker.
                PathRes::Partial(Target::Def(_), _) => {
                    segs.remove(0);
                    self.apply(segs, res, span, module, ns, scopes);
                }
                _ => self.apply(segs, res, span, module, ns, scopes),
            }
            return;
        }
        // Std source spliced at the root (a routed fn such as
        // `__lust_std_process_exit`) names the std crates, never a user
        // module of the same name: read it as if it started with `::`.
        if module == ROOT_MODULE
            && span.file == crate::diag::FileId(0)
            && self.std_splice_lo.is_some_and(|lo| span.lo >= lo)
            && names.first().is_some_and(|n| matches!(self.interner.get(*n), "std" | "core" | "alloc"))
        {
            match self.tables.resolve_path(module, &names, ns, PathMode::Lexical, true, self.interner) {
                res @ (PathRes::Done(Target::Def(_) | Target::Variant(..)) | PathRes::Partial(Target::Def(_), _)) => {
                    self.apply(segs, res, span, module, ns, scopes)
                }
                _ => {}
            }
            return;
        }
        // A name a block `use` of a block item binds reads as the
        // written path it stands for (`V` as `E::V`); check resolves
        // that through its block overlay.
        if let Some(FrameHit::LocalUse(u)) = self.frame_hit(&names, ns, scopes) {
            if let Some(path) = self.local_use_path(&u, names[0], span, scopes) {
                let mut out: Vec<PathSeg> = path.iter().map(|s| PathSeg::plain(*s)).collect();
                if let Some(last) = out.last_mut() {
                    last.args = segs[0].args.clone();
                }
                out.extend(segs[1..].iter().cloned());
                *segs = out;
            }
            return;
        }
        let (res, local) = self.resolve(&names, ns, module, scopes);
        if self.std_glob_ambiguous(&names, ns, module, scopes) {
            self.diags.push(crate::resolve::imports::ambiguous_diag(self.interner.get(names[0]), span));
            return;
        }
        if self.std_glob_check(&names, ns, module, scopes) {
            self.diags.push(crate::resolve::imports::std_glob_name_diag(self.interner.get(names[0]), span));
            return;
        }
        if !local {
            // A generic param of the item shadows module items and
            // imports: a type or const param in a type path, a const
            // param as a value, a type param before `::` in a value path
            // (`T::default()`). Check resolves the path as written.
            if let Some(i) = self.gen_params.iter().rposition(|(n, _)| Some(n) == names.first())
                && Self::param_takes(ns, names.len() == 1, self.gen_params[i].1)
            {
                if i < self.gen_floor {
                    self.diags.push(Diag::new(
                        if ns == Namespace::Type || names.len() > 1 { "L0102" } else { "L0101" },
                        span,
                        "can't use generic parameters from outer item",
                        "Give the inner item its own generic parameter, or pass the value in.",
                    ));
                }
                return;
            }
            if self.expand_std_alias(segs, &names, ns, module, scopes) || (res == PathRes::Absent && self.expand_module_std_alias(segs, &names, ns, module)) {
                // An alias of a std module whose item the shipped
                // platform crate defines (`use std::io; io::stdout()`)
                // resolves into that crate (W-SHIM).
                let full: Vec<Sym> = segs.iter().map(|s| s.name).collect();
                if self.tables.std_platform.is_some()
                    && full.first().is_some_and(|f| self.interner.get(*f) == "std")
                    && self.tables.std_platform_has(&full[1..], module, self.interner)
                {
                    let res = self.tables.resolve_path(module, &full, ns, PathMode::Lexical, true, self.interner);
                    self.apply(segs, res, span, module, ns, scopes);
                    return;
                }
                // An alias of a std module whose item a std source module
                // defines (`use std::panic; panic::set_hook(..)`,
                // `use std::sync; sync::LazyLock`, `cell::OnceCell::new`)
                // walks into it, as the full path does (W-UNWIND).
                if !self.tables.std_modules.is_empty() && full.len() >= 3 {
                    let res = self.tables.resolve_path(module, &full, ns, PathMode::Lexical, true, self.interner);
                    if matches!(res, PathRes::Done(t) if !matches!(t, Target::Extern(_))) || matches!(res, PathRes::Partial(Target::Def(_), _)) {
                        self.apply(segs, res, span, module, ns, scopes);
                    }
                }
                return;
            }
            // After std aliases: `use std as alloc;` binds the name.
            if res == PathRes::Absent && self.alloc_unlinked(&names, module, span) {
                return;
            }
            // A bare name a module-level glob of a sync or thread module
            // imports: rewrite it to the full std path (W-THREADS).
            if res == PathRes::Absent
                && let Some(&first) = names.first()
                && self.local_name(first).is_none()
                && let Some(path) = self.tables.std_sync_glob_path(module, self.interner.get(first), self.interner)
            {
                let mut out: Vec<PathSeg> = path.iter().map(|s| PathSeg::plain(*s)).collect();
                out.extend(segs.iter().cloned());
                *segs = out;
                return;
            }
            // Lexical scope (section 1.3): an unqualified name that only
            // another module defines is not found here, even though the
            // merged flat tables could answer it. Names no module
            // defines (primitives, builtins) fall through as before.
            // A non-prelude std type lust knows by name needs a `use`
            // in this module or fn body, as in Rust (W-STD-A). An
            // explicit one expanded above; a glob is the other way in.
            if res == PathRes::Absent
                && let Some(&first) = names.first()
                && crate::ty::lang::needs_std_use(self.interner.get(first))
                && self.local_name(first).is_none()
                && !self.tables.std_glob_imports(module, self.interner.get(first), self.interner)
            {
                let n = self.interner.get(first).to_string();
                let hint = crate::ty::lang::std_use_hint(&n);
                self.diags.push(Diag::new(
                    "L0102",
                    span,
                    format!("cannot find type `{n}` in this scope"),
                    format!("Import it: `use {hint};`."),
                ));
                return;
            }
            // A module prefix that resolves, with the next segment
            // missing in it (`ata::Missing`, `crate::a::b::Gone`):
            // name the missing segment and its module, as rustc does,
            // not the module's own name.
            if res == PathRes::Absent
                && let Some(d) = self.missing_in_module(&names, ns, module, span)
            {
                self.diags.push(d);
                return;
            }
            // A primitive type name another module defines an item of is
            // still the primitive here (rustc's lowest scope layer): a root
            // `type u8 = u16` does not reach `u8` in a module that does not
            // import it.
            if res == PathRes::Absent
                && ns == Namespace::Type
                && let [first] = names[..]
                && crate::ty::lang::is_primitive_type_name(self.interner.get(first))
            {
                self.apply(segs, res, span, module, ns, scopes);
                return;
            }
            if res == PathRes::Absent && names.first().is_some_and(|&n| self.local_name(n).is_some()) {
                // A bare path in a type position may name a const
                // item: a const generic argument the parser read as
                // a type (`Arr<N>`). Rust allows only a
                // single-segment path there (multi-segment const
                // paths need braces), so only those rewrite as the
                // const they name; collect/check kind-check the
                // position, and a const name in a true type
                // position still rejects there.
                if ns == Namespace::Type && names.len() == 1 {
                    let (vres, _) = self.resolve(&names, Namespace::Value, module, scopes);
                    if let PathRes::Done(Target::Def(def)) = vres
                        && self.tables.def_info.get(&def).is_some_and(|i| i.kind == ResKind::Const)
                    {
                        self.apply(segs, vres, span, module, Namespace::Value, scopes);
                        return;
                    }
                }
                // A name that no module defines in the namespace asked
                // here is not a lexical-scope miss: a type parameter `T`
                // next to a `static T` (value namespace) stays a param
                // (collect resolves params; W-STD-C).
                let asked = if names.len() > 1 { Namespace::Type } else { ns };
                let in_ns = names.first().and_then(|&n| self.local_name(n)).is_some_and(|m| m & (1 << ns_index(asked)) != 0);
                if !in_ns {
                    self.apply(segs, res, span, module, ns, scopes);
                    return;
                }
                let first = self.interner.get(names[0]).to_string();
                self.diags.push(if ns == Namespace::Type {
                    Diag::new(
                        "L0102",
                        span,
                        format!("cannot find type `{first}` in this scope"),
                        "Import it with `use`, or write its module path.",
                    )
                } else {
                    Diag::new(
                        "L0101",
                        span,
                        format!("cannot find value `{first}` in this scope"),
                        "Import it with `use`, or write its module path.",
                    )
                });
                return;
            }
            self.apply(segs, res, span, module, ns, scopes);
        }
    }

    /// Rewrites the type at `id`, recursing into compound types.
    /// Body callers pass their frames so a function-local `use`
    /// binds in type positions too; item signatures pass none.
    fn ty(&mut self, ast: &mut Ast, id: TyId, module: ModuleId, scopes: &[Frame]) {
        match ast.ty(id) {
            TyExpr::Path(_) => {
                let span = ast.ty_span(id);
                let TyExpr::Path(mut segs) = std::mem::replace(&mut ast.tys[id.0 as usize], TyExpr::Unit) else { return };
                self.rewrite_path(&mut segs, Namespace::Type, span, module, scopes, ast);
                ast.tys[id.0 as usize] = TyExpr::Path(segs);
            }
            TyExpr::Ref { inner, .. } => {
                let inner = *inner;
                self.ty(ast, inner, module, scopes);
            }
            TyExpr::Tuple(ts) => {
                let ts = ts.clone();
                for t in ts {
                    self.ty(ast, t, module, scopes);
                }
            }
            TyExpr::Slice(inner) | TyExpr::Paren(inner) | TyExpr::Ptr { inner, .. } => {
                let inner = *inner;
                self.ty(ast, inner, module, scopes);
            }
            TyExpr::Array { inner, len } => {
                let (inner, len) = (*inner, *len);
                self.ty(ast, inner, module, scopes);
                anon_const_module(ast, len, module);
                let mut scopes = vec![Frame::default()];
                self.expr(ast, len, module, &mut scopes);
            }
            TyExpr::Dyn { .. } | TyExpr::ImplTrait { .. } => {
                let span = ast.ty_span(id);
                let taken = std::mem::replace(&mut ast.tys[id.0 as usize], TyExpr::Unit);
                let mut taken = taken;
                match &mut taken {
                    TyExpr::Dyn { bounds, .. } | TyExpr::ImplTrait { bounds, .. } => self.bounds(ast, bounds, span, module),
                    _ => unreachable!(),
                }
                ast.tys[id.0 as usize] = taken;
            }
            TyExpr::QPath { .. } => {
                let span = ast.ty_span(id);
                let TyExpr::QPath { self_ty, trait_path, segs } = std::mem::replace(&mut ast.tys[id.0 as usize], TyExpr::Unit) else {
                    return;
                };
                let (mut trait_path, segs) = (trait_path, segs);
                self.ty(ast, self_ty, module, scopes);
                self.rewrite_path(&mut trait_path, Namespace::Type, span, module, scopes, ast);
                ast.tys[id.0 as usize] = TyExpr::QPath { self_ty, trait_path, segs };
            }
            TyExpr::FnPtr { inputs, ret, .. } => {
                let ins: Vec<TyId> = inputs.iter().map(|p| p.ty).collect();
                let ret = *ret;
                for t in ins {
                    self.ty(ast, t, module, scopes);
                }
                if let Some(r) = ret {
                    self.ty(ast, r, module, scopes);
                }
            }
            _ => {}
        }
    }

    /// Rewrites one block. Its items and `use`s bind first, for the
    /// whole block (a `use` after a call still covers the call, as in
    /// rustc); then the bodies of its items, which see every item and
    /// `use` of the enclosing blocks but no locals; then the
    /// statements in order, with `let` bindings.
    fn block(&mut self, ast: &mut Ast, id: BlockId, module: ModuleId, scopes: &mut Vec<Frame>) {
        scopes.push(Frame::default());
        let stmts = std::mem::take(&mut ast.blocks[id.0 as usize].stmts);
        let items: Vec<u32> = stmts.iter().filter_map(|s| if let Stmt::Item(i) = s { Some(*i) } else { None }).collect();
        // Items bind before `use`s: a `use` may name a block item
        // declared after it (`use E::A; enum E { A }`).
        let (uses, others): (Vec<u32>, Vec<u32>) =
            items.iter().partition(|&&i| matches!(ast.stmt_items.get(i as usize).map(|it| &it.kind), Some(ItemKind::Use(_))));
        for &idx in others.iter().chain(&uses) {
            self.stmt_item(ast, idx, module, scopes);
        }
        // With the block's bindings complete, every `use` of the
        // block re-reads its first segment under import resolution
        // (`import_seg`): a glob binding in scope here does not
        // shadow a different outer item for an import path, not
        // even for the glob import's own path (rustc E0659). This
        // second pass makes the check independent of item order,
        // as the whole-block scope is in rustc.
        for &idx in &items {
            self.check_block_use(ast, idx, module, scopes);
        }
        if !items.is_empty() {
            let outer: Vec<Frame> = scopes.iter().map(|f| Frame { locals: Vec::new(), ..f.clone() }).collect();
            for &idx in &items {
                self.stmt_item_body(ast, idx, module, &outer);
            }
        }
        let mut out = Vec::with_capacity(stmts.len());
        for stmt in stmts {
            match stmt {
                Stmt::Let { pat, ty, init, els, attrs, span } => {
                    if let Some(t) = ty {
                        self.ty(ast, t, module, scopes);
                    }
                    if let Some(e) = init {
                        self.expr(ast, e, module, scopes);
                    }
                    self.pat(ast, pat, module, scopes);
                    let mut names = Vec::new();
                    self.pat_bindings(ast, pat, &mut names);
                    if let Some(frame) = scopes.last_mut() {
                        frame.locals.extend(names);
                    }
                    if let Some(b) = els {
                        self.block(ast, b, module, scopes);
                    }
                    out.push(Stmt::Let { pat, ty, init, els, attrs, span });
                }
                Stmt::Expr { expr, semi, attrs } => {
                    self.expr(ast, expr, module, scopes);
                    out.push(Stmt::Expr { expr, semi, attrs });
                }
                Stmt::Item(idx) => out.push(Stmt::Item(idx)),
                Stmt::Macro { call, semi } => out.push(Stmt::Macro { call, semi }),
            }
        }
        ast.blocks[id.0 as usize].stmts = out;
        if let Some(tail) = ast.blocks[id.0 as usize].tail {
            self.expr(ast, tail, module, scopes);
        }
        scopes.pop();
    }

    /// Rewrites the signature and body of one block item (a nested fn,
    /// a const, or a static) in `outer`: the enclosing frames with
    /// their locals dropped, since an item cannot see them.
    fn stmt_item_body(&mut self, ast: &mut Ast, idx: u32, module: ModuleId, outer: &[Frame]) {
        let floor = std::mem::replace(&mut self.gen_floor, self.gen_params.len());
        self.stmt_item_kind(ast, idx, module, outer);
        self.gen_floor = floor;
    }

    /// `stmt_item_body` for one item kind, with the outer params below the floor.
    fn stmt_item_kind(&mut self, ast: &mut Ast, idx: u32, module: ModuleId, outer: &[Frame]) {
        let Some(item) = ast.stmt_items.get_mut(idx as usize) else { return };
        match &mut item.kind {
            ItemKind::Fn(f) => {
                let mut def = std::mem::replace(f, dummy_fn());
                self.fn_def_in(ast, &mut def, module, outer);
                if let ItemKind::Fn(f) = &mut ast.stmt_items[idx as usize].kind {
                    *f = def;
                }
            }
            ItemKind::Const(c) => {
                let (ty, value) = (c.ty, c.value);
                self.ty(ast, ty, module, outer);
                if let Some(v) = value {
                    let mut scopes = outer.to_vec();
                    self.expr(ast, v, module, &mut scopes);
                }
            }
            ItemKind::Static(st) => {
                let (ty, value) = (st.ty, st.value);
                self.ty(ast, ty, module, outer);
                if let Some(v) = value {
                    let mut scopes = outer.to_vec();
                    self.expr(ast, v, module, &mut scopes);
                }
            }
            // A block struct, enum, or alias: its field and target types
            // name module items through imports and module paths as a
            // module item's do, and see the block items around it
            // (R18). Their generics stay their own (`gen_floor`).
            ItemKind::Struct(s) => {
                let mut s = s.clone();
                let mark = self.push_params(&s.generics);
                self.generics(ast, &mut s.generics, &mut s.where_clause, module);
                if let VariantFields::Struct(fs) | VariantFields::Tuple(fs) = &s.fields {
                    for t in fs.iter().map(|f| f.ty).collect::<Vec<_>>() {
                        self.ty(ast, t, module, outer);
                    }
                }
                self.gen_params.truncate(mark);
                ast.stmt_items[idx as usize].kind = ItemKind::Struct(s);
            }
            ItemKind::Enum(e) => {
                let mut e = e.clone();
                let mark = self.push_params(&e.generics);
                self.generics(ast, &mut e.generics, &mut e.where_clause, module);
                let mut discs = Vec::new();
                for v in &e.variants {
                    if let VariantFields::Struct(fs) | VariantFields::Tuple(fs) = &v.fields {
                        for t in fs.iter().map(|f| f.ty).collect::<Vec<_>>() {
                            self.ty(ast, t, module, outer);
                        }
                    }
                    discs.extend(v.discriminant);
                }
                self.gen_params.truncate(mark);
                for d in discs {
                    anon_const_module(ast, d, module);
                    let mut scopes = outer.to_vec();
                    self.expr(ast, d, module, &mut scopes);
                }
                ast.stmt_items[idx as usize].kind = ItemKind::Enum(e);
            }
            ItemKind::Type(a) => {
                let mut a = a.clone();
                let mark = self.push_params(&a.generics);
                self.generics(ast, &mut a.generics, &mut a.where_clause, module);
                self.ty(ast, a.ty, module, outer);
                self.gen_params.truncate(mark);
                ast.stmt_items[idx as usize].kind = ItemKind::Type(a);
            }
            // A block impl: its header and method signatures and bodies
            // see the block items around it as a nested fn does (R18);
            // its own generics stay its own. Flatten then hoists it to
            // its module's items (`hoist_block_impls`).
            ItemKind::Impl(imp) => {
                let mut imp = imp.clone();
                let mark = self.push_params(&imp.generics);
                self.generics_in(ast, &mut imp.generics, &mut imp.where_clause, module, outer);
                if let Some(tr) = &mut imp.trait_ref {
                    self.rewrite_path(&mut tr.path, Namespace::Type, imp.span, module, outer, ast);
                }
                self.ty(ast, imp.self_ty, module, outer);
                for at in imp.types.iter_mut() {
                    self.bounds_in(ast, &mut at.bounds, at.span, module, outer);
                    self.generics_in(ast, &mut at.generics, &mut at.where_clause, module, outer);
                    if let Some(d) = at.default {
                        self.ty(ast, d, module, outer);
                    }
                }
                for t in imp.consts.iter().map(|c| c.ty).collect::<Vec<_>>() {
                    self.ty(ast, t, module, outer);
                }
                for v in imp.consts.iter().filter_map(|c| c.default).collect::<Vec<_>>() {
                    self.expr(ast, v, module, &mut outer.to_vec());
                }
                for f in &mut imp.fns {
                    self.fn_def_in(ast, f, module, outer);
                }
                self.gen_params.truncate(mark);
                ast.stmt_items[idx as usize].kind = ItemKind::Impl(imp);
            }
            _ => {}
        }
    }

    /// Records one trait target of a function-local `use` for the
    /// checker (`Ast::use_traits`): a trait in scope makes its
    /// methods callable in the block, which no path rewrite can
    /// express. Non-trait targets record nothing.
    fn record_use_trait_target(&self, ast: &mut Ast, span: Span, target: Target) {
        if let Target::Def(d) = target
            && let Some(info) = self.tables.def_info.get(&d)
            && info.kind == ResKind::Trait
        {
            ast.use_traits.push((span, UseTrait::Flat(info.flat)));
        }
    }

    /// Records a std trait path of a function-local `use`
    /// (`Ast::use_traits`), when the canonical path names a trait.
    fn record_use_trait_std(&self, ast: &mut Ast, span: Span, path: &[Sym]) {
        let p: Vec<&str> = path.iter().map(|s| self.interner.get(*s)).collect();
        if crate::ty::lang::std_path_kind(&p) == Some(crate::ty::lang::StdPathKind::Trait) {
            ast.use_traits.push((span, UseTrait::Std(path.to_vec())));
        }
    }

    /// Binds one statement item in its block's frame: a nested fn,
    /// const, or static by its value name (`Frame::items`), a `use` by
    /// its imports. `block` runs this for every item of the block
    /// before any statement, so both cover the whole block.
    fn stmt_item(&mut self, ast: &mut Ast, idx: u32, module: ModuleId, scopes: &mut Vec<Frame>) {
        let Some(item) = ast.stmt_items.get(idx as usize) else { return };
        // A nested item binds its name in this block at explicit rank, so
        // an explicit `use` of the same name in the block (either order)
        // is a duplicate. Item-to-item duplicates also fire here; collect
        // checks them again for entry points that skip this pass.
        {
            let item_name = match &item.kind {
                ItemKind::Fn(def) => Some((def.name, def.name_span)),
                ItemKind::Const(c) => c.name.map(|n| (n, c.name_span)),
                ItemKind::Static(s) => Some((s.name, s.name_span)),
                _ => None,
            };
            if let Some((name, span)) = item_name
                && let Some(frame) = scopes.last_mut()
            {
                let key = (name, ns_index(Namespace::Value));
                if frame.explicit.contains(&key) {
                    self.diags.push(Diag::new(
                        "L0106",
                        span,
                        format!("`{}` is defined more than once", self.interner.get(name)),
                        "Rename one of the definitions.",
                    ));
                } else {
                    frame.explicit.push(key);
                }
                frame.items.push(name);
            }
            // A type item binds the type namespace, and a unit or tuple
            // struct its constructor in the value namespace too (R18).
            // Two of one name in one block are rustc E0428.
            let type_item = match &item.kind {
                ItemKind::Struct(s) => Some((s.name, s.name_span, !matches!(s.fields, crate::ast::VariantFields::Struct(_)))),
                ItemKind::Enum(e) => Some((e.name, e.name_span, false)),
                ItemKind::Union(u) => Some((u.name, u.name_span, false)),
                ItemKind::Trait(t) => Some((t.name, t.name_span, false)),
                ItemKind::Type(a) => Some((a.name, a.name_span, false)),
                _ => None,
            };
            if let Some((name, span, ctor)) = type_item
                && let Some(frame) = scopes.last_mut()
            {
                let mut keys = vec![(name, ns_index(Namespace::Type))];
                if ctor {
                    keys.push((name, ns_index(Namespace::Value)));
                }
                if keys.iter().any(|k| frame.explicit.contains(k)) {
                    self.diags.push(Diag::new(
                        "L0106",
                        span,
                        format!("`{}` is defined more than once", self.interner.get(name)),
                        "Rename one of the definitions.",
                    ));
                } else {
                    frame.explicit.extend(keys);
                }
                frame.types.push((name, idx));
                if ctor {
                    frame.items.push(name);
                    frame.ctors.push(name);
                }
            }
        }
        let ItemKind::Use(u) = &item.kind else { return };
        let tree = u.tree.clone();
        let span = item.span;
        let mut flat = Vec::new();
        flatten_use(&tree, module, VisKind::Priv, &mut flat, self.interner);
        let self_sym = self.interner.intern("self");
        let crate_sym = self.interner.intern("crate");
        let super_sym = self.interner.intern("super");
        let self_ty = self.interner.intern("Self");
        let kw = |s: Sym| s == crate_sym || s == self_sym || s == super_sym;
        for imp in flat {
            // A first segment a block frame binds to a std path
            // (`use std::mem; use mem::swap;` in two blocks) reads
            // as that path, as a written std path does below.
            let mut imp = imp;
            if !imp.leading_colon {
                let first_of = |k: &ImportKind| match k {
                    ImportKind::Single { path, .. } | ImportKind::CheckPath { path } | ImportKind::Glob { path } => path.first().copied(),
                    ImportKind::BadLeading { .. } => None,
                };
                if let Some(first) = first_of(&imp.kind)
                    && !matches!(self.interner.get(first), "crate" | "self" | "super" | "Self")
                    && !self.tables.crate_magic.contains_key(&first)
                {
                    let (info, from_frame) = self.import_seg(first, Namespace::Type, module, scopes);
                    if from_frame
                        && let SegBind::Std(alias) = info.bind
                    {
                        let rewire = |path: &mut Vec<Sym>| {
                            let mut p = alias.clone();
                            p.extend_from_slice(&path[1..]);
                            *path = p;
                        };
                        match &mut imp.kind {
                            ImportKind::Single { path, .. } | ImportKind::CheckPath { path } | ImportKind::Glob { path } => rewire(path),
                            ImportKind::BadLeading { .. } => {}
                        }
                    } else if matches!(imp.kind, ImportKind::Glob { .. })
                        && matches!(info.bind, SegBind::Prelude(_))
                        && let Some(suffix) = crate::resolve::imports::prelude_std_suffix(self.interner.get(first))
                    {
                        // A glob of a prelude enum by its prelude
                        // name (`use Option::*;` in a body) reads as
                        // the canonical std path below.
                        if let ImportKind::Glob { path } = &mut imp.kind
                            && path.len() == 1
                        {
                            let mut p = vec![self.interner.intern("std")];
                            p.extend(suffix.iter().map(|s| self.interner.intern(s)));
                            *path = p;
                        }
                    }
                }
            }
            // A path through a block type item (`use E::V;` for an
            // enum of this or an enclosing block) binds a local use.
            if !imp.leading_colon
                && let ImportKind::Single { path, .. } | ImportKind::CheckPath { path } | ImportKind::Glob { path } = &imp.kind
                && let Some(&first) = path.first()
                && let Some((item, base)) = self.frame_type_item(first, scopes)
            {
                if base == [first] && self.macro_item_ambiguous(ast, first, module, scopes) {
                    let n = self.interner.get(first);
                    self.diags.push(Diag::new(
                        "L0507",
                        span,
                        format!("`{n}` is ambiguous: a block item made by a macro (a derive) and an outer item have this name"),
                        "Rename the block item, or import through a path that names one of them.",
                    ));
                    continue;
                }
                self.local_item_use(ast, &imp.kind, item, base, span, scopes);
                continue;
            }
            match imp.kind {
                ImportKind::BadLeading { .. } => {
                    self.diags.push(Diag::new(
                        "L0506",
                        span,
                        "the crate root in a `use` path can only be used in start position",
                        "Move the leading `::` to the start of the whole import, or remove it.",
                    ));
                }
                ImportKind::CheckPath { path } => {
                    if path.is_empty() {
                        continue;
                    }
                    if let PathRes::Done(Target::Extern(i)) = self.tables.resolve_module_path(module, &path, imp.leading_colon, self.interner)
                        && self.tables.externs[i as usize].is_std_lib
                    {
                        self.diags.extend(crate::resolve::imports::std_group_parent_diag(&path, span, self.interner));
                        continue;
                    }
                    let ok = matches!(self.frame_use_target(&path, imp.leading_colon, module, scopes), Some(PathRes::Done(_)))
                        || matches!(
                            self.tables.resolve_module_path(module, &path, imp.leading_colon, self.interner),
                            PathRes::Done(_)
                        )
                        || matches!(
                            self.tables.resolve_path(module, &path, Namespace::Type, PathMode::Use, imp.leading_colon, self.interner),
                            PathRes::Done(Target::Def(adt)) if self.tables.variants.contains_key(&adt)
                        );
                    if !ok {
                        self.diags.push(Diag::new(
                            "L0506",
                            span,
                            format!(
                                "unresolved import `{}`",
                                path.iter().map(|s| self.interner.get(*s)).collect::<Vec<_>>().join("::")
                            ),
                            "Check the path: every segment must name a module or item that is visible here.",
                        ));
                    }
                }
                ImportKind::Single { path, name } => {
                    if path.len() == 1 {
                        self.check_local_single_use(&path, name, imp.leading_colon, module, span, scopes);
                        continue;
                    }
                    // `use super::super as x;` and kin: the whole path is
                    // module keywords, the rename binds that module.
                    if *path.last().unwrap() != self_sym && name != *path.last().unwrap() && path.iter().all(|&s| kw(s)) {
                        match self.tables.resolve_module_path(module, &path, imp.leading_colon, self.interner) {
                            PathRes::Done(Target::Module(src)) => {
                                let bn = crate::resolve::imports::import_bind_name(name, Target::Module(src), self.interner);
                                if insert_local(scopes, bn, Namespace::Type, LocalBind::Target(Target::Module(src)), 2)
                                    && self.interner.get(name) != "_"
                                {
                                    self.push_local_dup(span, name);
                                }
                            }
                            PathRes::Done(Target::Extern(_)) => {}
                            _ => self.push_unresolved_use(span, &path),
                        }
                        continue;
                    }
                    // A trailing `self` binds the module (or enum) named
                    // by the prefix, under the segment before it.
                    if *path.last().unwrap() == self_sym {
                        let mod_path = &path[..path.len() - 1];
                        if name == self_sym && !matches!(mod_path.last(), Some(&c) if !kw(c) && c != self_ty) {
                            self.diags.push(Diag::new(
                                "L0506",
                                span,
                                "this import needs to be explicitly named",
                                "Add a rename, such as `use self as here;`.",
                            ));
                            continue;
                        }
                        let bind_name = if name == self_sym { *mod_path.last().unwrap() } else { name };
                        // A std module (`use std::rc::{self, Rc}`) binds as a
                        // std alias, as `use std::rc;` does.
                        if mod_path.len() > 1
                            && let PathRes::Done(Target::Extern(i)) | PathRes::Partial(Target::Extern(i), _) =
                                self.tables.resolve_module_path(module, mod_path, imp.leading_colon, self.interner)
                            && self.tables.externs[i as usize].is_std_lib
                            && self.tables.externs[i as usize].unsupported.is_none()
                        {
                            // `{self}` needs a module, enum, or trait.
                            if let Some(d) = crate::resolve::imports::std_group_parent_diag(mod_path, span, self.interner) {
                                self.diags.push(d);
                                continue;
                            }
                            if self.interner.get(bind_name) != "_" && insert_local_std(scopes, bind_name, Namespace::Type, mod_path.to_vec()) {
                                self.push_local_dup(span, bind_name);
                            }
                            continue;
                        }
                        let frame_target = self.frame_use_target(mod_path, imp.leading_colon, module, scopes);
                        let target = match frame_target {
                            Some(PathRes::Done(t)) => Some(t),
                            Some(_) => None,
                            None => match self.tables.resolve_module_path(module, mod_path, imp.leading_colon, self.interner) {
                                PathRes::Done(t) => Some(t),
                                _ => match self
                                    .tables
                                    .resolve_path(module, mod_path, Namespace::Type, PathMode::Use, imp.leading_colon, self.interner)
                                {
                                    PathRes::Done(Target::Def(adt)) if self.tables.variants.contains_key(&adt) => {
                                        Some(Target::Def(adt))
                                    }
                                    _ => None,
                                },
                            },
                        };
                        match target {
                            Some(t) => {
                                let bn = crate::resolve::imports::import_bind_name(bind_name, t, self.interner);
                                if insert_local(scopes, bn, Namespace::Type, LocalBind::Target(t), 2)
                                    && self.interner.get(bind_name) != "_"
                                {
                                    self.push_local_dup(span, bind_name);
                                }
                            }
                            None => self.push_unresolved_use(span, &path),
                        }
                        continue;
                    }
                    // `use a::E::V [as X];` imports one variant of a crate
                    // enum, as at module level, through a frame binding
                    // of the path's first segment when there is one.
                    let vres = match self.frame_use_target(&path, imp.leading_colon, module, scopes) {
                        Some(r) => r,
                        None => self.tables.resolve_path(module, &path, Namespace::Type, PathMode::Use, imp.leading_colon, self.interner),
                    };
                    if let PathRes::Partial(Target::Def(adt), rest) = vres
                        && rest + 1 == path.len()
                        && self.tables.variants.get(&adt).is_some_and(|vs| vs.contains(&path[rest]))
                    {
                        let target = Target::Variant(adt, path[rest]);
                        let bn = crate::resolve::imports::import_bind_name(name, target, self.interner);
                        // Both namespaces, as at module level.
                        let dup = insert_local(scopes, bn, Namespace::Value, LocalBind::Target(target), 2)
                            | insert_local(scopes, bn, Namespace::Type, LocalBind::Target(target), 2);
                        if dup && self.interner.get(name) != "_" {
                            self.push_local_dup(span, name);
                        }
                        continue;
                    }
                    // An item of a std source overlay module imports
                    // from it, as at module level (`try_import` in
                    // imports.rs): `use std::io::Write;` in a body binds
                    // the overlay trait, not the std compat tables.
                    let modres = match self.frame_use_target(&path[..path.len() - 1], imp.leading_colon, module, scopes) {
                        Some(res) => res,
                        None => match self.tables.resolve_module_path(module, &path[..path.len() - 1], imp.leading_colon, self.interner) {
                            PathRes::Done(Target::Extern(i))
                                if path.len() == 3
                                    && let Some((m, false)) = self.tables.std_module_at(i, path[1], self.interner)
                                    && [Namespace::Type, Namespace::Value, Namespace::Macro]
                                        .iter()
                                        .any(|&ns| self.tables.lookup(m, ns, *path.last().unwrap()).is_some()) =>
                            {
                                PathRes::Done(Target::Module(m))
                            }
                            other => other,
                        },
                    };
                    match modres {
                        PathRes::Done(Target::Module(src)) => {
                            let last = *path.last().unwrap();
                            let mut any = false;
                            let mut dup = false;
                            for ns in [Namespace::Type, Namespace::Value, Namespace::Macro] {
                                match self.tables.lookup(src, ns, last) {
                                    Some(BindState::One(b)) if self.tables.visible(&b.vis, b.def_module, module, self.interner) => {
                                        any = true;
                                        let target = b.target;
                                        let bn = crate::resolve::imports::import_bind_name(name, target, self.interner);
                                        dup |= insert_local(scopes, bn, ns, LocalBind::Target(target), 2);
                                        if ns == Namespace::Type {
                                            self.record_use_trait_target(ast, span, target);
                                        }
                                    }
                                    Some(BindState::Ambiguous) => {
                                        any = true;
                                        dup |= insert_local(scopes, name, ns, LocalBind::Ambiguous, 2);
                                    }
                                    // A std import of the source module
                                    // (`pub use std::rc::Rc;`) copies as an alias.
                                    Some(_) => {}
                                    None => {
                                        let key = (src, ns_index(ns) as u8, last);
                                        crate::resolve::mdr::read_key(src, key.1, last);
                                        if let Some((avis, apath)) = self.tables.std_aliases.get(&key).cloned()
                                            && self.tables.visible(&avis, self.tables.std_alias_def_module(key), module, self.interner)
                                        {
                                            any = true;
                                            if ns == Namespace::Type {
                                                self.record_use_trait_std(ast, span, &apath);
                                            }
                                            if self.interner.get(name) != "_" {
                                                dup |= insert_local_std(scopes, name, ns, apath);
                                            }
                                        }
                                    }
                                }
                            }
                            if dup && self.interner.get(name) != "_" {
                                self.diags.push(Diag::new(
                                    "L0106",
                                    span,
                                    format!("`{}` is defined more than once", self.interner.get(name)),
                                    "Rename one of the imports with `as`, or remove one.",
                                ));
                            }
                            if !any
                                && self.tables.std_platform_compat_fallback(&path, src, module, imp.leading_colon, self.interner)
                            {
                                // A std item the shipped platform module
                                // does not define keeps the std compat
                                // handling of the extern branch below, as
                                // at module level (fx-stdos).
                                self.record_use_trait_std(ast, span, &path);
                                if self.interner.get(name) != "_"
                                    && let Some(nss) = crate::resolve::imports::std_import_namespaces(self.interner, &path)
                                {
                                    let mut dup = false;
                                    for ns in nss {
                                        dup |= insert_local_std(scopes, name, ns, path.clone());
                                    }
                                    if dup {
                                        self.push_local_dup(span, name);
                                    }
                                }
                            } else if !any {
                                self.diags.push(Diag::new(
                                    "L0506",
                                    span,
                                    format!(
                                        "unresolved import `{}`",
                                        path.iter().map(|s| self.interner.get(*s)).collect::<Vec<_>>().join("::")
                                    ),
                                    "Check the path: every segment must name a module or item that is visible here.",
                                ));
                            }
                        }
                        PathRes::Done(Target::Extern(i)) => {
                            // An item of the shipped std source (`std::io::Write`)
                            // resolves through the extern prelude walk to its
                            // def: bind and record it like a module import
                            // above. Lang-table items do not resolve this
                            // way and keep the std compat handling below.
                            let mut any_def = false;
                            let mut dup_def = false;
                            for ns in [Namespace::Type, Namespace::Value] {
                                if let PathRes::Done(target @ Target::Def(_)) =
                                    self.tables.resolve_path(module, &path, ns, PathMode::Use, true, self.interner)
                                {
                                    any_def = true;
                                    if ns == Namespace::Type {
                                        self.record_use_trait_target(ast, span, target);
                                    }
                                    let bn = crate::resolve::imports::import_bind_name(name, target, self.interner);
                                    dup_def |= insert_local(scopes, bn, ns, LocalBind::Target(target), 2);
                                }
                            }
                            if any_def {
                                if dup_def && self.interner.get(name) != "_" {
                                    self.push_local_dup(span, name);
                                }
                                continue;
                            }
                            // A std trait is in scope for method calls
                            // even when imported as `_` (no name bound).
                            if self.tables.externs[i as usize].is_std_lib && self.tables.externs[i as usize].unsupported.is_none() {
                                self.record_use_trait_std(ast, span, &path);
                            }
                            if self.tables.externs[i as usize].is_std_lib && self.tables.externs[i as usize].unsupported.is_none() {
                                match crate::resolve::imports::std_import_namespaces(self.interner, &path) {
                                    Some(nss) if self.interner.get(name) != "_" => {
                                        let mut dup = false;
                                        for ns in nss {
                                            dup |= insert_local_std(scopes, name, ns, path.clone());
                                        }
                                        if dup {
                                            self.push_local_dup(span, name);
                                        }
                                    }
                                    Some(_) => {}
                                    // Never a silent accept of a std path
                                    // lust has no binding for.
                                    None => self.diags.extend(crate::resolve::imports::std_unbound_diag(&path, false, span, self.interner)),
                                }
                            }
                        }
                        _ => {
                            self.diags.push(Diag::new(
                                "L0506",
                                span,
                                format!(
                                    "unresolved import `{}`",
                                    path.iter().map(|s| self.interner.get(*s)).collect::<Vec<_>>().join("::")
                                ),
                                "Check the path: every segment must name a module or item that is visible here.",
                            ));
                        }
                    }
                }
                ImportKind::Glob { path } => {
                    if path.is_empty() {
                        self.diags.push(Diag::new(
                            "L0506",
                            span,
                            "cannot glob-import all possible crates",
                            "Name the module before the `*`, such as `use a::*;`.",
                        ));
                        continue;
                    }
                    // A first segment a block frame binds (an outer
                    // block's import) names the glob's source through
                    // that binding, not through the module tables.
                    if let Some(res) = self.frame_use_target(&path, imp.leading_colon, module, scopes) {
                        match res {
                            PathRes::Done(Target::Def(adt)) if self.tables.variants.contains_key(&adt) => {
                                for v in self.tables.variants[&adt].clone() {
                                    // Both namespaces, as at module level.
                                    insert_local(scopes, v, Namespace::Value, LocalBind::Target(Target::Variant(adt, v)), 1);
                                    insert_local(scopes, v, Namespace::Type, LocalBind::Target(Target::Variant(adt, v)), 1);
                                }
                            }
                            PathRes::Done(Target::Module(src)) => self.glob_from_module(ast, src, module, scopes, span),
                            PathRes::Ambiguous => {}
                            PathRes::OrderDep => {
                                let text: Vec<&str> = path.iter().map(|s| self.interner.get(*s)).collect();
                                self.diags.push(crate::resolve::order::order_diag(&text.join("::"), span));
                            }
                            _ => self.push_unresolved_use(span, &path),
                        }
                        continue;
                    }
                    // `use a::E::*;` in a body imports the variants.
                    if let PathRes::Done(Target::Def(adt)) =
                        self.tables.resolve_path(module, &path, Namespace::Type, PathMode::Use, imp.leading_colon, self.interner)
                        && self.tables.variants.contains_key(&adt)
                    {
                        for v in self.tables.variants[&adt].clone() {
                            insert_local(scopes, v, Namespace::Value, LocalBind::Target(Target::Variant(adt, v)), 1);
                            insert_local(scopes, v, Namespace::Type, LocalBind::Target(Target::Variant(adt, v)), 1);
                        }
                        continue;
                    }
                    match self.tables.resolve_module_path(module, &path, imp.leading_colon, self.interner) {
                        // A glob of a std module brings the non-prelude
                        // std types lust knows by name, below any
                        // explicit binding of the frame (W-STD-A).
                        PathRes::Done(Target::Extern(i)) => {
                            if self.tables.externs[i as usize].is_std_lib
                                && let Some(frame) = scopes.last_mut()
                            {
                                let p: Vec<&str> = path.iter().map(|s| self.interner.get(*s)).collect();
                                if let Some(d) = crate::resolve::imports::std_unbound_diag(&path, true, span, self.interner) {
                                    self.diags.push(d);
                                    continue;
                                }
                                frame.std_mod_glob |= crate::ty::lang::std_enum_variants(&p).is_empty();
                                frame.std_glob_paths.push(path.clone());
                                // The std source overlay's items (`use
                                // std::panic::*;` brings AssertUnwindSafe)
                                // and the std items lust knows by path.
                                let overlay = self.tables.std_overlay_items(i, &path, self.interner).or_else(|| self.tables.std_platform_glob_items(&path, module, self.interner));
                                for &(ns, name) in overlay.iter().flat_map(|(_, items)| items) {
                                    let mut full = path.clone();
                                    full.push(name);
                                    frame.std_imports.entry((name, ns_index(ns))).or_insert(full);
                                }
                                for (ns, name) in self.tables.std_glob_alias_items(&path, overlay.as_ref(), self.interner) {
                                    let mut full = path.clone();
                                    full.push(name);
                                    frame.std_imports.entry((name, ns_index(ns))).or_insert(full);
                                }
                                for n in crate::ty::lang::std_glob_names() {
                                    if crate::ty::lang::std_glob_imports(&p, n) {
                                        let name = self.interner.intern(n);
                                        let mut full = path.clone();
                                        full.push(name);
                                        self.record_use_trait_std(ast, span, &full);
                                        frame.std_imports.entry((name, ns_index(Namespace::Type))).or_insert(full);
                                    }
                                }
                                // A glob of a std enum's variants (`Ordering::*`).
                                for v in crate::ty::lang::std_enum_variants(&p) {
                                    let name = self.interner.intern(v);
                                    let mut full = path.clone();
                                    full.push(name);
                                    frame.std_imports.entry((name, ns_index(Namespace::Value))).or_insert(full);
                                }
                                // A std glob can bring a module named
                                // like the glob path's own first segment
                                // (`alloc::*` brings `alloc::alloc`),
                                // which lust does not model above:
                                // record that one name, so import
                                // resolution reports the glob binding
                                // as ambiguous with the crate root the
                                // segment names outside the block
                                // (rustc E0659), as for user modules.
                                if let Some(&first) = path.first() {
                                    let mut cand = path.clone();
                                    cand.push(first);
                                    let cs: Vec<&str> = cand.iter().map(|s| self.interner.get(*s)).collect();
                                    if matches!(
                                        crate::resolve::stdpaths::std_has(&cs),
                                        Some(crate::resolve::stdpaths::StdHas::Module | crate::resolve::stdpaths::StdHas::Enum)
                                    ) {
                                        frame.std_imports.entry((first, ns_index(Namespace::Type))).or_insert(cand);
                                    }
                                }
                            }
                        }
                        PathRes::Done(Target::Module(src)) => self.glob_from_module(ast, src, module, scopes, span),
                        _ => self.push_unresolved_use(span, &path),
                    }
                }
            }
        }
    }

    /// The block type item a path's first segment names through the
    /// block frames, innermost binding first: its `Ast::stmt_items`
    /// index and the written path that names it (`[E]`, or `[E]` for
    /// an `F` that `use E as F;` binds). None when the innermost frame
    /// binding of the name in the type namespace is something else (an
    /// import of a module item, a std import), or no frame binds it.
    fn frame_type_item(&self, first: Sym, scopes: &[Frame]) -> Option<(u32, Vec<Sym>)> {
        let key = (first, ns_index(Namespace::Type));
        for frame in scopes.iter().rev() {
            if let Some(&(_, idx)) = frame.types.iter().rev().find(|t| t.0 == first) {
                return Some((idx, vec![first]));
            }
            if let Some(u) = frame.local_uses.get(&key) {
                return (u.path.len() == 1 && !u.ambiguous).then(|| (u.item, u.path.clone()));
            }
            if frame.imports.contains_key(&key) || frame.std_imports.contains_key(&key) {
                return None;
            }
        }
        None
    }

    /// rustc E0659 for a `use` path whose first segment is a block type
    /// item that a macro made (a `#[derive]` on it, or an item from a
    /// macro call): import resolution treats it as macro-expanded, and
    /// any binding of the name outside its block (an outer block, the
    /// module, the std prelude, the extern prelude) is then ambiguous
    /// with it. Plain paths outside `use` are not affected.
    fn macro_item_ambiguous(&self, ast: &Ast, first: Sym, module: ModuleId, scopes: &[Frame]) -> bool {
        let Some(fi) = scopes.iter().rposition(|f| f.types.iter().any(|t| t.0 == first)) else { return false };
        let Some(&(_, idx)) = scopes[fi].types.iter().rev().find(|t| t.0 == first) else { return false };
        let Some(item) = ast.stmt_items.get(idx as usize) else { return false };
        let derived = match &item.kind {
            ItemKind::Struct(s) => !s.derives.is_empty(),
            ItemKind::Enum(e) => !e.derives.is_empty(),
            ItemKind::Union(u) => !u.derives.is_empty(),
            _ => false,
        };
        if !derived && item.span.ctxt == crate::diag::CtxtId::ROOT {
            return false;
        }
        !matches!(self.import_seg(first, Namespace::Type, module, &scopes[..fi]).0.bind, SegBind::None)
    }

    /// Binds one function-local `use` whose path starts at a block
    /// type item (`frame_type_item` gave `item` and the written `base`
    /// path to it): `use E::V [as X];` and `use E::*;` for a block
    /// enum's variants, `use S as T;` for the item itself. Other forms
    /// (an associated item, a deeper path) are unresolved imports, as
    /// in rustc. The bound names stay written paths (`local_use_path`).
    fn local_item_use(&mut self, ast: &Ast, kind: &ImportKind, item: u32, base: Vec<Sym>, span: Span, scopes: &mut [Frame]) {
        let self_sym = self.interner.intern("self");
        let Some(it) = ast.stmt_items.get(item as usize) else { return };
        // A variant's namespaces: a struct variant binds the type
        // namespace only (`X { .. }`), so a value of its name (the
        // prelude `Some`) stays visible; unit and tuple variants bind both.
        let variant_of = |v: Sym| -> Option<&'static [Namespace]> {
            let ItemKind::Enum(e) = &it.kind else { return None };
            e.variants.iter().find(|x| x.name == v).map(|x| match x.fields {
                crate::ast::VariantFields::Struct(_) => &[Namespace::Type][..],
                _ => &[Namespace::Type, Namespace::Value][..],
            })
        };
        let ctor = matches!(&it.kind, ItemKind::Struct(s) if !matches!(s.fields, crate::ast::VariantFields::Struct(_)));
        let bind = |this: &mut Self, scopes: &mut [Frame], name: Sym, nss: &[Namespace], path: Vec<Sym>, glob: bool| {
            if this.interner.get(name) == "_" {
                return;
            }
            let mut dup = false;
            for &ns in nss {
                let u = LocalUse { path: path.clone(), item, glob, ambiguous: false };
                dup |= insert_local_use(scopes, name, ns, u);
            }
            if dup {
                this.push_local_dup(span, name);
            }
        };
        match kind {
            ImportKind::Single { path, name } => {
                let mut rest = &path[1..];
                let mut name = *name;
                // `use E::{self};` binds the item itself.
                if rest == [self_sym] {
                    rest = &[];
                    if name == self_sym {
                        name = path[0];
                    }
                }
                match rest {
                    // `use S;` names an item already in scope: in its own
                    // block that is a second definition (rustc E0255),
                    // so only a rename (`use S as T;`) binds.
                    [] if name == path[0] => {
                        self.diags.push(crate::diag::not_yet("L0820", span, "a `use` of a block item without a rename"));
                    }
                    [] => {
                        let nss: &[Namespace] = if ctor { &[Namespace::Type, Namespace::Value] } else { &[Namespace::Type] };
                        bind(self, scopes, name, nss, base, false);
                    }
                    [v] if let Some(nss) = variant_of(*v) => {
                        let mut p = base;
                        p.push(*v);
                        bind(self, scopes, name, nss, p, false);
                    }
                    _ => self.push_unresolved_use(span, path),
                }
            }
            ImportKind::Glob { path } => match (&it.kind, path.len()) {
                (ItemKind::Enum(e), 1) => {
                    let vs: Vec<Sym> = e.variants.iter().map(|v| v.name).collect();
                    for v in vs {
                        let mut p = base.clone();
                        p.push(v);
                        let nss = variant_of(v).unwrap_or(&[]);
                        bind(self, scopes, v, nss, p, true);
                    }
                }
                _ => self.push_unresolved_use(span, path),
            },
            ImportKind::CheckPath { path } => {
                if !(path.len() == 1 || (path.len() == 2 && variant_of(path[1]).is_some())) {
                    self.push_unresolved_use(span, path);
                }
            }
            ImportKind::BadLeading { .. } => {}
        }
    }

    /// The written path a use site of a function-local import of a
    /// block item reads as (`Frame::local_uses`): the import's path,
    /// when the first segment of that path still names the same block
    /// item at the use site. An inner block that shadows it would make
    /// the written path name a different item, so that case is a
    /// not-yet reject instead (L0820), and two globs that bring
    /// different items are ambiguous (L0507, rustc E0659).
    fn local_use_path(&mut self, u: &LocalUse, name: Sym, span: Span, scopes: &[Frame]) -> Option<Vec<Sym>> {
        if u.ambiguous {
            self.diags.push(ambiguous_diag(self.interner.get(name), span));
            return None;
        }
        if self.frame_type_item(u.path[0], scopes).is_none_or(|(item, base)| item != u.item || base != [u.path[0]]) {
            self.diags.push(crate::diag::not_yet("L0820", span, "an imported block item whose path an inner block shadows"));
            return None;
        }
        Some(u.path.clone())
    }

    /// The L0506 diagnostic for a function-local `use` that does not
    /// resolve, matching the module-level fixpoint message.
    fn push_unresolved_use(&mut self, span: Span, path: &[Sym]) {
        self.diags.push(Diag::new(
            "L0506",
            span,
            format!("unresolved import `{}`", path.iter().map(|s| self.interner.get(*s)).collect::<Vec<_>>().join("::")),
            "Check the path: every segment must name a module or item that is visible here.",
        ));
    }

    /// The L0106 diagnostic for a repeated function-local import name.
    fn push_local_dup(&mut self, span: Span, name: Sym) {
        self.diags.push(Diag::new(
            "L0106",
            span,
            format!("`{}` is defined more than once", self.interner.get(name)),
            "Rename one of the imports with `as`, or remove one.",
        ));
    }

    /// Checks a one-segment function-local import (`use a;`, `use self;`,
    /// `use crate as x;`). These bind nothing the later walk needs (the
    /// name reads through the module tables), but a bad one is still an
    /// error in rustc, so it is validated and only that. A renamed
    /// std crate root (`use std as s;`) is the exception: it records
    /// a local std alias.
    fn check_local_single_use(&mut self, path: &[Sym], name: Sym, leading: bool, module: ModuleId, span: Span, scopes: &mut [Frame]) {
        let seg = path[0];
        let self_sym = self.interner.intern("self");
        let crate_sym = self.interner.intern("crate");
        let super_sym = self.interner.intern("super");
        if seg == crate_sym || seg == self_sym || seg == super_sym {
            if name == seg {
                self.diags.push(Diag::new(
                    "L0506",
                    span,
                    "this import needs to be explicitly named",
                    "Add a rename, such as `use self as here;`.",
                ));
            } else if !matches!(self.tables.resolve_module_path(module, path, leading, self.interner), PathRes::Done(_)) {
                self.push_unresolved_use(span, path);
            }
            return;
        }
        if let PathRes::Done(Target::Extern(i)) =
            self.tables.resolve_path(module, path, Namespace::Type, PathMode::Use, leading, self.interner)
        {
            if self.tables.externs[i as usize].is_std_lib
                && self.tables.externs[i as usize].unsupported.is_none()
                && self.interner.get(name) != "_"
                && insert_local_std(scopes, name, Namespace::Type, path.to_vec())
            {
                self.push_local_dup(span, name);
            }
            return;
        }
        // A name an enclosing block's `use` binds (glob or
        // explicit) is in scope for this import too, through the
        // frames; ambiguity with an outer item is the L0507
        // `check_block_use` reports, not an unresolved import.
        if !leading
            && [Namespace::Type, Namespace::Value, Namespace::Macro]
                .iter()
                .any(|&ns| matches!(self.import_seg(seg, ns, module, scopes), (info, true) if !matches!(info.bind, SegBind::None)))
        {
            return;
        }
        // `use E as V;` binds the item under the new name in every
        // namespace the item has (ts_goport `use ParsingContext as PC;`).
        // `use E;` names an item already in scope and binds nothing new.
        if name != seg {
            let mut any = false;
            let mut dup = false;
            for ns in [Namespace::Type, Namespace::Value, Namespace::Macro] {
                if let PathRes::Done(target) = self.tables.resolve_path(module, path, ns, PathMode::Use, leading, self.interner) {
                    any = true;
                    if self.interner.get(name) == "_" {
                        continue;
                    }
                    let bn = crate::resolve::imports::import_bind_name(name, target, self.interner);
                    dup |= insert_local(scopes, bn, ns, LocalBind::Target(target), 2);
                }
            }
            if dup {
                self.push_local_dup(span, name);
            }
            if any {
                return;
            }
        }
        let mut saw_private = false;
        for ns in [Namespace::Type, Namespace::Value, Namespace::Macro] {
            match self.tables.resolve_path(module, path, ns, PathMode::Use, leading, self.interner) {
                PathRes::Done(_) | PathRes::Partial(..) | PathRes::Prelude => return,
                PathRes::Private => saw_private = true,
                _ => {}
            }
        }
        if saw_private {
            self.diags.push(private_diag(self.interner.get(seg), span));
        } else {
            self.push_unresolved_use(span, path);
        }
    }

    /// A pattern binding name that resolves to a const, a unit
    /// struct, or an imported variant is a path pattern in Rust, not
    /// a fresh binding; one that resolves to a static is an error
    /// (L0633). Returns the replacement path pattern when it applies.
    fn binding_pat(&mut self, name: Sym, span: Span, module: ModuleId, scopes: &[Frame]) -> Option<Pat> {
        // An imported block enum variant or unit struct is a path
        // pattern through its written path.
        if let Some(FrameHit::LocalUse(u)) = self.frame_hit(&[name], Namespace::Value, scopes) {
            let path = self.local_use_path(&u, name, span, scopes)?;
            return Some(Pat::Path(path.iter().map(|s| PathSeg::plain(*s)).collect()));
        }
        // A block unit or tuple struct of the name (the innermost value
        // binding of it) makes the pattern a path pattern, as rustc
        // reads it: `let S = 5u8;` under `struct S;` is a type error.
        if let Some(f) = scopes.iter().rev().find(|f| f.locals.contains(&name) || f.items.contains(&name))
            && !f.locals.contains(&name)
            && f.ctors.contains(&name)
        {
            return Some(Pat::Path(vec![PathSeg::plain(name)]));
        }
        let (res, local) = self.resolve(&[name], Namespace::Value, module, scopes);
        if local {
            return None;
        }
        match res {
            PathRes::Done(Target::Def(def)) => match self.tables.def_info.get(&def) {
                Some(info) if info.kind == ResKind::Static => None,
                Some(info) if matches!(info.kind, ResKind::Const | ResKind::Adt) => Some(Pat::Path(vec![PathSeg::plain(info.flat)])),
                _ => None,
            },
            PathRes::Done(Target::Variant(def, variant)) => {
                self.tables.def_info.get(&def).map(|info| Pat::Path(vec![PathSeg::plain(info.flat), PathSeg::plain(variant)]))
            }
            PathRes::Ambiguous => {
                self.diags.push(ambiguous_diag(self.interner.get(name), span));
                None
            }
            PathRes::OrderDep => {
                self.diags.push(crate::resolve::order::order_diag(self.interner.get(name), span));
                None
            }
            PathRes::Private => {
                self.diags.push(private_diag(self.interner.get(name), span));
                None
            }
            // A std variant imported by name or glob (`use
            // std::cmp::Ordering::Less;`) is a path pattern, not a
            // binding: its full std path, as expressions expand it.
            _ => {
                let idx = ns_index(Namespace::Value);
                let alias = scopes
                    .iter()
                    .rev()
                    .find_map(|f| f.std_imports.get(&(name, idx)))
                    .or_else(|| {
                        crate::resolve::mdr::read_key(module, idx as u8, name);
                        self.tables.std_aliases.get(&(module, idx as u8, name)).map(|(_, p)| p)
                    })?;
                let strs: Vec<&str> = alias.iter().map(|s| self.interner.get(*s)).collect();
                (crate::ty::lang::std_path_kind(&strs) == Some(crate::ty::lang::StdPathKind::Variant))
                    .then(|| Pat::Path(alias.iter().map(|s| PathSeg::plain(*s)).collect()))
            }
        }
    }

    /// True when a std glob import may decide what the path's first
    /// segment names, and lust would pick something else:
    /// - a block with a glob of a std module shadows outer scopes for
    ///   every name the module exports, so a name lust finds only
    ///   outside that block (an outer local, item, or import, or a
    ///   module binding) may be the glob's instead;
    /// - in a module with a std glob, a name from a user glob may be
    ///   ambiguous with it (rustc E0659).
    /// Both apply only to names std 1.99 has in a glob's module (its
    /// path table). Names the block itself binds, generic params, names
    /// lust finds nowhere (the prelude, the std items a glob binds), and
    /// a std glob's own copy of an overlay item are fine.
    fn std_glob_check(&self, segs: &[Sym], ns: Namespace, module: ModuleId, scopes: &[Frame]) -> bool {
        let Some(&first) = segs.first() else { return false };
        if matches!(self.interner.get(first), "crate" | "self" | "super" | "Self" | "::") || self.gen_params.iter().any(|(n, _)| *n == first) {
            return false;
        }
        let asked = if segs.len() > 1 { Namespace::Type } else { ns };
        let key = (first, ns_index(asked));
        let binds = |f: &Frame| {
            (asked != Namespace::Type && (f.locals.contains(&first) || f.items.contains(&first)))
                || (asked == Namespace::Type && f.types.iter().any(|t| t.0 == first))
                || f.local_uses.contains_key(&key)
                || f.imports.contains_key(&key)
                || f.std_imports.contains_key(&key)
        };
        for (i, frame) in scopes.iter().enumerate().rev() {
            if binds(frame) {
                // A glob import beside the std glob in one block may
                // be ambiguous with it; an explicit binding wins.
                let glob_only = frame.imports.contains_key(&key)
                    && !frame.explicit.contains(&key)
                    && !(asked != Namespace::Type && (frame.locals.contains(&first) || frame.items.contains(&first)));
                return frame.std_mod_glob && glob_only;
            }
            // A block std glob that does not have the name (std 1.99's
            // path table) leaves it to the outer scopes.
            if frame.std_mod_glob && self.std_globs_bring(&frame.std_glob_paths, first, asked) {
                return scopes[..i].iter().any(binds) || self.tables.lookup(module, asked, first).is_some();
            }
        }
        // A glob copy of a std overlay item (`use std::cell::*;` binds
        // OnceCell) or of a platform crate item (`use std::io::*;` binds
        // stdout) is the std glob's own name; two std globs that bring
        // different items are `std_glob_ambiguous`.
        let platform = self.tables.std_platform.map(|(root, _)| root);
        let from_std = |key: (ModuleId, u8, Sym)| {
            crate::resolve::mdr::read_key(key.0, key.1, key.2);
            self.tables.glob_src.get(&key).is_some_and(|src| {
                self.tables.std_modules.iter().any(|&(_, m)| m == *src) || platform.is_some_and(|root| self.tables.root_of(*src) == root)
            })
        };
        matches!(self.tables.lookup(module, asked, first), Some(BindState::One(b)) if b.rank <= 1)
            && !from_std((module, ns_index(asked) as u8, first))
            && self.std_globs_bring(self.tables.std_globs.iter().filter(|(m, _)| *m == module).map(|(_, p)| p), first, asked)
    }

    /// True when one of the std globs `paths` brings `name` (std 1.99's
    /// path table) in namespace `ns`: `use std::rc::*;` brings `Weak`
    /// as a type only, so a value `Weak` comes from outside the glob.
    fn std_globs_bring<'p>(&self, paths: impl IntoIterator<Item = &'p Vec<Sym>>, name: Sym, ns: Namespace) -> bool {
        paths.into_iter().any(|p| {
            let mut full: Vec<&str> = p.iter().map(|s| self.interner.get(*s)).collect();
            full.push(self.interner.get(name));
            match ns {
                Namespace::Value => crate::resolve::stdpaths::std_has_value(&full),
                _ => crate::resolve::stdpaths::std_has(&full).is_some(),
            }
        })
    }

    /// True when two std globs in scope bring different std items named
    /// like the path's first segment (rustc E0659: `use std::rc::*; use
    /// std::sync::*;` and `Weak`, `use std::mem::*; use std::ptr::*;`
    /// and `swap`). The std 1.99 path table says what each glob brings,
    /// also the items lust has no form for. The innermost scope with a
    /// binding of the name decides: a local, an item, or an explicit
    /// import wins over globs; a block whose std globs bring the name
    /// hides the outer scopes.
    fn std_glob_ambiguous(&self, segs: &[Sym], ns: Namespace, module: ModuleId, scopes: &[Frame]) -> bool {
        let Some(&first) = segs.first() else { return false };
        let n_globs = scopes.iter().map(|f| f.std_glob_paths.len()).sum::<usize>() + self.tables.std_globs.iter().filter(|(m, _)| *m == module).count();
        if n_globs < 2 || matches!(self.interner.get(first), "crate" | "self" | "super" | "Self" | "::") || self.gen_params.iter().any(|(n, _)| *n == first) {
            return false;
        }
        let asked = if segs.len() > 1 { Namespace::Type } else { ns };
        let key = (first, ns_index(asked));
        let name = self.interner.get(first);
        let disagree = |paths: &mut dyn Iterator<Item = &Vec<Sym>>| -> Option<bool> {
            let mut seen: Option<Vec<&str>> = None;
            for p in paths {
                let mut full: Vec<&str> = p.iter().map(|s| self.interner.get(*s)).collect();
                full.push(name);
                // Ambiguity is per namespace: `use std::io::*; use
                // std::fmt::*;` and a value `Error` is fmt's unit struct.
                let has = match asked {
                    Namespace::Value => crate::resolve::stdpaths::std_has_value(&full),
                    _ => crate::resolve::stdpaths::std_has(&full).is_some(),
                };
                if !has {
                    continue;
                }
                match &seen {
                    None => seen = Some(full),
                    Some(old) if *old == full || (old.len() > 1 && old.len() == full.len() && old[1..] == full[1..]) => {}
                    Some(_) => return Some(true),
                }
            }
            seen.map(|_| false)
        };
        for frame in scopes.iter().rev() {
            if (asked != Namespace::Type && (frame.locals.contains(&first) || frame.items.contains(&first))) || frame.explicit.contains(&key) {
                return false;
            }
            if let Some(amb) = disagree(&mut frame.std_glob_paths.iter()) {
                return amb;
            }
            if frame.imports.contains_key(&key) || frame.std_imports.contains_key(&key) {
                return false;
            }
        }
        let mkey = (module, ns_index(asked) as u8, first);
        if matches!(self.tables.lookup(module, asked, first), Some(BindState::One(b)) if b.rank >= 2) || self.tables.explicit_std_alias(mkey) {
            return false;
        }
        disagree(&mut self.tables.std_globs.iter().filter(|(m, _)| *m == module).map(|(_, p)| p)).unwrap_or(false)
    }

    /// True when an uppercase binding name sits under a glob of a std
    /// module (in a block or the module) that brings an item of that name
    /// (std 1.99's path table): it may be a const (`use std::f64::consts::*;
    /// let PI = 3.0;` is rustc E0005), so lust rejects the binding. Globs
    /// of std enums' variants are left to the variant rewrite.
    fn binding_under_std_glob(&self, name: Sym, module: ModuleId, scopes: &[Frame]) -> bool {
        let module_glob = |p: &&Vec<Sym>| {
            let strs: Vec<&str> = p.iter().map(|s| self.interner.get(*s)).collect();
            crate::ty::lang::std_enum_variants(&strs).is_empty()
        };
        self.interner.get(name).starts_with(|c: char| c.is_ascii_uppercase())
            && !Self::frames_bind(scopes, name)
            && (scopes.iter().any(|f| f.std_mod_glob && self.std_globs_bring(f.std_glob_paths.iter().filter(module_glob), name, Namespace::Value))
                || self.std_globs_bring(self.tables.std_globs.iter().filter(|(m, _)| *m == module).map(|(_, p)| p).filter(module_glob), name, Namespace::Value))
    }

    /// rustc E0530 for a binding over a static or const that a block's
    /// `use` brings in: no binding may shadow a static, and only a plain
    /// binding may name a const (as its path pattern). The checker sees
    /// module imports and block items, but not block imports.
    fn binding_over_block_import(&mut self, name: Sym, plain: bool, span: Span, scopes: &[Frame]) {
        let Some(FrameHit::Import(LocalBind::Target(Target::Def(def)))) = self.frame_hit(&[name], Namespace::Value, scopes) else { return };
        let what = match self.tables.def_info.get(&def).map(|i| i.kind) {
            Some(ResKind::Static) => "statics",
            Some(ResKind::Const) if !plain => "constants",
            _ => return,
        };
        let n = self.interner.get(name);
        self.diags.push(Diag::new("L0110", span, format!("bindings cannot shadow {what}"), format!("Rename the binding: `{n}` names an item here.")));
    }

    /// Rewrites one pattern's paths.
    fn pat(&mut self, ast: &mut Ast, id: PatId, module: ModuleId, scopes: &[Frame]) {
        let span = ast.pat_span(id);
        match std::mem::replace(&mut ast.pats[id.0 as usize], Pat::Wild) {
            Pat::Binding { name, mutable, by_ref } => {
                if self.binding_under_std_glob(name, module, scopes) {
                    self.diags.push(crate::resolve::imports::std_glob_name_diag(self.interner.get(name), span));
                }
                self.binding_over_block_import(name, !mutable && !by_ref, span, scopes);
                let replacement = self.binding_pat(name, span, module, scopes);
                // A `mut` or `ref` binding may not reuse the name of a unit
                // or tuple struct, a variant, or a const in scope (rustc
                // E0530): only a plain one reads as their path pattern.
                if (mutable || by_ref) && replacement.is_some() {
                    let n = self.interner.get(name);
                    self.diags.push(Diag::new(
                        "L0110",
                        span,
                        format!("bindings cannot shadow `{n}`: it names a struct, variant, or constant here"),
                        format!("Rename the binding: `{n}` names an item here."),
                    ));
                }
                let replacement = if !mutable && !by_ref { replacement } else { None };
                ast.pats[id.0 as usize] = replacement.unwrap_or(Pat::Binding { name, mutable, by_ref });
            }
            Pat::Path(mut segs) => {
                self.rewrite_path(&mut segs, Namespace::Value, span, module, scopes, ast);
                ast.pats[id.0 as usize] = Pat::Path(segs);
            }
            Pat::QPath { self_ty, mut trait_path, segs } => {
                self.ty(ast, self_ty, module, scopes);
                if !trait_path.is_empty() {
                    self.rewrite_path(&mut trait_path, Namespace::Type, span, module, scopes, ast);
                }
                ast.pats[id.0 as usize] = Pat::QPath { self_ty, trait_path, segs };
            }
            Pat::TupleStruct { path: mut s, elems } => {
                self.rewrite_ctor_path(&mut s, span, module, scopes, ast);
                for e in &elems {
                    self.pat(ast, *e, module, scopes);
                }
                ast.pats[id.0 as usize] = Pat::TupleStruct { path: s, elems };
            }
            Pat::Struct { path: mut s, fields, rest } => {
                self.rewrite_ctor_path(&mut s, span, module, scopes, ast);
                for (_, f) in &fields {
                    self.pat(ast, *f, module, scopes);
                }
                ast.pats[id.0 as usize] = Pat::Struct { path: s, fields, rest };
            }
            node => {
                // Child patterns and expressions first, then the node
                // goes back unchanged.
                match &node {
                    Pat::Lit(e) => {
                        let e = *e;
                        let mut sc = scopes.to_vec();
                        self.expr(ast, e, module, &mut sc);
                    }
                    Pat::Or(elems) | Pat::Tuple(elems) => {
                        for e in elems {
                            self.pat(ast, *e, module, scopes);
                        }
                    }
                    Pat::Range { lo, hi, .. } => {
                        let mut sc = scopes.to_vec();
                        if let Some(e) = lo {
                            self.expr(ast, *e, module, &mut sc);
                        }
                        if let Some(e) = hi {
                            self.expr(ast, *e, module, &mut sc);
                        }
                    }
                    Pat::At { inner, name, .. } => {
                        let (inner, name) = (*inner, *name);
                        self.binding_over_block_import(name, false, span, scopes);
                        self.pat(ast, inner, module, scopes);
                    }
                    Pat::Ref { inner, .. } | Pat::Paren(inner) => {
                        let inner = *inner;
                        self.pat(ast, inner, module, scopes);
                    }
                    Pat::Slice { prefix, middle, suffix } => {
                        for e in prefix.iter().chain(suffix) {
                            self.pat(ast, *e, module, scopes);
                        }
                        if let Some(m) = middle {
                            self.pat(ast, *m, module, scopes);
                        }
                    }
                    _ => {}
                }
                ast.pats[id.0 as usize] = node;
            }
        }
    }

    /// Rewrites one expression subtree.
    /// One `if`/`while` condition with `let`s: operands of `&&` in order,
    /// each `let`'s scrutinee in the scopes so far, then a frame with its
    /// bindings pushed for what follows (the caller pops them).
    fn let_chain(&mut self, ast: &mut Ast, e: ExprId, module: ModuleId, scopes: &mut Vec<Frame>) {
        match &ast.exprs[e.0 as usize] {
            Expr::Binary { op: BinOp::And, lhs, rhs } => {
                let (lhs, rhs) = (*lhs, *rhs);
                self.let_chain(ast, lhs, module, scopes);
                self.let_chain(ast, rhs, module, scopes);
            }
            Expr::Let { pat, scrut } => {
                let (pat, scrut) = (*pat, *scrut);
                self.expr(ast, scrut, module, scopes);
                self.pat(ast, pat, module, scopes);
                let mut frame = Frame::default();
                self.pat_bindings(ast, pat, &mut frame.locals);
                scopes.push(frame);
            }
            _ => self.expr(ast, e, module, scopes),
        }
    }

    fn expr(&mut self, ast: &mut Ast, id: ExprId, module: ModuleId, scopes: &mut Vec<Frame>) {
        let span = ast.expr_span(id);
        // Nodes that carry a path are swapped out whole, rewritten, and
        // put back (the path rewrite needs `ast` for generic-arg types).
        if matches!(ast.exprs[id.0 as usize], Expr::Path(_)) {
            let Expr::Path(mut segs) = std::mem::replace(&mut ast.exprs[id.0 as usize], Expr::Unit) else { return };
            self.rewrite_path(&mut segs, Namespace::Value, span, module, scopes, ast);
            ast.exprs[id.0 as usize] = Expr::Path(segs);
            return;
        }
        // `<T as Trait>::item`: the self type and the trait resolve in
        // this module, as in a type position (a trait of the name at the
        // crate root must not win).
        if matches!(ast.exprs[id.0 as usize], Expr::QPath { .. }) {
            let Expr::QPath { self_ty, mut trait_path, segs } = std::mem::replace(&mut ast.exprs[id.0 as usize], Expr::Unit) else {
                return;
            };
            self.ty(ast, self_ty, module, scopes);
            if !trait_path.is_empty() {
                self.rewrite_path(&mut trait_path, Namespace::Type, span, module, scopes, ast);
            }
            ast.exprs[id.0 as usize] = Expr::QPath { self_ty, trait_path, segs };
            return;
        }
        if matches!(ast.exprs[id.0 as usize], Expr::StructLit { .. }) {
            let Expr::StructLit { path: mut segs, fields, update } = std::mem::replace(&mut ast.exprs[id.0 as usize], Expr::Unit) else {
                return;
            };
            self.rewrite_ctor_path(&mut segs, span, module, scopes, ast);
            for (_, _, e) in &fields {
                let e = *e;
                self.expr(ast, e, module, scopes);
            }
            if let Some(u) = update {
                self.expr(ast, u, module, scopes);
            }
            ast.exprs[id.0 as usize] = Expr::StructLit { path: segs, fields, update };
            return;
        }
        // A closure's params scope over its body: all of them in one
        // frame, pushed before the body (a param named like an item, such
        // as an imported fn, resolved to the item before).
        if let Expr::Closure { params, ret, body, .. } = &ast.exprs[id.0 as usize] {
            let (pats, ret, body): (Vec<PatId>, Option<TyId>, ExprId) = (params.iter().map(|p| p.pat).collect(), *ret, *body);
            // Parameter types too (`|c: &Cow<str>|` names an import).
            let tys: Vec<TyId> = params.iter().filter_map(|p| p.ty).collect();
            for t in tys.into_iter().chain(ret) {
                self.ty(ast, t, module, scopes);
            }
            let mut frame = Frame::default();
            for pat in pats {
                self.pat(ast, pat, module, scopes);
                self.pat_bindings(ast, pat, &mut frame.locals);
            }
            scopes.push(frame);
            self.expr(ast, body, module, scopes);
            scopes.pop();
            return;
        }
        // `if let` and `while let` (let chains too): each `let` binds over
        // the later conditions and the body, not the `else` branch (the
        // bindings scoped over nothing before, so a body name like an
        // imported fn resolved to the fn).
        if let Expr::If { cond, then, els } = &ast.exprs[id.0 as usize]
            && has_let(ast, *cond)
        {
            let (cond, then, els) = (*cond, *then, *els);
            let depth = scopes.len();
            self.let_chain(ast, cond, module, scopes);
            self.block(ast, then, module, scopes);
            scopes.truncate(depth);
            if let Some(e) = els {
                self.expr(ast, e, module, scopes);
            }
            return;
        }
        if let Expr::While { cond, body, .. } = &ast.exprs[id.0 as usize]
            && has_let(ast, *cond)
        {
            let (cond, body) = (*cond, *body);
            let depth = scopes.len();
            self.let_chain(ast, cond, module, scopes);
            self.block(ast, body, module, scopes);
            scopes.truncate(depth);
            return;
        }
        // Method turbofish types (`collect::<BTreeMap<_, _>>()`) name
        // types too: rewrite them like any written type (W-STD-C).
        if let Expr::MethodCall { generic_args, .. } = &ast.exprs[id.0 as usize] {
            let tys: Vec<TyId> = generic_args.iter().filter_map(|g| if let crate::ast::GenericArg::Type(t) = g { Some(*t) } else { None }).collect();
            for t in tys {
                self.ty(ast, t, module, scopes);
            }
        }
        match ast.exprs[id.0 as usize].kind_children() {
            ExprKids { blocks, exprs, pats_with_scope, tys } => {
                for t in tys {
                    self.ty(ast, t, module, scopes);
                }
                for e in exprs {
                    self.expr(ast, e, module, scopes);
                }
                for (pat, body) in pats_with_scope {
                    self.pat(ast, pat, module, scopes);
                    let mut frame = Frame::default();
                    self.pat_bindings(ast, pat, &mut frame.locals);
                    scopes.push(frame);
                    match body {
                        ScopeBody::Block(b) => self.block(ast, b, module, scopes),
                        ScopeBody::Expr(e) => self.expr(ast, e, module, scopes),
                        ScopeBody::None => {}
                    }
                    scopes.pop();
                }
                for b in blocks {
                    self.block(ast, b, module, scopes);
                }
            }
        }
    }
}

/// Rewrites the paths of one fn body in a merged Ast against frozen
/// tables, exactly as the rewrite pass does for that body in a full
/// resolve: the daemon's body patch (driver/patch.rs) re-parses one
/// body and rewrites it here instead of resolving the crate again.
/// `outer` holds the generics of the impl or trait around a method.
/// Its block items rewrite as in the full pass; the patch proves they
/// are the old ones (`same_items`). Returns the rewrite's diagnostics;
/// the patch gives up on any.
#[allow(clippy::too_many_arguments)]
pub fn rewrite_fn_body(
    tables: &ResolvedTables,
    interner: &Interner,
    local_names: &FxMap<Sym, u8>,
    std_splice_lo: Option<u32>,
    ast: &mut Ast,
    def: &FnDef,
    outer: Option<&Generics>,
    module: ModuleId,
) -> Vec<Diag> {
    let no_lists = FxMap::default();
    let mut rw = Rewrite {
        tables,
        interner,
        list_module: &no_lists,
        local_names,
        diags: Vec::new(),
        gen_params: Vec::new(),
        std_splice_lo,
        gen_floor: 0,
    };
    if let Some(g) = outer {
        rw.push_params(g);
    }
    rw.push_params(&def.generics);
    rw.fn_body(ast, def, module, &[]);
    rw.diags
}

/// The item patch's rewrite of one whole fn or method (signature types
/// and body), as the full rewrite's `items` pass does it for that fn:
/// `Rewrite::fn_def` under the impl's generics (`outer`), against frozen
/// tables. Returns the rewrite's diagnostics; any means the patch gives up.
#[allow(clippy::too_many_arguments)]
pub fn rewrite_fn_item(
    tables: &ResolvedTables,
    interner: &Interner,
    local_names: &FxMap<Sym, u8>,
    std_splice_lo: Option<u32>,
    ast: &mut Ast,
    def: &mut FnDef,
    outer: Option<&Generics>,
    module: ModuleId,
) -> Vec<Diag> {
    let no_lists = FxMap::default();
    let mut rw = Rewrite {
        tables,
        interner,
        list_module: &no_lists,
        local_names,
        diags: Vec::new(),
        gen_params: Vec::new(),
        std_splice_lo,
        gen_floor: 0,
    };
    if let Some(g) = outer {
        rw.push_params(g);
    }
    rw.fn_def(ast, def, module);
    rw.diags
}

/// True when an `if`/`while` condition holds a `let` (directly or in a
/// `&&` chain).
fn has_let(ast: &Ast, e: ExprId) -> bool {
    match ast.expr(e) {
        Expr::Let { .. } => true,
        Expr::Binary { op: BinOp::And, lhs, rhs } => has_let(ast, *lhs) || has_let(ast, *rhs),
        _ => false,
    }
}

/// Records `module` on the anonymous const whose value is `e`, if it
/// has an `Ast::anon_consts` entry. Returns whether it has one.
fn anon_const_module(ast: &mut Ast, e: crate::ast::ExprId, module: ModuleId) -> bool {
    let Some(i) = ast.anon_const(e) else { return false };
    ast.anon_consts[i as usize].module = Some(module);
    true
}

/// The generic-argument const expr ids under one segment's args.
fn collect_arg_consts(args: &GenericArgs, out: &mut Vec<crate::ast::ExprId>) {
    if let GenericArgs::Angle(args) = args {
        for a in args {
            match a {
                GenericArg::Const(e) => out.push(*e),
                GenericArg::Binding { kind: BindingKind::EqConst(e), .. } => out.push(*e),
                _ => {}
            }
        }
    }
}

/// The generic-argument type ids under one segment's args.
fn collect_arg_tys(args: &GenericArgs, out: &mut Vec<TyId>) {
    match args {
        GenericArgs::Angle(args) => {
            for a in args {
                match a {
                    GenericArg::Type(t) => out.push(*t),
                    GenericArg::Binding { kind: BindingKind::EqTy(t), .. } => out.push(*t),
                    _ => {}
                }
            }
        }
        GenericArgs::Parenthesized { inputs, output } => {
            out.extend(inputs.iter().copied());
            out.extend(output.iter().copied());
        }
        GenericArgs::None => {}
    }
}

/// Inserts one function-local import binding with a rank: an explicit
/// import (2) beats a glob (1); two globs with different targets are
/// ambiguous.
/// Inserts one function-local import binding. Returns true when an
/// explicit (rank 2) import rebinds a name an earlier explicit local
/// import already bound in this frame: a duplicate import (E0252).
/// Records one function-local std import alias at explicit rank.
/// Returns true when the name was already bound explicitly in
/// this frame and namespace (the caller reports a duplicate).
fn insert_local_std(scopes: &mut [Frame], name: Sym, ns: Namespace, path: Vec<Sym>) -> bool {
    let Some(frame) = scopes.last_mut() else { return false };
    let key = (name, ns_index(ns));
    if frame.explicit.contains(&key) {
        return true;
    }
    frame.explicit.push(key);
    // It beats an earlier glob binding of the name.
    frame.imports.remove(&key);
    frame.local_uses.remove(&key);
    frame.std_imports.insert(key, path);
    false
}

/// Records a std alias a function-local glob of a module brings
/// (`use crate::prelude::*;` with `pub use std::rc::Rc;` there). An
/// explicit binding of the frame wins; a glob of a crate item or of
/// another std item makes the name ambiguous.
fn insert_glob_local_std(scopes: &mut [Frame], name: Sym, ns: usize, path: Vec<Sym>) {
    let Some(frame) = scopes.last_mut() else { return };
    let key = (name, ns);
    if frame.explicit.contains(&key) || matches!(frame.imports.get(&key), Some(LocalBind::Ambiguous)) {
        return;
    }
    if let Some(u) = frame.local_uses.get_mut(&key) {
        u.ambiguous = true;
        return;
    }
    let same = |old: &[Sym]| old == path.as_slice() || (old.len() > 1 && old.len() == path.len() && old[1..] == path[1..]);
    if frame.imports.contains_key(&key) || frame.std_imports.get(&key).is_some_and(|old| !same(old)) {
        frame.std_imports.remove(&key);
        frame.imports.insert(key, LocalBind::Ambiguous);
        return;
    }
    frame.std_imports.insert(key, path);
}

fn insert_local(scopes: &mut [Frame], name: Sym, ns: Namespace, bind: LocalBind, rank: u8) -> bool {
    let Some(frame) = scopes.last_mut() else { return false };
    let key = (name, ns_index(ns));
    let dup = rank >= 2 && frame.explicit.contains(&key);
    if rank >= 2 && !dup {
        frame.explicit.push(key);
    }
    // A glob local use of a block item (`use E::*;` for a block enum)
    // beside this binding: an explicit one replaces it, a glob one of
    // a different item makes the name ambiguous.
    if let Some(u) = frame.local_uses.get_mut(&key) {
        if rank >= 2 {
            frame.local_uses.remove(&key);
        } else {
            if !frame.explicit.contains(&key) {
                u.ambiguous = true;
            }
            return false;
        }
    }
    // An explicit binding of the frame (an import, a std import, or a
    // block item) beats a glob.
    if rank <= 1 && frame.explicit.contains(&key) {
        return false;
    }
    // A glob of a crate item beside a glob std alias of the name.
    if rank <= 1 && frame.std_imports.remove(&key).is_some() {
        frame.imports.insert(key, LocalBind::Ambiguous);
        return false;
    }
    match (frame.imports.get(&key), bind) {
        (Some(LocalBind::Target(old)), LocalBind::Target(new)) if *old != new && rank <= 1 => {
            frame.imports.insert(key, LocalBind::Ambiguous);
        }
        (Some(_), _) if rank <= 1 => {}
        _ => {
            frame.imports.insert(key, bind);
        }
    }
    dup
}

/// Binds a function-local import of a block item in the innermost
/// frame (`Frame::local_uses`), with `insert_local`'s ranks: an
/// explicit binding beats a glob, and two globs that bring different
/// items make the name ambiguous. Returns true for a second explicit
/// binding of the name in the frame (a duplicate).
fn insert_local_use(scopes: &mut [Frame], name: Sym, ns: Namespace, u: LocalUse) -> bool {
    let Some(frame) = scopes.last_mut() else { return false };
    let key = (name, ns_index(ns));
    if !u.glob {
        let dup = frame.explicit.contains(&key);
        if !dup {
            frame.explicit.push(key);
        }
        frame.imports.remove(&key);
        frame.std_imports.remove(&key);
        frame.local_uses.insert(key, u);
        return dup;
    }
    if frame.explicit.contains(&key) {
        return false;
    }
    let other = frame.imports.contains_key(&key) || frame.std_imports.contains_key(&key);
    match frame.local_uses.get_mut(&key) {
        Some(old) => old.ambiguous |= other || old.path != u.path,
        None => {
            frame.local_uses.insert(key, LocalUse { ambiguous: other, ..u });
        }
    }
    false
}

/// A throwaway FnDef for `mem::replace` during the item walk.
fn dummy_fn() -> FnDef {
    FnDef {
        name: Sym(0),
        name_span: Span::default(),
        is_test: false,
        vis: Vis::Private,
        attrs: Vec::new(),
        qual: Default::default(),
        generics: Default::default(),
        self_param: None,
        params: Vec::new(),
        variadic: false,
        ret: None,
        where_clause: Default::default(),
        body: None,
        exprs: (0, 0),
        pats: (0, 0),
    }
}

/// Which child nodes an expression has, grouped by how the walk treats
/// them. Pattern-plus-body pairs get a scope frame from the pattern.
struct ExprKids {
    blocks: Vec<BlockId>,
    exprs: Vec<ExprId>,
    pats_with_scope: Vec<(PatId, ScopeBody)>,
    tys: Vec<TyId>,
}

enum ScopeBody {
    Block(BlockId),
    Expr(ExprId),
    None,
}

/// Child enumeration for the rewrite walk, over the expression forms the
/// parser produces. Match arms: the walk needs arms one by one (each
/// arm's guard and body see the arm pattern's bindings), so Match is
/// expanded here into scrutinee plus one scoped pair per arm.
trait KindChildren {
    fn kind_children(&self) -> ExprKids;
}

impl KindChildren for Expr {
    fn kind_children(&self) -> ExprKids {
        let mut k = ExprKids { blocks: Vec::new(), exprs: Vec::new(), pats_with_scope: Vec::new(), tys: Vec::new() };
        match self {
            Expr::Int(..)
            | Expr::Bool(_)
            | Expr::Str(_)
            | Expr::ByteStr(_)
            | Expr::Char(_)
            | Expr::Unit
            | Expr::SelfValue
            | Expr::Float(_)
            | Expr::Underscore => {}
            Expr::Path(_) | Expr::StructLit { .. } => {}
            Expr::OffsetOf { ty, .. } => k.tys.push(*ty),
            Expr::Block(b) | Expr::UnsafeBlock(b) | Expr::ConstBlock(b) => k.blocks.push(*b),
            Expr::LabeledBlock { body, .. } | Expr::AsyncBlock { body, .. } => k.blocks.push(*body),
            Expr::If { cond, then, els } => {
                k.exprs.push(*cond);
                k.blocks.push(*then);
                if let Some(e) = els {
                    k.exprs.push(*e);
                }
            }
            Expr::While { cond, body, .. } => {
                k.exprs.push(*cond);
                k.blocks.push(*body);
            }
            Expr::Loop { body, .. } => k.blocks.push(*body),
            Expr::For { pat, iter, body, .. } => {
                k.exprs.push(*iter);
                k.pats_with_scope.push((*pat, ScopeBody::Block(*body)));
            }
            Expr::Match { scrut, arms } => {
                k.exprs.push(*scrut);
                for a in arms {
                    if let Some(g) = a.guard {
                        k.pats_with_scope.push((a.pat, ScopeBody::Expr(g)));
                    }
                    k.pats_with_scope.push((a.pat, ScopeBody::Expr(a.body)));
                }
            }
            Expr::Call { callee, args } => {
                k.exprs.push(*callee);
                k.exprs.extend(args.iter().copied());
            }
            Expr::MethodCall { recv, args, generic_args, .. } => {
                k.exprs.push(*recv);
                k.exprs.extend(args.iter().copied());
                // Imported names in the turbofish (`collect::<HashMap<_, _>>()`).
                k.tys.extend(generic_args.iter().filter_map(|g| match g {
                    GenericArg::Type(t) => Some(*t),
                    _ => None,
                }));
            }
            Expr::Field { base, .. } | Expr::TupleField { base, .. } => k.exprs.push(*base),
            Expr::Index { base, index } => {
                k.exprs.push(*base);
                k.exprs.push(*index);
            }
            Expr::Binary { lhs, rhs, .. } | Expr::Assign { lhs, rhs } | Expr::AssignOp { lhs, rhs, .. } => {
                k.exprs.push(*lhs);
                k.exprs.push(*rhs);
            }
            Expr::Unary { expr, .. } | Expr::Ref { expr, .. } | Expr::Deref(expr) | Expr::Try(expr) | Expr::Await(expr) => {
                k.exprs.push(*expr)
            }
            Expr::Cast { expr, ty } => {
                k.exprs.push(*expr);
                k.tys.push(*ty);
            }
            Expr::Range { lo, hi, .. } => {
                if let Some(e) = lo {
                    k.exprs.push(*e);
                }
                if let Some(e) = hi {
                    k.exprs.push(*e);
                }
            }
            Expr::Break { value, .. } => {
                if let Some(e) = value {
                    k.exprs.push(*e);
                }
            }
            Expr::Continue(_) => {}
            Expr::Return(e) => {
                if let Some(e) = e {
                    k.exprs.push(*e);
                }
            }
            Expr::Macro { args, .. } => k.exprs.extend(args.iter().copied()),
            Expr::Tuple(es) | Expr::Array(es) => k.exprs.extend(es.iter().copied()),
            Expr::ArrayRepeat { value, len } => {
                k.exprs.push(*value);
                k.exprs.push(*len);
            }
            Expr::Closure { params, ret, body, .. } => {
                for p in params {
                    // Imported names in a parameter type (`|c: &Cow<str>|`)
                    // resolve like any other written type.
                    k.tys.extend(p.ty);
                    k.pats_with_scope.push((p.pat, ScopeBody::None));
                }
                k.tys.extend(*ret);
                k.exprs.push(*body);
            }
            Expr::Let { pat, scrut } => {
                k.exprs.push(*scrut);
                k.pats_with_scope.push((*pat, ScopeBody::None));
            }
            Expr::QPath { .. } | Expr::MacroCall(_) => {}
        }
        k
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::def::{CrateIds, LOCAL_CRATE, stable_crate_hash};
    use crate::driver::graph::Reads;
    use crate::intern::{Interner, Known};
    use crate::protocol::ProfileFlags;

    /// A macro definition's own string table holds only the strings of its
    /// tokens, with the same texts as the file's table (`own_def_strings`).
    #[test]
    fn macro_def_owns_only_its_strings() {
        let interner = Interner::default();
        let src = "fn a() { \"x\"; 1.5; }\nmacro_rules! m { () => { (\"y\", 2.5, 'c') } }\nfn b() { \"z\"; }";
        let lexed = lexer::lex(src, FileId(0), 0, &interner).unwrap();
        let at = lexed.tokens.iter().position(|t| matches!(t.tok, crate::lexer::Tok::Ident(s) if interner.get(s) == "macro_rules")).unwrap();
        let (lo, hi) = macro_tok_range(&lexed.tokens, at);
        let (toks, strings) = own_def_strings(&lexed.tokens[lo..hi], &lexed.strings);
        assert!(strings.len() < lexed.strings.len(), "{strings:?} vs {:?}", lexed.strings);
        let texts = |toks: &[crate::lexer::Token], table: &[String]| -> Vec<String> {
            toks.iter().filter_map(|t| crate::lexer::lit_text(&t.tok, table).map(|c| c.into_owned())).collect()
        };
        assert_eq!(texts(&toks, &strings), texts(&lexed.tokens[lo..hi], &lexed.strings));
        assert!(!strings.iter().any(|s| s.contains('x') || s.contains('z')));
    }

    /// The platform crate loads for a platform module mention, a `std::{..}`
    /// group that names one (or `self`), and not for compiler-handled items.
    #[test]
    fn std_platform_mentions() {
        for (text, want) in [
            ("use std::io::Write;", true),
            ("fn main() { std::fs::write(\"a\", \"b\"); }", true),
            ("use std::{collections::HashMap, io::{self, Read}};", true),
            ("use std::{self as s};", true),
            ("use std::{};", false),
            ("use std::{rc::Rc, cell::{Cell, RefCell}}; mod io {}", false),
            ("let n = std::env::args().count(); std::process::exit(0);", false),
            ("std::env::args_os()", true),
            ("std::envy", true),
        ] {
            assert_eq!(mentions_std_platform(text), want, "{text}");
        }
    }


    /// Routing a big file in parallel pieces answers exactly as one serial
    /// lex: triggers in any piece count (a `use`, a leading `::`, or an
    /// `include!` mid-file, a `static` at the end), and triggers inside a
    /// raw string or a block comment that spans a cut do not.
    #[test]
    fn parallel_routing_matches_serial() {
        let filler: String = (0..3000).map(|i| format!("fn f{i}() -> i64 {{ {i} }}\nstruct S{i};\n")).collect();
        let serial = |t: &str| {
            let i = Interner::default();
            needs_resolve_lexed(&lexer::lex(t, FileId(0), 0, &i).unwrap(), &i)
        };
        let half = filler.len() / 2;
        let cut = half + filler[half..].find("}\n").unwrap() + 2;
        let cases = [
            filler.clone(),
            format!("{}use std::fmt;\n{}", &filler[..cut], &filler[cut..]),
            format!("{}static X: i64 = 1;\n", filler),
            format!("{}fn h() -> &'static str {{ r#\"\nuse a;\n{}\"# }}\n", &filler[..cut], &filler[cut..]),
            format!("{}/*\nmod m;\n{}*/\n", &filler[..cut], &filler[cut..]),
            format!("{}fn g() -> i64 {{ 1 }}\n::std::process::exit(0);\n{}", &filler[..cut], &filler[cut..]),
            format!("{}include!(\"part.rs\");\n{}", &filler[..cut], &filler[cut..]),
        ];
        for (k, text) in cases.iter().enumerate() {
            assert!(route_pieces(text).is_some_and(|p| p.len() > 1), "case {k} splits");
            let i = Interner::default();
            assert_eq!(needs_resolve(text, &i), serial(text), "case {k}");
            // The root tokens for discovery: exactly the serial lex, on yes.
            let (yes, lexed) = route_root(text, &i);
            assert_eq!(lexed.is_some(), yes, "case {k}");
            if let Some(l) = lexed {
                let s = lexer::lex(text, FileId(0), 0, &i).unwrap();
                assert!(l.strings == s.strings && l.tokens.len() == s.tokens.len(), "case {k}");
                assert!(l.tokens.iter().zip(&s.tokens).all(|(a, b)| a.tok == b.tok && a.span == b.span), "case {k}");
            }
        }
        let answers: Vec<bool> = cases.iter().map(|t| serial(t)).collect();
        assert_eq!(answers, [false, true, true, false, false, true, true]);
    }

    /// The std source module scan that routing does per piece answers as
    /// `stdmods::needs` on the whole file: a trigger word in any piece,
    /// at a piece's first or last line, counts; a trigger inside a longer
    /// word does not.
    #[test]
    fn parallel_std_scan_matches_serial() {
        let filler: String = (0..3000).map(|i| format!("fn f{i}() -> i64 {{ {i} }}\nstruct S{i};\n")).collect();
        let pieces = route_pieces(&filler).unwrap();
        let (a, b) = pieces[1];
        let cases = [
            filler.clone(),
            format!("{}fn t() {{ let _ = time; }}\n{}", &filler[..a], &filler[a..]),
            format!("{}fn t() {{ let _ = runtime; }}\n{}", &filler[..b], &filler[b..]),
            format!("{}// a LazyLock in a comment\n", filler),
            format!("{}fn t() {{ let _ = PhantomData_x; }}\n", filler),
        ];
        for (k, text) in cases.iter().enumerate() {
            let i = Interner::default();
            let (_, std_mods, _) = route_root_std(text, &i, true);
            assert_eq!(std_mods, crate::stdmods::needs(text), "case {k}");
            assert_eq!(route_root_std(text, &i, false).1, 0, "case {k}");
        }
        let answers: Vec<bool> = cases.iter().map(|t| crate::stdmods::needs(t) != 0).collect();
        assert_eq!(answers, [false, true, false, true, false]);
    }

    /// A big file lexed in parallel pieces joins into exactly the serial
    /// token list and string table, with every kind that indexes the string
    /// table (`Tok::string_index`) in pieces after the first, so each is
    /// moved past the earlier pieces' strings.
    #[test]
    fn parallel_lex_matches_serial() {
        let text: String = (0..4000)
            .map(|i| {
                format!(
                    "/// doc {i}\nfn f{i}() -> u8 {{ let _s = \"s{i}\"; let _b = b\"b{i}\"; let _f = {i}.5; b'{}' }}\n",
                    (b'a' + (i % 26) as u8) as char
                )
            })
            .collect();
        let pieces = route_pieces(&text).expect("big text splits");
        assert!(pieces.len() > 1);
        let i = Interner::default();
        let serial = lexer::lex(&text, FileId(3), 0, &i).unwrap();
        let joined = lex_file(&text, FileId(3), &i).unwrap();
        assert_eq!(joined.strings, serial.strings);
        assert_eq!(joined.tokens.len(), serial.tokens.len());
        for (a, b) in joined.tokens.iter().zip(&serial.tokens) {
            assert!(a.tok == b.tok && a.span == b.span, "{:?} vs {:?}", a, b);
        }
        // The string-table kinds all occur past the first cut.
        let first_cut = pieces[0].1 as u32;
        let later = |k: fn(lexer::Tok) -> bool| serial.tokens.iter().any(|t| t.span.lo >= first_cut && k(t.tok));
        assert!(later(|t| matches!(t, lexer::Tok::Str(..))));
        assert!(later(|t| matches!(t, lexer::Tok::ByteStr(_))));
        assert!(later(|t| matches!(t, lexer::Tok::ByteChar(_))));
        assert!(later(|t| matches!(t, lexer::Tok::Float(_))));
        assert!(later(|t| matches!(t, lexer::Tok::DocStr(_))));
    }

    /// Resolves `text` as a one-file crate two ways: one-shot (a big file
    /// parses in item segments) and with a daemon cache (whole files).
    fn resolve_both_ways(text: &str, name: &str) -> [Result<ResolvedCrate, ResolveError>; 2] {
        let interner = Interner::default();
        let known = Known::new(&interner);
        let dir = std::env::temp_dir().join(format!("lust-worklist-test-{}-{name}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let root = dir.join("main.rs");
        std::fs::write(&root, text).unwrap();
        let input = CrateInput {
            root_path: root,
            root_text: text.to_string(),
            env: CfgEnv::new("", &[], false, ProfileFlags::DEV),
            crate_ids: CrateIds { local: LOCAL_CRATE, stable: stable_crate_hash(&format!("pkg:{name}"), "bin", name, false) },
            crate_name: name.into(),
            cargo_env: Vec::new(),
            deps: Vec::new(),
            client: Default::default(),
            std_splice_lo: None,
            display_root: None,
        };
        let out = [true, false].map(|one_shot| resolve_crate_cached(&input, &interner, &known, &mut ResolveCache::new(one_shot)));
        let _ = std::fs::remove_dir_all(&dir);
        out
    }

    /// Both resolves of `resolve_both_ways` succeed with equal crates: fn
    /// lines, body hashes, the structure hash, every item and body scan, and
    /// fn modules. Scans hash string, float, byte string, and byte char
    /// literals, so a literal that read another segment's string would show.
    fn assert_segmented_equals_whole(text: &str, name: &str) {
        let interner = Interner::default();
        let toks = lexer::lex(text, FileId(0), 0, &interner).unwrap().tokens;
        assert!(item_segments(&toks, &interner).len() > 1, "the file splits");
        let [one, whole] = resolve_both_ways(text, name);
        let one = one.ok().expect("segmented resolves");
        let whole = whole.ok().expect("whole resolves");
        assert_eq!(one.fn_lines, whole.fn_lines);
        assert_eq!(one.body_hashes, whole.body_hashes);
        assert_eq!(one.structure_hash, whole.structure_hash);
        assert_eq!(one.scans.bodies, whole.scans.bodies);
        let item_hashes = |r: &ResolvedCrate| r.scans.items.iter().map(|i| (i.hash, i.fn_name)).collect::<Vec<_>>();
        assert_eq!(item_hashes(&one), item_hashes(&whole));
        assert_eq!(one.tables.fn_module, whole.tables.fn_module);
    }

    /// A one-shot resolve parses a big file in item segments; the crate it
    /// returns equals the whole-file resolve of a daemon (persistent) cache.
    #[test]
    fn segmented_resolve_matches_whole_file() {
        let mut text = String::from("mod m {\n    pub fn g() -> i64 { 1 }\n}\nuse m::g;\n");
        for i in 0..6000 {
            text += &format!(
                "fn f{i}() -> usize {{ let s = \"s{i}\"; let b = b\"b{i}\"; let c = b'x'; let f = {i}.5; s.len() + b.len() + c as usize + f as usize + g() as usize }}\n"
            );
        }
        text += "fn main() {\n    f0();\n}\n";
        assert_segmented_equals_whole(&text, "segments");
    }

    /// Macros do not stop segmenting: expansion runs on the whole file first,
    /// so segments cut the expanded stream. Macro-made items and a macro
    /// defined mid-file (used only after it, across later cuts) give the
    /// same crate as the whole-file resolve.
    #[test]
    fn segmented_resolve_with_macros_matches_whole_file() {
        let mut text = String::from(
            "macro_rules! twice { ($e:expr) => { $e * 2 }; }\nmacro_rules! mk { ($n:ident) => { fn $n() -> usize { twice!(3) } }; }\n",
        );
        for i in 0..6000 {
            if i == 3000 {
                text += "macro_rules! late { ($n:ident, $v:expr) => { fn $n() -> usize { $v + twice!(1) } }; }\n";
            }
            if i % 500 == 7 {
                text += &format!("mk!(g{i});\n");
            }
            if i > 3000 && i % 500 == 9 {
                text += &format!("late!(h{i}, {i});\n");
            }
            text += &format!("fn f{i}() -> usize {{ let s = \"s{i}\"; s.len() + twice!({i}) }}\n");
        }
        text += "fn main() {\n    f0();\n}\n";
        assert_segmented_equals_whole(&text, "segments-macros");
    }

    /// A bad item right before a cut: its segment ends at the cut, so the
    /// segment's own parse fails at the end of input instead of at the next
    /// item. The one-shot resolve parses the whole file again and gives the
    /// whole-file diagnostic.
    #[test]
    fn segment_error_gives_whole_file_diagnostic() {
        let interner = Interner::default();
        let known = Known::new(&interner);
        let fns: Vec<String> = (0..6000).map(|i| format!("fn f{i}() -> usize {{ let s = \"s{i}\"; s.len() + {i} }}\n")).collect();
        let main = "fn main() {}\n";
        // A const with no `;`. Its value ends in a block at depth zero, so
        // a cut fits right after it, and it is long enough to pass the
        // segment's size target on its own.
        let bad = format!("const C: usize = {{ {} }}\n", vec!["1"; 80].join(" + "));
        let good = fns.concat() + main;
        let good_toks = lexer::lex(&good, FileId(0), 0, &interner).unwrap().tokens;
        let first_cut = item_segments(&good_toks, &interner)[1].start;
        let k = good[..good_toks[first_cut].span.lo as usize].matches('\n').count();
        // Put the const before one of the items near the first cut, so that
        // the cut moves right after it.
        let (text, lexed, seg) = (k.saturating_sub(3)..=k)
            .find_map(|j| {
                let text = fns[..j].concat() + &bad + &fns[j..].concat() + main;
                let close = fns[..j].iter().map(|f| f.len()).sum::<usize>() + bad.len() - 2;
                let lexed = lexer::lex(&text, FileId(0), 0, &interner).unwrap();
                let seg =
                    item_segments(&lexed.tokens, &interner).into_iter().find(|r| lexed.tokens[r.end - 1].span.lo as usize == close)?;
                Some((text, lexed, seg))
            })
            .expect("a cut lands right after the bad const");
        let seg_err = parser::parse_items(&lexed, seg, &interner, &known).err().expect("the segment fails");
        let whole_err = parser::parse(&lexed, &interner, &known).err().expect("the file fails");
        assert_ne!(format!("{:?}", seg_err), format!("{:?}", whole_err), "the cut moves the error");
        let [one, whole] = resolve_both_ways(&text, "segment-error").map(|r| r.err().expect("the resolve fails").diags);
        assert_eq!(format!("{one:?}"), format!("{whole:?}"));
        assert_eq!(format!("{:?}", one[0]), format!("{whole_err:?}"));
    }

    /// Two definitions of one name in two item segments of a file are a
    /// duplicate (rustc E0428), as in one piece: the segments share the
    /// file's name set. Two `mod a` items, or a `mod a` and a `struct a`,
    /// were accepted when they sat in different segments.
    #[test]
    fn duplicates_across_segments_are_rejected() {
        let fns: String = (0..6000).map(|i| format!("fn f{i}() -> usize {{ let s = \"s{i}\"; s.len() + {i} }}\n")).collect();
        for (first, last) in [("mod a { pub fn x() {} }", "mod a { pub fn y() {} }"), ("mod a { pub fn x() {} }", "struct a;"), ("fn d() {}", "fn d() {}")] {
            let text = format!("{first}\n{fns}{last}\nfn main() {{}}\n");
            let [one, whole] = resolve_both_ways(&text, "segment-dups").map(|r| r.err().expect("a duplicate is an error").diags);
            assert_eq!(format!("{one:?}"), format!("{whole:?}"), "{last}");
            assert_eq!(one[0].code, "L0106", "{last}");
        }
    }

    fn resolve(files: &[(&str, &str)], crate_name: &str) -> Result<ResolvedCrate, ResolveError> {
        let dir = std::env::temp_dir().join(format!("lust-worklist-test-{}-{}", std::process::id(), crate_name));
        let _ = std::fs::remove_dir_all(&dir);
        for (rel, text) in files {
            let p = dir.join(rel);
            std::fs::create_dir_all(p.parent().unwrap()).unwrap();
            std::fs::write(&p, text).unwrap();
        }
        let interner = Interner::default();
        let known = Known::new(&interner);
        let root = dir.join("main.rs");
        let input = CrateInput {
            root_path: root.clone(),
            root_text: std::fs::read_to_string(&root).unwrap(),
            env: CfgEnv::new("", &[], false, ProfileFlags::DEV),
            crate_ids: CrateIds { local: LOCAL_CRATE, stable: stable_crate_hash(&format!("pkg:{crate_name}"), "bin", crate_name, false) },
            crate_name: crate_name.into(),
            cargo_env: Vec::new(),
            deps: Vec::new(),
            client: Default::default(),
            std_splice_lo: None,
            display_root: None,
        };
        // The interner must outlive the tables' Syms only for lookups in
        // the test; leak it (tests are short-lived).
        let interner: &'static Interner = Box::leak(Box::new(interner));
        let known: &'static Known = Box::leak(Box::new(known));
        resolve_crate(&input, interner, known)
    }

    /// The per-file cache is transparent: a second resolve with the
    /// same cache (one shared interner, as in a daemon session) gives
    /// the same crate, an edit to one file is seen, and deleting a
    /// module file still errors instead of serving the cached stream.
    #[test]
    fn resolve_cache_is_transparent() {
        let dir = std::env::temp_dir().join(format!("lust-worklist-cache-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("main.rs"), "mod a;\nmod b;\nfn main() { println!(\"{}\", a::v() + b::v()); }").unwrap();
        std::fs::write(dir.join("a.rs"), "pub fn v() -> i64 { 1 }").unwrap();
        std::fs::write(dir.join("b.rs"), "pub fn v() -> i64 { 2 }").unwrap();
        let interner: &'static Interner = Box::leak(Box::new(Interner::default()));
        let known: &'static Known = Box::leak(Box::new(Known::new(interner)));
        let input = |dir: &std::path::Path| CrateInput {
            root_path: dir.join("main.rs"),
            root_text: std::fs::read_to_string(dir.join("main.rs")).unwrap(),
            env: CfgEnv::new("", &[], false, ProfileFlags::DEV),
            crate_ids: CrateIds { local: LOCAL_CRATE, stable: stable_crate_hash("pkg:cachetest", "bin", "cachetest", false) },
            crate_name: "cachetest".into(),
            cargo_env: Vec::new(),
            deps: Vec::new(),
            client: Default::default(),
            std_splice_lo: None,
            display_root: None,
        };
        let mut cache = ResolveCache::new(false);
        let first = resolve_crate_cached(&input(&dir), interner, known, &mut cache).ok().expect("first resolves");
        let second = resolve_crate_cached(&input(&dir), interner, known, &mut cache).ok().expect("cached resolves");
        assert_eq!(first.fn_lines, second.fn_lines);
        assert_eq!(first.body_hashes, second.body_hashes);
        assert_eq!(first.structure_hash, second.structure_hash);
        assert_eq!(first.ast.items.len(), second.ast.items.len());
        // The cache now holds final chunks, and the assembled chunk
        // scans equal a fresh scan of the merged Ast.
        assert!(cache.files.values().all(|f| f.final_chunk.is_some()), "every file is cached");
        let fresh = crate::driver::ast_hash::scan_ast(&second.ast);
        assert_eq!(
            second.scans.items.iter().map(|i| i.hash).collect::<Vec<_>>(),
            fresh.items.iter().map(|i| i.hash).collect::<Vec<_>>()
        );
        assert_eq!(second.scans.bodies, fresh.bodies);
        assert_eq!(first.tables.fn_module, second.tables.fn_module);
        // An import edit moves the rewrite epoch: chunks rebuild and
        // the answer still matches a fresh scan.
        std::fs::write(dir.join("main.rs"), "mod a;\nmod b;\nuse crate::a::v as av;\nfn main() { println!(\"{}\", av() + b::v()); }").unwrap();
        let imported = resolve_crate_cached(&input(&dir), interner, known, &mut cache).ok().expect("import edit resolves");
        let fresh = crate::driver::ast_hash::scan_ast(&imported.ast);
        assert_eq!(
            imported.scans.items.iter().map(|i| i.hash).collect::<Vec<_>>(),
            fresh.items.iter().map(|i| i.hash).collect::<Vec<_>>()
        );
        assert_eq!(imported.scans.bodies, fresh.bodies);
        std::fs::write(dir.join("main.rs"), "mod a;\nmod b;\nfn main() { println!(\"{}\", a::v() + b::v()); }").unwrap();
        let _ = resolve_crate_cached(&input(&dir), interner, known, &mut cache).ok().expect("import edit back resolves");
        // An edit to one file changes exactly its body hash.
        std::fs::write(dir.join("b.rs"), "pub fn v() -> i64 { 3 }").unwrap();
        let third = resolve_crate_cached(&input(&dir), interner, known, &mut cache).ok().expect("edited resolves");
        let changed: Vec<usize> = (0..first.body_hashes.len()).filter(|&i| first.body_hashes[i] != third.body_hashes[i]).collect();
        assert_eq!(changed.len(), 1, "only the edited file's fn rehashes");
        // A deleted module file is an error, never a cached stream.
        std::fs::remove_file(dir.join("b.rs")).unwrap();
        assert!(resolve_crate_cached(&input(&dir), interner, known, &mut cache).is_err(), "missing file errors");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The expansion cache keys a file on the macro seeds it reaches
    /// (`expand::reach_seeds`): an edit of one macro re-expands the files
    /// that call it (directly, through another macro's body, or through a
    /// glob import) and a file that `include!`s; the others, a file whose
    /// glob brings the macro but never calls it too, take their streams
    /// back. Every step resolves as a fresh cache does.
    #[test]
    fn expansions_key_on_the_seeds_a_file_reaches() {
        let dir = std::env::temp_dir().join(format!("lust-worklist-expkey-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let macros = |one: u8, inner: u8, hidden: u8| {
            format!(
                "#[macro_export]\nmacro_rules! one {{ () => {{ {one} }} }}\n#[macro_export]\nmacro_rules! outer {{ () => {{ $crate::inner!() }} }}\n#[macro_export]\nmacro_rules! inner {{ () => {{ {inner} }} }}\nmacro_rules! hidden {{ () => {{ {hidden} }} }}\npub(crate) use hidden;\n"
            )
        };
        let files = [
            ("main.rs", "mod m;\nmod a;\nmod b;\nmod c;\nmod d;\nmod e;\nmod f;\nfn main() { println!(\"{}\", a::v() + b::v() + c::v() + d::v() + e::v() + f::v()); }"),
            ("a.rs", "pub fn v() -> i64 { crate::one!() }"),
            ("b.rs", "pub fn v() -> i64 { crate::outer!() }"),
            ("c.rs", "pub fn v() -> i64 { 3 }"),
            ("d.rs", "include!(\"d.in\");"),
            ("d.in", "pub fn v() -> i64 { crate::one!() }"),
            ("e.rs", "use crate::m::*;\npub fn v() -> i64 { 4 }"),
            ("f.rs", "use crate::m::*;\npub fn v() -> i64 { hidden!() }"),
        ];
        for (name, text) in files {
            std::fs::write(dir.join(name), text).unwrap();
        }
        std::fs::write(dir.join("m.rs"), macros(1, 2, 7)).unwrap();
        let interner: &'static Interner = Box::leak(Box::new(Interner::default()));
        let known: &'static Known = Box::leak(Box::new(Known::new(interner)));
        let input = CrateInput {
            root_path: dir.join("main.rs"),
            root_text: std::fs::read_to_string(dir.join("main.rs")).unwrap(),
            env: CfgEnv::new("", &[], false, ProfileFlags::DEV),
            crate_ids: CrateIds { local: LOCAL_CRATE, stable: stable_crate_hash("pkg:expkey", "bin", "expkey", false) },
            crate_name: "expkey".into(),
            cargo_env: Vec::new(),
            deps: Vec::new(),
            client: Default::default(),
            std_splice_lo: None,
            display_root: None,
        };
        // Resolves with `cache`, checks the answer against a fresh cache's, and gives the
        // number of files expanded again.
        let step = |cache: &mut ResolveCache| {
            let before = cache.expansions();
            let warm = resolve_crate_cached(&input, interner, known, cache).ok().expect("resolves");
            let cold = resolve_crate_cached(&input, interner, known, &mut ResolveCache::new(false)).ok().expect("resolves cold");
            assert_eq!(warm.body_hashes, cold.body_hashes);
            cache.expansions() - before
        };
        let mut cache = ResolveCache::new(false);
        let mut counts = vec![step(&mut cache), step(&mut cache)];
        // `one` edited: m, a, d. `inner` edited: m, b (through `outer`), d. `hidden` edited:
        // m, f (through its glob), d. Every macro moved: m, a, b, d, f.
        for text in [macros(5, 2, 7), macros(5, 6, 7), macros(5, 6, 8), format!("\n{}", macros(5, 6, 8))] {
            std::fs::write(dir.join("m.rs"), text).unwrap();
            counts.push(step(&mut cache));
        }
        assert!(counts[0] >= 8, "cold: every file");
        assert_eq!(counts[1..], [0, 3, 3, 3, 5], "files expanded: no edit, then each m.rs edit");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A file's cached `use` sites hold its module path: the same text under another module
    /// (`#[path]`, same file key) scans again, so its macro re-export binds there.
    #[test]
    fn use_sites_key_on_the_module_path() {
        let dir = std::env::temp_dir().join(format!("lust-worklist-sites-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("m.rs"), "macro_rules! hidden { () => { 7 } }\npub(crate) use hidden;\n").unwrap();
        std::fs::write(dir.join("x.rs"), "pub(crate) use crate::m::hidden as h;\npub fn v() -> i64 { 1 }\n").unwrap();
        let interner: &'static Interner = Box::leak(Box::new(Interner::default()));
        let known: &'static Known = Box::leak(Box::new(Known::new(interner)));
        let mut cache = ResolveCache::new(false);
        for name in ["a", "b"] {
            let root = format!("mod m;\n#[path = \"x.rs\"]\nmod {name};\nfn main() {{ println!(\"{{}}\", {name}::v() + {name}::h!()); }}\n");
            std::fs::write(dir.join("main.rs"), &root).unwrap();
            let input = CrateInput {
                root_path: dir.join("main.rs"),
                root_text: root,
                env: CfgEnv::new("", &[], false, ProfileFlags::DEV),
                crate_ids: CrateIds { local: LOCAL_CRATE, stable: stable_crate_hash("pkg:sites", "bin", "sites", false) },
                crate_name: "sites".into(),
                cargo_env: Vec::new(),
                deps: Vec::new(),
                client: Default::default(),
                std_splice_lo: None,
                display_root: None,
            };
            let warm = resolve_crate_cached(&input, interner, known, &mut cache).ok().expect("resolves");
            let cold = resolve_crate_cached(&input, interner, known, &mut ResolveCache::new(false)).ok().expect("resolves cold");
            assert_eq!(warm.scans.bodies, cold.scans.bodies, "module {name}");
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Every renamed def records its source path in
    /// `display_names`, so flat names stay out of program output and
    /// diagnostics. Root defs keep plain names and need no entry.
    #[test]
    fn flat_names_record_display_paths() {
        // The fallback string forms: a dependency hash segment drops,
        // module segments join with `::`, plain names pass through.
        assert_eq!(crate::intern::source_name("k0123456789abcdef$inner$Deep"), "Deep");
        assert_eq!(crate::intern::source_name("a$b$Deep"), "Deep");
        assert_eq!(crate::intern::source_path("k0123456789abcdef$inner$Deep"), "inner::Deep");
        assert_eq!(crate::intern::source_path("Plain"), "Plain");

        let dir = std::env::temp_dir().join(format!("lust-worklist-display-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("a")).unwrap();
        std::fs::write(dir.join("main.rs"), "mod a;\nstruct Root;\nfn main() { let _ = a::b::Deep; let _ = Root; }").unwrap();
        std::fs::write(dir.join("a.rs"), "pub mod b;\npub struct Shallow;\npub fn f() {}\npub const C: i64 = 1;").unwrap();
        std::fs::write(dir.join("a/b.rs"), "pub struct Deep;").unwrap();
        let interner: &'static Interner = Box::leak(Box::new(Interner::default()));
        let known: &'static Known = Box::leak(Box::new(Known::new(interner)));
        let input = CrateInput {
            root_path: dir.join("main.rs"),
            root_text: std::fs::read_to_string(dir.join("main.rs")).unwrap(),
            env: CfgEnv::new("", &[], false, ProfileFlags::DEV),
            crate_ids: CrateIds { local: LOCAL_CRATE, stable: stable_crate_hash("pkg:displaytest", "bin", "displaytest", false) },
            crate_name: "displaytest".into(),
            cargo_env: Vec::new(),
            deps: Vec::new(),
            client: Default::default(),
            std_splice_lo: None,
            display_root: None,
        };
        let r = resolve_crate(&input, interner, known).ok().expect("display test crate resolves");
        let shown = |flat_text: &str| r.tables.display_names.get(&interner.intern(flat_text)).map(|&d| interner.get(d).to_string());
        assert_eq!(shown("a$b$Deep").as_deref(), Some("a::b::Deep"));
        assert_eq!(shown("a$Shallow").as_deref(), Some("a::Shallow"));
        assert_eq!(shown("a$f").as_deref(), Some("a::f"));
        assert_eq!(shown("a$C").as_deref(), Some("a::C"));
        assert_eq!(shown("Root"), None, "root defs keep plain names");
        // A warm resolve through the cache rebuilds the same table.
        let mut cache = ResolveCache::new(false);
        let warm = resolve_crate_cached(&input, interner, known, &mut cache).ok().expect("warm resolve");
        assert_eq!(warm.tables.display_names, r.tables.display_names);
        let warm2 = resolve_crate_cached(&input, interner, known, &mut cache).ok().expect("cached resolve");
        assert_eq!(warm2.tables.display_names, r.tables.display_names);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Nested (body-local) fns keep collect's order through the
    /// per-file chunk scans: every top-level body first, then every
    /// nested body, on a cold and on a fully cached resolve.
    #[test]
    fn resolve_cache_nested_fn_scan_order() {
        let dir = std::env::temp_dir().join(format!("lust-worklist-nested-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("main.rs"), "mod a;\nfn main() { fn inner(x: i64) -> i64 { x + 1 } println!(\"{}\", inner(a::v())); }").unwrap();
        std::fs::write(dir.join("a.rs"), "pub fn v() -> i64 { fn deep() -> i64 { 7 } deep() }").unwrap();
        let interner: &'static Interner = Box::leak(Box::new(Interner::default()));
        let known: &'static Known = Box::leak(Box::new(Known::new(interner)));
        let input = CrateInput {
            root_path: dir.join("main.rs"),
            root_text: std::fs::read_to_string(dir.join("main.rs")).unwrap(),
            env: CfgEnv::new("", &[], false, ProfileFlags::DEV),
            crate_ids: CrateIds { local: LOCAL_CRATE, stable: stable_crate_hash("pkg:nestedtest", "bin", "nestedtest", false) },
            crate_name: "nestedtest".into(),
            cargo_env: Vec::new(),
            deps: Vec::new(),
            client: Default::default(),
            std_splice_lo: None,
            display_root: None,
        };
        let mut cache = ResolveCache::new(false);
        for round in 0..2 {
            let r = resolve_crate_cached(&input, interner, known, &mut cache).ok().expect("nested resolves");
            let fresh = crate::driver::ast_hash::scan_ast(&r.ast);
            assert_eq!(r.scans.bodies, fresh.bodies, "round {round}: chunk scan order matches the merged scan");
            assert_eq!(r.scans.bodies.len(), r.fn_lines.len(), "round {round}: one body scan per fn line");
            assert_eq!(r.fn_lines.len(), 4, "main, a::v, and two nested fns");
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The same file in two crates gets two DefIds (section 1.2): AST
    /// and defs are per (crate, module), never shared by file.
    #[test]
    fn shared_file_two_crates_two_def_ids() {
        let files: &[(&str, &str)] = &[("main.rs", "mod s;\nfn main() { println!(\"{}\", s::v()); }"), ("s.rs", "pub fn v() -> i64 { 1 }")];
        let a = resolve(files, "crate_a").ok().expect("crate a resolves");
        let b = resolve(files, "crate_b").ok().expect("crate b resolves");
        let defs = |r: &ResolvedCrate| {
            let mut v: Vec<u64> = r.tables.def_info.keys().map(|d| d.hash.0).collect();
            v.sort_unstable();
            v
        };
        assert!(!defs(&a).is_empty());
        assert_ne!(defs(&a), defs(&b), "same file, different crates, different defs");
    }

    fn dep_unit(name: &str, version: &str, source: Option<&str>) -> super::super::cargo::DepUnit {
        super::super::cargo::DepUnit {
            extern_name: name.replace('-', "_"),
            package_id: format!("pkg:{name}"),
            package_name: name.into(),
            version: version.into(),
            source: source.map(str::to_string),
            lib_src: PathBuf::from("/nonexistent/lib.rs"),
            lib_name: name.into(),
            edition: "2021".into(),
            manifest_dir: PathBuf::new(),
            cargo_env: Vec::new(),
            build_cfgs: Vec::new(),
            build_check_cfgs: Vec::new(),
            features: Vec::new(),
            deps: Vec::new(),
        }
    }

    /// Dependency classification (ARCH 1.1 table): a path package is
    /// lust source whatever its name; a registry adapter or shim with
    /// no lust-side crate rejects with a reason naming the crate.
    #[test]
    fn dep_classification_names_unsupported_crates() {
        let registry = Some("registry+https://github.com/rust-lang/crates.io-index");
        match classify_dep(&dep_unit("indexmap", "2.14.0", registry)) {
            DepClass::Unsupported(why) => assert!(why.contains("indexmap"), "{why}"),
            DepClass::Source { .. } => {
                // A lust adapter may have landed in library/deps since
                // this test was written; then source is the answer.
            }
        }
        match classify_dep(&dep_unit("indexmap", "0.1.0", None)) {
            DepClass::Source { lust_owned, adapter, .. } => {
                assert!(!lust_owned && adapter.is_none(), "a path package named indexmap is plain source")
            }
            DepClass::Unsupported(why) => panic!("path package must be source: {why}"),
        }
        // The memchr adapter pins 2.8.2: another version is a mismatch
        // that names both versions, never a silent swap.
        match classify_dep(&dep_unit("memchr", "2.8.3", registry)) {
            DepClass::Unsupported(why) => assert!(why.contains("2.8.3") && why.contains("2.8.2"), "{why}"),
            DepClass::Source { .. } => panic!("a version the adapter does not match must not swap in"),
        }
        match classify_dep(&dep_unit("memchr", "2.8.2", registry)) {
            DepClass::Source { lust_owned, adapter, .. } => assert!(lust_owned && adapter.is_some()),
            DepClass::Unsupported(why) => panic!("memchr 2.8.2 has an adapter: {why}"),
        }
        match classify_dep(&dep_unit("rustix", "1.0.0", registry)) {
            DepClass::Unsupported(why) => assert!(why.contains("rustix"), "{why}"),
            DepClass::Source { .. } => {}
        }
        match classify_dep(&dep_unit("frobnicator", "1.0.0", registry)) {
            DepClass::Unsupported(why) => assert!(why.contains("frobnicator"), "{why}"),
            DepClass::Source { .. } => panic!("an unknown registry crate has no lust form"),
        }
    }

    /// The explicit-through-glob example of section 1.3 resolves, and a
    /// glob collision is stored ambiguous without error until used:
    /// both crates resolve here, and the binding answer differs
    /// (Def for the pinned crate, Ambiguous for the colliding one).
    #[test]
    fn glob_bindings_pin_and_ambiguity() {
        let pinned: &[(&str, &str)] = &[
            ("main.rs", "mod checker;\nmod prelude;\nuse prelude::Kind;\nfn main() { println!(\"{}\", 1); }"),
            ("prelude.rs", "pub use crate::checker::Kind;"),
            ("checker.rs", "pub mod mapper;\npub use mapper::*;"),
            ("checker/mapper.rs", "pub enum Kind { A }"),
        ];
        let r = resolve(pinned, "pin");
        assert!(r.is_ok(), "pinned resolves: {:?}", r.err().map(|e| e.diags.len()));

        let colliding: &[(&str, &str)] = &[
            ("main.rs", "mod a;\nmod b;\nuse a::*;\nuse b::*;\nfn main() { println!(\"{}\", 1); }"),
            ("a.rs", "pub fn v() -> i64 { 1 }"),
            ("b.rs", "pub fn v() -> i64 { 2 }"),
        ];
        let r = resolve(colliding, "collide").ok().expect("unused collision resolves");
        let interner = Interner::default();
        let name = interner.intern("v");
        // The tables were built with a leaked interner in `resolve`;
        // Sym values differ across interners, so ask through the flat
        // index state instead: the root map holds the ambiguity.
        let _ = name;
        let ambiguous =
            r.tables.maps.first().is_some_and(|maps| maps.iter().any(|m| m.values().any(|s| matches!(s, BindState::Ambiguous))));
        assert!(ambiguous, "glob collision stored ambiguous, no error while unused");
        let _reads = Reads::new();
    }
}

/// Moves inline module bodies into the flat item list, dropping mod,
/// use, and extern crate items (their bindings live in the tables).
/// Flattens one file's items for the merged Ast, recording the module
/// each surviving item came from in `out_mods` (parallel to `out`).
/// Inline module bodies splice in with their child module from
/// `list_module`; mod, use, and extern crate items drop.
/// Moves each impl inside a fn body (`Ast::stmt_items`) to the module
/// items, right after the module item whose span holds it and in that
/// item's module. An impl in a block is global for method lookup and
/// coherence (rustc), so collect and check take it as a module impl;
/// its header and bodies see the block items around it by its span (R18,
/// `collect::apply_stmt_overlay`). The other body items keep their order
/// and `Stmt::Item` indexes follow them. A body impl from a macro
/// expansion, or one no item holds, stays a body item (collect: L0820).
fn hoist_block_impls(ast: &mut Ast, items: &mut Vec<Item>, mods: &mut Vec<ModuleId>) {
    let holds = |s: Span, t: Span| s.file == t.file && s.lo <= t.lo && t.hi <= s.hi;
    let owner = |it: &Item| {
        (matches!(it.kind, ItemKind::Impl(_)) && it.span.ctxt == crate::diag::CtxtId::ROOT)
            .then(|| items.iter().position(|o| o.span.ctxt == crate::diag::CtxtId::ROOT && holds(o.span, it.span)))
            .flatten()
    };
    let owners: Vec<Option<usize>> = ast.stmt_items.iter().map(owner).collect();
    if owners.iter().all(Option::is_none) {
        return;
    }
    let mut remap: Vec<Option<u32>> = vec![None; owners.len()];
    let mut hoisted: Vec<Vec<Item>> = vec![Vec::new(); items.len()];
    let mut kept = Vec::with_capacity(owners.len());
    for (i, mut item) in std::mem::take(&mut ast.stmt_items).into_iter().enumerate() {
        match owners[i] {
            Some(o) => {
                if let ItemKind::Impl(imp) = &mut item.kind {
                    imp.in_body = true;
                }
                hoisted[o].push(item);
            }
            None => {
                remap[i] = Some(kept.len() as u32);
                kept.push(item);
            }
        }
    }
    ast.stmt_items = kept;
    for b in &mut ast.blocks {
        b.stmts.retain_mut(|s| match s {
            Stmt::Item(i) => match remap[*i as usize] {
                Some(n) => {
                    *i = n;
                    true
                }
                None => false,
            },
            _ => true,
        });
    }
    let (mut out, mut out_mods) = (Vec::with_capacity(items.len()), Vec::with_capacity(items.len()));
    for ((item, m), extra) in std::mem::take(items).into_iter().zip(std::mem::take(mods)).zip(hoisted) {
        out.push(item);
        out_mods.push(m);
        out_mods.extend(std::iter::repeat_n(m, extra.len()));
        out.extend(extra);
    }
    *items = out;
    *mods = out_mods;
}

fn flatten_items_mods(
    items: Vec<Item>,
    module: ModuleId,
    fi: usize,
    prefix: &[Sym],
    list_module: &FxMap<ItemListKey, ModuleId>,
    out: &mut Vec<Item>,
    out_mods: &mut Vec<ModuleId>,
) {
    for item in items {
        match item.kind {
            ItemKind::Mod(m) => {
                if let Some(body) = m.body {
                    let mut key = prefix.to_vec();
                    key.push(m.name);
                    let child = list_module.get(&(fi, key.clone())).copied().unwrap_or(module);
                    flatten_items_mods(body, child, fi, &key, list_module, out, out_mods);
                }
            }
            ItemKind::Use(_) | ItemKind::ExternCrate(_) => {}
            _ => {
                out.push(item);
                out_mods.push(module);
            }
        }
    }
}
